INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 1, 'OT', 'В начале сотворил Бог небо и землю.'),
(2, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 2, 'OT', 'Земля же была пустота и пустошь, и тьма над лицом бездны, и дух Божий носился над лицом вод.'),
(3, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 3, 'OT', 'И сказал Бог: да будет свет. И стал свет.'),
(4, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 4, 'OT', 'И увидел Бог свет, что он хорош, и отделил Бог свет от тьмы.'),
(5, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 5, 'OT', 'И назвал Бог свет днём, а тьму назвал ночью. И был вечер, и было утро: день один.'),
(6, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 6, 'OT', 'И сказал Бог: да будет твердь посреди воды, и да отделяет она воду от воды.'),
(7, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 7, 'OT', 'И создал Бог твердь, и отделил воду, которая под твердью, от воды, которая над твердью; и стало так.'),
(8, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 8, 'OT', 'И назвал Бог твердь небом; и был вечер, и было утро: день второй.'),
(9, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 9, 'OT', 'И сказал Бог: пусть соберётся вода из-под неба в одно место, и пусть явится суша. И стало так.'),
(10, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 10, 'OT', 'И назвал Бог сушу землёю, а собрание вод назвал морями; и увидел Бог, что это хорошо.'),
(11, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 11, 'OT', 'И сказал Бог: да произрастит земля траву, траву, сеющую семя, дерево плодовитое, приносящее плод по роду своему, в котором семя его на земле. И стало так.'),
(12, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 12, 'OT', 'И произвела земля траву, траву, сеющую семя по роду её, и дерево, приносящее плод, в котором семя его по роду его; и увидел Бог, что это хорошо.'),
(13, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 13, 'OT', 'И был вечер, и было утро: день третий.'),
(14, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 14, 'OT', 'И сказал Бог: да будут светила на тверди неба, чтобы отделять день от ночи, и да будут они для знамений и для времен, и для дней и годов.'),
(15, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 15, 'OT', 'И будут они светилами на тверди неба, чтобы светить на землю; и стало так.'),
(16, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 16, 'OT', 'И создал Бог два великих светила: светило великое для владычества дня, и светило малое для владычества ночи, и звезды.'),
(17, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 17, 'OT', 'И поместил их Бог на тверди небесной, чтобы светить на землю.'),
(18, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 18, 'OT', 'и владычествовать над днём и над ночью, и отделять между светом и между тьмою; и увидел Бог, что это хорошо.'),
(19, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 19, 'OT', 'И был вечер, и было утро: день четвёртый.'),
(20, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 20, 'OT', 'И сказал Бог: да воскишат воды гадом, душою живою, и птица да полетит над землёю, по лицу тверди небесной.'),
(21, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 21, 'OT', 'И сотворил Бог больших драконов, и всякую душу живую, пресмыкающуюся, которою кишат воды, по роду их, и всякую птицу крылатую по роду её; и увидел Бог, что это хорошо.'),
(22, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 22, 'OT', 'И благословил их Бог, говоря: плодитесь и размножайтесь, и наполняйте воды в морях, и птица да умножается на земле.'),
(23, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 23, 'OT', 'И был вечер, и было утро: день пятый.'),
(24, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 24, 'OT', 'И сказал Бог: да произведёт земля живое существо по роду её, скот и пресмыкающееся, и зверей земли по роду её; и стало так.'),
(25, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 25, 'OT', 'И создал Бог зверей земных по роду их, и скот по роду его, и всё пресмыкающееся по земле по роду его; и увидел Бог, что это хорошо.'),
(26, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 26, 'OT', 'И сказал Бог: сотворим человека по образу нашему, по подобию нашему, и да владычествуют они над рыбами морскими, и над птицами небесными, и над скотом, и над всею землёю, и над всеми пресмыкающимися, пресмыкающимися по земле.'),
(27, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 27, 'OT', 'И сотворил Бог человека по образу Своему, по образу Божию сотворил его; мужчину и женщину сотворил их.'),
(28, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 28, 'OT', 'И благословил их Бог, и сказал им Бог: плодитесь и размножайтесь, и наполняйте землю, и обладайте ею, и владычествуйте над рыбами морскими, и над птицами небесными, и над всем живым, что пресмыкается по земле.'),
(29, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 29, 'OT', 'И сказал Бог: вот, Я дал вам всю траву, сеющую семя, которая на лице всей земли, и всякое дерево, на котором плод дерева, сеющий семя, — вам это будет в пищу.'),
(30, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 30, 'OT', 'И всем зверям земли, и всем птицам небесным, и всему, что ползает по земле, в котором есть живое существо, — вся зелень травы в пищу. И стало так.'),
(31, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 1, 31, 'OT', 'И увидел Бог всё, что Он создал, и вот, это было очень хорошо. И был вечер, и было утро: день шестой.'),
(32, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 1, 'OT', 'И завершены были небо и земля и весь сонм их.'),
(33, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 2, 'OT', 'И завершил Бог в день седьмой работу Свою, которую Он делал, и почил в день седьмой от всей работы Своей, которую Он делал.'),
(34, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 3, 'OT', 'И благословил Бог седьмой день, и освятил его, ибо в нём Он почил от всей Своей работы, которую Бог сотворил, чтобы сделать.'),
(35, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 4, 'OT', 'Вот родословие неба и земли, при сотворении их, в день, когда Господь Бог создал землю и небо.'),
(36, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 5, 'OT', 'И всякий куст полевой ещё не был на земле, и всякая трава полевая ещё не росла, ибо не посылал Господь Бог дождя на землю, и человека не было для возделывания земли.'),
(37, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 6, 'OT', 'И пар поднимался от земли и орошал всё лицо земли.'),
(38, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 7, 'OT', 'И создал Господь Бог человека из праха земного, и вдунул в ноздри его дыхание жизни, и стал человек душою живою.'),
(39, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 8, 'OT', 'Господь Бог насадил сад в Едеме на востоке, и поместил там человека, которого создал.'),
(40, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 9, 'OT', 'И произрастил Господь Бог из земли всякое дерево, приятное на вид и хорошее для пищи, и дерево жизни посреди сада, и дерево познания добра и зла.'),
(41, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 10, 'OT', 'И река выходила из Едема, чтобы орошать сад, и оттуда разделялась и становилась четырьмя рукавами.'),
(42, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 11, 'OT', 'Имя одного — Фисон; он обходит всю землю Хавила, где золото.'),
(43, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 12, 'OT', 'И золото той земли хорошее; там бдолах и камень оникс.'),
(44, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 13, 'OT', 'Имя второй реки — Гихон; она обходит всю землю Ефиопии.'),
(45, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 14, 'OT', 'Имя третьей реки — Хиддекель; она течёт к востоку от Ассирии. А четвёртая река — это Евфрат.'),
(46, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 15, 'OT', 'И взял Господь Бог человека, и поместил его в саду Едем, чтобы возделывать его и хранить его.'),
(47, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 16, 'OT', 'И повелел Господь Бог человеку, говоря: от всякого дерева сада ты будешь есть.'),
(48, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 17, 'OT', 'А от дерева познания добра и зла не ешь от него, ибо в день, когда ты вкусишь от него, смертью умрёшь.'),
(49, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 18, 'OT', 'И сказал Господь Бог: не хорошо быть человеку отдельно; сделаю ему помощь, соответствующую ему.'),
(50, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 19, 'OT', 'Господь Бог образовал из земли всех животных полевых и всех птиц небесных, и привёл их к человеку, чтобы видеть, как он назовёт их; и как назовёт человек всякое живое существо, так и было имя её.'),
(51, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 20, 'OT', 'И нарек человек имена всем скотам и птицам небесным и всем зверям полевым, но для человека не нашлось помощи, подобной ему.'),
(52, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 21, 'OT', 'Господь Бог навёл глубокий сон на человека, и он уснул; и взял одно из рёбер его, и закрыл плотью место того.'),
(53, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 22, 'OT', 'И построил Господь Бог ребро, которое взял из человека, в жену, и привёл её к человеку.'),
(54, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 23, 'OT', 'И сказал человек: вот, на этот раз кость от костей моих и плоть от плоти моей; она будет называться женою, ибо от человека взята она.'),
(55, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 24, 'OT', 'Поэтому оставит человек отца своего и мать свою, и прилепится к жене своей, и будут они одной плотью.'),
(56, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 2, 25, 'OT', 'И были оба наги, человек и жена его, и не стыдились.'),
(57, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 1, 'OT', 'Змей был хитрее всех зверей полевых, которых создал Господь Бог, и сказал жене: подлинно ли сказал Бог: не ешьте ни от какого дерева в саду?'),
(58, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 2, 'OT', 'Жена сказала змею: плод дерева сада мы едим.'),
(59, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 3, 'OT', 'А от плода дерева, которое в середине сада, сказал Бог: не ешьте от него и не прикасайтесь к нему, чтобы вам не умереть.'),
(60, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 4, 'OT', 'И сказал змей жене: не смертью умрёте.'),
(61, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 5, 'OT', 'Ибо знает Бог, что в день, когда вы вкусите от него, откроются ваши очи, и вы будете как Бог, знающие добро и зло.'),
(62, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 6, 'OT', 'И увидела жена, что дерево хорошо для пищи, и что оно — желание для очей, и вожделенно дерево для уразумения, и взяла от плода его, и ела, и дала также человеку своему, который был с нею, и он ел.'),
(63, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 7, 'OT', 'И открылись глаза у обоих, и узнали они, что наги они, и сшили листья смоковницы, и сделали себе пояса.'),
(64, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 8, 'OT', 'И услышали они голос Господа Бога, ходящего в саду в прохладе дня, и скрылся человек и жена его от лица Господа Бога среди дерева сада.'),
(65, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 9, 'OT', 'И воззвал Господь Бог к человеку и сказал ему: где ты?'),
(66, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 10, 'OT', 'И сказал: голос Твой услышал я в саду, и убоялся, потому что наг я, и скрылся.'),
(67, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 11, 'OT', 'И сказал: кто сказал тебе, что ты наг? Не от дерева ли, с которого Я заповедал тебе не есть, ты ел?'),
(68, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 12, 'OT', 'И сказал человек: жена, которую Ты дал мне, она дала мне от дерева, и я ел.'),
(69, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 13, 'OT', 'И сказал Господь Бог жене: что это ты сделала? И сказала жена: змей обольстил меня, и я ела.'),
(70, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 14, 'OT', 'И сказал Господь Бог змею: за то, что ты сделал это, проклят ты более всего скота и более всех зверей полевых; на чреве твоём будешь ходить, и прах будешь есть во все дни жизни твоей.'),
(71, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 15, 'OT', 'И вражду положу между тобою и между женою, и между семенем твоим и между семенем её; оно будет поражать тебя в главу, а ты будешь поражать его в пяту.'),
(72, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 16, 'OT', 'Жене сказал: умножая умножу скорбь твою и зачатие твоё; в скорби будешь рождать сыновей; и к человеку твоему влечение твоё, и он будет господствовать над тобою.'),
(73, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 17, 'OT', 'Адаму же сказал: за то, что ты послушал голоса жены твоей и ел от дерева, о котором Я заповедал тебе, говоря: не ешь от него, проклята земля из-за тебя; в скорби будешь питаться от неё во все дни жизни твоей.'),
(74, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 18, 'OT', 'Тёрн и волчец произрастит она тебе, и будешь питаться травой полевой.'),
(75, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 19, 'OT', 'В поте лица твоего будешь есть хлеб, доколе не возвратишься в землю, ибо из неё ты взят; ибо прах ты, и в прах возвратишься.'),
(76, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 20, 'OT', 'И нарек человек имя жене своей Ева, ибо она стала матерью всего живого.'),
(77, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 21, 'OT', 'Сделал Господь Бог человеку и жене его хитоны из кожи и одел их.'),
(78, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 22, 'OT', 'И сказал Господь Бог: вот, человек стал как один из Нас, зная добро и зло; и теперь, как бы не простёр он руки своей и не взял также от дерева жизни, и не вкусил, и не стал жить вечно.'),
(79, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 23, 'OT', 'И выслал его Господь Бог из сада Едемского, чтобы возделывать землю, из которой он был взят.'),
(80, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 3, 24, 'OT', 'И изгнал человека, и поставил на востоке у сада Едемского херувимов и пламя меча обращающегося, чтобы охранять путь к дереву жизни.'),
(81, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 1, 'OT', 'И познал человек Еву, жену свою; и она зачала, и родила Каина, и сказала: приобрела я человека от Господа.'),
(82, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 2, 'OT', 'И родила она ещё брата его, Авеля. И был Авель пастухом овец, а Каин был земледельцем, обрабатывающим землю.'),
(83, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 3, 'OT', 'И было по прошествии дней: принёс Каин от плода земли дар Господу.'),
(84, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 4, 'OT', 'И Авель также принёс от первородства овец своих и от тука их; и призрел Господь на Авеля и на дар его.'),
(85, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 5, 'OT', 'А к Каину и к дару его не призрел; и сильно разгневался Каин, и поникло лицо его.'),
(86, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 6, 'OT', 'И сказал Господь Каину: почему разгневался ты, и почему поникло лицо твоё?'),
(87, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 7, 'OT', 'Разве не если будешь делать добро, возвышение (лицо будет поднято), а если не будешь делать добра, у двери грех лежит, и к тебе влечение его, и ты будешь господствовать над ним.'),
(88, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 8, 'OT', 'И сказал Каин Авелю, брату своему: пойдём в поле. И когда они были в поле, восстал Каин на Авеля, брата своего, и убил его.'),
(89, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 9, 'OT', 'И сказал Господь Каину: где Авель, брат твой? И сказал он: не знаю; разве я сторож брату моему?'),
(90, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 10, 'OT', 'И сказал: что ты сделал? Голос крови брата твоего вопиет ко Мне из земли.'),
(91, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 11, 'OT', 'И ныне проклят ты от земли, которая отверзла уста свои, чтобы принять кровь брата твоего из руки твоей.'),
(92, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 12, 'OT', 'Когда ты будешь возделывать землю, она не будет больше давать тебе свою силу; скитальцем и бродягой будешь ты на земле.'),
(93, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 13, 'OT', 'И сказал Каин Господу: велико беззаконие моё, чтобы нести его.'),
(94, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 14, 'OT', 'Вот ты изгнал меня сегодня с лица земли, и от лица твоего я скроюсь, и буду я скитальцем и бродягой на земле, и всякий, кто найдёт меня, убьёт меня.'),
(95, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 15, 'OT', 'И сказал ему Господь: за то всякому, кто убьёт Каина, отомстится семерицею. И сделал Господь Каину знамение, чтобы не поразил его всякий, кто встретит его.'),
(96, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 16, 'OT', 'И вышел Каин от лица Господня и поселился в земле Нод, к востоку от Едема.'),
(97, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 17, 'OT', 'Каин познал жену свою, и она зачала и родила Еноха; и он стал строить город, и назвал имя города по имени сына своего Еноха.'),
(98, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 18, 'OT', 'И родил Енох Ирада, и Ирад родил Мехиаеля, и Мехиаель родил Мафусаила, и Мафусаил родил Ламеха.'),
(99, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 19, 'OT', 'Взял себе Ламех двух жён: имя одной Ада, а имя второй Цилла.'),
(100, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 20, 'OT', 'Ада родила Иавала: он был отцом живущих в шатре и со скотом.'),
(101, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 21, 'OT', 'Имя брата его — Иувал: он был отцом всех играющих на гуслях и органе.'),
(102, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 22, 'OT', 'И Цилла также родила Тувалкаина, который был ковачом всякого орудия из меди и железа; и сестра Тувалкаина — Наама.'),
(103, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 23, 'OT', 'И сказал Ламех женам своим: Ада и Цилла, слушайте голос мой, жены Ламеха, внимайте слову моему: ибо я убил человека за рану мою и дитя за рану мою.'),
(104, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 24, 'OT', 'Если Каин отмстится семерицею, то Ламех — семьдесят раз и семь.'),
(105, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 25, 'OT', 'Адам познал ещё жену свою, и она родила сына, и нарекла ему имя Сиф, говоря: Бог дал мне другое семя вместо Авеля, потому что убил его Каин.'),
(106, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 4, 26, 'OT', 'И у Сифа также родился сын, и он назвал его имя Енос; тогда начали призывать имя Господа.'),
(107, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 1, 'OT', 'Вот книга родословия Адама: в день, когда Бог сотворил человека, по подобию Бога сделал его.'),
(108, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 2, 'OT', 'Мужчину и женщину сотворил их, и благословил их, и назвал имя их человек в день сотворения их.'),
(109, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 3, 'OT', 'Адам жил сто тридцать лет и родил сына по подобию своему, по образу своему, и нарек ему имя Сиф.'),
(110, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 4, 'OT', 'И было дней Адама после рождения им Сифа восемьсот лет, и родил он сынов и дочерей.'),
(111, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 5, 'OT', 'Все дни Адама, которые он жил, были девятьсот тридцать лет, и он умер.'),
(112, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 6, 'OT', 'Сиф жил сто пять лет и родил Еноса.'),
(113, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 7, 'OT', 'И жил Сиф после рождения Еноса семь лет и восемьсот лет, и родил сыновей и дочерей.'),
(114, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 8, 'OT', 'И было всех дней Сифа двести двенадцать лет и девятьсот лет, и он умер.'),
(115, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 9, 'OT', 'Енос жил девяносто лет и родил Каинана.'),
(116, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 10, 'OT', 'И жил Енос после рождения Каинана пятнадцать лет и восемьсот лет, и родил сыновей и дочерей.'),
(117, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 11, 'OT', 'И было всех дней Еноса девятьсот пять лет; и он умер.'),
(118, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 12, 'OT', 'Каинан жил семьдесят лет и родил Малелеила.'),
(119, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 13, 'OT', 'И жил Каинан после рождения Малелеила сорок лет и восемьсот лет, и родил сыновей и дочерей.'),
(120, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 14, 'OT', 'И было всех дней Каинана десять лет и девятьсот лет, и он умер.'),
(121, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 15, 'OT', 'Малелеил жил шестьдесят пять лет и родил Иареда.'),
(122, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 16, 'OT', 'И жил Малелеил после рождения Иареда тридцать лет и восемьсот лет, и родил сыновей и дочерей.'),
(123, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 17, 'OT', 'И было всех дней Малелеила пятьсот девяносто пять лет, и он умер.'),
(124, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 18, 'OT', 'И жил Иаред сто шестьдесят два года и родил Еноха.'),
(125, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 19, 'OT', 'И жил Иаред после рождения им Еноха восемьсот лет, и родил сыновей и дочерей.'),
(126, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 20, 'OT', 'И было всех дней Иареда: две и шестьдесят лет и девятьсот лет; и он умер.'),
(127, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 21, 'OT', 'Енох жил шестьдесят пять лет и родил Мафусала.'),
(128, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 22, 'OT', 'И ходил Енох пред Богом, после того как родил Мафусала, триста лет, и родил сыновей и дочерей.'),
(129, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 23, 'OT', 'И было всех дней Еноха: пять и шестьдесят лет и триста лет.'),
(130, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 24, 'OT', 'И ходил Енох с Богом; и не стало его, потому что Бог взял его.'),
(131, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 25, 'OT', 'И жил Мафусал сто восемьдесят семь лет и родил Ламеха.'),
(132, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 26, 'OT', 'И жил Мафусал после рождения Ламеха семьсот восемьдесят два года и родил сыновей и дочерей.'),
(133, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 27, 'OT', 'И было всех дней Мафусала девятьсот шестьдесят девять лет, и он умер.'),
(134, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 28, 'OT', 'И жил Ламех сто восемьдесят два года и родил сына.'),
(135, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 29, 'OT', 'И нарек ему имя Ной, говоря: этот утешит нас в деле нашем и в скорби рук наших от земли, которую проклял Господь.'),
(136, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 30, 'OT', 'И жил Ламех после рождения Ноя девяносто пять лет и пятьсот лет, и родил сыновей и дочерей.'),
(137, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 31, 'OT', 'И было всех дней Ламеха семьсот семьдесят семь лет, и он умер.'),
(138, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 5, 32, 'OT', 'И было Ною пятьсот лет, и родил Ной Сима, Хама и Иафета.'),
(139, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 1, 'OT', 'И было, когда начал человек умножаться на лице земли, и дочери родились у них.'),
(140, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 2, 'OT', 'Сыны Бога увидели дочерей человеческих, что они хороши, и взяли себе жён из всех, которых выбрали.'),
(141, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 3, 'OT', 'И сказал Господь: не будет дух Мой пребывать в человеке вечно, потому что он плоть; и будут дни его сто двадцать лет.'),
(142, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 4, 'OT', 'Исполины были на земле в те дни, и также после того, как сыны Бога приходили к дочерям человеческим, и они рождали им: это сильные, которые издревле, люди имени.'),
(143, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 5, 'OT', 'И увидел Господь, что велико зло человека на земле, и весь образ замыслов сердца его — только зло во все дни.'),
(144, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 6, 'OT', 'И раскаялся Господь, что создал человека на земле, и опечалился в сердце Своём.'),
(145, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 7, 'OT', 'И сказал Господь: истреблю человека, которого Я сотворил, с лица земли, от человека до скота, до пресмыкающегося и до птицы небесной, ибо Я раскаялся, что создал их.'),
(146, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 8, 'OT', 'Ной обрёл благодать в очах Господа.'),
(147, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 9, 'OT', 'Вот родословие Ноя: Ной был человек праведный и непорочный в роде своём; с Богом ходил Ной.'),
(148, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 10, 'OT', 'Ной родил трёх сыновей: Сима, Хама и Иафета.'),
(149, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 11, 'OT', 'И развратилась земля пред лицом Бога, и наполнилась земля насилием.'),
(150, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 12, 'OT', 'И увидел Бог землю, и вот, она растлилась, ибо всякая плоть извратила путь свой на земле.'),
(151, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 13, 'OT', 'И сказал Бог Ною: конец всякой плоти пришёл пред лицо Моё, ибо земля наполнилась насилием от лица их; и вот, Я истреблю их с землёю.'),
(152, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 14, 'OT', 'Сделай себе ковчег из дерева гофер; гнезда сделай в ковчеге, и покрой его изнутри дома и снаружи выкупом.'),
(153, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 15, 'OT', 'И вот как сделаешь её: триста локтей долгота ковчега, пятьдесят локтей ширина его, и тридцать локтей рост его.'),
(154, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 16, 'OT', 'Сделай полдень для ковчега, и в локоть заверши его сверху, и дверь ковчега помести сбоку его; нижние, вторые и третьи сделай его.'),
(155, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 17, 'OT', 'И вот, Я навожу потоп, воду на землю, чтобы истребить всякую плоть, в которой есть дух жизни, из-под неба; всё, что на земле, умрёт.'),
(156, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 18, 'OT', 'И восставлю Я завет Мой с тобою, и войдёшь в ковчег ты, и сыновья твои, и жена твоя, и жёны сыновей твоих с тобою.'),
(157, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 19, 'OT', 'И из всего живого, из всякой плоти, по два из всего введи в ковчег, чтобы сохранить жизнь с тобою; мужчина и женщина пусть будут.'),
(158, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 20, 'OT', 'От птиц по роду их, и от скота по роду его, от всех пресмыкающихся земли по роду их, по два из всех войдут к тебе, чтобы сохранить им жизнь.'),
(159, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 21, 'OT', 'И возьми себе из всей пищи, которую едят, и собери её к себе; и будет она тебе и им для пищи.'),
(160, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 6, 22, 'OT', 'И сделал Ной всё, что повелел ему Бог, так и сделал.'),
(161, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 1, 'OT', 'Сказал Господь Ною: войди ты и весь дом твой в ковчег, ибо тебя Я увидел праведным пред лицом Моим в этом роде.'),
(162, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 2, 'OT', 'Из всего скота чистого возьми себе по семь, человека и жену его, а из скота, который нечист, по два, человека и жену его.'),
(163, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 3, 'OT', 'Также из птиц небесных по семь, самца и самку, чтобы сохранить семя на лице всей земли.'),
(164, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 4, 'OT', 'Ибо ещё через семь дней Я пролью дождь на землю сорок дней и сорок ночей, и истреблю все существа, которые Я создал, с лица земли.'),
(165, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 5, 'OT', 'И сделал Ной всё, что повелел ему Господь.'),
(166, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 6, 'OT', 'Ной был сыном шестисот лет, и потоп был вода на земле.'),
(167, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 7, 'OT', 'И вошёл Ной, и сыновья его, и жена его, и жёны сыновей его с ним в ковчег от лица вод потопа.'),
(168, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 8, 'OT', 'из скота чистого и из скота нечистого, и из птиц, и всё, что пресмыкается по земле'),
(169, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 9, 'OT', 'По два, по два приходили к Ною в ковчег, самец и женщина, как повелел Бог Ною.'),
(170, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 10, 'OT', 'И было по прошествии семи дней, и воды потопа были на земле.'),
(171, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 11, 'OT', 'В шестьсотый год жизни Ноя, во второй месяц, в семнадцатый день месяца, в этот день разверзлись все источники великой бездны, и окна небесные открылись.'),
(172, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 12, 'OT', 'И был дождь на земле сорок дней и сорок ночей.'),
(173, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 13, 'OT', 'В самый этот день вошёл Ной, и Сим, и Хам, и Иафет, сыновья Ноя, и жена Ноя, и три жены сыновей его с ними в ковчег.'),
(174, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 14, 'OT', 'Они и всё животное по роду своему, и весь скот по роду своему, и всё пресмыкающееся, пресмыкающееся по земле, по роду своему, и вся птица по роду своему, всё, что с крыльями, всякая птица.'),
(175, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 15, 'OT', 'И пришли к Ною в ковчег по два от всякой плоти, в которой есть дух жизни.'),
(176, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 16, 'OT', 'И входившие, самец и женщина, от всякой плоти, вошли, как повелел ему Бог; и затворил Господь за ним.'),
(177, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 17, 'OT', 'И был потоп сорок дней на земле, и умножились воды, и подняли ковчег, и он возвысился над землёю.'),
(178, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 18, 'OT', 'И усилилась вода и весьма умножилась на земле, и ковчег плавал по лицу воды.'),
(179, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 19, 'OT', 'И воды чрезвычайно усилились на земле, и покрылись все высокие горы, которые под всем небом.'),
(180, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 20, 'OT', 'Пятнадцать локтей сверху поднялась вода, и покрылись горы.'),
(181, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 21, 'OT', 'И погибла всякая плоть, движущаяся по земле: из птиц, и из скота, и из зверей, и из всех гадов, ползающих по земле, и все люди.'),
(182, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 22, 'OT', 'Всё, что имело дыхание духа жизни в ноздрях своих, из всего, что на суше, умерло.'),
(183, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 23, 'OT', 'И истребил Он всё существа, которое на лице земли, от человека до скота, до пресмыкающегося и до птицы небесной, и истребились они с земли; и остался только Ной и то, что с ним в ковчеге.'),
(184, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 7, 24, 'OT', 'И вода усиливалась на земле сто пятьдесят дней.'),
(185, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 1, 'OT', 'И вспомнил Бог о Ное и о всех животных и о всём скоте, который был с ним в ковчеге, и провёл Бог ветер над землёю, и утихли воды.'),
(186, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 2, 'OT', 'И закрылись источники бездны и окна неба, и перестал дождь с неба.'),
(187, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 3, 'OT', 'И возвращались воды с земли, отходя и приходя, и убывали воды по истечении ста пятидесяти дней.'),
(188, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 4, 'OT', 'И остановился ковчег в седьмом месяце, в семнадцатый день месяца, на горах Арарата.'),
(189, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 5, 'OT', 'И вода продолжала убывать до десятого месяца; в первый день десятого месяца показались главы гор.'),
(190, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 6, 'OT', 'И было по прошествии сорока дней, и открыл Ной окно ковчега, которое он сделал.'),
(191, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 7, 'OT', 'И выпустил ворона, и он вылетал и возвращался, пока не высохла вода на земле.'),
(192, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 8, 'OT', 'И выпустил голубя от себя, чтобы увидеть, убыла ли вода с лица земли.'),
(193, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 9, 'OT', 'И не нашла голубка покоя для подошвы ноги своей, и возвратилась к нему в ковчег, ибо вода была на лице всей земли; и простёр он руку свою, и взял её, и внёс её к себе в ковчег.'),
(194, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 10, 'OT', 'И подождал ещё семь других дней, и снова послал голубя из ковчега.'),
(195, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 11, 'OT', 'И голубь пришёл к нему во время вечера, и вот, свежий лист маслины в устах его; и узнал Ной, что вода убыла с земли.'),
(196, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 12, 'OT', 'И подождал ещё семь других дней, и выпустил голубя, и он не возвратился к нему более.'),
(197, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 13, 'OT', 'И было в шестьсот первом году, в первый день первого месяца, высохла вода с поверхности земли; и снял Ной покрывало с ковчега, и увидел, и вот, высохло лицо земли.'),
(198, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 14, 'OT', 'И во втором месяце, в двадцать седьмой день месяца, высохла земля.'),
(199, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 15, 'OT', 'И сказал Бог Ною, говоря:'),
(200, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 16, 'OT', 'Выйди из ковчега, ты и жена твоя, и сыновья твои, и жёны сыновей твоих с тобою.'),
(201, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 17, 'OT', 'Выведи с собою всех зверей, что с тобою, из всякой плоти: из птиц, и из скота, и из всех пресмыкающихся, ползающих по земле, — пусть они кишат на земле, и плодятся, и размножаются на земле.'),
(202, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 18, 'OT', 'И вышел Ной, и сыновья его, и жена его, и жёны сыновей его с ним.'),
(203, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 19, 'OT', 'Всё звери, всё пресмыкающееся и все птицы, всё, что движется по земле, по семействам их, вышли из ковчега.'),
(204, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 20, 'OT', 'И построил Ной жертвенник Господу, и взял из всего скота чистого и из всей птицы чистой, и вознёс всесожжения на жертвеннике.'),
(205, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 21, 'OT', 'И ощутил Господь запах приятного благоухания, и сказал Господь в сердце Своём: не буду более проклинать землю ради человека, ибо образ сердца человеческого — зло от юности его, и не буду более поражать всё живое, как Я сделал.'),
(206, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 8, 22, 'OT', 'Всё время, пока существует земля, семя и жатва, холод и зной, лето и зима, день и ночь не прекратятся.'),
(207, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 1, 'OT', 'И благословил Бог Ноя и сыновей его, и сказал им: плодитесь и размножайтесь, и наполняйте землю.'),
(208, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 2, 'OT', 'И ужас ваш и трепет пред вами да будет на всяком звере земном и на всякой птице небесной, во всём, что движется по земле, и во всех рыбах морских: в руки ваши они отданы.'),
(209, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 3, 'OT', 'Всё пресмыкающееся, которое живо, будет вам в пищу; как зелень травы, дал Я вам всё.'),
(210, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 4, 'OT', 'Только плоти с жизнью её, кровью её, не ешьте.'),
(211, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 5, 'OT', 'И взыщу вашу кровь за ваши жизни: от руки всякого живого существа взыщу её, и от руки человека, от руки каждого человека за брата его взыщу жизнь человека.'),
(212, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 6, 'OT', 'Кто прольёт кровь человека, того кровь прольётся человеком, ибо по образу Бога Он создал человека.'),
(213, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 7, 'OT', 'Вы же плодитесь и размножайтесь, кишите на земле и размножайтесь на ней.'),
(214, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 8, 'OT', 'И сказал Бог Ною и сыновьям его с ним, говоря:'),
(215, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 9, 'OT', 'И вот, Я устанавливаю завет Мой с вами и с семенем вашим после вас.'),
(216, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 10, 'OT', 'И со всяким существом живым, которое с вами, из птиц, из скота и из всего зверя земли с вами, из всех выходящих из ковчега, для всякого зверя земли.'),
(217, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 11, 'OT', 'И поставлю завет Мой с вами, и не будет истреблена всякая плоть водами потопа, и не будет уже потопа на погибель земли.'),
(218, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 12, 'OT', 'И сказал Бог: вот знамение завета, который Я даю между Мною и между вами, и между всяким существом живым, которое с вами, в роды вечности.'),
(219, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 13, 'OT', 'Лук Мой Я дал в облаке, и будет он знамением завета между Мною и землёю.'),
(220, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 14, 'OT', 'И будет, когда Я наведу облако на землю, и явится лук в облаке.'),
(221, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 15, 'OT', 'И вспомню Я завет Мой, который между Мною и между вами, и между всяким существом живым во всякой плоти; и не будет более вода потопом на истребление всякой плоти.'),
(222, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 16, 'OT', 'И будет лук в облаке, и увижу его, чтобы помнить завет вечности между Богом и между всякою душою живою во всякой плоти, которая на земле.'),
(223, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 17, 'OT', 'И сказал Бог Ною: вот знамение завета, который Я поставил между Мною и между всякою плотью, которая на земле.'),
(224, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 18, 'OT', 'Сыновья Ноя, вышедшие из ковчега, были Сим, Хам и Иафет; и Хам был отцом Ханаана.'),
(225, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 19, 'OT', 'Эти трое — сыновья Ноя, и от них распространилось всё по земле.'),
(226, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 20, 'OT', 'И начал Ной, человек земли, и насадил виноградник.'),
(227, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 21, 'OT', 'И пил он от вина и опьянел, и обнажился в середине шатра своего.'),
(228, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 22, 'OT', 'Хам, отец Ханаана, увидел наготу отца своего, и рассказал двум братьям своим на улице.'),
(229, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 23, 'OT', 'Сим и Иафет взяли одежду, и положили её на плечи обоих своих, и пошли задом наперёд, и покрыли наготу отца своего; и лица их были обращены назад, и наготы отца своего они не видели.'),
(230, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 24, 'OT', 'Ной пробудился от вина своего, и узнал, что сделал ему младший сын его.'),
(231, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 25, 'OT', 'И сказал он: проклят Ханаан; рабом рабов будет он у братьев своих.'),
(232, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 26, 'OT', 'Сказал он: благословен Господь, Бог Сима, и да будет Ханаан рабом ему.'),
(233, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 27, 'OT', 'Да распространит Бог Иафета, и да вселится он в шатрах Сима; и да будет Ханаан рабом ему.'),
(234, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 28, 'OT', 'И жил Ной после потопа триста пятьдесят лет.'),
(235, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 9, 29, 'OT', 'И было всех дней Ноя девятьсот пятьдесят лет, и он умер.'),
(236, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 1, 'OT', 'И вот родословие сыновей Ноя: Сима, Хама и Иафета; и родились у них сыновья после потопа.'),
(237, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 2, 'OT', 'Сыновья Иафета: Гомер, Магог, Мидия, Иаван, Фувал, Мешех и Фиррас.'),
(238, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 3, 'OT', 'Сыновья Гомера: Ашкеназ, Рифат и Фогарма.'),
(239, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 4, 'OT', 'Сыновья Иавана: Елиса и Фарсис, Киттим и Доданим.'),
(240, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 5, 'OT', 'От этих отделились прибрежные земли народов в землях их, каждый человек по языку своему, по семействам их, в народах их.'),
(241, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 6, 'OT', 'Сыновья Хама: Ефиопия, Египет, Фут и Ханаан.'),
(242, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 7, 'OT', 'Сыновья Ефиопии: Себа, и Хавила, и Савта, и Рама, и Савтеха; и сыновья Рамы: Сава и Дедан.'),
(243, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 8, 'OT', 'Ефиопия родила Нимрода; он начал быть сильным на земле.'),
(244, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 9, 'OT', 'Он был могучим ловцом пред лицом Господа; потому и говорится: как Нимрод, могучий ловец пред лицом Господа.'),
(245, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 10, 'OT', 'Началом его царства были Вавилон, Ерех, Аккад и Калне в земле Сеннаар.'),
(246, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 11, 'OT', 'Из той земли вышел Ассирия и построил Ниневию, и Реховоф-город, и Келах.'),
(247, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 12, 'OT', 'И Ресен между Ниневиею и между Келахом; это город великий.'),
(248, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 13, 'OT', 'Египет родил Лидийцев, и Анамим, и Легавим, и Нафтухим.'),
(249, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 14, 'OT', 'и Патрусим, и Каслухим, от которых произошли Филистимляне, и Кафторим.'),
(250, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 15, 'OT', 'Ханаан родил Сидона, первенца своего, и Хета.'),
(251, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 16, 'OT', 'Иевусеев, и Аморрея, и Гергесеев'),
(252, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 17, 'OT', 'и Евеев, и Аркитов, и Синитов'),
(253, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 18, 'OT', 'И Арвадитянина, и Земаритянина, и хаматянина; а после рассеялись семейства Хананеянина.'),
(254, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 19, 'OT', 'И была граница Хананеянина от Сидона к Герару до Газы, идущая к Содому и Гоморре, и Адме, и Цевоиму, до Леши.'),
(255, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 20, 'OT', 'Это сыны Хама по семействам их, по языкам их, в землях их, в народах их.'),
(256, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 21, 'OT', 'И у Сима родился также сын, он отец всех сынов Евера, брат Иафета старшего.'),
(257, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 22, 'OT', 'Сыновья Сима: Елам, и Ассирия, и Арфаксад, и Луд, и Сирия.'),
(258, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 23, 'OT', 'Сыновья Сирии: Уц, Хул, Гетер и Маш.'),
(259, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 24, 'OT', 'Арфаксад родил Салу, и Сала родил Евера.'),
(260, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 25, 'OT', 'И у Евера родились два сына: имя одному Фалек, потому что во дни его разделилась земля, и имя брату его Иоктан.'),
(261, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 26, 'OT', 'Иоктан родил Алмодада, и Шелефа, и Хазармавефа, и Иераха.'),
(262, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 27, 'OT', 'Адорама, и Узала, и Диклу'),
(263, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 28, 'OT', 'И Овала, и Авимаила, и Саву.'),
(264, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 29, 'OT', 'И Офира, и Хавилу, и Иовава; все эти — сыны Иоктана.'),
(265, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 30, 'OT', 'И было жилище их от Меши, доходя до Сефара, гора востока.'),
(266, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 31, 'OT', 'Вот сыны Сима по семействам их, по языкам их, в землях их, по народам их.'),
(267, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 10, 32, 'OT', 'Вот эти семейства сынов Ноя по их родословиям, в их народах, и от них разделились народы по земле после потопа.'),
(268, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 1, 'OT', 'И была вся земля одним языком и одними словами.'),
(269, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 2, 'OT', 'И было, когда они двинулись с востока, они нашли долину в земле Сеннаар и поселились там.'),
(270, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 3, 'OT', 'И сказали человек ближнему своему: давайте сделаем кирпичи и обожжём их сожжением; и стал у них кирпич вместо камня, а смола была у них вместо глины.'),
(271, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 4, 'OT', 'И сказали они: давайте построим себе город и башню, и вершина её до неба, и сделаем себе имя, чтобы не рассеяться по лицу всей земли.'),
(272, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 5, 'OT', 'И сошёл Господь посмотреть на город и на башню, которую построили сыны человеческие.'),
(273, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 6, 'OT', 'И сказал Господь: вот, народ один, и язык один у всех, и это они начали делать; и теперь не будет для них невозможного, что бы они ни замыслили сделать.'),
(274, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 7, 'OT', 'Давайте сойдём и смешаем там язык их, чтобы не слышал человек язык ближнего своего.'),
(275, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 8, 'OT', 'И рассеял Господь их оттуда по лицу всей земли, и они перестали строить город.'),
(276, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 9, 'OT', 'Потому дано ему имя Вавилон, ибо там смешал Господь язык всей земли, и оттуда рассеял их Господь по лицу всей земли.'),
(277, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 10, 'OT', 'Вот родословие Сима: Сим был сыном ста лет и родил Арфаксада через два года после потопа.'),
(278, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 11, 'OT', 'И жил Сим после рождения Арфаксада пятьсот лет и родил сыновей и дочерей.'),
(279, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 12, 'OT', 'Арфаксад жил тридцать пять лет и родил Салу.'),
(280, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 13, 'OT', 'И жил Арфаксад после рождения Салы три года и четыреста лет, и родил сыновей и дочерей.'),
(281, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 14, 'OT', 'Сала жил тридцать лет и родил Евера.'),
(282, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 15, 'OT', 'И жил Сала после рождения Евера триста тридцать лет и родил сыновей и дочерей.'),
(283, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 16, 'OT', 'Евер жил тридцать четыре года и родил Фалека.'),
(284, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 17, 'OT', 'И жил Евер после рождения Фалека тридцать лет и четыреста лет, и родил сыновей и дочерей.'),
(285, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 18, 'OT', 'И жил Фалек тридцать лет и родил Рагава.'),
(286, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 19, 'OT', 'И жил Фалек после того, как родил Рагава, двести девять лет и родил сыновей и дочерей.'),
(287, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 20, 'OT', 'Рагав жил тридцать два года и родил Серуха.'),
(288, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 21, 'OT', 'Рагав жил после рождения Серуха двести семь лет и родил сыновей и дочерей.'),
(289, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 22, 'OT', 'Серух жил тридцать лет и родил Нахора.'),
(290, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 23, 'OT', 'И жил Серух после рождения Нахора двести лет и родил сыновей и дочерей.'),
(291, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 24, 'OT', 'Нахор жил двадцать девять лет и родил Фарру.'),
(292, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 25, 'OT', 'Жил Нахор после рождения Фарры сто девятнадцать лет и родил сыновей и дочерей.'),
(293, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 26, 'OT', 'Фарра жил семьдесят лет и родил Аврама, Нахора и Харрана.'),
(294, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 27, 'OT', 'И вот родословие Фарры: Фарра родил Аврама, Нахора и Харрана, а Харран родил Лота.'),
(295, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 28, 'OT', 'И умер Харран при лице Фарры, отца своего, в земле родины своей, в Уре Халдеев.'),
(296, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 29, 'OT', 'И взял Аврам и Нахор себе жён; имя жены Аврама — Сарай, а имя жены Нахора — Милка, дочь Харрана, отца Милки и отца Иски.'),
(297, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 30, 'OT', 'Сарай была бесплодна; не было у неё дитя.'),
(298, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 31, 'OT', 'И взял Фарра Аврама, сына своего, и Лота, сына Харрана, сына сына своего, и Сарай, невестку свою, жену Аврама, сына своего; и вышли они с ними из Ура Халдейского, чтобы идти в землю Ханаанскую; и дошли до Харана, и поселились там.'),
(299, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 11, 32, 'OT', 'И было дней Фарры двести пять лет, и умер Фарра в Харане.'),
(300, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 1, 'OT', 'И сказал Господь Авраму: пойди из земли твоей, и с родины твоей, и из дома отца твоего, в землю, которую Я укажу тебе.'),
(301, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 2, 'OT', 'И сделаю тебя народом великим, и благословлю тебя, и возвеличу имя твоё; и будь благословением.'),
(302, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 3, 'OT', 'И благословлю благословляющих тебя, и проклинающего тебя прокляну; и благословятся в тебе все семейства земли.'),
(303, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 4, 'OT', 'И пошёл Аврам, как сказал ему Господь, и пошёл с ним Лот; и Аврам был сыном семидесяти пяти лет, когда вышел из Харана.'),
(304, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 5, 'OT', 'Аврам взял Сарай, жену свою, и Лота, сына брата своего, и всё имущество их, которое они приобрели, и людей, которых они сделали в Харане, и вышли, чтобы идти в землю Ханаанскую, и пришли в землю Ханаанскую.'),
(305, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 6, 'OT', 'И прошёл Аврам по земле до места Сихема, до дуба Море; и Хананеянин тогда был в земле.'),
(306, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 7, 'OT', 'Господь явился Авраму и сказал: семени твоему дам Я эту землю. И он построил там жертвенник Господу, Который явился ему.'),
(307, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 8, 'OT', 'И двинулся он оттуда на гору, к востоку от Вефиля, и раскинул шатёр свой: Вефиль с запада, а Гай с востока; и соорудил там жертвенник Господу, и призвал имя Господа.'),
(308, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 9, 'OT', 'И двинулся Аврам, идя и продвигаясь к югу.'),
(309, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 10, 'OT', 'И был голод на земле, и сошёл Аврам в Египет, чтобы пожить там, ибо тяжёл был голод на земле.'),
(310, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 11, 'OT', 'И было, когда он приблизился к входу в Египет, он сказал Саре, жене своей: вот, я знаю, что ты жена, прекрасная видом.'),
(311, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 12, 'OT', 'И будет, когда увидят тебя Египтяне, и скажут: «это жена его», — и убьют меня, а тебя оставят в живых.'),
(312, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 13, 'OT', 'Скажи же, что ты сестра моя, чтобы ради тебя мне было хорошо, и жива была душа моя ради тебя.'),
(313, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 14, 'OT', 'И было, когда пришёл Аврам в Египет, и увидели египтяне жену, что она очень красива.'),
(314, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 15, 'OT', 'И увидели её князья фараона и восхвалили её перед фараоном, и взята была жена в дом фараона.'),
(315, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 16, 'OT', 'И Авраму он оказал добро ради неё; и были у него овцы и крупный рогатый скот, и ослы, и рабы, и служанки, и ослицы, и верблюды.'),
(316, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 17, 'OT', 'И поразил Господь фараона великими язвами и дом его за слово Сары, жены Аврама.'),
(317, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 18, 'OT', 'Фараон призвал Аврама и сказал: что это ты сделал мне? Почему не объявил мне, что она — твоя жена?'),
(318, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 19, 'OT', 'Зачем ты сказал: «она моя сестра», и я взял её себе в жёны? А теперь вот твоя жена — возьми и иди.'),
(319, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 12, 20, 'OT', 'И дал фараон повеление о нём людям, и проводили его и жену его, и всё, что у него было.'),
(320, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 1, 'OT', 'Аврам поднялся из Египта, он и жена его, и всё, что у него было, и Лот с ним, на юг.'),
(321, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 2, 'OT', 'Аврам был очень богат скотом, серебром и золотом.'),
(322, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 3, 'OT', 'И пошёл он по путям своим от юга до Вефиля, до того места, где был шатёр его в начале, между Вефилем и Гаем.'),
(323, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 4, 'OT', 'к месту жертвенника, который он сделал там вначале, и призвал там Аврам имя Господа.'),
(324, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 5, 'OT', 'И также у Лота, который ходил с Аврамом, были овцы и крупный рогатый скот, и шатёр.'),
(325, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 6, 'OT', 'И не вмещала их земля, чтобы жить вместе, ибо имущество их было велико, и не могли они жить вместе.'),
(326, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 7, 'OT', 'И была тяжба между пастухами скота Аврама и пастухами скота Лота; и Хананеянин и Ферезеи тогда жили в земле.'),
(327, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 8, 'OT', 'Аврам сказал Лоту: пусть не будет Меривы между мною и тобою, и между пастухами моими и пастухами твоими, ибо мы люди, братья.'),
(328, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 9, 'OT', 'Вот не вся ли земля пред лицом твоим? Отделись же от меня: если на левую сторону, то я направо, а если на правую руку, то я налево.'),
(329, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 10, 'OT', 'Лот поднял око своё и увидел всю равнину Иордана, что весь он — орошаемый, прежде чем Господь истребил Содом и Гоморру, как сад Господень, как земля Египетская, до прихода в Цоар.'),
(330, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 11, 'OT', 'И выбрал Лот себе всю равнину Иордана, и двинулся Лот с востока, и отделились человек от брата своего.'),
(331, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 12, 'OT', 'Аврам жил в земле Ханаанской, а Лот жил в городах равнины и раскинул шатры до Содома.'),
(332, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 13, 'OT', 'Люди же Содома были злы и грешны пред Господом весьма.'),
(333, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 14, 'OT', 'Господь сказал Авраму после того, как Лот отделился от него: подними ныне очи твои и посмотри с места, где ты находишься, на север, и на юг, и на восток, и на запад.'),
(334, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 15, 'OT', 'Ибо всю землю, которую ты видишь, тебе дам Я и семени твоему до вечности.'),
(335, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 16, 'OT', 'И сделаю семя твоё как прах земли; если сможет человек сосчитать прах земли, то и семя твоё сочтётся.'),
(336, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 17, 'OT', 'Встань, пройди по земле в долготу её и в ширину её, ибо тебе Я дам её.'),
(337, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 13, 18, 'OT', 'И раскинул шатёр Аврам, и пришёл, и поселился у дубов Мамаре, что в Хевроне, и построил там жертвенник Господу.'),
(338, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 1, 'OT', 'И было во дни Амрафела, царя Сеннаара, Ариоха, царя Елласара, Кедорлаомера, царя Елама, и Фидала, царя народов.'),
(339, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 2, 'OT', 'Они вели войну против Беры, царя Содома, и против Вирши, царя Гоморры, Шинава, царя Адмы, и Шемевера, царя Цевоима, и царя Валы, которая есть Цоар.'),
(340, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 3, 'OT', 'Все эти соединились в долине Сиддим, это море соли.'),
(341, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 4, 'OT', 'Двенадцать лет служили они Кедорлаомеру, а в тринадцатый год восстали.'),
(342, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 5, 'OT', 'В четырнадцатый же год пришёл Кедорлаомер и цари, которые были с ним, и поразили исполинов в Аштероф-Карнаиме, и Зузимов в Хаме, и Емимов в Шаве-Кириафаиме.'),
(343, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 6, 'OT', 'и Хорреев на горе их Сеир, до Ел-Парана, что при пустыне.'),
(344, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 7, 'OT', 'И возвратились они и пришли к Ен-Мишпату, который есть Кадес, и поразили всё поле Амаликитянина, и также Аморрея, живущего в Хацацон-Фамаре.'),
(345, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 8, 'OT', 'Вышел царь Содома и царь Гоморры, и царь Адмы, и царь Цевоима, и царь Валы, она же Цоар, и выстроились с ними к войне в долине Сиддим.'),
(346, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 9, 'OT', 'Кедорлаомера, царя Еламского, и Фидала, царя народов, и Амрафела, царя Сеннаарского, и Ариоха, царя Елласарского, — четыре царя против пяти.'),
(347, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 10, 'OT', 'Долина же Сиддим была полна смоляных колодезей, и цари Содома и Гоморры побежали и упали туда, а оставшиеся убежали в гору.'),
(348, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 11, 'OT', 'И взяли всё имущество Содома и Гоморры и всю пищу их, и ушли.'),
(349, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 12, 'OT', 'И взяли Лота и имущество его, сына брата Аврама, и ушли; а он жил в Содоме.'),
(350, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 13, 'OT', 'И пришёл беглец и рассказал Авраму Еврею; а он жил в дубраве Мамаре Аморрея, брата Ешкола и брата Анера, и они были союзниками завета Аврама.'),
(351, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 14, 'OT', 'Услышал Аврам, что пленён брат его, и вооружил обученных своих, рождённых в доме его, восемнадцать и триста, и погнался до Дана.'),
(352, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 15, 'OT', 'И разделился он против них ночью, он и рабы его, и поразил их, и преследовал их до Ховы, что с левой стороны от Дамаска.'),
(353, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 16, 'OT', 'И возвратил всё имущество, и также Лота, брата своего, и имущество его возвратил, и также жён и народ.'),
(354, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 17, 'OT', 'И вышел царь Содома навстречу ему после того, как он возвратился от поражения Кедорлаомера и царей, которые были с ним, в долину Шаве, что есть долина царя.'),
(355, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 18, 'OT', 'И Мелхиседек, царь Салима, вынес хлеб и вино; и он был священником Бога Всевышнего.'),
(356, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 19, 'OT', 'И благословил он его и сказал: благословен Аврам у Бога Всевышнего, Владыки неба и земли.'),
(357, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 20, 'OT', 'И благословен Бог Всевышний, Который предал врагов твоих в руку твою. И дал ему десятину из всего.'),
(358, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 21, 'OT', 'Царь Содома сказал Авраму: отдай мне души, а имущество возьми себе.'),
(359, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 22, 'OT', 'И сказал Аврам царю Содома: поднял я руку мою к Господу, Богу Всевышнему, Творцу неба и земли.'),
(360, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 23, 'OT', 'Если нить, и даже ремень обуви, и если я возьму из всего, что твоё, чтобы ты не сказал: я обогатил Аврама.'),
(361, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 14, 24, 'OT', 'Кроме меня, только то, что съели отроки, и часть людей, которые ходили со мною: Анер, Ешкол и Мамаре — они возьмут свою часть.'),
(362, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 1, 'OT', 'После этих событий было слово Господа к Авраму в видении, говорящее: не бойся, Аврам; Я — щит твой, плата твоя весьма велика.'),
(363, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 2, 'OT', 'И сказал Аврам: Господь Бог, что Ты дашь мне, а я хожу бездетным, и сын дома моего — он домоправитель мой, Дамаск Елиезер.'),
(364, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 3, 'OT', 'И сказал Аврам: вот, мне Ты не дал семени, и вот, сын дома моего — наследник мой.'),
(365, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 4, 'OT', 'И вот слово Господа было к нему: не наследует тебе этот, но тот, кто выйдет из чрева твоего, он наследует тебе.'),
(366, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 5, 'OT', 'И вывел его наружу, на улицу, и сказал: посмотри на небо и сосчитай звёзды, если можешь сосчитать их; и сказал ему: так будет семя твоё.'),
(367, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 6, 'OT', 'И он поверил Господу, и Он вменил ему это в праведность.'),
(368, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 7, 'OT', 'И сказал ему: Я Господь, Который вывел тебя из Ура Халдейского, чтобы дать тебе эту землю во владение.'),
(369, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 8, 'OT', 'Господь Бог, по чему мне узнать, что я наследуют её?'),
(370, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 9, 'OT', 'И сказал ему: возьми Мне тёлку трёхлетнюю, и козу трёхлетнюю, и овна трёхлетнего, и горлицу, и птенца.'),
(371, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 10, 'OT', 'Он взял себе всех этих животных, рассек их посредине, и положил каждый человек свою часть напротив своего ближнего; но птицу не рассек.'),
(372, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 11, 'OT', 'И спустилась хищная птица на трупы, и отогнал их Аврам.'),
(373, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 12, 'OT', 'Солнце клонилось к закату, и глубокий сон напал на Аврама; и вот, ужас и тьма великая напали на него.'),
(374, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 13, 'OT', 'И сказал Авраму: знай, что пришельцем будет семя твоё в земле, которая не их, и поработит их, и будут угнетать их четыреста лет.'),
(375, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 14, 'OT', 'И народ, которому они будут служить, Я буду судить; и после того они выйдут с большим имуществом.'),
(376, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 15, 'OT', 'А ты отойдёшь к отцам твоим в мире, будешь погребён в доброй седине.'),
(377, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 16, 'OT', 'И четвёртый род возвратится сюда, ибо не завершилось беззаконие Аморрея доныне.'),
(378, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 17, 'OT', 'Солнце зашло, и наступила тьма; и вот, печь дыма и факел огня, который прошёл между этими частями.'),
(379, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 18, 'OT', 'В тот день заключил Господь с Аврамом завет, говоря: потомству твоему дал Я эту землю, от реки Египетской до великой реки, реки Евфрат.'),
(380, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 19, 'OT', 'Кенеев, и Кенезеев, и Кадмонитов'),
(381, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 20, 'OT', 'и Хеттеянина, и Ферезеев, и исполинов'),
(382, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 15, 21, 'OT', 'и Аморрея, и Хананеянина, и Гергесеев, и Иевусеев'),
(383, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 1, 'OT', 'Сарай, жена Аврама, не рождала ему; и была у неё служанка-египтянка, и имя её Агарь.'),
(384, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 2, 'OT', 'Сарай сказала Авраму: вот, Господь заключил меня от рождения, войди же к служанке моей; может быть, я устроюсь от неё. И послушал Аврам голоса Сарай.'),
(385, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 3, 'OT', 'Сарай, жена Аврама, взяла Агарь, Египтянку, служанку свою, по прошествии десяти лет, как Аврам жил в земле Ханаанской, и дала её Авраму, мужу своему, ему в жёны.'),
(386, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 4, 'OT', 'И вошёл он к Агари, и она зачала; и когда она увидела, что зачала, госпожа её стала презренна в очах её.'),
(387, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 5, 'OT', 'Сарай сказала Авраму: обида моя на тебе; я дала служанку мою в недро твоё, и она увидела, что зачала, и я стала презренна в очах её; пусть Господь рассудит между мною и между тобою.'),
(388, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 6, 'OT', 'Аврам сказал Саре: вот, служанка твоя в руке твоей; делай с нею то, что хорошо в очах твоих. И притесняла её Сарай, и она убежала от лица её.'),
(389, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 7, 'OT', 'Нашёл её ангел Господень у источника воды в пустыне, у источника на пути в Сур.'),
(390, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 8, 'OT', 'И сказал: Агарь, служанка Сары, откуда ты пришла и куда идёшь? И она сказала: от лица Сары, госпожи моей, я бегу.'),
(391, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 9, 'OT', 'И сказал ей ангел Господень: возвратись к госпоже твоей и смирись под рукою её.'),
(392, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 10, 'OT', 'Ангел Господень сказал ей: умножая умножу семя твоё, и не будет оно сочтено от множества.'),
(393, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 11, 'OT', 'Ангел Господень сказал ей: вот, ты беременна и родишь сына, и наречёшь ему имя Измаил, ибо Господь услышал бедствие твоё.'),
(394, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 12, 'OT', 'Он будет диким ослом среди людей; рука его — против всего, и рука всего — против него; и пред лицом всех братьев своих он будет жить.'),
(395, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 13, 'OT', 'И назвала она имя Господа, говорившего с нею: Ты — Бог зрелища, ибо сказала: неужели и здесь я видела после видящего меня?'),
(396, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 14, 'OT', 'Посему он назвал колодезь Беэр-лахай-рои; вот, он между Кадесом и между Вереда.'),
(397, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 15, 'OT', 'Агарь родила Авраму сына, и нарек Аврам имя сыну своему, которого родила Агарь, Измаил.'),
(398, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 16, 16, 'OT', 'Аврам был сыном восьмидесяти шести лет, когда Агарь родила Измаила Авраму.'),
(399, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 1, 'OT', 'Аврам был сыном девяноста лет и девяти лет, и явился Господь Авраму и сказал ему: Я Бог Вседержитель; ходи пред лицом Моим и будь непорочен.'),
(400, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 2, 'OT', 'И заключу завет Мой между Мною и тобою, и весьма, весьма размножу тебя.'),
(401, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 3, 'OT', 'И пал Аврам на лицо своё, и говорил с ним Бог, говоря:'),
(402, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 4, 'OT', 'Я, вот завет Мой с тобою, и будешь ты отцом множества народов.'),
(403, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 5, 'OT', 'И не будет более называться имя твоё Аврам, но будет имя твоё Авраам, ибо отцом множества народов Я сделал тебя.'),
(404, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 6, 'OT', 'И сделаю тебя весьма, весьма плодовитым, и произведу от тебя народы, и цари произойдут от тебя.'),
(405, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 7, 'OT', 'И поставлю завет Мой между Мною и тобою и между семенем твоим после тебя в роды их, заветом вечным, чтобы быть Мне Богом для тебя и для семени твоего после тебя.'),
(406, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 8, 'OT', 'И дам тебе и семени твоему после тебя землю странствий твоих, всю землю Ханаан, во владение вечное; и буду им Богом.'),
(407, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 9, 'OT', 'И сказал Бог Аврааму: и ты соблюдай завет Мой, ты и семя твоё после тебя в роды их.'),
(408, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 10, 'OT', 'Вот завет Мой, который вы должны соблюдать между Мною и между вами и между семенем твоим после тебя: да будет обрезан у вас всякий мужской пол.'),
(409, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 11, 'OT', 'Обрежьте крайнюю плоть вашу, и это будет знамением завета между Мною и вами.'),
(410, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 12, 'OT', 'Сын восьми дней да будет обрезан у вас всякий мужского пола в роды ваши, рождённый в доме и купленный за серебро у всякого сына чужого, который не от семени твоего.'),
(411, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 13, 'OT', 'Да будет обрезан рождённый в доме твоём и купленный за серебро твоё, и будет завет Мой в плоти вашей заветом вечности.'),
(412, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 14, 'OT', 'А необрезанный мужчина, который не обрежет плоть крайней плоти своей, — истребится душа та из народа своего: завет Мой он нарушил.'),
(413, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 15, 'OT', 'И сказал Бог Аврааму: жену твою Сарай не называй именем её Сарай, ибо Сарра имя её.'),
(414, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 16, 'OT', 'И благословлю её, и дам тебе от неё сына; и благословлю её, и будет она народами; цари народов произойдут от неё.'),
(415, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 17, 'OT', 'И пал Авраам на лицо своё и рассмеялся, и сказал в сердце своём: родится ли сын у ста лет, и Сарра, в возрасте девяноста лет, родит ли?'),
(416, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 18, 'OT', 'И сказал Авраам Богу: о, если бы Измаил жил пред лицом Твоим!'),
(417, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 19, 'OT', 'И сказал Бог: но Сарра, жена твоя, родит тебе сына, и наречёшь ему имя Исаак; и поставлю завет Мой с ним заветом вечным для семени его после него.'),
(418, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 20, 'OT', 'И об Измаиле Я услышал тебя: вот, Я благословил его, и сделаю его плодовитым, и весьма, весьма умножу его; двенадцать князей родит он, и сделаю его великим народом.'),
(419, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 21, 'OT', 'И завет Мой поставлю с Исааком, которого родит тебе Сарра к назначенному сроку в следующем году.'),
(420, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 22, 'OT', 'И окончил Он говорить с ним, и поднялся Бог от Авраама.'),
(421, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 23, 'OT', 'Взял Авраам Измаила, сына своего, и всех рождённых в доме своём, и всех купленных за серебро своё, всех мужского пола из людей дома Авраама, и обрезал плоть крайней плоти их в самый кость дня этого, как говорил с ним Бог.'),
(422, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 24, 'OT', 'Авраам был сыном девяноста девяти лет, когда была обрезана плоть крайней плоти его.'),
(423, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 25, 'OT', 'Измаил, сын его, был тринадцати лет, когда была обрезана плоть крайней плоти его.'),
(424, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 26, 'OT', 'В самый кость этого дня был обрезан Авраам, и Измаил, сын его.'),
(425, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 17, 27, 'OT', 'И все люди дома его, рождённые в доме и купленные за серебро у сына чужого, были обрезаны с ним.'),
(426, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 1, 'OT', 'Господь явился ему у дубов Мамаре, когда он сидел у двери шатра в зной дня.'),
(427, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 2, 'OT', 'Он поднял свои очи и увидел: вот три человека стоят напротив него. Увидев, он побежал навстречу им от входа в шатёр и поклонился до земли.'),
(428, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 3, 'OT', 'И сказал: Господин мой! Если я обрёл благодать в очах твоих, не пройди мимо раба твоего.'),
(429, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 4, 'OT', 'Пусть принесут немного воды, и омойте ваши ноги, и отдохните под деревом.'),
(430, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 5, 'OT', 'И я принесу кусок хлеба, и подкрепите сердце ваше, после пойдёте, ибо для того вы и прошли мимо раба вашего. И сказали они: так сделай, как ты сказал.'),
(431, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 6, 'OT', 'И поспешил Авраам в шатёр к Сарре и сказал: поспеши, три меры муки лучшей замеси и сделай лепёшки.'),
(432, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 7, 'OT', 'И побежал Авраам к крупному рогатому скоту, и взял сына крупного рогатого скота, нежного и хорошего, и дал отроку, и поспешил приготовить его.'),
(433, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 8, 'OT', 'Он взял масло и молоко и сына крупного рогатого скота, которого приготовил, и поставил перед ними, а сам стоял подле них под деревом, и они ели.'),
(434, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 9, 'OT', 'И сказали они ему: где Сарра, жена твоя? И сказал он: вот, в шатре.'),
(435, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 10, 'OT', 'Сказал: возвращаясь, возвращусь я к тебе в это же время, и вот сын у Сарры, жены твоей; и Сарра слушала у двери шатра, а он был позади него.'),
(436, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 11, 'OT', 'Авраам и Сарра были стары, вошли в дни; прекратился у Сарры путь, как у жён.'),
(437, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 12, 'OT', 'Сарра рассмеялась внутри себя, говоря: после того как я изнемогла, было ли мне наслаждение? И господин мой стар.'),
(438, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 13, 'OT', 'И сказал Господь Аврааму: почему это рассмеялась Сарра, говоря: неужели я действительно рожу, когда я состарилась?'),
(439, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 14, 'OT', 'Разве не возможно для Господа слово? В назначенный срок возвращусь я к тебе в это же время, и у Сарры будет сын.'),
(440, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 15, 'OT', 'Сарра же отреклась, сказав: я не смеялась, ибо испугалась. Но Он сказал: нет, ты смеялась.'),
(441, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 16, 'OT', 'Встали оттуда те люди, и посмотрели на лицо Содома; и Авраам шёл с ними, чтобы проводить их.'),
(442, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 17, 'OT', 'И сказал Господь: утаю ли Я от Авраама, что делаю?'),
(443, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 18, 'OT', 'Авраам же будет народом великим и сильным, и благословятся в нём все народы земли.'),
(444, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 19, 'OT', 'Ибо Я избрал его, чтобы он заповедал сыновьям своим и дому своему после себя соблюдать путь Господа, творя праведность и суд, дабы Господь навёл на Авраама то, что сказал о нём.'),
(445, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 20, 'OT', 'И сказал Господь: вопль Содома и Гоморры, ибо он велик, и грех их, ибо он тяжёл весьма.'),
(446, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 21, 'OT', 'Сойду и посмотрю, точно ли вопль её, дошедший до Меня, совершили до конца; а если нет, узнаю.'),
(447, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 22, 'OT', 'И повернули те люди оттуда и пошли в Содом; а Авраам ещё стоял пред лицом Господа.'),
(448, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 23, 'OT', 'И подошёл Авраам и сказал: неужели Ты погубишь праведника вместе с нечестивым?'),
(449, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 24, 'OT', 'Может быть, есть пятьдесят праведников в середине города; неужели Ты погубишь и не пощадишь место ради пятидесяти праведников, которые в нём?'),
(450, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 25, 'OT', 'Да не будет Тебе, чтобы сделать такое слово, чтобы умертвить праведного с нечестивым, и чтобы было праведному как нечестивому! Да не будет Тебе! Судья всей земли не совершит ли суда?'),
(451, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 26, 'OT', 'И сказал Господь: если найду в Содоме пятьдесят праведников в середине города, то прощу всё место ради них.'),
(452, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 27, 'OT', 'И ответил Авраам и сказал: вот, я решился говорить к Господу, хотя я прах и пепел.'),
(453, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 28, 'OT', 'Может быть, недостанет пятидесяти праведников пяти, неужели Ты погубишь за пять весь город? И сказал он: не погублю, если найду там сорок пять.'),
(454, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 29, 'OT', 'И продолжал он говорить с Ним и сказал: может быть, найдётся там сорок; и сказал Он: не сделаю ради сорока.'),
(455, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 30, 'OT', 'Да не прогневается Господь, и я скажу: может быть, найдётся там тридцать? И сказал: не сделаю, если найду там тридцать.'),
(456, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 31, 'OT', 'И сказал он: вот, я решился говорить Господу моему; может быть, найдётся там двадцать. И сказал Он: не истреблю ради двадцати.'),
(457, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 32, 'OT', 'Да не прогневается Господь, и я скажу ещё раз: может быть, найдётся там десять? И сказал Он: не истреблю ради десяти.'),
(458, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 18, 33, 'OT', 'И пошёл Господь, когда окончил говорить с Авраамом; и Авраам возвратился на место своё.'),
(459, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 1, 'OT', 'И пришли два ангела в Содом вечером, и Лот сидел у ворот Содома; и увидел Лот, и встал навстречу им, и поклонился лицом до земли.'),
(460, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 2, 'OT', 'Он сказал: вот, господин мой, зайдите, пожалуйста, в дом раба вашего и ночуйте, и омойте ноги ваши, и встанете рано и пойдёте путём вашим. Но они сказали: нет, мы будем ночевать на площади.'),
(461, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 3, 'OT', 'И он сильно упрашивал их, и они свернули к нему, и вошли в дом его; и он сделал им пир, и опресноки испёк, и они ели.'),
(462, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 4, 'OT', 'Ещё не легли они спать, как люди города, люди Содома, окружили дом, от отрока и до старца, весь народ с края.'),
(463, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 5, 'OT', 'И воззвали к Лоту и сказали ему: где люди, которые пришли к тебе ночью? Выведи их к нам, и мы познаем их.'),
(464, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 6, 'OT', 'И вышел к ним Лот к двери, и дверь закрыл за собою.'),
(465, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 7, 'OT', 'Не делайте зла, братья мои, прошу вас.'),
(466, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 8, 'OT', 'Вот, есть у меня две дочери, которые не знали человека; выведу их к вам, и делайте с ними, что хорошо в очах ваших; только этим людям не делайте слова, ибо для того они вошли под тень балки моей.'),
(467, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 9, 'OT', 'И сказали они: отойди дальше. И сказали: этот один пришёл жить, и он судит судом? Теперь мы сделаем тебе хуже, чем им. И они сильно налегли на человека, на Лота, и приблизились, чтобы сломать дверь.'),
(468, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 10, 'OT', 'И протянули те люди руки свои, и ввели Лота к себе в дом, и дверь заперли.'),
(469, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 11, 'OT', 'И людей, которые были у двери дома, поразили слепотой, от малого до большого, и они изнемогли, ища дверь.'),
(470, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 12, 'OT', 'И сказали те люди Лоту: ещё кто у тебя здесь? зять, и сыновья твои, и дочери твои, и всё, что у тебя в городе, выведи из места сего.'),
(471, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 13, 'OT', 'Ибо мы истребляем это место, потому что велик вопль их пред лицом Господа, и послал нас Господь истребить его.'),
(472, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 14, 'OT', 'Лот вышел и говорил с зятьями своих дочерей, и сказал: встаньте, выйдите из этого места, ибо Господь истребляет город. И был он как шутящий в глазах зятьёв своих.'),
(473, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 15, 'OT', 'И когда взошёл рассвет, ангелы торопили Лота, говоря: встань, возьми жену твою и двух дочерей твоих, которые находятся здесь, чтобы не погибнуть тебе в беззаконии города.'),
(474, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 16, 'OT', 'И он медлил, и взяли те люди за руку его и за руку жены его и за руку двух дочерей его, по милости Господа к нему, и вывели его, и оставили его вне города на улице.'),
(475, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 17, 'OT', 'И было, когда вывели их наружу на улицу, он сказал: спасай свою душу, не оглядывайся назад и не останавливайся нигде во всей равнине; спасайся на гору, чтобы не погибнуть.'),
(476, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 18, 'OT', 'Лот сказал им: нет, Господь!'),
(477, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 19, 'OT', 'Вот, раб твой нашёл благодать в глазах твоих, и ты умножил милость твою, которую оказал мне, чтобы сохранить жизнь душе моей; но я не могу бежать на гору, чтобы не постигло меня зло, и я не умер.'),
(478, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 20, 'OT', 'Вот этот город близок, чтобы убежать туда, и он малый; спасусь я там — не малый ли он? и будет жива душа моя.'),
(479, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 21, 'OT', 'И сказал ему: вот, я уважил лицо твоё и в этом слове, чтобы не разрушить город, о котором ты говорил.'),
(480, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 22, 'OT', 'Спеши спастись туда, ибо я не могу сделать слово, пока ты не придёшь туда; поэтому названо имя города Цоар.'),
(481, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 23, 'OT', 'Солнце взошло над землёю, и Лот пришёл в Цоар.'),
(482, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 24, 'OT', 'И Господь пролил на Содом и на Гоморру серу и огонь от Господа с неба.'),
(483, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 25, 'OT', 'И ниспроверг Он города те, и всю равнину, и всех жителей городов, и отрасль земли.'),
(484, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 26, 'OT', 'Жена его оглянулась позади него и стала соляным гарнизоном.'),
(485, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 27, 'OT', 'Встал Авраам рано утром на место, где стоял пред лицом Господа.'),
(486, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 28, 'OT', 'И он взглянул на лицо Содома и Гоморры и на всё лицо земли равнины, и увидел: вот, поднимается дым земли, как дым печи.'),
(487, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 29, 'OT', 'И было, когда Бог разрушал города равнины, вспомнил Бог об Аврааме и выслал Лота из середины ниспровержения, когда ниспровергал города, в которых жил Лот.'),
(488, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 30, 'OT', 'Лот поднялся из Цоара и поселился на горе, и две его дочери с ним, ибо он боялся жить в Цоаре; и поселился в пещере, он и две его дочери.'),
(489, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 31, 'OT', 'Первенец сказал младшей: отец наш стар, и человека нет на земле, чтобы войти к нам по пути всей земли.'),
(490, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 32, 'OT', 'Пойдём, напоим отца нашего вином, и ляжем с ним, и сохраним от отца нашего семя.'),
(491, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 33, 'OT', 'И они напоили отца своего вином в ту ночь, и вошла первенец, и легла с отцом своим, и он не знал, когда она легла и когда встала.'),
(492, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 34, 'OT', 'И было на следующий день, сказала первенец младшей: вот, я спала прошлой ночью с отцом моим; напоим его вином и в эту ночь, и войди, ложись с ним, и сохраним от отца нашего семя.'),
(493, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 35, 'OT', 'И они напоили также в ту ночь отца своего вином, и встала младшая, и легла с ним, и он не знал, когда она легла и когда встала.'),
(494, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 36, 'OT', 'И забеременели обе дочери Лота от отца своего.'),
(495, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 37, 'OT', 'Первенец родила сына и нарекла ему имя Моав; он отец Моава до сего дня.'),
(496, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 19, 38, 'OT', 'И младшая также родила сына, и нарекла ему имя Вен-Амми; он отец сынов Аммона до сего дня.'),
(497, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 1, 'OT', 'И двинулся оттуда Авраам в землю южную, и поселился между Кадесом и между Суром, и жил в Гераре.'),
(498, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 2, 'OT', 'И сказал Авраам о Сарре, жене своей: она сестра моя. И послал Авимелех, царь Герара, и взял Сарру.'),
(499, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 3, 'OT', 'И пришёл Бог к Авимелеху во сне ночью и сказал ему: вот, ты умрёшь из-за жены, которую ты взял, а она имеет господина.'),
(500, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 4, 'OT', 'Авимелех не приближался к ней, и сказал: Господь, неужели народ, даже праведный, Ты убьёшь?'),
(501, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 5, 'OT', 'Разве не он сказал мне: «она — моя сестра», и она сама сказала: «он — мой брат»? В целостности сердца моего и в невинности рук моих я сделал это.'),
(502, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 6, 'OT', 'И сказал ему Бог во сне: и Я знаю, что в целостности сердца твоего ты сделал это, и Я также удержал тебя от греха предо Мною; поэтому Я не дал тебе прикоснуться к ней.'),
(503, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 7, 'OT', 'И теперь возврати жену человека, ибо он пророк, и он помолится о тебе, и ты будешь жив; а если не возвращаешь, знай, что смертью умрёшь ты и всё, что у тебя.'),
(504, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 8, 'OT', 'Авимелех встал рано утром и призвал всех рабов своих, и пересказал все эти слова в уши их; и очень испугались те люди.'),
(505, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 9, 'OT', 'Авимелех позвал Авраама и сказал ему: что ты сделал нам, и чем я согрешил против тебя, что ты навёл на меня и на царство моё великий грех? Дела, которых не должно делать, ты сделал со мною.'),
(506, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 10, 'OT', 'И сказал Авимелех Аврааму: что ты увидел, что сделал это слово?'),
(507, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 11, 'OT', 'Авраам сказал: потому что я сказал: только нет страха Божьего на этом месте, и убьют меня за слово жены моей.'),
(508, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 12, 'OT', 'И также поистине она сестра моя, дочь отца моего, но не дочь матери моей, и стала она мне женой.'),
(509, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 13, 'OT', 'И было, когда Бог увёл меня из дома отца моего, я сказал ей: вот милость твоя, которую ты окажешь мне: во всякое место, куда мы придём, говори обо мне: он брат мой.'),
(510, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 14, 'OT', 'Авимелех взял овец и крупный рогатый скот, и рабов, и служанок, и дал Аврааму, и возвратил ему Сарру, жену его.'),
(511, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 15, 'OT', 'И сказал Авимелех: вот, земля моя пред лицом твоим; где хорошо в очах твоих, живи.'),
(512, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 16, 'OT', 'И Сарре сказал: вот, я дал тысячу денег брату твоему; вот, оно для тебя покрывалом для очей для всех, кто с тобою, и для всего, и она оправдана.'),
(513, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 17, 'OT', 'И помолился Авраам Богу, и исцелил Бог Авимелеха, и жену его, и служанок его, и они родили.'),
(514, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 20, 18, 'OT', 'Ибо Господь заключил всякую матку в доме Авимелеха из-за слова Сарры, жены Авраама.'),
(515, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 1, 'OT', 'Господь посетил Сарру, как сказал, и сделал Господь Сарре, как говорил.'),
(516, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 2, 'OT', 'Сарра зачала и родила Аврааму сына в старости его, в назначенное время, о котором говорил ей Бог.'),
(517, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 3, 'OT', 'Авраам нарек имя сыну своему, рождённому ему, которого родила ему Сарра, Исаак.'),
(518, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 4, 'OT', 'И обрезал Авраам Исаака, сына своего, в восьмой день, как повелел ему Бог.'),
(519, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 5, 'OT', 'Авраам был сыном ста лет, когда родился у него Исаак, сын его.'),
(520, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 6, 'OT', 'Сарра сказала: насмешку сделал мне Бог; всякий, кто услышит, будет смеяться надо мною.'),
(521, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 7, 'OT', 'И сказала она: кто бы сказал Аврааму, что Сарра будет кормить грудью сыновей? Ибо я родила сына в старости его.'),
(522, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 8, 'OT', 'Дитя выросло и было отнято от груди; и устроил Авраам большой пир в день, когда отнимали от груди Исаака.'),
(523, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 9, 'OT', 'Сарра увидела сына Агари Египтянки, которого та родила Аврааму, смеющимся.'),
(524, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 10, 'OT', 'И сказала Аврааму: прогони эту служанку и сына её, ибо не наследует сын этой служанки с сыном моим, с Исааком.'),
(525, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 11, 'OT', 'И было это слово весьма тягостно в очах Авраама ради сына его.'),
(526, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 12, 'OT', 'И сказал Бог Аврааму: не будет это злом в очах твоих из-за отрока и из-за служанки твоей; всё, что скажет тебе Сарра, слушай голоса её, ибо в Исааке назовётся тебе семя.'),
(527, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 13, 'OT', 'И также сына служанки Я сделаю народом, потому что он — семя твоё.'),
(528, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 14, 'OT', 'Встал Авраам рано утром, взял хлеб и мех с водой, и дал Агари, положив на плечо её, и дитя, и отпустил её. И пошла она, и блуждала в пустыне Вирсавии.'),
(529, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 15, 'OT', 'Иссякла вода из меха, и она бросила дитя под одним из кустов.'),
(530, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 16, 'OT', 'И пошла она, и села напротив, вдали, на расстоянии выстрела из лука, ибо сказала: «Не хочу видеть смерть дитяти». И села напротив, и подняла свой голос, и заплакала.'),
(531, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 17, 'OT', 'И услышал Бог голос отрока, и воззвал ангел Божий к Агари с неба, и сказал ей: что тебе, Агарь? Не бойся, ибо услышал Бог голос отрока там, где он находится.'),
(532, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 18, 'OT', 'Встань, возьми отрока и держи его за руку, ибо Я сделаю его великим народом.'),
(533, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 19, 'OT', 'И открыл Бог око её, и она увидела колодезь с водою, и пошла, и наполнила мех водою, и напоила отрока.'),
(534, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 20, 'OT', 'Бог был с отроком, и он вырос, и жил в пустыне, и стал лучником.'),
(535, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 21, 'OT', 'И жил он в пустыне Фаран, и взяла ему мать его жену из земли Египетской.'),
(536, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 22, 'OT', 'И было в то время, Авимелех и Фихол, военачальник войска его, сказали Аврааму: Бог с тобою во всём, что ты делаешь.'),
(537, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 23, 'OT', 'И ныне поклянись мне Богом, что не солжёшь мне, ни потомку моему, ни внуку моему; по милости, которую я оказал тебе, ты сделаешь со мною и с землёю, в которой ты жил.'),
(538, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 24, 'OT', 'И сказал Авраам: я клянусь.'),
(539, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 25, 'OT', 'Авраам упрекал Авимелеха ради колодезя с водою, который отняли рабы Авимелеха.'),
(540, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 26, 'OT', 'Авимелех сказал: не знал я, кто сделал это слово, и ты не известил меня, и я не слышал до сего дня.'),
(541, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 27, 'OT', 'Взял Авраам овец и крупный рогатый скот, и дал Авимелеху, и заключили они оба завет.'),
(542, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 28, 'OT', 'И поставил Авраам семь овец из стада отдельно.'),
(543, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 29, 'OT', 'Авимелех сказал Аврааму: что это за семь овец, которых ты поставил отдельно?'),
(544, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 30, 'OT', 'Он сказал: потому что семь овец ты возьмёшь из руки моей, ради того, чтобы это было мне свидетельством, что я выкопал этот колодезь.'),
(545, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 31, 'OT', 'Поэтому он назвал то место Вирсавия, потому что там оба они поклялись.'),
(546, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 32, 'OT', 'И заключили завет в Вирсавии, и встал Авимелех, и Фихол, военачальник войска его, и возвратились в землю Филистимлян.'),
(547, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 33, 'OT', 'И посадил тамариск в Вирсавии, и призвал там имя Господа, Бога вечности.'),
(548, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 21, 34, 'OT', 'И жил Авраам в земле Филистимлян много дней.'),
(549, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 1, 'OT', 'И было после этих слов, и Бог испытал Авраама, и сказал ему: Авраам! И он сказал: вот я.'),
(550, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 2, 'OT', 'Возьми сына твоего, единственного твоего, которого ты любишь, Исаака, и пойди в землю Мориа, и принеси его там во всесожжение на одной из гор, о которой Я скажу тебе.'),
(551, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 3, 'OT', 'Встал Авраам рано утром, оседлал осла своего, взял с собою двух отроков своих и Исаака, сына своего, и наколол дров для всесожжения, и встал, и пошёл на место, о котором сказал ему Бог.'),
(552, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 4, 'OT', 'На третий день Авраам поднял свои очи и увидел то место издалека.'),
(553, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 5, 'OT', 'Авраам сказал отрокам своим: останьтесь здесь с ослом, а я и отрок пойдём до того места, и поклонимся, и возвратимся к вам.'),
(554, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 6, 'OT', 'Авраам взял дерево для всесожжения и возложил на Исаака, сына своего, и взял в руку свою огонь и нож, и пошли оба вместе.'),
(555, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 7, 'OT', 'И сказал Исаак Аврааму, отцу своему, и сказал: отец мой! И он сказал: вот я, сын мой. И сказал: вот огонь и дерево, а где овца для всесожжения?'),
(556, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 8, 'OT', 'Авраам сказал: Бог усмотрит Себе овцу для всесожжения, сын мой. И пошли оба вместе.'),
(557, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 9, 'OT', 'И пришли они к месту, о котором сказал ему Бог, и построил там Авраам жертвенник, и разложил дерево, и связал Исаака, сына своего, и положил его на жертвенник поверх дерева.'),
(558, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 10, 'OT', 'И простёр Авраам руку свою, и взял нож, чтобы заколоть сына своего.'),
(559, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 11, 'OT', 'И воззвал к нему ангел Господень с неба и сказал: Авраам! Авраам! И он сказал: вот я.'),
(560, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 12, 'OT', 'Не протягивай руки твоей к отроку и не делай ему ничего, ибо теперь Я знаю, что ты боишься Бога и не пожалел сына твоего, единственного твоего, для Меня.'),
(561, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 13, 'OT', 'И поднял Авраам очи свои, и увидел: вот, овен, запутавшийся рогами своими в чаще, позади; и пошёл Авраам, и взял овна, и вознёс его во всесожжение вместо сына своего.'),
(562, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 14, 'OT', 'И нарек Авраам имя месту тому Господь усмотрит, как говорится и в сей день: на горе Господней усмотрится.'),
(563, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 15, 'OT', 'И воззвал ангел Господень к Аврааму вторично с неба.'),
(564, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 16, 'OT', 'И сказал: Мною клянусь, изречение Господа: за то, что ты сделал это слово и не пощадил сына твоего, единственного твоего,'),
(565, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 17, 'OT', 'Ибо благословляя благословлю тебя и умножу семя твоё, как звёзды небесные и как песок, который на берегу моря; и овладеет семя твоё воротами врагов своих.'),
(566, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 18, 'OT', 'И благословятся в семени твоём все народы земли, за то, что ты послушался голоса Моего.'),
(567, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 19, 'OT', 'И возвратился Авраам к отрокам своим, и встали они, и пошли вместе к Вирсавии; и жил Авраам в Вирсавии.'),
(568, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 20, 'OT', 'И было после этих слов, возвещено было Аврааму, говоря: вот, Милка также родила сыновей Нахору, брату твоему.'),
(569, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 21, 'OT', 'Уца, первенца его, и Буза, брата его, и Кемуила, отца Сирии.'),
(570, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 22, 'OT', 'и Хеседа, и Азо, и Филдаша, и Идлафа, и Вефуила.'),
(571, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 23, 'OT', 'Вефуил родил Ревекку; восемь этих родила Милка Нахору, брату Авраама.'),
(572, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 22, 24, 'OT', 'И наложница его, имя ей Реума, также родила Февана, и Гахама, и Фаха, и Мааху.'),
(573, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 1, 'OT', 'И было жизни Сарры сто лет и двадцать лет и семь лет; годы жизни Сарры.'),
(574, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 2, 'OT', 'Умерла Сарра в Кириаф-Арбе, это Хеврон, в земле Ханаанской; и пришёл Авраам оплакивать Сарру и плакать о ней.'),
(575, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 3, 'OT', 'И встал Авраам с лица умершего своего, и говорил к сынам Хета, говоря:'),
(576, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 4, 'OT', 'Я пришелец и поселенец среди вас; дайте мне владение для гроба среди вас, и я похороню моего умершего.'),
(577, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 5, 'OT', 'Сыновья Хета ответили Аврааму, говоря ему:'),
(578, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 6, 'OT', 'Выслушай нас, господин мой: ты князь Божий среди нас; в избранном из наших гробов похорони твоего мертвеца; ни один человек из нас не удержит от тебя своего гроба, чтобы похоронить твоего мертвеца.'),
(579, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 7, 'OT', 'И встал Авраам, и поклонился народу земли, сынам Хета.'),
(580, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 8, 'OT', 'И говорил он с ними, говоря: если вы согласны похоронить моего умершего, послушайте меня и вступитесь за меня пред Ефроном, сыном Цохара.'),
(581, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 9, 'OT', 'И пусть он даст мне пещеру Махпелу, которая у него, которая на краю поля его; за полное серебро пусть отдаст её мне среди вас во владение для гроба.'),
(582, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 10, 'OT', 'Ефрон же сидел среди сынов Хета; и отвечал Ефрон Хеттеянин Аврааму в уши сынов Хета, всем входящим в ворота города его, говоря:'),
(583, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 11, 'OT', 'Нет, господин мой, послушай меня: поле я даю тебе, и пещеру, которая в нём, тебе даю её; пред очами сынов народа моего даю её тебе, похорони умершего твоего.'),
(584, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 12, 'OT', 'И поклонился Авраам лицом перед народом земли.'),
(585, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 13, 'OT', 'И сказал он Ефрону в уши народа земли, говоря: если же ты, послушай меня, я даю серебро за поле, возьми от меня, и я похороню там моего мертвеца.'),
(586, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 14, 'OT', 'И ответил Ефрон Аврааму, говоря ему:'),
(587, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 15, 'OT', 'Господин мой, послушай меня: земля в четыреста сиклей серебра, между мною и тобою, что это? И умершего твоего похорони.'),
(588, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 16, 'OT', 'И послушал Авраам Ефрона, и отвесил Авраам Ефрону серебро, которое он назвал в уши сыновей Хета: четыреста сиклей серебра, ходящего у купца.'),
(589, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 17, 'OT', 'И утвердилось поле Ефрона, которое в Махпеле, что перед лицом Мамаре, поле и пещера, которая в нём, и все дерево, которое на поле, во всех границах его, вокруг.'),
(590, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 18, 'OT', 'Аврааму в куплю пред очами сынов Хета, пред всеми входящими в ворота города его.'),
(591, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 19, 'OT', 'И после того погреб Авраам Сарру, жену свою, в пещере поля Махпела, напротив Мамаре, то есть Хеврона, в земле Ханаанской.'),
(592, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 23, 20, 'OT', 'И стало поле и пещера, которая в нём, владением Авраама для гроба, от сынов Хета.'),
(593, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 1, 'OT', 'Авраам был стар, вошёл в дни, и Господь благословил Авраама во всём.'),
(594, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 2, 'OT', 'И сказал Авраам рабу своему, старейшине дома своего, владеющему всем, что у него: положи, пожалуйста, руку твою под бедро моё.'),
(595, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 3, 'OT', 'и закляну тебя Господом, Богом неба и Богом земли, что ты не возьмёшь жену сыну моему из дочерей Хананеянина, среди которого я живу.'),
(596, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 4, 'OT', 'но к земле моей и к родине моей пойдёшь, и возьмёшь жену сыну моему Исааку.'),
(597, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 5, 'OT', 'И сказал ему раб: может быть, не захочет жена идти за мною в эту землю; возвратить ли мне сына твоего в землю, из которой ты вышел?'),
(598, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 6, 'OT', 'И сказал ему Авраам: берегись, чтобы не возвратил ты сына моего туда.'),
(599, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 7, 'OT', 'Господь, Бог неба, Который взял меня из дома отца моего и из земли рождения моего, и Который говорил мне, и Который клялся мне, говоря: «Семени твоему дам Я эту землю», — Он пошлёт ангела Своего пред лицом твоим, и возьмёшь жену сыну моему оттуда.'),
(600, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 8, 'OT', 'А если не захочет жена идти за тобою, то ты будешь свободен от этой клятвы моей; только сына моего не возвращай туда.'),
(601, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 9, 'OT', 'И положил раб руку свою под бедро Авраама, господина своего, и поклялся ему в этом слове.'),
(602, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 10, 'OT', 'И взял раб десять верблюдов из верблюдов господина своего, и пошёл, и всё лучшее господина своего в руке его; и встал, и пошёл в Месопотамию, в город Нахора.'),
(603, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 11, 'OT', 'Он опустил верблюдов на колени вне города, у колодезя с водой, во время вечера, во время, когда выходят черпающие воду.'),
(604, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 12, 'OT', 'И сказал: Господь, Бог господина моего Авраама, пошли мне навстречу сегодня, и сотвори милость с господином моим Авраамом.'),
(605, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 13, 'OT', 'Вот я стою у источника воды, и дочери людей города выходят черпать воду.'),
(606, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 14, 'OT', 'И будет: девица, которой я скажу: «наклони кувшин твой, и я напьюсь», и она скажет: «пей, и верблюдам твоим я дам пить», — та, которую Ты назначил рабу Твоему Исааку; и по ней я узнаю, что Ты сотворил милость с господином моим.'),
(607, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 15, 'OT', 'И было: он ещё не кончил говорить, и вот, Ревекка выходит, которая родилась у Вефуила, сына Милки, жены Нахора, брата Авраама, и кувшин её на плече её.'),
(608, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 16, 'OT', 'Девица была очень хороша видом, дева, которую не познал человек; она спустилась к источнику, наполнила кувшин свой и поднялась.'),
(609, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 17, 'OT', 'И побежал раб навстречу ей, и сказал: дай мне немного воды из твоего кувшина.'),
(610, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 18, 'OT', 'Она сказала: пей, господин мой, и поспешно опустила свой кувшин на руку свою, и напоила его.'),
(611, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 19, 'OT', 'И когда она напоила его, сказала: также и для верблюдов твоих я буду черпать, пока они не напьются.'),
(612, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 20, 'OT', 'И поспешила она, и опорожнила кувшин свой в корыто, и побежала опять к колодезю черпать, и начерпала для всех верблюдов его.'),
(613, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 21, 'OT', 'И человек смотрел на неё, молча, чтобы узнать, благословил ли Господь путь его или нет.'),
(614, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 22, 'OT', 'И было, когда верблюды кончили пить, взял человек золотое кольцо, полсикля весом его, и два запястья на руки её, десять золота весом их.'),
(615, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 23, 'OT', 'Чья ты дочь? Скажи мне, пожалуйста; есть ли в доме отца твоего место для нас переночевать?'),
(616, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 24, 'OT', 'Она сказала ему: я дочь Вефуила, сына Милки, которого она родила Нахору.'),
(617, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 25, 'OT', 'И сказала ему: и соломы, и корма много у нас, и место для ночлега.'),
(618, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 26, 'OT', 'И поклонился человек и пал ниц пред Господом.'),
(619, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 27, 'OT', 'Благословен Господь, Бог господина моего Авраама, Который не оставил милости Своей и истины Своей от господина моего; я на пути, Господь вёл меня к дому братьев господина моего.'),
(620, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 28, 'OT', 'Побежала девица и рассказала в доме матери своей о словах этих.'),
(621, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 29, 'OT', 'И у Ревекки был брат, имя его Лаван; и побежал Лаван к человеку на улицу, к источнику.'),
(622, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 30, 'OT', 'И было: когда он увидел кольцо и запястья на руках сестры своей и услышал слова Ревекки, сестры своей, которые говорила: так говорил мне тот человек, — пошёл он к человеку, и вот, он стоит у верблюдов, у источника.'),
(623, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 31, 'OT', 'Войди, благословенный Господом, зачем тебе стоять на улице, когда я приготовил дом и место для верблюдов.'),
(624, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 32, 'OT', 'И вошёл человек в дом, и распряг верблюдов, и дал солому и корм верблюдам, и воду, чтобы омыть ноги его и ноги людей, которые были с ним.'),
(625, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 33, 'OT', 'И поставлено было перед лицом его есть, и сказал он: не буду есть, пока не скажу слов моих. И сказал он: говори.'),
(626, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 34, 'OT', 'Я раб Авраама.'),
(627, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 35, 'OT', 'Господь благословил господина моего весьма, и он стал великим; и дал ему овец и крупный рогатый скот, и серебро и золото, и рабов и служанок, и верблюдов и ослов.'),
(628, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 36, 'OT', 'Сарра, жена господина моего, родила сына господину моему после старости её, и он дал ему всё, что у него было.'),
(629, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 37, 'OT', 'И заклял меня господин мой, говоря: не бери жены сыну моему из дочерей Хананеянина, в земле которого я живу.'),
(630, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 38, 'OT', 'Если же не пойдёшь к дому отца моего и к семейству моему, то возьмёшь жену для сына моего.'),
(631, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 39, 'OT', 'И сказал я господину моему: может быть, не пойдёт жена за мною.'),
(632, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 40, 'OT', 'И сказал он мне: Господь, пред лицом Которого я ходил, пошлёт ангела Своего с тобою и направит путь твой, и возьмёшь жену сыну моему из семейства моего и из дома отца моего.'),
(633, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 41, 'OT', 'Тогда будешь свободен от клятвы моей, когда придёшь к семейству моему; и если не дадут тебе, то будешь свободен от клятвы моей.'),
(634, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 42, 'OT', 'И пришёл я сегодня к источнику, и сказал: Господь, Бог господина моего Авраама, если Ты благоволишь пути моему, которым я иду,'),
(635, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 43, 'OT', 'Вот я стою у источника воды, и дева, выходящая черпать, — и я скажу ей: дай мне напиться немного воды из твоего кувшина.'),
(636, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 44, 'OT', 'И скажет она мне: и ты пей, и верблюдам твоим я начерпаю, — она та жена, которую Господь назначил сыну господина моего.'),
(637, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 45, 'OT', 'Я ещё не окончил говорить в сердце своём, и вот Ревекка выходит, и кувшин её на плече её, и спустилась к источнику, и почерпнула; и я сказал ей: напой меня, пожалуйста.'),
(638, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 46, 'OT', 'Она поспешила и спустила свой кувшин с плеча, и сказала: «Пей, и верблюдов твоих я напою». И я пил, и верблюдов она напоила.'),
(639, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 47, 'OT', 'И я спросил её и сказал: чья ты дочь? И она сказала: дочь Вефуила, сына Нахора, которого родила ему Милка. И я возложил кольцо на её нос и запястья на её руки.'),
(640, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 48, 'OT', 'И я преклонился и поклонился Господу, и благословил Господа, Бога господина моего Авраама, Который направил меня на путь истины, чтобы взять дочь брата господина моего для сына его.'),
(641, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 49, 'OT', 'Итак, если вы делаете милость и истину с моим господином, скажите мне; а если нет, скажите мне, и я обращусь направо или налево.'),
(642, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 50, 'OT', 'Лаван и Вефуил ответили и сказали: от Господа вышло это слово; не можем мы сказать тебе ни худого, ни доброго.'),
(643, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 51, 'OT', 'Вот Ревекка перед лицом твоим; возьми и иди, и пусть она будет женою сыну господина твоего, как сказал Господь.'),
(644, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 52, 'OT', 'И было: когда услышал раб Авраама слова их, поклонился он до земли Господу.'),
(645, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 53, 'OT', 'И вынес раб сосуды серебра и сосуды золота и одежды, и дал Ревекке; и дары дал брату её и матери её.'),
(646, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 54, 'OT', 'И ели и пили он и люди, которые были с ним, и ночевали; и встали утром, и сказал: отпусти меня к господину моему.'),
(647, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 55, 'OT', 'Сказал брат её и мать её: пусть побудет девица с нами дни или десятиструнный; после пойдёт.'),
(648, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 56, 'OT', 'Он сказал им: не удерживайте меня, ибо Господь благословил путь мой; отпустите меня, и я пойду к господину моему.'),
(649, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 57, 'OT', 'И сказали они: позовём девицу и спросим её уста.'),
(650, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 58, 'OT', 'И позвали Ревекку и сказали ей: пойдёшь ли с этим человеком? И она сказала: пойду.'),
(651, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 59, 'OT', 'И отпустили они Ревекку, сестру свою, и кормилицу её, и раба Авраамова, и людей его.'),
(652, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 60, 'OT', 'И благословили Ревекку и сказали ей: сестра наша! будь матерью тысяч и тьмы, и да наследует семя твоё ворота врагов своих.'),
(653, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 61, 'OT', 'Встала Ревекка и девицы её, и сели на верблюдов, и поехали за человеком тем; и взял раб Ревекку и пошёл.'),
(654, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 62, 'OT', 'И Исаак пришёл от Беэр-лахай-рои, и он жил в земле юга.'),
(655, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 63, 'OT', 'Вышел Исаак размышлять в поле к наступлению вечера, и поднял он очи свои, и увидел: вот, верблюды идут.'),
(656, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 64, 'OT', 'И подняла Ревекка очи свои, и увидела Исаака, и упала с верблюда.'),
(657, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 65, 'OT', 'Она сказала рабу: кто этот человек, идущий по полю навстречу нам? И сказал раб: это господин мой. И взяла она покрывало и покрылась.'),
(658, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 66, 'OT', 'И рассказал раб Исааку все слова, которые он сделал.'),
(659, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 24, 67, 'OT', 'И привёл её Исаак в шатёр Сарры, матери своей, и взял Ревекку, и стала она ему женою, и возлюбил её; и утешился Исаак после смерти матери своей.'),
(660, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 1, 'OT', 'И продолжил Авраам, и взял жену, и имя её Хеттура.'),
(661, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 2, 'OT', 'И родила она ему Зимрана, и Иокшана, и Медана, и Мадиана, и Ишбака, и Шуаха.'),
(662, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 3, 'OT', 'Иокшан родил Саву и Дедана, и сыновья Дедана были Ашуриты, Летушим и Леуммим.'),
(663, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 4, 'OT', 'И сыновья Мадиана: Ефа, и Ефер, и Енох, и Авида, и Елдаа; все эти — сыновья Хеттуры.'),
(664, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 5, 'OT', 'И отдал Авраам всё, что у него было, Исааку.'),
(665, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 6, 'OT', 'Сыновьям наложниц, которые были у Авраама, дал Авраам дары, и отослал их от Исаака, сына своего, пока он ещё был жив, на восток, в землю восточную.'),
(666, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 7, 'OT', 'И вот дни жизни Авраама, которые он прожил: сто семьдесят пять лет.'),
(667, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 8, 'OT', 'И умер Авраам в доброй седине, старый и насыщенный, и приобщился к народу своему.'),
(668, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 9, 'OT', 'И погребли его Исаак и Измаил, сыновья его, в пещере Махпела, в поле Ефрона, сына Цохара, Хеттеянина, которое против лица Мамаре.'),
(669, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 10, 'OT', 'Поле, которое Авраам купил у сыновей Хета, там был похоронен Авраам и Сарра, жена его.'),
(670, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 11, 'OT', 'И было после смерти Авраама, и благословил Бог Исаака, сына его; и поселился Исаак при Беэр-лахай-рои.'),
(671, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 12, 'OT', 'И вот родословие Измаила, сына Авраама, которого родила Агарь, Египтянка, служанка Сарры, Аврааму.'),
(672, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 13, 'OT', 'И вот имена сыновей Измаила, по именам их, по родословиям их: первенец Измаила Неваиоф, и Кидар, и Адбеел, и Мибсам.'),
(673, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 14, 'OT', 'Мишма, Дума и Масса.'),
(674, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 15, 'OT', 'Адад и Фема, Иетур, Нафиш и Кедема.'),
(675, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 16, 'OT', 'Это сыны Измаила, и вот их имена, по их дворам и по их укреплённых поселениях: двенадцать князей по их народам.'),
(676, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 17, 'OT', 'И вот годы жизни Измаила: сто тридцать семь лет; и он испустил дух, и умер, и приложился к народу своему.'),
(677, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 18, 'OT', 'И жили они от Хавилы до Сура, что перед лицом Египта, по пути в Ассирию; перед лицом всех братьев своих он пал.'),
(678, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 19, 'OT', 'И вот родословие Исаака, сына Авраама: Авраам родил Исаака.'),
(679, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 20, 'OT', 'Исаак был сыном сорока лет, когда взял Ревекку, дочь Вефуила Сирийца из Паддан-Арама, сестру Лавана Сирийца, себе в жёны.'),
(680, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 21, 'OT', 'И молился Исаак Господу о жене своей, потому что она была бесплодна; и Господь услышал его, и зачала Ревекка, жена его.'),
(681, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 22, 'OT', 'Сыновья толкались в утробе её, и она сказала: если так, то зачем мне это? И пошла она вопрошать Господа.'),
(682, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 23, 'OT', 'Господь сказал ей: два народа в чреве твоём, и два народа из чрева твоего разделятся; и народ будет сильнее народа, и старший будет служить младшему.'),
(683, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 24, 'OT', 'И исполнились дни её родить, и вот близнецы в чреве её.'),
(684, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 25, 'OT', 'Первый вышел красный, весь как мантия из волос, и назвали его имя Исав.'),
(685, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 26, 'OT', 'И после того вышел брат его, и рука его держалась за пяту Исава, и нарекли ему имя Иаков; и Исаак был сын шестидесяти лет, когда родила их.'),
(686, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 27, 'OT', 'Отроки выросли, и стал Исав человеком, знающим ловлю, человеком поля, а Иаков — человеком кротким, живущим в шатрах.'),
(687, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 28, 'OT', 'Исаак любил Исава, потому что ловля была во рту его, а Ревекка любила Иакова.'),
(688, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 29, 'OT', 'Иаков сварил похлёбку, и пришёл Исав с поля, и он был утомлён.'),
(689, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 30, 'OT', 'И сказал Исав Иакову: дай мне поесть красного, красного этого, ибо я устал; потому и названо имя его Идумея.'),
(690, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 31, 'OT', 'И сказал Иаков: продай мне сегодня первородство твоё.'),
(691, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 32, 'OT', 'И сказал Исав: вот, я иду умирать, и для чего мне это первородство?'),
(692, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 33, 'OT', 'И сказал Иаков: поклянись мне сегодня; и он поклялся ему, и продал своё первородство Иакову.'),
(693, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 25, 34, 'OT', 'Иаков дал Исаву хлеб и похлёбку из чечевицы, и он ел и пил, и встал и ушёл; и пренебрёг Исав первородством.'),
(694, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 1, 'OT', 'Был голод на земле, кроме прежнего голода, который был во дни Авраама; и пошёл Исаак к Авимелеху, царю Филистимлян, в Герар.'),
(695, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 2, 'OT', 'И явился ему Господь и сказал: не сходи в Египет; живи на земле, которую Я укажу тебе.'),
(696, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 3, 'OT', 'Живи в этой земле, и Я буду с тобою и благословлю тебя, ибо тебе и семени твоему дам все эти земли, и исполню клятву, которою Я клялся Аврааму, отцу твоему.'),
(697, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 4, 'OT', 'И умножу семя твоё, как звёзды небесные, и дам семени твоему все эти земли; и благословятся в семени твоём все народы земли.'),
(698, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 5, 'OT', 'За то, что Авраам послушался голоса Моего, и соблюдал стражу Мою, заповеди Мои, уставы Мои и законы Мои.'),
(699, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 6, 'OT', 'Исаак жил в Гераре.'),
(700, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 7, 'OT', 'И спрашивали люди того места о жене его, и он сказал: она сестра моя, потому что боялся сказать: жена моя, — чтобы не убили меня люди того места из-за Ревекки, ибо она была прекрасна видом.'),
(701, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 8, 'OT', 'И было, когда долгими стали там дни, выглянул Авимелех, царь Филистимлян, в окно и увидел: вот, Исаак играет с Ревеккой, женой своей.'),
(702, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 9, 'OT', 'И призвал Авимелех Исаака и сказал: вот, она жена твоя; и как же ты сказал: она сестра моя? И сказал ему Исаак: потому что я сказал: чтобы мне не умереть из-за неё.'),
(703, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 10, 'OT', 'Авимелех сказал: что это ты сделал нам? Едва не случилось, что один из народа не лёг с твоею женою, и ты навёл бы на нас жертву повинности.'),
(704, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 11, 'OT', 'И повелел Авимелех всему народу, говоря: кто прикоснётся к этому человеку и к жене его, смертью умрёт.'),
(705, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 12, 'OT', 'Исаак сеял в земле той и нашёл в тот год сто крат, и благословил его Господь.'),
(706, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 13, 'OT', 'И возвеличился человек, и шёл, возрастая, пока не стал весьма велик.'),
(707, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 14, 'OT', 'И был у него скот из овец и скот из крупного рогатого скота, и дом слуг великий; и позавидовали ему Филистимляне.'),
(708, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 15, 'OT', 'И все колодези, которые выкопали рабы отца его во дни Авраама, отца его, засыпали Филистимляне и наполнили их прахом.'),
(709, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 16, 'OT', 'Авимелех сказал Исааку: уйди от нас, ибо ты стал гораздо сильнее нас.'),
(710, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 17, 'OT', 'И ушёл оттуда Исаак, и расположился станом в потоке Герар, и жил там.'),
(711, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 18, 'OT', 'И возвратился Исаак и выкопал колодези воды, которые выкопали во дни Авраама, отца его, и засыпали их Филистимляне после смерти Авраама; и назвал он им имена теми же именами, которыми назвал им отец его.'),
(712, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 19, 'OT', 'И копали рабы Исаака в потоке, и нашли там колодезь живой воды.'),
(713, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 20, 'OT', 'И спорили пастухи Герара с пастухами Исаака, говоря: наша вода. И назвал он имя колодезю Есек, потому что они спорили с ним.'),
(714, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 21, 'OT', 'И выкопали другой колодезь, и спорили также о нём; и назвал имя его Сидна.'),
(715, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 22, 'OT', 'И он перешёл оттуда и выкопал другой колодезь, и не спорили о нём; и назвал имя его Реховоф, и сказал: ибо теперь Господь дал нам простор, и мы размножимся на земле.'),
(716, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 23, 'OT', 'И поднялся он оттуда в Вирсавию.'),
(717, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 24, 'OT', 'И явился ему Господь в ту ночь и сказал: Я Бог Авраама, отца твоего; не бойся, ибо Я с тобою, и благословлю тебя и умножу семя твоё ради Авраама, раба Моего.'),
(718, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 25, 'OT', 'И построил там жертвенник, и призвал имя Господа, и раскинул там шатёр свой, и выкопали там рабы Исаака колодезь.'),
(719, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 26, 'OT', 'И пошёл к нему Авимелех из Герара, и Ахузаф, друг его, и Фихол, военачальник войска его.'),
(720, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 27, 'OT', 'И сказал им Исаак: зачем вы пришли ко мне, если вы возненавидели меня и отослали меня от себя?'),
(721, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 28, 'OT', 'И сказали они: мы ясно увидели, что Господь был с тобою, и сказали: пусть будет клятва между нами, между нами и тобою, и заключим завет с тобою.'),
(722, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 29, 'OT', 'если ты сделаешь нам зло, как мы не коснулись тебя и как мы сделали с тобой только добро, и отпустили тебя с миром, то ты теперь благословен Господом.'),
(723, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 30, 'OT', 'И устроил он для них пир, и они ели и пили.'),
(724, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 31, 'OT', 'И встали они рано утром, и поклялись друг другу, человек брату своему, и отпустил их Исаак, и они ушли от него с миром.'),
(725, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 32, 'OT', 'И было в тот день, и пришли рабы Исаака, и возвестили ему о колодезе, который они копали, и сказали ему: мы нашли воду.'),
(726, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 33, 'OT', 'И назвал он её Шива; поэтому имя города — Вирсавия до сего дня.'),
(727, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 34, 'OT', 'Исав был сорока лет, и взял жену Иегудифь, дочь Веери Хеттеянина, и Васемафу, дочь Елона Хеттеянина.'),
(728, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 26, 35, 'OT', 'И были они горестью для духа Исаака и Ревекки.'),
(729, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 1, 'OT', 'И было, когда состарился Исаак, и притупились глаза его, чтобы видеть, и позвал он Исава, сына своего старшего, и сказал ему: сын мой! И сказал он ему: вот я.'),
(730, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 2, 'OT', 'Вот, я состарился, не знаю дня смерти моей.'),
(731, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 3, 'OT', 'Итак, возьми теперь оружие твоё, колчан твой и лук твой, и выйди в поле, и добудь мне продовольствие.'),
(732, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 4, 'OT', 'Приготовь мне лакомство, какое я люблю, и принеси мне, и я поем, ради того чтобы благословила тебя душа моя, прежде чем я умру.'),
(733, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 5, 'OT', 'Ревекка слышала, когда Исаак говорил с Исавом, сыном своим; и пошёл Исав в поле, чтобы наловить ловли, чтобы принести.'),
(734, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 6, 'OT', 'Ревекка сказала Иакову, сыну своему, так: вот, я слышала отца твоего, говорящего Исаву, брату твоему, так:'),
(735, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 7, 'OT', 'Принеси мне ловлю и приготовь мне лакомства, и я поем, и благословлю тебя пред лицом Господа, пред лицом смерти моей.'),
(736, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 8, 'OT', 'Итак, сын мой, послушай голоса моего, как я повелеваю тебе.'),
(737, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 9, 'OT', 'Пойди к овцам и возьми мне оттуда двух хороших козлят из коз, и я приготовлю из них лакомство для твоего отца, как он любит.'),
(738, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 10, 'OT', 'И принесёшь отцу твоему, и он поест, ради того, чтобы он благословил тебя пред лицом смерти своей.'),
(739, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 11, 'OT', 'И сказал Иаков Ревекке, матери своей: вот, Исав, брат мой, человек волосатый, а я человек гладкий.'),
(740, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 12, 'OT', 'Может быть, ощупает меня отец мой, и буду я в глазах его как обманщик, и наведу на себя проклятие, а не благословение.'),
(741, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 13, 'OT', 'Сказала ему его мать: на мне проклятие твоё, сын мой; только послушайся голоса моего и пойди, возьми мне.'),
(742, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 14, 'OT', 'И пошёл он, и взял, и принёс матери своей; и приготовила мать его лакомства, как любил отец его.'),
(743, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 15, 'OT', 'Ревекка взяла одежду Исава, сына своего старшего, лучшую, которая была у неё в доме, и одела Иакова, сына своего младшего.'),
(744, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 16, 'OT', 'И козлиную кожу козлят одела на руки его и на гладкое место шеи его.'),
(745, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 17, 'OT', 'И дала лакомства и хлеб, который приготовила, в руку Иакова, сына своего.'),
(746, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 18, 'OT', 'И пришёл он к отцу своему и сказал: отец мой! И сказал он: вот я, кто ты, сын мой?'),
(747, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 19, 'OT', 'И сказал Иаков отцу своему: я Исав, первенец твой; я сделал, как ты говорил мне; встань, сядь и поешь от ловли моей, ради того чтобы благословила меня душа твоя.'),
(748, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 20, 'OT', 'И сказал Исаак сыну своему: что это ты так скоро нашёл, сын мой? И сказал: потому что Господь Бог твой послал мне это навстречу, пред лицо моё.'),
(749, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 21, 'OT', 'И сказал Исаак Иакову: подойди же, и я ощупаю тебя, сын мой, ты ли это, сын мой Исав, или нет.'),
(750, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 22, 'OT', 'И подошёл Иаков к Исааку, отцу своему, и ощупал его, и сказал: голос — голос Иакова, а руки — руки Исава.'),
(751, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 23, 'OT', 'И не узнал его, потому что руки его были, как руки Исава, брата его, волосатые; и благословил его.'),
(752, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 24, 'OT', 'И сказал он: ты ли это сын мой Исав? И сказал он: я.'),
(753, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 25, 'OT', 'Сказал: поднеси мне, и я поем от ловли сына моего, чтобы благословила тебя душа моя; и он поднёс ему, и он ел, и принёс ему вино, и он пил.'),
(754, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 26, 'OT', 'И сказал ему Исаак, отец его: подойди же и поцелуй меня, сын мой.'),
(755, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 27, 'OT', 'И подошёл он, и поцеловал его, и обонял запах одежды его, и благословил его, и сказал: вот, запах сына моего, как запах поля, которое благословил Господь.'),
(756, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 28, 'OT', 'И даст тебе Бог от росы небесной и от богатств земли, и множество хлеба и вина.'),
(757, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 29, 'OT', 'Да послужат тебе народы, и да поклонятся тебе племена; будь господином над братьями твоими, и да поклонятся тебе сыны матери твоей; проклинающие тебя — прокляты, а благословляющие тебя — благословенны.'),
(758, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 30, 'OT', 'И было, когда окончил Исаак благословлять Иакова, и было: лишь только вышел Иаков от лица Исаака, отца своего, Исав, брат его, пришёл с ловли своей.'),
(759, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 31, 'OT', 'И он также приготовил лакомства и принёс отцу своему, и сказал отцу своему: встань, отец мой, и поешь от ловли сына твоего, ради того чтобы благословила меня душа твоя.'),
(760, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 32, 'OT', 'И сказал ему Исаак, отец его: кто ты? И сказал: я сын твой, первенец твой, Исав.'),
(761, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 33, 'OT', 'Исаак затрепетал трепетом великим до крайности и сказал: кто же это, который сделал ловлю и принёс мне, и я ел от всего, прежде чем ты пришёл, и я благословил его? он и будет благословен.'),
(762, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 34, 'OT', 'Когда Исав услышал слова отца своего, он поднял великий и горький вопль до крайности, и сказал отцу своему: благослови и меня, отец мой!'),
(763, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 35, 'OT', 'И сказал он: пришёл брат твой с коварством и взял благословение твоё.'),
(764, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 36, 'OT', 'И сказал он: не потому ли имя ему Иаков, что он запнул меня уже два раза? Первородство моё он взял, и вот теперь взял благословение моё. И сказал: не оставил ли ты для меня благословения?'),
(765, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 37, 'OT', 'Исаак ответил и сказал Исаву: вот, господином я поставил его над тобою, и всех братьев его отдал ему в рабы, и хлебом и вином я поддержал его; и для тебя, что же я сделаю, сын мой?'),
(766, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 38, 'OT', 'И сказал Исав отцу своему: неужели одно только благословение у тебя, отец мой? Благослови и меня, отец мой! И возвысил Исав голос свой и заплакал.'),
(767, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 39, 'OT', 'И отвечал Исаак, отец его, и сказал ему: вот, от тука земли будет место проживания твоё и от росы неба свыше над.'),
(768, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 40, 'OT', 'И будешь жить мечом твоим, и брату твоему будешь служить; но когда воспротивишься, сбросишь ярмо его с шеи твоей.'),
(769, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 41, 'OT', 'Исав возненавидел Иакова за благословение, которым благословил его отец его, и сказал Исав в сердце своём: приближаются дни плача по отце моём, и я убью Иакова, брата моего.'),
(770, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 42, 'OT', 'И было пересказано Ревекке слово Исава, сына её старшего, и она послала и призвала Иакова, сына её младшего, и сказала ему: вот, Исав, брат твой, утешает себя тем, что убьёт тебя.'),
(771, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 43, 'OT', 'Итак, сын мой, послушай голоса моего, и встань, беги к Лавану, брату моему, в Харан.'),
(772, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 44, 'OT', 'И живи с ним несколько дней, пока не утихнет ярость брата твоего.'),
(773, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 45, 'OT', 'пока не отвратится гнев брата твоего от тебя, и он не забудет того, что ты сделал ему; и я пошлю и возьму тебя оттуда; зачем мне лишиться обоих вас в один день?'),
(774, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 27, 46, 'OT', 'Ревекка сказала Исааку: я тягочусь жизнью моею из-за дочерей Хета; если Иаков возьмёт жену из дочерей Хета, подобных этим, из дочерей земли, то зачем мне жизнь?'),
(775, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 1, 'OT', 'Исаак призвал Иакова, и благословил его, и заповедал ему, и сказал: не бери жены из дочерей Ханаана.'),
(776, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 2, 'OT', 'Встань, иди в Паддан-Арам, в дом Вефуила, отца матери твоей, и возьми себе оттуда жену из дочерей Лавана, брата матери твоей.'),
(777, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 3, 'OT', 'Бог Вседержитель благословит тебя, и расплодит тебя, и размножит тебя, и будешь ты собранием народов.'),
(778, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 4, 'OT', 'И да даст тебе благословение Авраама, тебе и семени твоему с тобою, чтобы наследовать тебе землю странствия твоего, которую дал Бог Аврааму.'),
(779, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 5, 'OT', 'И послал Исаак Иакова, и пошёл он в Паддан-Арам, к Лавану, сыну Вефуила Сирийца, брату Ревекки, матери Иакова и Исава.'),
(780, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 6, 'OT', 'И увидел Исав, что Исаак благословил Иакова и послал его в Паддан-Арам, чтобы взять себе оттуда жену, и что, благословляя его, он заповедал ему, говоря: не бери жены из дочерей Ханаана.'),
(781, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 7, 'OT', 'И послушался Иаков отца своего и матери своей, и пошёл в Паддан-Арам.'),
(782, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 8, 'OT', 'И увидел Исав, что дочери Ханаана злы в очах Исаака, отца его.'),
(783, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 9, 'OT', 'И пошёл Исав к Измаилу, и взял Махалаф, дочь Измаила, сына Авраама, сестру Неваиофа, себе в жёны сверх своих жён.'),
(784, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 10, 'OT', 'Иаков вышел из Вирсавии и пошёл в Харан.'),
(785, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 11, 'OT', 'И он достиг места, и ночевал там, потому что зашло солнце, и взял из камней места, и положил в изголовье своё, и лёг на том месте.'),
(786, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 12, 'OT', 'И приснилось ему: вот, лестница стоит на земле, и глава её достигает неба; и вот, ангелы Божии восходят и нисходят по ней.'),
(787, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 13, 'OT', 'И вот, Господь стоял над ним и сказал: Я Господь, Бог Авраама, отца твоего, и Бог Исаака; землю, на которой ты лежишь, тебе дам Я и семени твоему.'),
(788, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 14, 'OT', 'И будет семя твоё как прах земли, и распространишься к западу и к востоку, и к северу и к югу, и благословятся в тебе все семейства земли и в семени твоём.'),
(789, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 15, 'OT', 'И вот, Я с тобою, и сохраню тебя во всём, куда ты пойдёшь, и возвращу тебя на эту землю, ибо не оставлю тебя, доколе не сделаю того, что сказал тебе.'),
(790, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 16, 'OT', 'Иаков пробудился от сна своего и сказал: истинно Господь присутствует на месте этом, а я не знал.'),
(791, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 17, 'OT', 'И убоялся, и сказал: как страшно место это! Это не что иное, как дом Божий, и это ворота неба.'),
(792, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 18, 'OT', 'И встал Иаков рано утром, и взял камень, который положил в изголовье своё, и поставил его столбом, и возлил елей на главу его.'),
(793, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 19, 'OT', 'И назвал он имя месту тому Вефиль; а прежде имя городу было Луз.'),
(794, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 20, 'OT', 'И дал Иаков обет, говоря: если Бог будет со мною и сохранит меня на этом пути, которым я иду, и даст мне хлеб есть и одежду одеться,'),
(795, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 21, 'OT', 'и возвращусь в мире в дом отца моего, и будет Господь мне Богом.'),
(796, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 28, 22, 'OT', 'И этот камень, который я поставил столбом, будет домом Божьим, и всё, что Ты дашь мне, я непременно отдам Тебе десятину.'),
(797, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 1, 'OT', 'И поднял Иаков ноги свои, и пошёл в землю сынов востока.'),
(798, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 2, 'OT', 'И увидел он: вот, колодезь в поле, и вот, там три стада овец, лежащие при нём, ибо из того колодезя поили стада; и камень большой был на устах колодезя.'),
(799, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 3, 'OT', 'И собирались туда все стада, и отваливали камень от устья колодезя, и поили овец, и возвращали камень на устье колодезя на место его.'),
(800, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 4, 'OT', 'И сказал им Иаков: братья мои, откуда вы? И сказали они: из Харана мы.'),
(801, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 5, 'OT', 'И сказал им: знаете ли вы Лавана, сына Нахора? И сказали: знаем.'),
(802, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 6, 'OT', 'И сказал им: мир ли ему? И сказали: мир; и вот Рахиль, дочь его, идёт с овцами.'),
(803, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 7, 'OT', 'Он сказал: вот, ещё день велик, не время собирать скот; напойте овец и идите, пасите.'),
(804, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 8, 'OT', 'И сказали они: не можем, пока не соберутся все стада, и не отвалят камень от устья колодезя, и не напоят овец.'),
(805, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 9, 'OT', 'Он ещё говорил с ними, когда пришла Рахиль с овцами своего отца, ибо она была пастушкой.'),
(806, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 10, 'OT', 'И было: когда увидел Иаков Рахиль, дочь Лавана, брата матери своей, и овец Лавана, брата матери своей, то подошёл Иаков и отвалил камень от отверстия колодезя, и напоил овец Лавана, брата матери своей.'),
(807, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 11, 'OT', 'И поцеловал Иаков Рахиль, и возвысил голос свой, и заплакал.'),
(808, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 12, 'OT', 'Иаков рассказал Рахили, что он брат её отца и что он сын Ревекки; и она побежала и рассказала отцу своему.'),
(809, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 13, 'OT', 'И было, когда услышал Лаван слух об Иакове, сыне сестры своей, побежал навстречу ему, и обнял его, и поцеловал его, и привёл его в дом свой; и рассказал Лавану все эти слова.'),
(810, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 14, 'OT', 'И сказал ему Лаван: подлинно ты кость моя и плоть моя. И жил он с ним месяц дней.'),
(811, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 15, 'OT', 'Лаван сказал Иакову: разве ты мой брат, и будешь служить мне даром? Скажи мне, какова твоя награда.'),
(812, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 16, 'OT', 'У Лавана было две дочери: имя старшей — Лия, а имя младшей — Рахиль.'),
(813, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 17, 'OT', 'Очи Лии были слабы, а Рахиль была красива видом и прекрасна видом.'),
(814, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 18, 'OT', 'Иаков полюбил Рахиль и сказал: я буду служить тебе семь лет за Рахиль, младшую дочь твою.'),
(815, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 19, 'OT', 'Лаван сказал: лучше отдать её тебе, чем отдать её другому человеку; живи со мной.'),
(816, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 20, 'OT', 'Иаков служил за Рахиль семь лет, и они были в его очах как несколько дней, по любви его к ней.'),
(817, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 21, 'OT', 'И сказал Иаков Лавану: дай мне жену мою, ибо исполнились дни мои, и войду к ней.'),
(818, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 22, 'OT', 'Лаван собрал всех людей того места и устроил пир.'),
(819, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 23, 'OT', 'И было вечером, и взял он Лию, дочь свою, и привёл её к нему, и он вошёл к ней.'),
(820, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 24, 'OT', 'И дал Лаван ей Зелфу, служанку свою, Лии, дочери своей, в служанки.'),
(821, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 25, 'OT', 'И было утром, и вот это Лия; и сказал он Лавану: что это ты сделал мне? Не за Рахиль ли я служил у тебя, и зачем ты обманул меня?'),
(822, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 26, 'OT', 'Лаван сказал: не делается так в нашем месте, чтобы отдавать младшую пред лицом первенца.'),
(823, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 27, 'OT', 'Доведи до конца эту седмицу, и дадим тебе и эту за работу, которую ты будешь работать у меня ещё семь других лет.'),
(824, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 28, 'OT', 'Иаков сделал так, и исполнил эту седмицу; и он дал ему Рахиль, дочь свою, ему в жену.'),
(825, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 29, 'OT', 'И дал Лаван Рахили, дочери своей, Валлу, служанку свою, ей в служанки.'),
(826, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 30, 'OT', 'И вошёл также к Рахили, и возлюбил также Рахиль более, чем Лию, и служил у него ещё семь других лет.'),
(827, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 31, 'OT', 'Господь увидел, что Лия была ненавидима, и открыл её матку, а Рахиль была бесплодна.'),
(828, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 32, 'OT', 'Лия зачала и родила сына, и нарекла ему имя Рувим, ибо сказала: Господь увидел бедствие моё; теперь возлюбит меня человек мой.'),
(829, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 33, 'OT', 'И снова зачала она и родила сына, и сказала: потому что услышал Господь, что я ненавидима, и дал мне также и этого; и нарекла имя ему Симеон.'),
(830, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 34, 'OT', 'И снова зачала она и родила сына, и сказала: теперь-то прилепится ко мне человек мой, ибо я родила ему трёх сыновей; поэтому наречено было имя его Левий.'),
(831, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 29, 35, 'OT', 'И снова зачала она и родила сына, и сказала: теперь я восхвалю Господа; поэтому нарекла имя ему Иуда. И перестала рожать.'),
(832, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 1, 'OT', 'Рахиль увидела, что не родила Иакову, и позавидовала Рахиль сестре своей, и сказала Иакову: дай мне сыновей, а если нет, я умираю.'),
(833, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 2, 'OT', 'Воспламенился гнев Иакова на Рахиль, и сказал он: разве я вместо Бога, который лишил тебя плода чрева?'),
(834, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 3, 'OT', 'Вот, служанка моя Валла; войди к ней, и пусть она родит на колени мои, и я буду иметь детей через неё.'),
(835, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 4, 'OT', 'И дала она Валлу, служанку свою, ему в жёны; и вошёл к ней Иаков.'),
(836, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 5, 'OT', 'Валла зачала и родила Иакову сына.'),
(837, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 6, 'OT', 'Рахиль сказала: Бог рассудил меня, и также услышал голос мой, и дал мне сына; поэтому она нарекла ему имя Дан.'),
(838, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 7, 'OT', 'И снова зачала, и родила Валла, служанка Рахили, второго сына Иакову.'),
(839, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 8, 'OT', 'Рахиль сказала: борьбою Божьей я боролась с сестрою моею и превозмогла; и нарекла имя ему Неффалим.'),
(840, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 9, 'OT', 'И увидела Лия, что перестала рожать, и взяла Зелфу, служанку свою, и дала её Иакову в жёны.'),
(841, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 10, 'OT', 'Зелфа, служанка Лии, родила Иакову сына.'),
(842, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 11, 'OT', 'И сказала Лия: «Отряд!» — и нарекла ему имя: Гад.'),
(843, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 12, 'OT', 'Зелфа, служанка Лии, родила второго сына Иакову.'),
(844, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 13, 'OT', 'Лия сказала: к блаженству моему, ибо дочери назовут меня блаженной; и нарекла ему имя Асир.'),
(845, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 14, 'OT', 'Пошёл Рувим во дни жатвы пшеницы и нашёл мандрагоры в поле, и принёс их Лии, матери своей. И сказала Рахиль Лии: дай мне, пожалуйста, из мандрагор сына твоего.'),
(846, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 15, 'OT', 'Она сказала ей: немного ли, что ты взяла моего человека, и хочешь взять также мандрагоры моего сына? И сказала Рахиль: поэтому он будет спать с тобою эту ночь за мандрагоры твоего сына.'),
(847, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 16, 'OT', 'Иаков пришёл с поля вечером, и вышла Лия навстречу ему, и сказала: ко мне войди, ибо я наняла тебя за мандрагоры сына моего; и спал с нею в ту ночь.'),
(848, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 17, 'OT', 'И услышал Бог Лию, и она зачала, и родила Иакову сына, пятого.'),
(849, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 18, 'OT', 'И сказала Лия: Бог дал мне плату за то, что я отдала служанку мою человеку моему. И нарекла ему имя Иссахар.'),
(850, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 19, 'OT', 'И снова зачала Лия и родила шестого сына Иакову.'),
(851, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 20, 'OT', 'И сказала Лия: Бог дал мне приданое доброе; теперь раз будет жить со мной человек мой, потому что я родила ему шесть сыновей. И нарекла ему имя Завулон.'),
(852, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 21, 'OT', 'И после того родила дочь и нарекла ей имя Дина.'),
(853, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 22, 'OT', 'И вспомнил Бог о Рахили, и услышал её Бог, и открыл матку её.'),
(854, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 23, 'OT', 'Она зачала и родила сына, и сказала: Бог снял моё поношение.'),
(855, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 24, 'OT', 'И нарекла ему имя Иосиф, говоря: Господь прибавит мне другого сына.'),
(856, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 25, 'OT', 'И было, когда родила Рахиль Иосифа, сказал Иаков Лавану: отпусти меня, и пойду я в место моё и в землю мою.'),
(857, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 26, 'OT', 'Отдай мне моих жён и моих детей, за которых я служил тебе, и я пойду; ибо ты знаешь моё служение, которым я служил тебе.'),
(858, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 27, 'OT', 'И сказал ему Лаван: если я нашёл благодать в очах твоих, я узнал по приметам, и благословил меня Господь ради тебя.'),
(859, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 28, 'OT', 'И сказал: назначь плату твою у меня, и я дам.'),
(860, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 29, 'OT', 'Он сказал ему: ты знаешь, как я служил тебе, и каков был скот твой при мне.'),
(861, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 30, 'OT', 'Ибо немногое, что было у тебя перед лицом моим, умножилось во множество, и благословил тебя Господь по стопам моим; и когда же сделаю и я что-нибудь для дома моего?'),
(862, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 31, 'OT', 'И сказал он: что мне дать тебе? И сказал Иаков: не давай мне ничего, если сделаешь мне это слово: я снова буду пасти овец твоих и стеречь их.'),
(863, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 32, 'OT', 'Пройду сегодня среди всех овец твоих, отдели оттуда всякую овцу пеструю и пятнистую, и всякую овцу черную среди ягнят, и пятнистую и пеструю среди коз, и будет это моей платой.'),
(864, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 33, 'OT', 'И ответит мне честность моя в день завтра, когда придёшь ты на плату мою пред лицом твоим: всё, что не пёстрое и не пятнистое у коз, и тёмное у ягнят, — украденное оно у меня.'),
(865, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 34, 'OT', 'И сказал Лаван: пусть будет по слову твоему.'),
(866, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 35, 'OT', 'И в тот день отделил он козлов пёстрых и пятнистых, и всех коз с крапинами и пятнами, всё, что было у Лавана, и всех бурых среди ягнят, и отдал в руки сыновьям своим.'),
(867, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 36, 'OT', 'И установил он путь в три дня между собою и Иаковом; а Иаков пас оставшихся овец Лавана.'),
(868, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 37, 'OT', 'И взял себе Иаков жезл свежий тополя, и орешника, и каштана, и ободрал на них полосы белые, обнажив белое, что на жезлах.'),
(869, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 38, 'OT', 'И поставил жезлы, которые он ободрал, в жёлобах, в корытах для воды, куда приходили овцы пить, напротив овец, и они разгорячались, приходя пить.'),
(870, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 39, 'OT', 'Овцы разгорались к жезлам, и рождали овцы пестрых, крапчатых и пятнистых.'),
(871, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 40, 'OT', 'И ягнят отделил Иаков, и повернул овец мордой к полосатым и ко всему тёмному в стаде Лавана, и устроил себе стада отдельно, и не ставил их с овцами Лавана.'),
(872, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 41, 'OT', 'И было: во всякое время, когда овцы крепкие зачинают, Иаков клал жезлы пред очами овец в жёлобах, чтобы они зачинали у жезлов.'),
(873, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 42, 'OT', 'А когда овцы были слабыми, он не клал их, и слабые доставались Лавану, а крепкие — Иакову.'),
(874, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 30, 43, 'OT', 'И распространился человек весьма, весьма, и было у него овец много, и служанок, и рабов, и верблюдов, и ослов.'),
(875, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 1, 'OT', 'И услышал Иаков слова сыновей Лавана, говорящих: взял Иаков всё, что у отца нашего, и из того, что у отца нашего, сделал всю эту славу.'),
(876, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 2, 'OT', 'И увидел Иаков лицо Лавана, и вот, оно не было с ним, как вчера и третьего дня.'),
(877, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 3, 'OT', 'И сказал Господь Иакову: возвратись в землю отцов твоих и на родину твою, и Я буду с тобою.'),
(878, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 4, 'OT', 'И послал Иаков и призвал Рахиль и Лию в поле к овцам своим.'),
(879, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 5, 'OT', 'И сказал им: я вижу лицо отца вашего, что оно не ко мне, как вчера и третьего дня; но Бог отца моего был со мною.'),
(880, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 6, 'OT', 'А вы знаете, что я всеми силами своими служил отцу вашему.'),
(881, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 7, 'OT', 'Ваш отец обманул меня и десять раз менял мою награду, но Бог не позволил ему причинить мне зло.'),
(882, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 8, 'OT', 'Если он скажет: «пёстрые будут твоей платой», то всё стадо родит пёстрых; а если он скажет: «полосатые будут твоей платой», то всё стадо родит полосатых.'),
(883, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 9, 'OT', 'Бог отнял скот у отца вашего и отдал мне.'),
(884, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 10, 'OT', 'И было во время, когда овцы зачинают, и я поднял око моё, и увидел во сне: вот козлы, поднимающиеся на овец, пёстрые, крапчатые и пятнистые.'),
(885, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 11, 'OT', 'И сказал мне ангел Бога во сне: Иаков! И я сказал: вот я.'),
(886, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 12, 'OT', 'Подними ныне очи твои и увидь всех козлов, поднимающихся на овец: пёстрых, крапчатых и пятнистых, ибо Я увидел всё, что Лаван делает тебе.'),
(887, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 13, 'OT', 'Я Бог Вефиля, где ты помазал столб и где дал Мне обет; теперь встань, выйди из этой земли и возвратись в землю родины твоей.'),
(888, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 14, 'OT', 'И ответила Рахиль и Лия, и сказали ему: есть ли ещё нам часть и наследие в доме отца нашего?'),
(889, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 15, 'OT', 'Разве не чужеземками мы считаемся у него, ибо он продал нас, и съел даже деньги наши.'),
(890, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 16, 'OT', 'Ибо всё богатство, которое Бог отнял у отца нашего, — наше и сыновей наших; итак, всё, что Бог сказал тебе, делай.'),
(891, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 17, 'OT', 'И встал Иаков, и посадил сыновей своих и жён своих на верблюдов.'),
(892, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 18, 'OT', 'И он погнал весь скот свой и всё имущество своё, которое приобрёл, скот имения своего, который приобрёл в Паддан-Араме, чтобы идти к Исааку, отцу своему, в землю Ханаанскую.'),
(893, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 19, 'OT', 'Лаван же пошёл стричь своих овец, а Рахиль украла идолов, которые были у её отца.'),
(894, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 20, 'OT', 'Иаков украл сердце Лавана Сирийца, потому что не сказал ему, что он убегает.'),
(895, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 21, 'OT', 'И он бежал сам и всё, что у него было, и встал, и перешёл реку, и обратил лицо своё к горе Галаад.'),
(896, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 22, 'OT', 'И было возвещено Лавану на третий день, что убежал Иаков.'),
(897, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 23, 'OT', 'И взял братьев своих с собою, и гнался за ним путём семи дней, и настиг его на горе Галаад.'),
(898, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 24, 'OT', 'И пришёл Бог к Лавану Сирийцу во сне ночью и сказал ему: берегись, чтобы не говорить с Иаковом от добра до зла.'),
(899, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 25, 'OT', 'И настиг Лаван Иакова; и Иаков поставил шатёр свой на горе, и Лаван поставил братьев своих на горе Галаад.'),
(900, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 26, 'OT', 'Лаван сказал Иакову: что ты сделал, и украл сердце моё, и увёл дочерей моих, как пленниц меча?'),
(901, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 27, 'OT', 'Зачем ты тайно убежал и утаил от меня, и не сказал мне, чтобы я отпустил тебя с радостью и с песнями, с тимпаном и с гуслями?'),
(902, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 28, 'OT', 'И не дал ты мне поцеловать сыновей моих и дочерей моих; теперь ты поступил глупо.'),
(903, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 29, 'OT', 'Есть в руке моей сила сделать вам зло, но Бог отца вашего вчера говорил ко мне, говоря: берегись, не говори с Иаковом ни добра, ни зла.'),
(904, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 30, 'OT', 'Итак, ты ушёл, потому что сильно возжелал дома отца твоего; зачем же ты украл моих богов?'),
(905, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 31, 'OT', 'Иаков ответил и сказал Лавану: я боялся, ибо думал, что ты отнимешь у меня дочерей твоих.'),
(906, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 32, 'OT', 'У кого найдёшь богов твоих, тот не будет жить; перед братьями нашими узнай, что у меня, и возьми себе. И не знал Иаков, что Рахиль украла их.'),
(907, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 33, 'OT', 'И вошёл Лаван в шатёр Иакова, и в шатёр Лии, и в шатёр двух служанок, и не нашёл; и вышел из шатра Лии, и вошёл в шатёр Рахили.'),
(908, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 34, 'OT', 'Рахиль взяла идолов и положила их в седло верблюда, и села на них; и Лаван ощупал весь шатёр, но не нашёл.'),
(909, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 35, 'OT', 'И сказала она отцу своему: да не разгорится гнев в очах господина моего, что я не могу встать пред лицом твоим, ибо у меня путь женский. И он искал, но не нашёл идолов.'),
(910, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 36, 'OT', 'И разгневался Иаков и препирался с Лаваном, и отвечал Иаков и сказал Лавану: какое преступление моё, какой грех мой, что ты преследовал меня?'),
(911, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 37, 'OT', 'Так как ты ощупал все мои вещи, что нашёл из всех вещей твоего дома? Положи здесь перед братьями моими и братьями твоими, и пусть они рассудят между нами обоими.'),
(912, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 38, 'OT', 'Вот уже двадцать лет я с тобою; овцы твои и козы твои не выкидывали, и овнов стада твоего я не ел.'),
(913, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 39, 'OT', 'Растерзанное зверем я не приносил тебе; я сам возмещал его; из руки моей ты взыскивал его; украденное днём и украденное ночью.'),
(914, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 40, 'OT', 'Днём пожирала меня засуха, а ночью лёд, и сон мой убегал от очей моих.'),
(915, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 41, 'OT', 'Вот уже двадцать лет я у тебя в доме: четырнадцать лет я служил тебе за двух твоих дочерей и шесть лет за твоих овец, а ты десять раз менял мою награду.'),
(916, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 42, 'OT', 'Если бы не Бог отца моего, Бог Авраама и страх Исаака, который был со мною, то теперь ты отпустил бы меня с пустыми руками; бедствие моё и труд рук моих увидел Бог, и Он рассудил вчера.'),
(917, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 43, 'OT', 'И ответил Лаван и сказал Иакову: дочери — дочери мои, и сыновья — сыновья мои, и овцы — овцы мои, и всё, что ты видишь, — моё; а для дочерей моих что сделаю я им в этот день или для сыновей их, которых они родили?'),
(918, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 44, 'OT', 'Итак, пойдём, заключим завет я и ты, и он будет свидетелем между мною и тобою.'),
(919, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 45, 'OT', 'И взял Иаков камень и поставил его столбом.'),
(920, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 46, 'OT', 'И сказал Иаков братьям своим: наберите камней. И взяли они камни, и сделали груду, и ели там на груде.'),
(921, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 47, 'OT', 'И назвал его Лаван Иегар-Сагадуфа, а Иаков назвал его Галед.'),
(922, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 48, 'OT', 'И сказал Лаван: эта груда — свидетель между мною и тобою в этот день; поэтому он назвал его именем Галед.'),
(923, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 49, 'OT', 'И Мицпа, о которой он сказал: да наблюдает Господь между мною и между тобою, когда мы скроемся друг от друга, человек от ближнего своего.'),
(924, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 50, 'OT', 'Если ты будешь притеснять моих дочерей, и если возьмёшь жён сверх моих дочерей, — нет человека с нами; вот, Бог — свидетель между мною и тобою.'),
(925, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 51, 'OT', 'И сказал Лаван Иакову: вот эта груда и вот столб, который я поставил между мною и тобою.'),
(926, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 52, 'OT', 'Свидетель груда эта, и свидетельство столб; если я не перейду к тебе через груду эту, и если ты не перейдёшь ко мне через груду эту и столб этот для зла.'),
(927, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 53, 'OT', 'Бог Авраама и Бог Нахора да судят между нами, Бог отца их. И поклялся Иаков Страхом (т.е. Тем, Кого боялся) отца своего Исаака.'),
(928, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 54, 'OT', 'И принёс Иаков жертву на горе, и позвал братьев своих есть хлеб; и ели они хлеб, и ночевали на горе.'),
(929, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 31, 55, 'OT', 'Лаван встал рано утром, и поцеловал сыновей своих и дочерей своих, и благословил их, и пошёл, и возвратился Лаван в место своё.'),
(930, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 1, 'OT', 'Иаков пошёл своим путём, и встретили его ангелы Божьи.'),
(931, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 2, 'OT', 'И сказал Иаков, когда увидел их: это стан Божий. И назвал имя месту тому Маханаим.'),
(932, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 3, 'OT', 'И послал Иаков посланников пред лицом своим к Исаву, брату своему, в землю Сеир, в поле Идумеи.'),
(933, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 4, 'OT', 'И приказал им, говоря: так скажите господину моему Исаву: так говорит раб твой Иаков: с Лаваном я жил и замедлил доныне.'),
(934, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 5, 'OT', 'И стало у меня волы и ослы, овцы и раб и служанка; и послал я возвестить господину моему, чтобы найти благодать в очах твоих.'),
(935, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 6, 'OT', 'И возвратились посланники к Иакову и сказали: мы пришли к брату твоему, к Исаву, и он идёт навстречу тебе, и с ним четыреста человек.'),
(936, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 7, 'OT', 'Иаков очень испугался, и было тесно ему; и разделил он народ, который был с ним, и овец, и крупный рогатый скот, и верблюдов на два стана.'),
(937, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 8, 'OT', 'И сказал: если придёт Исав к одному стану и поразит его, то остальной стан будет для спасения.'),
(938, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 9, 'OT', 'И сказал Иаков: Бог отца моего Авраама и Бог отца моего Исаака, Господь, сказавший мне: возвратись в землю твою и на родину твою, и Я сделаю добро с тобою.'),
(939, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 10, 'OT', 'Я недостоин всех милостей и всей истины, которые Ты совершил для раба Твоего, ибо с жезлом моим я перешёл этот Иордан, а теперь стал двумя станами.'),
(940, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 11, 'OT', 'Спаси меня, пожалуйста, от руки брата моего, от руки Исава, ибо я боюсь его, чтобы он не пришёл и не поразил меня, мать с сыновьями.'),
(941, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 12, 'OT', 'И ты сказал: «Я непременно сделаю тебе добро и сделаю семя твоё как песок морской, который не может быть исчислен от множества».'),
(942, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 13, 'OT', 'И ночевал там в ту ночь, и взял из того, что было в руке его, дар Исаву, брату своему.'),
(943, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 14, 'OT', 'двести коз и двадцать козлов, двести овец и двадцать овнов'),
(944, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 15, 'OT', 'верблюдиц доящих и сыновей их тридцать, коров сорок и тельцов десять, ослиц двадцать и молодых ослов десять'),
(945, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 16, 'OT', 'И отдал в руку рабов своих стадо отдельно, и сказал рабам своим: пройдите перед лицом моим, и пространство сделайте между стадом и стадом.'),
(946, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 17, 'OT', 'И приказал он первому, говоря: когда встретит тебя Исав, брат мой, и спросит тебя, говоря: чей ты, и куда идёшь, и чьи эти перед лицом твоим,'),
(947, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 18, 'OT', 'И скажи рабу твоему Иакову: это дар, посланный господину моему Исаву; и вот, он сам идёт за нами.'),
(948, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 19, 'OT', 'И приказал он также второму, также третьему, также всем, идущим за стадами, говоря: таким словом говорите Исаву, когда встретите его.'),
(949, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 20, 'OT', 'И скажите: вот, раб твой Иаков идёт за нами. Ибо он сказал: умилостивлю лицо его даром, идущим передо мною, и после того увижу лицо его; может быть, он примет лицо моё.'),
(950, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 21, 'OT', 'И перешёл дар пред лицом его, а он ночевал в ту ночь в стане.'),
(951, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 22, 'OT', 'И встал он в ту ночь, и взял двух своих жён, и двух своих служанок, и одиннадцать своих детей, и перешёл переправу Иавок.'),
(952, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 23, 'OT', 'И взял их, и перевёл их через поток, и перевёл всё, что у него было.'),
(953, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 24, 'OT', 'Иаков остался отдельно, и боролся человек с ним до восхода рассвета.'),
(954, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 25, 'OT', 'И увидел он, что не может одолеть его, и коснулся сустава бедра его, и вывихнулся сустав бедра Иакова, когда он боролся с ним.'),
(955, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 26, 'OT', 'И сказал он: отпусти меня, ибо взошёл рассвет. И сказал он: не отпущу тебя, пока не благословишь меня.'),
(956, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 27, 'OT', 'И сказал ему: какое имя твоё? И сказал: Иаков.'),
(957, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 28, 'OT', 'И сказал: не Иаковом будет называться впредь имя твоё, но Израилем; ибо ты боролся с Богом и с людьми, и одолел.'),
(958, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 29, 'OT', 'И спросил Иаков и сказал: скажи же имя твоё. И сказал он: зачем ты спрашиваешь об имени моём? И благословил он его там.'),
(959, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 30, 'OT', 'И нарек Иаков имя месту тому Пенуэл, ибо я видел Бога лицом к лицу, и сохранилась душа моя.'),
(960, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 31, 'OT', 'И взошло ему солнце, когда он прошёл Пенуэл, и он хромал на бедро своё.'),
(961, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 32, 32, 'OT', 'Поэтому не едят сыны Израиля жилу, которая ссохлась, на суставе бедра, до сего дня, потому что Он коснулся сустава бедра Иакова в жиле, которая ссохлась.'),
(962, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 1, 'OT', 'И поднял Иаков очи свои, и увидел: вот, Исав идёт, и с ним четыреста человек; и разделил детей на Лию, и на Рахиль, и на двух служанок.'),
(963, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 2, 'OT', 'И поставил служанок и детей их впереди, а Лию и детей её позади, а Рахиль и Иосифа позади.'),
(964, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 3, 'OT', 'И он прошёл перед лицом их, и поклонился до земли семь раз, пока не приблизился к брату своему.'),
(965, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 4, 'OT', 'И побежал Исав навстречу ему, и обнял его, и пал на шею его, и целовал его, и плакали они.'),
(966, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 5, 'OT', 'Он поднял свои очи и увидел жён и детей, и сказал: кто это у тебя? И сказал: дети, которых Бог даровал рабу твоему.'),
(967, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 6, 'OT', 'Подошли служанки с детьми своими и поклонились.'),
(968, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 7, 'OT', 'Подошла также Лия и дети её, и поклонились; и после подошли Иосиф и Рахиль, и поклонились.'),
(969, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 8, 'OT', 'И сказал он: что у тебя весь этот стан, который я встретил? И сказал он: чтобы найти благодать в очах господина моего.'),
(970, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 9, 'OT', 'Исав сказал: у меня много, брат мой; пусть будет у тебя твоё.'),
(971, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 10, 'OT', 'И сказал Иаков: нет, пожалуйста, если я нашёл благодать в очах твоих, то прими дар мой из руки моей, ибо я увидел лицо твоё, как видят лицо Бога, и ты благоволил ко мне.'),
(972, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 11, 'OT', 'Прими, прошу, моё благословение, которое принесено тебе, потому что Бог оказал мне милость и потому что у меня есть всё. И он настаивал на нём, и тот взял.'),
(973, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 12, 'OT', 'И сказал: двинемся и пойдём, и пойду пред тобою.'),
(974, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 13, 'OT', 'Он сказал ему: господин мой знает, что дети нежны, и овцы и крупный рогатый скот у меня на попечении; если погнать их один день, умрёт всё стадо овец.'),
(975, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 14, 'OT', 'Да пройдёт господин мой пред лицом раба своего, а я пойду тихо, по мере работы, которая пред лицом моим, и по мере детей, доколе не приду к господину моему в Сеир.'),
(976, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 15, 'OT', 'Исав сказал: «Оставлю я с тобой из народа, который со мной». И сказал он: «Зачем это? Мне найти благодать в очах господина моего».'),
(977, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 16, 'OT', 'И возвратился в тот день Исав на путь свой в Сеир.'),
(978, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 17, 'OT', 'Иаков отправился в Сокхоф, и построил себе дом, и для скота своего сделал кущи; поэтому он назвал имя месту тому Сокхоф.'),
(979, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 18, 'OT', 'И пришёл Иаков целым в город Сихем, который в земле Ханаан, когда он пришёл из Паддан-Арама, и расположился станом перед лицом города.'),
(980, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 19, 'OT', 'И купил участок поля, где раскинул шатёр свой, из рук сыновей Еммора, отца Сихема, за сто монет.'),
(981, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 33, 20, 'OT', 'И поставил там жертвенник, и назвал его Бог, Бог Израиля.'),
(982, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 1, 'OT', 'И вышла Дина, дочь Лии, которую она родила Иакову, посмотреть на дочерей земли.'),
(983, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 2, 'OT', 'Увидел её Сихем, сын Еммора, Евея, князя земли, и взял её, и лёг с ней, и унизил её.'),
(984, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 3, 'OT', 'И прилепилась душа его к Дине, дочери Иакова, и полюбил он девицу, и говорил по сердцу девицы.'),
(985, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 4, 'OT', 'И сказал Сихем Еммору, отцу своему, говоря: возьми мне эту девицу в жёны.'),
(986, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 5, 'OT', 'Иаков услышал, что он осквернил Дину, дочь его, а сыновья его были со скотом его в поле; и молчал Иаков, пока они не пришли.'),
(987, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 6, 'OT', 'И вышел Еммор, отец Сихема, к Иакову, чтобы говорить с ним.'),
(988, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 7, 'OT', 'И сыновья Иакова пришли с поля, когда услышали, и огорчились те люди, и сильно разгневались, потому что гнусность совершил он в Израиле, лёжа с дочерью Иакова, и так не должно делаться.'),
(989, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 8, 'OT', 'Еммор говорил с ними и сказал: Сихем, сын мой, прилепилась душа его к вашей дочери; дайте же её ему в жёны.'),
(990, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 9, 'OT', 'И породнитесь с нами: дочерей ваших отдавайте нам, а наших дочерей берите себе.'),
(991, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 10, 'OT', 'И с нами живите; и земля будет перед лицом вашим: живите и торгуйте ею, и владейте ею.'),
(992, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 11, 'OT', 'Сихем сказал отцу её и братьям её: если я нашёл благодать в очах ваших, то что скажете мне, то дам.'),
(993, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 12, 'OT', 'Умножьте на меня очень вено и дар, и я дам, как скажете мне; и дайте мне девицу в жёны.'),
(994, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 13, 'OT', 'Сыновья Иакова ответили Сихему и Еммору, отцу его, с коварством и говорили, потому что он осквернил Дину, сестру их.'),
(995, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 14, 'OT', 'И сказали им: не можем мы сделать это слово — отдать сестру нашу человеку, у которого крайняя плоть, ибо это поношение для нас.'),
(996, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 15, 'OT', 'Только в этом мы согласимся с вами: если вы будете, как мы, чтобы обрезан был у вас всякий мужчина.'),
(997, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 16, 'OT', 'И отдадим мы дочерей наших вам, и дочерей ваших возьмём себе, и будем жить с вами, и станем одним народом.'),
(998, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 17, 'OT', 'А если вы не послушаете нас, чтобы обрезаться, то мы возьмём нашу дочь и уйдём.'),
(999, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 18, 'OT', 'И понравились слова их в очах Еммора и в очах Сихема, сына Емморова.'),
(1000, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 19, 'OT', 'И не замедлил отрок сделать это слово, ибо он желал дочь Иакова; а он был почтен более всего дома отца своего.'),
(1001, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 20, 'OT', 'И пришёл Еммор и Сихем, сын его, к воротам города своего, и говорили с людьми города своего, говоря:'),
(1002, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 21, 'OT', 'Эти люди мирны с нами, и пусть они живут на земле и торгуют ею; и вот, земля обширна перед лицом их; дочерей их возьмём себе в жёны, а наших дочерей отдадим им.'),
(1003, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 22, 'OT', 'Только на этом условии согласятся эти люди жить с нами и стать одним народом, если будет обрезан у нас всякий мужчина, как они обрезаны.'),
(1004, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 23, 'OT', 'Их скот и имение их, и весь скот их — разве не наши они? Только согласимся с ними, и будут жить с нами.'),
(1005, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 24, 'OT', 'И послушались Еммора и Сихема, сына его, все выходящие из ворот его города, и обрезаны были все мужеского пола, все выходящие из ворот его города.'),
(1006, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 25, 'OT', 'И было на третий день, когда они были в боли, взяли два сына Иакова, Симеон и Левий, братья Дины, каждый человек свой меч, и пришли на город в безопасности, и убили всё мужское.'),
(1007, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 26, 'OT', 'И Еммора и Сихема, сына его, убили остриём меча, и взяли Дину из дома Сихема, и вышли.'),
(1008, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 27, 'OT', 'Сыновья Иакова пришли на убитых и разграбили город, потому что они осквернили их сестру.'),
(1009, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 28, 'OT', 'Овец их и крупный рогатый скот их, и ослов их, и то, что в городе, и то, что в поле, взяли.'),
(1010, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 29, 'OT', 'И всё имущество их, и всех детей их, и жён их взяли в плен и разграбили, и всё, что в доме.'),
(1011, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 30, 'OT', 'И сказал Иаков Симеону и Левию: вы смутили меня, сделав меня ненавистным для жителей земли, для Хананеянина и Ферезеев; а я — люди немногие по числу, и соберутся они против меня, и поразит меня, и истреблён буду я и дом мой.'),
(1012, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 34, 31, 'OT', 'И сказали они: разве можно обращаться с нашей сестрой как с блудницей?'),
(1013, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 1, 'OT', 'И сказал Бог Иакову: встань, поднимись в Вефиль и живи там, и устрой там жертвенник Богу, явившемуся тебе, когда ты бежал от лица Исава, брата твоего.'),
(1014, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 2, 'OT', 'И сказал Иаков дому своему и всему, что было с ним: удалите богов чужих, которые в середине вашей, и очиститесь, и перемените одежды ваши.'),
(1015, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 3, 'OT', 'Встанем и пойдём в Вефиль; и я устрою там жертвенник Богу, Который ответил мне в день скорби моей и был со мною на пути, которым я шёл.'),
(1016, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 4, 'OT', 'И отдали Иакову всех чужих богов, которые были в руках их, и кольца, которые были в ушах их, и закопал их Иаков под дубом, который близ Сихема.'),
(1017, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 5, 'OT', 'И отправились они; и был ужас Божий на городах, которые вокруг них, и не преследовали сыновей Иакова.'),
(1018, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 6, 'OT', 'И пришёл Иаков в Луз, который в земле Ханаанской, это Вефиль, он и весь народ, который с ним.'),
(1019, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 7, 'OT', 'И построил там жертвенник, и назвал то место Бог Вефиль, ибо там открылся ему Бог, когда он бежал от лица брата своего.'),
(1020, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 8, 'OT', 'Умерла Девора, кормилица Ревекки, и была погребена ниже Вефиля под дубом; и нарек он имя ему Аллон-бакут.'),
(1021, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 9, 'OT', 'И явился Бог Иакову ещё, когда он пришёл из Паддана, и благословил его.'),
(1022, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 10, 'OT', 'И сказал ему Бог: имя твоё Иаков; не будет уже называться имя твоё Иаков, но Израиль будет имя твоё. И нарек ему имя Израиль.'),
(1023, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 11, 'OT', 'И сказал ему Бог: Я Бог Вседержитель; плодись и умножайся; народ и собрание народов будет от тебя, и цари из чресл твоих произойдут.'),
(1024, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 12, 'OT', 'И землю, которую Я дал Аврааму и Исааку, тебе дам её, и семени твоему после тебя дам землю.'),
(1025, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 13, 'OT', 'И поднялся Бог от него с места, где говорил с ним.'),
(1026, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 14, 'OT', 'Иаков поставил столб на месте, где говорил с ним Бог, столп каменный, и возлил на него возлияние, и вылил на него елей.'),
(1027, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 15, 'OT', 'И нарек Иаков имя месту тому, где говорил с ним Бог, Вефиль.'),
(1028, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 16, 'OT', 'И отправились они из Вефиля, и было ещё малое расстояние земли, чтобы прийти в Ефрафу, и родила Рахиль, и трудно было ей в родах её.'),
(1029, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 17, 'OT', 'И было, когда она мучилась при родах, сказала ей повивальная бабка: не бойся, ибо и этот у тебя сын.'),
(1030, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 18, 'OT', 'И было, когда выходила её душа, ибо она умирала, и она назвала его имя Бен-Они; а его отец назвал его Вениамин.'),
(1031, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 19, 'OT', 'И умерла Рахиль, и была погребена на пути к Ефрафе, то есть Вифлеему.'),
(1032, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 20, 'OT', 'И поставил Иаков столб над погребением её; это столп погребения Рахили до сего дня.'),
(1033, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 21, 'OT', 'И отправился Израиль, и раскинул шатёр свой за Мигдал-Эдер.'),
(1034, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 22, 'OT', 'И было, когда Израиль жил в той земле, пошёл Рувим и лёг с Валлой, наложницей отца своего, и услышал Израиль. И было сыновей Иакова двенадцать.'),
(1035, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 23, 'OT', 'Сыновья Лии, первенец Иакова, Рувим, и Симеон, и Левий, и Иуда, и Иссахар, и Завулон.'),
(1036, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 24, 'OT', 'Сыновья Рахили: Иосиф и Вениамин.'),
(1037, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 25, 'OT', 'Сыновья Валлы, служанки Рахили: Дан и Неффалим.'),
(1038, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 26, 'OT', 'Сыновья Зелфы, служанки Лии: Гад и Асир. Это сыновья Иакова, которые родились у него в Паддане Араме.'),
(1039, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 27, 'OT', 'И пришёл Иаков к Исааку, отцу своему, в Мамаре, в Кириаф-Арбу, то есть Хеврон, где жил Авраам и Исаак.'),
(1040, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 28, 'OT', 'И было дней Исаака сто лет и восемьдесят лет.'),
(1041, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 35, 29, 'OT', 'И умер Исаак, и скончался, и приложился к народу своему, будучи стар и насыщен днями; и погребли его Исав и Иаков, сыновья его.'),
(1042, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 1, 'OT', 'И вот родословие Исава, он же Идумея.'),
(1043, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 2, 'OT', 'Исав взял себе жён из дочерей Ханаана: Аду, дочь Елона Хеттеянина, и Оголиваму, дочь Аны, дочь Цивеона Евея.'),
(1044, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 3, 'OT', 'И Васемафу, дочь Измаила, сестру Неваиофа.'),
(1045, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 4, 'OT', 'Ада родила Исаву Елифаза, а Васемафа родила Рагуила.'),
(1046, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 5, 'OT', 'Оголивама родила Иеуша, и Иалама, и Корея; это сыновья Исава, которые родились ему в земле Ханаанской.'),
(1047, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 6, 'OT', 'И взял Исав жён своих и сыновей своих, и дочерей своих, и всех людей дома своего, и скот свой, и весь скот свой, и всё имение своё, которое приобрёл в земле Ханаанской, и пошёл в землю от лица Иакова, брата своего.'),
(1048, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 7, 'OT', 'Ибо имущество их было так велико, что они не могли жить вместе, и земля странствия их не могла вместить их из-за скота их.'),
(1049, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 8, 'OT', 'И поселился Исав на горе Сеир; Исав — это Идумея.'),
(1050, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 9, 'OT', 'И вот родословие Исава, отца Идумеи, на горе Сеир.'),
(1051, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 10, 'OT', 'Вот имена сыновей Исава: Елифаз, сын Ады, жены Исава; Рагуил, сын Васемафы, жены Исава.'),
(1052, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 11, 'OT', 'И были сыновья Елифаза: Феман, Омар, Цефо, Гафам и Кеназ.'),
(1053, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 12, 'OT', 'Фамарь была наложницей Елифаза, сына Исава, и родила Елифазу Амалика; это сыновья Ады, жены Исава.'),
(1054, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 13, 'OT', 'И вот сыновья Рагуила: Нахаф и Зерах, Шамма и Мицца; это были сыновья Васемафы, жены Исава.'),
(1055, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 14, 'OT', 'И вот были сыновья Оголивамы, дочери Аны, дочери Цивеона, жены Исава; и она родила Исаву Иеуша, и Иалама, и Корея.'),
(1056, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 15, 'OT', 'Вот вожди сыновей Исава: сыновья Елифаза, первенца Исава: вождь Феман, вождь Омар, вождь Цефо, вождь Кеназ.'),
(1057, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 16, 'OT', 'Вождь Корей, вождь Гафам, вождь Амалик: это вожди Елифаза в земле Идумеи; это сыновья Ады.'),
(1058, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 17, 'OT', 'И вот сыновья Рагуила, сына Исава: вождь Нахаф, вождь Зерах, вождь Шамма, вождь Мицца; это вожди Рагуила в земле Идумеи; это сыновья Васемафы, жены Исава.'),
(1059, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 18, 'OT', 'И вот сыновья Оголивамы, жены Исава: вождь Иеуш, вождь Иалам, вождь Корей; это вожди Оголивамы, дочери Аны, жены Исава.'),
(1060, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 19, 'OT', 'Вот эти сыновья Исава, и вот их вожди: он — Идумея.'),
(1061, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 20, 'OT', 'Вот сыновья Сеира Хоррея, жители земли той: Лотан и Шовал, и Цивеон, и Ана.'),
(1062, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 21, 'OT', 'Дишон, и Ецер, и Дишан — это вожди Хорреев, сыновья Сеира, в земле Идумеи.'),
(1063, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 22, 'OT', 'Сыновья Лотана: Хори и Еман, и сестра Лотана — Фамарь.'),
(1064, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 23, 'OT', 'И вот сыновья Шовала: Алван и Манахаф, и Евал, Шефо и Онам.'),
(1065, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 24, 'OT', 'И вот сыновья Цивеона: Аия и Ана; это тот Ана, который нашёл мулов в пустыне, когда пас ослов Цивеона, отца своего.'),
(1066, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 25, 'OT', 'И вот сыновья Аны: Дишон; и Оголивама, дочь Аны.'),
(1067, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 26, 'OT', 'И вот сыновья Дишана: Хемдан, и Ешбан, и Ифран, и Херан.'),
(1068, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 27, 'OT', 'Вот сыны Ецера: Вилган, Зааван и Акан.'),
(1069, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 28, 'OT', 'Вот сыновья Дишана: Уц и Аран.'),
(1070, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 29, 'OT', 'Вот вожди Хорреев: вождь Лотан, вождь Шовал, вождь Цивеон, вождь Ана.'),
(1071, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 30, 'OT', 'Вождь Дишон, вождь Ецер, вождь Дишан: это вожди Хори, по их вождям, в земле Сеир.'),
(1072, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 31, 'OT', 'И вот цари, которые царствовали в земле Идумеи прежде, чем воцарился царь у сынов Израиля.'),
(1073, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 32, 'OT', 'И царствовал в Идумее Вала, сын Веора, и имя города его Динхава.'),
(1074, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 33, 'OT', 'И умер Вала, и воцарился вместо него Иовав, сын Зераха из Боцры.'),
(1075, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 34, 'OT', 'И умер Иовав, и воцарился вместо него Хушам из земли Феманитянина.'),
(1076, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 35, 'OT', 'И умер Хушам, и воцарился вместо него Адад, сын Ведада, который поразил Мадиана на поле Моава; и имя города его — Авиф.'),
(1077, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 36, 'OT', 'Умер Адад, и воцарился вместо него Самла из Масреки.'),
(1078, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 37, 'OT', 'И умер Самла, и воцарился вместо него Саул из Реховофа, что при реке.'),
(1079, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 38, 'OT', 'Умер Саул, и воцарился вместо него Ваалханан, сын Ахбора.'),
(1080, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 39, 'OT', 'И умер Ваалханан, сын Ахбора, и воцарился вместо него Адар, и имя города его — Пау, и имя жены его — Мегетавел, дочь Мареда, дочь Мезахава.'),
(1081, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 40, 'OT', 'И вот имена вождей Исава по их семействам, по их местам, по их именам: вождь Фамарь, вождь Алва, вождь Иефеф.'),
(1082, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 41, 'OT', 'вождь Оголивама, вождь Ела, вождь Пинон'),
(1083, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 42, 'OT', 'вождь Кеназ, вождь Феман, вождь Мивцар'),
(1084, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 36, 43, 'OT', 'Вождь Магдиил, вождь Ирам; это вожди Идумеи по их жилищам в земле их владения; это Исав, отец Идумеи.'),
(1085, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 1, 'OT', 'Иаков жил в земле странствий отца своего, в земле Ханаанской.'),
(1086, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 2, 'OT', 'Вот родословие Иакова: Иосиф, сын семнадцати лет, пас овец вместе с братьями своими, и он был отроком при сыновьях Валлы и при сыновьях Зелфы, жён отца своего; и донёс Иосиф клевету их злую до отца их.'),
(1087, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 3, 'OT', 'Израиль любил Иосифа больше всех своих сыновей, потому что он был сыном его старости, и сделал ему хитон из разноцветной одежды.'),
(1088, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 4, 'OT', 'И видели братья его, что отец их любит его более всех братьев его, и возненавидели его, и не могли говорить с ним мирно.'),
(1089, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 5, 'OT', 'Иосиф видел сон и рассказал его братьям, и они ещё больше возненавидели его.'),
(1090, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 6, 'OT', 'И сказал им: послушайте же это сновидение, которое я видел.'),
(1091, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 7, 'OT', 'Вот, мы вяжем снопы посреди поля, и вот, мой сноп встал и стал прямо, и вот, ваши снопы окружили его и поклонились моему снопу.'),
(1092, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 8, 'OT', 'И сказали ему братья его: неужели ты будешь царствовать над нами, или будешь владычествовать над нами? И прибавили ещё ненавидеть его за сны его и за слова его.'),
(1093, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 9, 'OT', 'И снова видел он другой сон, и рассказал его братьям своим, и сказал: вот, я видел ещё сон: вот, солнце и луна и одиннадцать звёзд поклоняются мне.'),
(1094, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 10, 'OT', 'И рассказал он отцу своему и братьям своим, и упрекнул его отец его, и сказал ему: что это за сон, который ты видел? Неужели я и мать твоя и братья твои придём поклониться тебе до земли?'),
(1095, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 11, 'OT', 'И завидовали ему братья его, а отец его сохранил это слово.'),
(1096, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 12, 'OT', 'И пошли братья его пасти овец отца своего в Сихеме.'),
(1097, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 13, 'OT', 'И сказал Израиль Иосифу: не братья ли твои пасут в Сихеме? Пойди, и я пошлю тебя к ним. И сказал он ему: вот я.'),
(1098, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 14, 'OT', 'И сказал ему: пойди, посмотри на благополучие братьев твоих и на благополучие овец, и принеси мне слово. И послал его из долины Хеврона, и пришёл он в Сихем.'),
(1099, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 15, 'OT', 'И нашёл его человек, и вот, он блуждал в поле; и спросил его тот человек, говоря: что ты ищешь?'),
(1100, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 16, 'OT', 'Я ищу братьев моих; скажи мне, пожалуйста, где они пасут.'),
(1101, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 17, 'OT', 'Человек сказал: они ушли отсюда, ибо я слышал, как они говорили: пойдём в Дофан. И пошёл Иосиф за братьями своими, и нашёл их в Дофане.'),
(1102, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 18, 'OT', 'И увидели они его издалека, и прежде чем он приблизился к ним, замыслили против него, чтобы умертвить его.'),
(1103, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 19, 'OT', 'И сказали человек брату своему: вот, этот владелец снов (имеющий сны) пришёл.'),
(1104, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 20, 'OT', 'Итак, пойдите, убьём его и бросим в один из колодезей, и скажем: злой зверь съел его, и посмотрим, что будет с его снами.'),
(1105, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 21, 'OT', 'Рувим услышал и избавил его от руки их, и сказал: не лишим его жизни.'),
(1106, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 22, 'OT', 'И сказал им Рувим: не проливайте крови; бросьте его в этот колодезь, который в пустыне, и не налагайте на него руки, чтобы избавить его от рук их и возвратить его к отцу его.'),
(1107, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 23, 'OT', 'И было, когда пришёл Иосиф к братьям своим, они сняли с Иосифа хитон его, хитон разноцветный, который был на нём.'),
(1108, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 24, 'OT', 'И взяли его и бросили его в колодезь; а колодезь был пуст, воды в нём не было.'),
(1109, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 25, 'OT', 'И сели они есть хлеб, и подняли глаза свои, и увидели: вот, караван Измаильтян идёт из Галаада, и верблюды их несут пряности, бальзам и мирру, идут, чтобы доставить это в Египет.'),
(1110, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 26, 'OT', 'И сказал Иуда братьям своим: какая корысть, если мы убьём брата нашего и скроем кровь его?'),
(1111, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 27, 'OT', 'Пойдём, и продадим его Измаильтянам, а рука наша да не будет на нём, ибо он брат наш, плоть наша; и послушали его братья.'),
(1112, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 28, 'OT', 'Проходили люди Мадианитяне, купцы, и вытащили и подняли Иосифа из колодезя, и продали Иосифа Измаильтянам за двадцать серебряных монет, и привели Иосифа в Египет.'),
(1113, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 29, 'OT', 'И возвратился Рувим к яме, и вот, нет Иосифа в яме, и разодрал он одежду свою.'),
(1114, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 30, 'OT', 'И возвратился он к братьям своим и сказал: дитя нет его, а я — куда я иду?'),
(1115, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 31, 'OT', 'И взяли они хитон Иосифа, и закололи козла из коз, и окунули хитон в кровь.'),
(1116, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 32, 'OT', 'И послали они разноцветную одежду, и принесли её к отцу своему, и сказали: это мы нашли; узнай, хитон ли это сына твоего, или нет.'),
(1117, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 33, 'OT', 'Хитон сына моего; зверь съел его; растерзан, растерзан Иосиф.'),
(1118, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 34, 'OT', 'И разодрал Иаков одежды свои, и возложил вретище на чресла свои, и оплакивал сына своего многие дни.'),
(1119, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 35, 'OT', 'И поднялись все сыновья его и все дочери его, чтобы утешить его, но он отказался утешиться и сказал: ибо сойду к сыну моему, оплакивая, в ад; и плакал о нём отец его.'),
(1120, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 37, 36, 'OT', 'Мадианитяне продали его в Египет Потифару, евнуху фараона, начальнику телохранителей.'),
(1121, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 1, 'OT', 'И было в то время: сошёл Иуда от братьев своих и пришёл до человека Адолламитянина, имя которому Хира.'),
(1122, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 2, 'OT', 'И увидел там Иуда дочь человека Хананеянина, и имя его Шуа, и взял её, и вошёл к ней.'),
(1123, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 3, 'OT', 'Она зачала и родила сына, и он назвал его имя Ир.'),
(1124, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 4, 'OT', 'И снова она зачала и родила сына, и нарекла ему имя Онан.'),
(1125, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 5, 'OT', 'И ещё родила сына и нарекла ему имя Шела; и было это в Хезиве, когда она родила его.'),
(1126, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 6, 'OT', 'И взял Иуда жену Иру, первенцу своему, и имя ей Фамарь.'),
(1127, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 7, 'OT', 'Ир, первенец Иуды, был зол в очах Господа, и Господь умертвил его.'),
(1128, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 8, 'OT', 'И сказал Иуда Онану: войди к жене брата твоего и соверши левиратный брак с нею, и восстанови семя брату твоему.'),
(1129, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 9, 'OT', 'Онан знал, что семя будет не ему, и когда входил к жене брата своего, изливал на землю, чтобы не дать семени брату своему.'),
(1130, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 10, 'OT', 'И было зло в глазах Господа то, что он сделал, и умертвил Он также и его.'),
(1131, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 11, 'OT', 'И сказал Иуда Фамари, невестке своей: живи вдовою в доме отца твоего, пока не вырастет Шела, сын мой; ибо он сказал: как бы не умер и он, как братья его. И пошла Фамарь, и жила в доме отца своего.'),
(1132, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 12, 'OT', 'И умножились дни, и умерла дочь Шуи, жена Иуды; и утешился Иуда, и поднялся к стригущим овец своих, он и Хира, ближний его, Адолламитянин, в Фамну.'),
(1133, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 13, 'OT', 'И было возвещено Фамари: вот, тёсть твой восходит в Фамну стричь овец своих.'),
(1134, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 14, 'OT', 'Она сняла с себя одежду вдовства, покрылась покрывалом и закрыла лицо, и села у входа в Енаим, что на пути в Фамну; ибо она видела, что Шела вырос, но она не была дана ему в жёны.'),
(1135, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 15, 'OT', 'Иуда увидел её и посчитал её блудницей, потому что она закрыла своё лицо.'),
(1136, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 16, 'OT', 'Он свернул к ней на путь и сказал: «Дай мне войти к тебе», ибо не знал, что она его невестка. И она сказала: «Что ты дашь мне, если войдёшь ко мне?»'),
(1137, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 17, 'OT', 'Он сказал: я пришлю козлёнка из стада овец. И она сказала: дашь ли ты залог, пока не пришлёшь?'),
(1138, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 18, 'OT', 'Он сказал: что за залог, который я дам тебе? И она сказала: твою печать, и твой шнур, и твой жезл, который в твоей руке. И он дал ей, и вошёл к ней, и она зачала от него.'),
(1139, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 19, 'OT', 'Она встала, и пошла, и сняла с себя покрывало, и надела одежды вдовства своего.'),
(1140, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 20, 'OT', 'И послал Иуда козлёнка от коз через руку ближнего своего, Адолламитянина, чтобы взять залог из рук жены, и не нашёл её.'),
(1141, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 21, 'OT', 'И спросил он людей места её, говоря: где блудница, которая была в Енаиме при пути? И сказали: не было здесь блудницы.'),
(1142, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 22, 'OT', 'И возвратился он к Иуде и сказал: не нашёл её, и также люди того места сказали: не было здесь блудницы.'),
(1143, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 23, 'OT', 'Иуда сказал: пусть она возьмёт себе, чтобы нам не быть в презрении; вот, я послал этого козлёнка, но ты не нашёл её.'),
(1144, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 24, 'OT', 'И было около трёх месяцев, и сказали Иуде, говоря: согрешила блудом Фамарь, невестка твоя, и вот, она беременна от блуда. И сказал Иуда: выведите её, и пусть она будет сожжена.'),
(1145, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 25, 'OT', 'Она была выведена, и она послала к своему тёстю сказать: «Я беременна от человека, которому принадлежат эти вещи». И сказала: «Узнай же, чей это перстень, и шнур, и жезл».'),
(1146, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 26, 'OT', 'Иуда узнал и сказал: она правее меня, потому что я не дал её Шеле, сыну моему. И не познал её более.'),
(1147, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 27, 'OT', 'И было во время родов её, и вот, близнецы в чреве её.'),
(1148, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 28, 'OT', 'И было при родах её, и он протянул руку, и взяла повивальная бабка и привязала к руке его багрянец, говоря: этот вышел первым.'),
(1149, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 29, 'OT', 'И было, когда он возвращал руку свою, вот, вышел брат его, и она сказала: как ты проломил себе пролом! И нарекли имя ему Фарес.'),
(1150, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 38, 30, 'OT', 'И вышел после брат его, на руке которого была багряная нить, и нарекли ему имя Зерах.'),
(1151, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 1, 'OT', 'Иосиф был отведён в Египет, и купил его Потифар, евнух фараона, начальник телохранителей, человек Египтянин, из руки Измаильтян, которые привели его туда.'),
(1152, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 2, 'OT', 'И был Господь с Иосифом, и был он человеком преуспевающим, и был он в доме господина своего, Египтянина.'),
(1153, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 3, 'OT', 'И увидел господин его, что Господь с ним, и всё, что он делает, Господь делает успешным в руке его.'),
(1154, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 4, 'OT', 'И нашёл Иосиф благодать в очах его, и служил ему, и поставил его над домом своим, и всё, что имел, отдал в руку его.'),
(1155, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 5, 'OT', 'И было с того времени, как он поставил его над домом своим и над всем, что у него было, благословил Господь дом Египтянина ради Иосифа; и было благословение Господне на всём, что у него было, в доме и в поле.'),
(1156, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 6, 'OT', 'И оставил всё, что имел, в руке Иосифа, и не знал он с ним ничего, кроме хлеба, который он ел; и был Иосиф красив видом и красив видом.'),
(1157, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 7, 'OT', 'И было после этих слов, и подняла жена господина его очи свои на Иосифа, и сказала: ляг со мною.'),
(1158, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 8, 'OT', 'Он отказался и сказал жене своего господина: вот, господин мой не знает, что со мной в доме, и всё, что у него есть, отдал в мою руку.'),
(1159, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 9, 'OT', 'Нет никого больше меня в этом доме, и он не утаил от меня ничего, кроме тебя, потому что ты жена его; как же я совершу это великое зло и согрешу пред Богом?'),
(1160, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 10, 'OT', 'И было, когда она говорила Иосифу день за днём, он не слушал её, чтобы лечь с нею и быть с нею.'),
(1161, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 11, 'OT', 'И было в тот день, и вошёл он в дом делать работу свою, и не было ни одного человека из людей дома там в доме.'),
(1162, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 12, 'OT', 'Она схватила его за одежду, говоря: «Ляг со мной», — но он оставил свою одежду в руке её, и побежал, и вышел на улицу.'),
(1163, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 13, 'OT', 'И было, когда она увидела, что он оставил свою одежду в руке её, и побежал наружу.'),
(1164, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 14, 'OT', 'Она позвала людей своего дома и сказала им: «Смотрите, он привёл к нам человека-Еврея, чтобы посмеяться над нами; он пришёл ко мне, чтобы лечь со мной, и я закричала громким голосом».'),
(1165, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 15, 'OT', 'И когда он услышал, что я подняла голос мой и закричала, он оставил одежду свою у меня и побежал, и вышел на улицу.'),
(1166, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 16, 'OT', 'И она оставила его одежду у себя, пока не пришёл господин его в дом свой.'),
(1167, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 17, 'OT', 'И она говорила ему такие слова: пришёл ко мне раб, Еврей, которого ты привёл к нам, чтобы посмеяться надо мной.'),
(1168, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 18, 'OT', 'И было, когда я подняла голос мой и закричала, он оставил одежду свою у меня и убежал на улицу.'),
(1169, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 19, 'OT', 'И было: когда господин его услышал слова жены своей, которые она говорила ему, говоря: «такие слова сделал мне раб твой», — воспылал гнев его.'),
(1170, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 20, 'OT', 'Господин Иосифа взял его и отдал его в дом темницы, место, где узники царя были заключены; и был он там в доме темницы.'),
(1171, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 21, 'OT', 'И был Господь с Иосифом, и простер к нему милость, и дал ему благодать в очах начальника дома темницы.'),
(1172, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 22, 'OT', 'Начальник дома темницы передал в руку Иосифа всех узников, которые были в доме темницы, и всё, что они там делали, он делал.'),
(1173, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 39, 23, 'OT', 'Начальник дома темницы не видел в руке его ничего, потому что Господь был с ним, и что он делал, Господь делал успешным.'),
(1174, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 1, 'OT', 'И было после этих слов: согрешили виночерпий царя Египетского и пекарь пред господином своим, царём Египетским.'),
(1175, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 2, 'OT', 'Разгневался фараон на двух своих евнухов, на начальника виночерпиев и на начальника пекарей.'),
(1176, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 3, 'OT', 'И отдал их под стражу в дом начальника телохранителей, в дом темницы, на место, где Иосиф был заключён.'),
(1177, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 4, 'OT', 'Князь поваров поручил Иосифа им, и он прислуживал им; и были дни в заключении.'),
(1178, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 5, 'OT', 'И видели сон оба они, каждый человек сон свой в одну ночь, каждый человек согласно истолкованию сна своего, виночерпий и пекарь, которые принадлежали царю Египта, которые были заключены в доме темницы.'),
(1179, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 6, 'OT', 'И пришёл к ним Иосиф утром, и увидел их, и вот они были мрачны.'),
(1180, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 7, 'OT', 'И спросил он евнухов фараона, которые были с ним под стражей в доме господина его, говоря: почему лица ваши печальны сегодня?'),
(1181, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 8, 'OT', 'И сказали они ему: сон снили мы, и истолкователя нет у него. И сказал им Иосиф: не у Бога ли истолкования? Расскажите же мне.'),
(1182, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 9, 'OT', 'И рассказал начальник виночерпиев свой сон Иосифу и сказал ему: во сне моём, и вот виноградная лоза перед лицом моим.'),
(1183, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 10, 'OT', 'И на виноградной лозе было три ветви; и она, распускаясь, подняла свой цветок, созрели гроздья её в виноград.'),
(1184, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 11, 'OT', 'И чаша фараона в руке моей, и я взял виноград, и выжал их в чашу фараона, и отдал чашу на ладонь фараона.'),
(1185, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 12, 'OT', 'И сказал ему Иосиф: вот истолкование его: три ветви — это три дня.'),
(1186, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 13, 'OT', 'Ещё через три дня фараон поднимет твою голову и возвратит тебя на твоё основание, и ты подашь чашу фараона в его руку, по прежнему обычаю, когда ты был его виночерпием.'),
(1187, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 14, 'OT', 'Но вспомни обо мне, когда будет хорошо тебе, и сделай, пожалуйста, милость со мною, и упомяни меня фараону, и выведи меня из этого дома.'),
(1188, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 15, 'OT', 'Ибо я был украден из земли Евреев, и также здесь я не сделал ничего, за что посадили бы меня в темницу.'),
(1189, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 16, 'OT', 'И увидел начальник пекарей, что хорошо истолковал он, и сказал Иосифу: и я в сне моём, и вот, три корзины белых на голове моей.'),
(1190, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 17, 'OT', 'И в верхней корзине — всякая пища фараона, изделие пекаря, и птица ела их из корзины над моей главой.'),
(1191, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 18, 'OT', 'И ответил Иосиф и сказал: вот истолкование его: три корзины — это три дня.'),
(1192, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 19, 'OT', 'Ещё через три дня фараон поднимет твою голову с тебя и повесит тебя на дерево, и птица съест твою плоть с тебя.'),
(1193, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 20, 'OT', 'И было на третий день, день рождения фараона, и он устроил пир для всех рабов своих, и поднял голову начальника виночерпиев и голову начальника пекарей среди рабов своих.'),
(1194, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 21, 'OT', 'И возвратил начальника виночерпиев на его виночерпие, и дал чашу в ладонь фараона.'),
(1195, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 22, 'OT', 'А начальника пекарей повесил, как истолковал им Иосиф.'),
(1196, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 40, 23, 'OT', 'И не вспомнил начальник виночерпиев об Иосифе и забыл его.'),
(1197, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 1, 'OT', 'По прошествии двух лет дней, фараону снилось, и вот, он стоит над рекой.'),
(1198, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 2, 'OT', 'И вот, из реки выходят семь коров, красивых видом и тучных плотью, и паслись они на лугу.'),
(1199, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 3, 'OT', 'И вот, семь других коров выходят из реки вслед за ними, худые видом и тощие плотью, и стали они рядом с теми коровами на берегу реки.'),
(1200, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 4, 'OT', 'И поели коровы худые видом и тощие плотью семь коров красивых видом и тучных, и пробудился фараон.'),
(1201, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 5, 'OT', 'И заснул он, и увидел сон во второй раз: вот, семь колосьев поднимаются на одном тростнике, полные и хорошие.'),
(1202, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 6, 'OT', 'И вот, семь колосьев тощих и опалённых востоком, выросших после них.'),
(1203, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 7, 'OT', 'Тощие колосья поглотили семь колосьев тучных и полных, и пробудился фараон, и вот, это был сон.'),
(1204, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 8, 'OT', 'И было утром, и смутился дух его, и послал он, и призвал всех чародеев Египта и всех мудрецов его, и рассказал фараон им сон свой, и не было толкующего их фараону.'),
(1205, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 9, 'OT', 'И сказал начальник виночерпиев фараону, говоря: грехи мои я вспоминаю сегодня.'),
(1206, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 10, 'OT', 'Фараон разгневался на рабов своих и отдал меня под стражу в дом начальника телохранителей, меня и начальника пекарей.'),
(1207, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 11, 'OT', 'И приснился нам сон в одну ночь, мне и ему; каждому человеку снился сон по истолкованию его сна.'),
(1208, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 12, 'OT', 'И был там с нами отрок Еврей, раб начальника телохранителей; и мы рассказали ему, и он истолковал нам наши сны: каждому человеку по его сну истолковал.'),
(1209, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 13, 'OT', 'И было: как он истолковал нам, так и случилось — меня возвратил на моё основание, а его повесил.'),
(1210, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 14, 'OT', 'Послал фараон и призвал Иосифа, и поспешно вывели его из темницы; и он обрился, и переменил одежды свои, и пришёл к фараону.'),
(1211, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 15, 'OT', 'Фараон сказал Иосифу: сон я видел, и нет толкователя ему; а о тебе я слышал, что ты слышишь сон, чтобы истолковать его.'),
(1212, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 16, 'OT', 'И ответил Иосиф фараону, говоря: не от меня; Бог даст ответ о благополучии фараона.'),
(1213, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 17, 'OT', 'И сказал фараон Иосифу: в сне моём, вот, я стою на берегу реки.'),
(1214, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 18, 'OT', 'И вот, из реки выходят семь коров, тучных плотью и красивых видом, и пасутся на лугу.'),
(1215, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 19, 'OT', 'И вот, семь коров других выходят после них, тощие и злые видом весьма, и худые плотью; не видал я таких во всей земле Египетской для зла.'),
(1216, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 20, 'OT', 'И съели тощие и худые коровы семь первых тучных коров.'),
(1217, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 21, 'OT', 'И вошли они в их утробу, и не было видно, что они вошли в их утробу, и вид их был худ, как в начале; и я пробудился.'),
(1218, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 22, 'OT', 'И я видел во сне: вот, семь колосьев поднимались на одном тростнике, полные и хорошие.'),
(1219, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 23, 'OT', 'И вот, семь колосьев тощих и иссохших, опалённых востоком, выросших после них.'),
(1220, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 24, 'OT', 'И поглотили тощие колосья семь тучных колосьев; и сказал я чародеям, но никто не объяснил мне.'),
(1221, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 25, 'OT', 'И сказал Иосиф фараону: сон фараона один есть; то, что Бог делает, Он возвестил фараону.'),
(1222, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 26, 'OT', 'Семь коров хороших — это семь лет, и семь колосьев хороших — это семь лет; это один сон.'),
(1223, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 27, 'OT', 'И семь коров тощих и худых, выходящих после них, — это семь лет; и семь колосьев пустых, опалённых востоком, будут семь лет голода.'),
(1224, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 28, 'OT', 'Это то слово, которое я сказал фараону: что Бог делает, то Он показал фараону.'),
(1225, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 29, 'OT', 'Вот, наступают семь лет великого изобилия во всей земле Египетской.'),
(1226, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 30, 'OT', 'И наступят семь лет голода после них, и забудется всё изобилие в земле Египетской, и истощит голод землю.'),
(1227, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 31, 'OT', 'И не будет узнано изобилие на земле из-за того голода, который после этого, ибо он очень тяжёл.'),
(1228, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 32, 'OT', 'А что сон повторился фараону два раза, это потому, что слово определено у Бога, и Бог скоро исполнит его.'),
(1229, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 33, 'OT', 'И ныне пусть фараон усмотрит человека разумного и мудрого, и поставит его над землёю Египетскою.'),
(1230, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 34, 'OT', 'Пусть фараон сделает это и назначит надзирателей над землёю, и пусть он соберёт пятую часть земли Египетской в семь лет изобилия.'),
(1231, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 35, 'OT', 'И пусть соберут всю пищу этих наступающих хороших годов, и пусть складывают зерно под власть фараона, пищу по городам, и пусть хранят.'),
(1232, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 36, 'OT', 'И будет пища в поклажу для земли на семь лет голода, который будет в земле Египетской, и не погибнет земля от голода.'),
(1233, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 37, 'OT', 'И понравилось слово это в очах фараона и в очах всех рабов его.'),
(1234, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 38, 'OT', 'И сказал фараон рабам своим: найдётся ли такой человек, в котором был бы дух Божий?'),
(1235, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 39, 'OT', 'И сказал фараон Иосифу: после того как Бог открыл тебе всё это, нет никого столь разумного и мудрого, как ты.'),
(1236, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 40, 'OT', 'Ты будешь над домом моим, и по слову твоему будет целовать весь народ мой; только престолом я буду больше тебя.'),
(1237, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 41, 'OT', 'И сказал фараон Иосифу: вот, я поставил тебя над всею землёю Египетскою.'),
(1238, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 42, 'OT', 'Снял фараон перстень свой с руки своей и дал его на руку Иосифа, и одел его в одежды из виссона, и возложил золотую цепочку на шею его.'),
(1239, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 43, 'OT', 'И посадил его на колесницу вторую, которая была у него, и провозглашали пред лицом его: «Абрех!» — и поставил его над всею землёю Египетскою.'),
(1240, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 44, 'OT', 'И сказал фараон Иосифу: я фараон; и без тебя не поднимет человек руки своей и ноги своей во всей земле Египетской.'),
(1241, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 45, 'OT', 'И нарек фараон имя Иосифу: Цафнаф-панеах, и дал ему Асенефу, дочь Потифера, священника Она, в жену; и вышел Иосиф над землею Египетскою.'),
(1242, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 46, 'OT', 'Иосиф был сыном тридцати лет, когда предстал пред лицом фараона, царя Египта; и вышел Иосиф от лица фараона и прошёл по всей земле Египетской.'),
(1243, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 47, 'OT', 'И земля в семь лет изобилия приносила по горсти.'),
(1244, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 48, 'OT', 'И собрал он всю пищу семь годов, которые были в земле Египетской, и дал пищу в городах; пищу поля города, которое вокруг него, дал в середине его.'),
(1245, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 49, 'OT', 'Иосиф собрал зерно, как песок морской, чрезвычайно много, так что перестал считать, ибо не было числа.'),
(1246, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 50, 'OT', 'И у Иосифа родились два сына прежде, чем наступил год голода, которых родила ему Асенефа, дочь Потифера, священника из Она.'),
(1247, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 51, 'OT', 'Иосиф нарек имя первенцу Манассия, потому что Бог дал мне забыть весь труд мой и весь дом отца моего.'),
(1248, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 52, 'OT', 'Имя второго он назвал Ефрем, потому что Бог размножил меня в земле бедствия моего.'),
(1249, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 53, 'OT', 'И кончились семь лет изобилия, которое было в земле Египетской.'),
(1250, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 54, 'OT', 'И начались семь лет голода, как сказал Иосиф; и был голод во всех землях, а во всей земле Египетской был хлеб.'),
(1251, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 55, 'OT', 'И вся земля Египетская голодала, и народ воззвал к фараону о хлебе, и сказал фараон всем египтянам: идите к Иосифу, и что он скажет вам, то делайте.'),
(1252, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 56, 'OT', 'И был голод по всему лицу земли; и открыл Иосиф всё, что было в них, и продавал египтянам, и усилился голод в земле Египетской.'),
(1253, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 41, 57, 'OT', 'И вся земля приходила в Египет к Иосифу покупать хлеб, ибо голод усилился по всей земле.'),
(1254, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 1, 'OT', 'Иаков увидел, что есть хлеб в Египте, и сказал Иаков сыновьям своим: зачем вы смотрите друг на друга?'),
(1255, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 2, 'OT', 'И сказал: вот, я слышал, что есть хлеб в Египте; пойдите туда и купите нам оттуда хлеба, чтобы нам жить и не умереть.'),
(1256, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 3, 'OT', 'И спустились братья Иосифа, десятеро, чтобы купить зерно из Египта.'),
(1257, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 4, 'OT', 'Вениамина же, брата Иосифа, не послал Иаков с братьями его, ибо сказал: как бы не постигла его беда.'),
(1258, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 5, 'OT', 'Сыновья Израиля пришли покупать хлеб среди приходящих, ибо был голод в земле Ханаанской.'),
(1259, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 6, 'OT', 'Иосиф был правителем над землёю; он продавал зерно всему народу земли. И пришли братья Иосифа и поклонились ему лицом до земли.'),
(1260, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 7, 'OT', 'Иосиф увидел братьев своих и узнал их, но сделал себя неузнаваемым для них, и говорил с ними сурово, и сказал им: откуда вы пришли? Они сказали: из земли Ханаанской, чтобы купить пищи.'),
(1261, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 8, 'OT', 'Иосиф узнал своих братьев, а они не узнали его.'),
(1262, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 9, 'OT', 'И вспомнил Иосиф сны, которые он видел о них, и сказал им: вы соглядатаи, чтобы увидеть слабое место земли вы пришли.'),
(1263, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 10, 'OT', 'Они сказали ему: нет, господин мой, но рабы твои пришли купить пищу.'),
(1264, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 11, 'OT', 'Мы все сыновья одного человека; мы честные люди, рабы твои не были соглядатаями.'),
(1265, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 12, 'OT', 'И сказал он им: нет, но слабое место земли вы пришли посмотреть.'),
(1266, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 13, 'OT', 'Двенадцать рабов твоих, братья мы, сыновья одного человека в земле Ханаанской; и вот, младший с отцом нашим сегодня, а одного нет.'),
(1267, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 14, 'OT', 'И сказал им Иосиф: это то, что я говорил вам, говоря: вы соглядатаи.'),
(1268, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 15, 'OT', 'Этим вы будете испытаны: клянусь жизнью фараона, вы не выйдете отсюда, пока не придёт сюда ваш младший брат.'),
(1269, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 16, 'OT', 'Пошлите одного из вас, и пусть он приведёт брата вашего, а вы будете заключены, и проверятся слова ваши: истина ли с вами; а если нет, то, клянусь жизнью фараона, вы — соглядатаи.'),
(1270, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 17, 'OT', 'И собрал их под стражу на три дня.'),
(1271, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 18, 'OT', 'И сказал им Иосиф на третий день: это сделайте, и будете жить; Бога я боюсь.'),
(1272, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 19, 'OT', 'Если вы честны, то один брат ваш пусть будет заключён в доме стражи вашей, а вы идите, привезите хлеб для голода домов ваших.'),
(1273, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 20, 'OT', 'Приведите вашего младшего брата ко мне, и подтвердятся ваши слова, и вы не умрёте. И они сделали так.'),
(1274, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 21, 'OT', 'И сказали они друг другу: поистине мы виновны перед братом нашим, ибо видели скорбь души его, когда он умолял нас, и не послушали; потому и постигла нас эта скорбь.'),
(1275, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 22, 'OT', 'Рувим ответил им, говоря: не говорил ли я вам, говоря: не грешите против дитяти? И вы не послушали; и вот, кровь его взыскивается.'),
(1276, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 23, 'OT', 'Они не знали, что Иосиф слышит, ибо переводчик был между ними.'),
(1277, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 24, 'OT', 'И отвернулся от них и заплакал, и возвратился к ним, и говорил с ними, и взял от них Симеона, и связал его пред очами их.'),
(1278, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 25, 'OT', 'И приказал Иосиф, и наполнили сосуды их зерном, и возвратить серебро каждого человека во вретище его, и дать им продовольствие на путь; и сделал им так.'),
(1279, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 26, 'OT', 'И подняли они свой хлеб на ослов своих, и пошли оттуда.'),
(1280, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 27, 'OT', 'И открыл один из них вретище своё, чтобы дать корм ослу своему в гостинице, и увидел серебро своё, и вот оно в отверстии мешка его.'),
(1281, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 28, 'OT', 'И сказал он братьям своим: деньги мои возвращены, и вот они в мешке моём. И вышло сердце их, и они трепетали, говоря друг другу, человек брату своему: что это сделал Бог нам?'),
(1282, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 29, 'OT', 'И пришли они к Иакову, отцу своему, в землю Ханаанскую, и рассказали ему всё, что случилось с ними, говоря:'),
(1283, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 30, 'OT', 'Человек, господин земли, говорил с нами сурово и принял нас за соглядатаев земли.'),
(1284, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 31, 'OT', 'Мы сказали ему: мы честные, мы не были соглядатаями.'),
(1285, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 32, 'OT', 'Нас двенадцать братьев, сыновей отца нашего; одного нет, а младший сегодня с отцом нашим в земле Ханаанской.'),
(1286, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 33, 'OT', 'И сказал нам тот человек, господин земли: вот как я узнаю, что вы честны: оставьте у меня одного из ваших братьев, а голод домов ваших возьмите и идите.'),
(1287, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 34, 'OT', 'И приведите вашего младшего брата ко мне, и я узнаю, что вы не соглядатаи, а честные люди; брата вашего я отдам вам, и землю вы будете торговать.'),
(1288, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 35, 'OT', 'И было: когда они опорожняли свои вретища, вот, у каждого человека мешок денег его во вретище его; и увидели они мешки денег своих, они и отец их, и испугались.'),
(1289, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 36, 'OT', 'И сказал им Иаков, отец их: меня вы лишили детей; Иосифа нет, и Симеона нет, и Вениамина вы хотите взять; всё это на меня.'),
(1290, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 37, 'OT', 'И сказал Рувим отцу своему, говоря: двух сыновей моих умертви, если не приведу его к тебе; отдай его на руку мою, и я возвращу его тебе.'),
(1291, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 42, 38, 'OT', 'И сказал он: не пойдёт сын мой с вами, потому что брат его умер, и он остался один отдельно; и постигнет его беда на пути, которым вы пойдёте, и сведёте вы седину мою с печалью в ад.'),
(1292, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 1, 'OT', 'Голод был тяжёл на земле.'),
(1293, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 2, 'OT', 'И было, когда они доели хлеб, который привезли из Египта, отец их сказал им: возвращайтесь, купите нам немного пищи.'),
(1294, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 3, 'OT', 'И сказал ему Иуда, говоря: засвидетельствовал нам тот человек, говоря: не увидите лица моего, если не будет брат ваш с вами.'),
(1295, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 4, 'OT', 'Если ты пошлёшь нашего брата с нами, мы сойдём и купим тебе пищи.'),
(1296, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 5, 'OT', 'А если ты не пошлёшь его, мы не пойдём, потому что тот человек сказал нам: не увидите лица моего, если брат ваш не будет с вами.'),
(1297, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 6, 'OT', 'Израиль сказал: зачем вы сделали мне зло, сказав человеку, что у вас есть ещё брат?'),
(1298, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 7, 'OT', 'И сказали они: расспрашивал человек о нас и о родстве нашем, говоря: жив ли ещё отец ваш? есть ли у вас брат? И мы рассказали ему согласно этим словам; разве могли мы знать, что он скажет: приведите брата вашего?'),
(1299, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 8, 'OT', 'Иуда сказал Израилю, отцу своему: отпусти отрока со мною, и встанем и пойдём, и будем жить, и не умрём — ни мы, ни ты, ни дети наши.'),
(1300, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 9, 'OT', 'Я ручаюсь за него, из моей руки ты потребуешь его; если я не приведу его к тебе и не поставлю его перед лицом твоим, то буду виновен перед тобою во все дни.'),
(1301, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 10, 'OT', 'Ведь если бы мы не медлили, то уже теперь возвратились бы два раза.'),
(1302, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 11, 'OT', 'И сказал им Израиль, отец их: если так, то вот что сделайте: возьмите из лучших плодов земли в сосуды ваши и отнесите человеку дар: немного бальзама и немного мёда, пряности и мирру, орехи и миндаль.'),
(1303, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 12, 'OT', 'Возьмите в руки ваши серебро вдвойне, и серебро, возвращённое в отверстии ваших мешков, верните в ваши руки; может быть, это заблуждение.'),
(1304, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 13, 'OT', 'Возьмите вашего брата и встаньте, возвратитесь к тому человеку.'),
(1305, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 14, 'OT', 'И Бог Вседержитель да даст вам милость пред лицом того человека, и отпустит вам вашего другого брата и Вениамина; а я, как я осиротел, так и осиротел.'),
(1306, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 15, 'OT', 'Взяли те люди этот дар, и серебра вдвое больше взяли в руку свою, и Вениамина, и встали, и спустились в Египет, и предстали пред лицо Иосифа.'),
(1307, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 16, 'OT', 'И увидел Иосиф с ними Вениамина и сказал начальнику над домом своим: введи этих людей в дом, и заколи заклание, и приготовь, ибо со мною будут есть эти люди в полдень.'),
(1308, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 17, 'OT', 'И сделал человек, как сказал Иосиф, и ввёл человек тех людей в дом Иосифа.'),
(1309, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 18, 'OT', 'Испугались те люди, потому что их привели в дом Иосифа, и сказали: из-за слова о деньгах, возвращённых в мешки наши в начале, мы приведены, чтобы напасть на нас и обрушиться на нас, и взять нас в рабы, и ослов наших.'),
(1310, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 19, 'OT', 'И подошли они к человеку, который был над домом Иосифа, и говорили с ним у двери дома.'),
(1311, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 20, 'OT', 'Господин мой, мы приходили в начале, чтобы купить пищи.'),
(1312, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 21, 'OT', 'И было, когда мы пришли в гостиницу и открыли наши мешки, вот серебро каждого человека в отверстии его мешка, серебро наше по весу его, и мы возвратили его в руку нашу.'),
(1313, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 22, 'OT', 'И другое серебро мы принесли в руке нашей, чтобы купить пищи; мы не знаем, кто положил серебро наше в мешки наши.'),
(1314, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 23, 'OT', 'Он сказал: мир вам, не бойтесь; Бог ваш и Бог отца вашего дал вам сокровище в мешках ваших; серебро ваше дошло до меня. И вывел к ним Симеона.'),
(1315, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 24, 'OT', 'И ввёл тот человек людей в дом Иосифа, и дал воды, и они омыли ноги свои, и дал корм ослам их.'),
(1316, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 25, 'OT', 'Они приготовили дар, пока не пришёл Иосиф в полдень, ибо услышали, что там будут есть хлеб.'),
(1317, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 26, 'OT', 'Иосиф пришёл в дом, и они принесли ему дар, который был в их руках, в дом, и поклонились ему до земли.'),
(1318, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 27, 'OT', 'И спросил он их о мире, и сказал: мирен ли отец ваш, старец, о котором вы говорили? Жив ли он ещё?'),
(1319, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 28, 'OT', 'Они сказали: мир рабу твоему, отцу нашему; он ещё жив. И поклонились они и пали ниц.'),
(1320, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 29, 'OT', 'И поднял он очи свои, и увидел Вениамина, брата своего, сына матери своей, и сказал: это ли брат ваш меньший, о котором вы говорили мне? И сказал: Бог да помилует тебя, сын мой.'),
(1321, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 30, 'OT', 'Иосиф поспешил, ибо его жалость к брату его всколыхнулась, и он искал, где заплакать, и вошёл во внутреннюю комнату, и плакал там.'),
(1322, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 31, 'OT', 'Он умыл лицо своё и вышел, и сдержался, и сказал: положите хлеб.'),
(1323, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 32, 'OT', 'И подали ему отдельно, и им отдельно, и египтянам, евшим с ним, отдельно, потому что египтяне не могут есть хлеб с евреями, ибо это мерзость для египтян.'),
(1324, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 33, 'OT', 'И сели они перед лицом его, первенец по первородству своему, и младший по юности своей; и дивились те люди, человек к ближнему своему.'),
(1325, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 43, 34, 'OT', 'И взял он дары от лица своего и послал им, и увеличился дар Вениамина сверх даров всех их в пять порций, и пили они и пьянели с ним.'),
(1326, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 1, 'OT', 'И приказал он тому, кто над домом его, говоря: наполни мешки людей пищею, сколько они могут нести, и положи серебро каждого человека в отверстие мешка его.'),
(1327, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 2, 'OT', 'И чашу мою, чашу серебряную, положи в отверстие мешка младшего, и серебро за хлеб его. И сделал он по слову Иосифа, которое он сказал.'),
(1328, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 3, 'OT', 'Утро рассвело, и люди были отправлены, они и ослы их.'),
(1329, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 4, 'OT', 'Они вышли из города, недалеко ушли, и Иосиф сказал тому, кто был над его домом: встань, догони этих людей, и когда догонишь их, скажи им: зачем вы воздали злом за добро?'),
(1330, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 5, 'OT', 'Разве не это тот, из которого пьёт мой господин, и он, верно, гадает на нём? Вы поступили худо, сделав это.'),
(1331, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 6, 'OT', 'И догнал их, и сказал им эти слова.'),
(1332, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 7, 'OT', 'И сказали они ему: зачем господин наш говорит такие слова? Да не будет того, чтобы рабы твои сделали такое дело!'),
(1333, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 8, 'OT', 'Вот серебро, которое мы нашли в отверстиях наших мешков, мы возвратили тебе из земли Ханаанской; как же нам украсть из дома господина твоего серебро или золото?'),
(1334, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 9, 'OT', 'У кого из рабов твоих найдётся он, тот умрёт, и также мы будем господину нашему рабами.'),
(1335, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 10, 'OT', 'И сказал он: пусть будет по словам вашим: тот, у кого найдётся, будет мне рабом, а вы будете чисты.'),
(1336, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 11, 'OT', 'И поспешили они, и спустили каждый человек свой мешок на землю, и открыли каждый человек свой мешок.'),
(1337, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 12, 'OT', 'Он обыскал, начав со старшего, и кончил младшим, и нашлась чаша в мешке Вениамина.'),
(1338, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 13, 'OT', 'И разорвали они одежды свои, и навьючил каждый человек на осла своего, и возвратились в город.'),
(1339, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 14, 'OT', 'И пришёл Иуда и братья его в дом Иосифа, и он ещё был там, и пали они на лицо своё пред ним на землю.'),
(1340, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 15, 'OT', 'И сказал им Иосиф: что это за дело, которое вы сделали? Разве вы не знали, что человек, подобный мне, непременно гадает?'),
(1341, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 16, 'OT', 'Сказал Иуда: что нам сказать господину моему? что говорить и чем оправдаться? Бог нашёл беззаконие рабов твоих; вот мы рабы господину моему, и мы, и тот, у кого найдена чаша в руке его.'),
(1342, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 17, 'OT', 'Он сказал: да не будет мне сделать это; человек, у которого найдена чаша в руке его, он будет мне рабом, а вы поднимитесь с миром к отцу вашему.'),
(1343, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 18, 'OT', 'Подошёл к нему Иуда и сказал: прошу, господин мой, пусть раб твой скажет слово в уши господина моего, и да не разгорится гнев твой на раба твоего, ибо ты — как фараон.'),
(1344, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 19, 'OT', 'Господин мой спрашивал рабов своих, говоря: есть ли у вас отец или брат?'),
(1345, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 20, 'OT', 'И мы сказали господину нашему: есть у нас отец престарелый, и дитя старости малое, и брат его умер, и остался он один у матери своей, и отец его любит его.'),
(1346, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 21, 'OT', 'И сказал ты рабам твоим: приведите его ко мне, и я положу взгляд мой на него.'),
(1347, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 22, 'OT', 'Мы сказали господину моему: не может отрок оставить отца своего; а если оставит отца своего, то умрёт.'),
(1348, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 23, 'OT', 'И ты сказал рабам твоим: если не сойдёт с вами младший брат ваш, то не увидите более лица моего.'),
(1349, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 24, 'OT', 'И было, когда мы поднялись к рабу твоему, отцу моему, и пересказали ему слова господина моего.'),
(1350, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 25, 'OT', 'И сказал отец наш: возвращайтесь, купите нам немного пищи.'),
(1351, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 26, 'OT', 'И мы сказали: не можем мы спуститься; если брат наш меньший будет с нами, то спустимся, ибо не можем мы видеть лицо того человека, а брат наш меньший не с нами.'),
(1352, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 27, 'OT', 'И сказал раб твой, отец наш, нам: вы знаете, что двух родила мне жена моя.'),
(1353, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 28, 'OT', 'Один ушёл от меня, и я сказал: наверное, он растерзан зверем, и я не видел его доныне.'),
(1354, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 29, 'OT', 'И если вы возьмёте также этого от лица моего, и постигнет его беда, то вы сведёте седину мою во зло в ад.'),
(1355, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 30, 'OT', 'Итак, когда я приду к рабу твоему, отцу моему, а отрока не будет с нами, — а душа его привязана к его душе,'),
(1356, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 31, 'OT', 'И будет, когда увидит он, что отрока нет, то умрёт; и сведут рабы твои седину раба твоего, отца нашего, в печали в ад.'),
(1357, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 32, 'OT', 'Ибо раб твой поручился за отрока пред отцом моим, сказав: если не приведу его к тебе, то буду виновен пред отцом моим во все дни.'),
(1358, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 33, 'OT', 'Итак, пусть раб твой останется вместо отрока рабом у господина моего, а отрок пусть пойдёт с братьями своими.'),
(1359, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 44, 34, 'OT', 'Ибо как я взойду к отцу моему, когда отрока нет со мною? Чтобы я не увидел бедствия, которое постигнет отца моего.'),
(1360, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 1, 'OT', 'И не мог Иосиф удержаться при всех стоявших пред ним, и воскликнул: выведите всех людей от меня. И не осталось ни одного человека с ним, когда Иосиф открылся братьям своим.'),
(1361, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 2, 'OT', 'И он возвысил свой голос в плаче, и услышали Египтяне, и услышал дом фараона.'),
(1362, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 3, 'OT', 'И сказал Иосиф братьям своим: я Иосиф; жив ли ещё отец мой? И не могли братья его ответить ему, потому что смутились пред лицом его.'),
(1363, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 4, 'OT', 'И сказал Иосиф братьям своим: подойдите ко мне, и они подошли. И сказал: я Иосиф, брат ваш, которого вы продали в Египет.'),
(1364, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 5, 'OT', 'И теперь не печальтесь и не гневайтесь в душе вашей, что вы продали меня сюда, ибо для жизни послал меня Бог пред лицом вашим.'),
(1365, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 6, 'OT', 'Ибо вот два года голода внутри земли, и ещё пять лет, в которые не будет ни пахоты, ни жатвы.'),
(1366, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 7, 'OT', 'И послал меня Бог перед лицом вашим, чтобы оставить вам остаток на земле и сохранить вам жизнь для великого спасения.'),
(1367, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 8, 'OT', 'Итак, не вы послали меня сюда, но Бог; и Он поставил меня отцом фараону и господином всему дому его, и владыкою над всею землёю Египетскою.'),
(1368, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 9, 'OT', 'Поспешите и поднимитесь к отцу моему, и скажите ему: так говорит сын твой Иосиф: Бог поставил меня господином над всем Египтом; сойди ко мне, не медли.'),
(1369, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 10, 'OT', 'И будешь жить в земле Гошен, и будешь близок ко мне, ты и сыновья твои, и сыновья сыновей твоих, и овцы твои, и крупный рогатый скот твой, и всё, что у тебя.'),
(1370, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 11, 'OT', 'И прокормлю тебя там, ибо ещё пять лет голода, чтобы не обнищал ты и дом твой и всё, что у тебя есть.'),
(1371, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 12, 'OT', 'И вот, очи ваши видят, и очи брата моего Вениамина, что уста мои говорят с вами.'),
(1372, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 13, 'OT', 'Расскажите отцу моему о всей славе моей в Египте и обо всём, что вы видели, и поспешите, и приведите отца моего сюда.'),
(1373, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 14, 'OT', 'И пал он на шею Вениамина, брата своего, и плакал; и Вениамин плакал на шее его.'),
(1374, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 15, 'OT', 'И поцеловал всех братьев своих и плакал над ними; и после того братья его говорили с ним.'),
(1375, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 16, 'OT', 'И голос был услышан в доме фараона: пришли братья Иосифа; и было это хорошо в очах фараона и в очах рабов его.'),
(1376, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 17, 'OT', 'Фараон сказал Иосифу: скажи братьям твоим: вот что сделайте: навьючьте скот ваш и идите, приходите в землю Ханаан.'),
(1377, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 18, 'OT', 'Возьмите отца вашего и дома ваши и придите ко мне, и я дам вам лучшее земли Египетской, и будете есть тук земли.'),
(1378, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 19, 'OT', 'И ты повелел это сделать: возьмите себе из земли Египетской повозки для детей ваших и для жён ваших, и возьмите отца вашего, и приходите.'),
(1379, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 20, 'OT', 'И око ваше да не жалеет об имуществе вашем, ибо благо всей земли Египетской — оно ваше.'),
(1380, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 21, 'OT', 'Сыновья Израиля сделали так, и дал им Иосиф повозки по приказу фараона, и дал им продовольствие на путь.'),
(1381, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 22, 'OT', 'Всем им дал каждому человеку смены одежд, а Вениамину дал триста сиклей серебра и пять смен одежд.'),
(1382, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 23, 'OT', 'И отцу своему послал он такое: десять ослов, несущих лучшее Египта, и десять ослиц, несущих зерно, и хлеб, и пищу отцу своему на путь.'),
(1383, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 24, 'OT', 'И отпустил он братьев своих, и они пошли, и сказал им: не ссорьтесь в пути.'),
(1384, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 25, 'OT', 'Они поднялись из Египта и пришли в землю Ханаан, к Иакову, отцу своему.'),
(1385, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 26, 'OT', 'И они сказали ему: «Иосиф ещё жив, и он правит всей землёй Египетской». И оцепенело сердце его, ибо он не поверил им.'),
(1386, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 27, 'OT', 'И они пересказали ему все слова Иосифа, которые он говорил им, и он увидел повозки, которые послал Иосиф, чтобы везти его, и ожил дух Иакова, отца их.'),
(1387, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 45, 28, 'OT', 'Сказал Израиль: довольно ещё того, что Иосиф, сын мой, жив; пойду и увижу его, прежде чем умру.'),
(1388, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 1, 'OT', 'Израиль отправился в путь со всем, что у него было, и пришёл в Вирсавию, и принёс жертвы Богу отца своего Исаака.'),
(1389, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 2, 'OT', 'И сказал Бог Израилю в ночном видении, и сказал: Иаков, Иаков! И сказал он: вот я.'),
(1390, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 3, 'OT', 'И сказал: Я Бог, Бог отца твоего; не бойся идти в Египет, ибо там Я сделаю тебя великим народом.'),
(1391, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 4, 'OT', 'Я сойду с тобою в Египет, и Я выведу тебя обратно, и Иосиф положит руку свою на глаза твои.'),
(1392, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 5, 'OT', 'Встал Иаков из Вирсавии, и понесли сыны Израиля Иакова, отца своего, и детей своих, и жён своих на повозках, которые послал фараон, чтобы везти его.'),
(1393, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 6, 'OT', 'Они взяли свой скот и своё имущество, которое приобрели в земле Ханаан, и пришли в Египет, Иаков и всё его семя с ним.'),
(1394, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 7, 'OT', 'Сыновей своих и сыновей сыновей своих с ним, дочерей своих и дочерей сыновей своих, и всё семя своё привёл он с собою в Египет.'),
(1395, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 8, 'OT', 'И вот имена сыновей Израиля, приходящих в Египет: Иаков и сыновья его; первенец Иакова — Рувим.'),
(1396, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 9, 'OT', 'Сыновья Рувима: Енох, Фаллу, Хецрон и Кармий.'),
(1397, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 10, 'OT', 'Сыновья Симеона: Емуил, и Иамин, и Охад, и Иахин, и Цохар, и Саул, сын Хананеянина.'),
(1398, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 11, 'OT', 'Сыновья Левия: Герсон, Кааф и Мерари.'),
(1399, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 12, 'OT', 'Сыновья Иуды: Ир, Онан, Шела, Фарес и Зерах; и умерли Ир и Онан в земле Ханаанской; и были сыновья Фареса: Хецрон и Хамул.'),
(1400, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 13, 'OT', 'Сыновья Иссахара: Тола, и Фува, и Иов, и Шимрон.'),
(1401, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 14, 'OT', 'Сыновья Завулона: Сер, Елон и Иахлеил.'),
(1402, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 15, 'OT', 'Это сыновья Лии, которых она родила Иакову в Паддане, и Дина, дочь его; всех душ сыновей его и дочерей его — тридцать три.'),
(1403, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 16, 'OT', 'Сыновья Гада: Цифион, и Хагги, и Шуни, и Ецбон, Ерий, и Ароди, и Арели.'),
(1404, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 17, 'OT', 'Сыновья Асира: Имна, Ишва, Ишви и Берия, и Серах, сестра их; и сыновья Берии: Хевер и Малкиил.'),
(1405, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 18, 'OT', 'Это сыновья Зелфы, которую дал Лаван Лии, дочери своей; и родила она их Иакову: шестнадцать душ.'),
(1406, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 19, 'OT', 'Сыновья Рахили, жены Иакова: Иосиф и Вениамин.'),
(1407, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 20, 'OT', 'И родился у Иосифа в земле Египетской, которого родила ему Асенефа, дочь Потифера, священника Она, Манассия и Ефрем.'),
(1408, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 21, 'OT', 'Сыновья Вениамина: Вала и Бехер, и Ашбель, Гера и Нееман, Ехий и Рош, Муфим и Хуппим, и Ард.'),
(1409, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 22, 'OT', 'Это сыновья Рахили, которые родились у Иакова, всего душ четырнадцать.'),
(1410, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 23, 'OT', 'Сыновья Дана: Хушим.'),
(1411, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 24, 'OT', 'Сыновья Неффалима: Иахцеил, и Гуни, и Иецер, и Шиллем.'),
(1412, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 25, 'OT', 'Это сыновья Валлы, которую дал Лаван Рахили, дочери своей; и она родила этих Иакову: всего душ семь.'),
(1413, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 26, 'OT', 'Всё число душ, пришедших с Иаковом в Египет, вышедших из бедра его, отдельно от жён сыновей Иакова, — всего душ шестьдесят шесть.'),
(1414, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 27, 'OT', 'Сыновья Иосифа, которые родились ему в Египте, — две души. Всех душ дома Иакова, пришедших в Египет, — семьдесят.'),
(1415, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 28, 'OT', 'И послал Иуду пред лицом своим к Иосифу, чтобы указать путь пред ним в Гошен, и пришли они в землю Гошен.'),
(1416, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 29, 'OT', 'И запряг Иосиф колесницу свою, и пошёл навстречу Израилю, отцу своему, в Гошен, и явился ему, и пал на шею его, и плакал на шее его долго.'),
(1417, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 30, 'OT', 'Израиль сказал Иосифу: умру я на этот раз, после того как увидел лицо твоё, ибо ты ещё жив.'),
(1418, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 31, 'OT', 'И сказал Иосиф братьям своим и дому отца своего: пойду и возвещу фараону, и скажу ему: братья мои и дом отца моего, которые в земле Ханаанской, пришли ко мне.'),
(1419, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 32, 'OT', 'И люди — пастухи овец, ибо они были людьми скотоводческими, и овец своих, и крупный рогатый скот свой, и всё, что у них было, они привели.'),
(1420, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 33, 'OT', 'И будет, когда фараон призовёт вас и скажет: каково ваше дело?'),
(1421, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 46, 34, 'OT', 'И скажите: люди, владеющие скотом, были рабы твои от юности нашей и доныне, и мы, и отцы наши, — ради того, чтобы вам жить в земле Гошен, ибо мерзость для Египтян всякий пастух овец.'),
(1422, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 1, 'OT', 'И пришёл Иосиф и возвестил фараону, и сказал: отец мой и братья мои, и овцы их, и крупный рогатый скот их, и всё, что у них, пришли из земли Ханаан, и вот они в земле Гошен.'),
(1423, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 2, 'OT', 'И из числа братьев своих взял он пять человек и поставил их пред лицо фараона.'),
(1424, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 3, 'OT', 'И сказал фараон братьям его: какое дело ваше? И сказали они фараону: пастухи овец — рабы твои, и мы, и отцы наши.'),
(1425, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 4, 'OT', 'И сказали они фараону: пришли мы пожить в этой земле, потому что нет пастбища для овец у рабов твоих, ибо тяжёл голод в земле Ханаанской; итак, пусть теперь рабы твои поселятся в земле Гошен.'),
(1426, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 5, 'OT', 'И сказал фараон Иосифу, говоря: отец твой и братья твои пришли к тебе.'),
(1427, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 6, 'OT', 'Земля Египетская пред лицом твоим; в лучшей земле посели отца твоего и братьев твоих, пусть живут в земле Гошен; и если знаешь, что есть среди них способные люди, то поставь их начальниками над скотом моим.'),
(1428, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 7, 'OT', 'Иосиф привёл Иакова, отца своего, и поставил его пред лицо фараона, и благословил Иаков фараона.'),
(1429, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 8, 'OT', 'И сказал фараон Иакову: сколько дней лет жизни твоей?'),
(1430, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 9, 'OT', 'И сказал Иаков фараону: дней странствия моего сто тридцать лет; малы и злы были дни жизни моей, и не достигли они дней жизни отцов моих во дни странствия их.'),
(1431, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 10, 'OT', 'И благословил Иаков фараона, и вышел от лица фараона.'),
(1432, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 11, 'OT', 'И поселил Иосиф отца своего и братьев своих, и дал им владение в земле Египетской, в лучшей части земли, в земле Раамсес, как повелел фараон.'),
(1433, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 12, 'OT', 'Иосиф снабжал отца своего и братьев своих, и весь дом отца своего хлебом, по числу детей.'),
(1434, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 13, 'OT', 'И не было хлеба во всей земле, ибо голод был очень тяжёл, и изнемогла земля Египетская и земля Ханаанская от лица голода.'),
(1435, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 14, 'OT', 'И собрал Иосиф всё серебро, найденное в земле Египетской и в земле Ханаанской, за хлеб, который они покупали, и принёс Иосиф серебро в дом фараона.'),
(1436, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 15, 'OT', 'И когда серебро истощилось в земле Египетской и в земле Ханаанской, пришли все Египтяне к Иосифу, говоря: дай нам хлеба; зачем нам умирать пред тобою? ибо серебро иссякло.'),
(1437, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 16, 'OT', 'И сказал Иосиф: дайте скот ваш, и я дам вам за скот ваш, если серебро истощилось.'),
(1438, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 17, 'OT', 'И привели они скот свой к Иосифу, и дал им Иосиф хлеб за коней, и за скот овец, и за скот крупного рогатого скота, и за ослов; и снабжал их хлебом за весь скот их в тот год.'),
(1439, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 18, 'OT', 'И когда окончился тот год, пришли к нему во второй год и сказали ему: не скроем от господина моего, что серебро истощилось, и скот домашний перешёл к господину моему; не осталось пред лицом господина моего ничего, кроме тел наших и земли нашей.'),
(1440, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 19, 'OT', 'Зачем нам умирать пред очами твоими, и нам, и земле нашей? Купи нас и землю нашу за хлеб, и будем мы, и земля наша, рабами фараону; и дай семя, чтобы нам жить и не умереть, и земля не опустеет.'),
(1441, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 20, 'OT', 'И купил Иосиф всю землю Египетскую для фараона, потому что продали Египтяне каждый человек поле своё, ибо усилился над ними голод; и стала земля фараону.'),
(1442, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 21, 'OT', 'И народ он перевёл в города, от края границы Египта и до края её.'),
(1443, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 22, 'OT', 'Только земли священников не купил он, ибо доля для священников была от фараона, и они ели свою долю, которую дал им фараон; поэтому они не продали свою землю.'),
(1444, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 23, 'OT', 'И сказал Иосиф народу: вот, я купил вас сегодня и землю вашу для фараона; вот вам семя, и засевайте землю.'),
(1445, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 24, 'OT', 'И будет в доходах: отдавайте пятую часть фараону, а четыре части будут вашими — для семени поля, и для пищи вашей, и для тех, кто в домах ваших, и для еды детям вашим.'),
(1446, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 25, 'OT', 'И сказали они: ты сохранил нам жизнь; да найдём мы благодать в очах господина нашего, и будем рабами фараону.'),
(1447, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 26, 'OT', 'И установил это Иосиф в устав до сего дня на земле Египетской: фараону — пятая часть; только земля священников отдельно не была у фараона.'),
(1448, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 27, 'OT', 'И жил Израиль в земле Египетской, в земле Гошен, и владели они ею, и плодились, и размножались весьма.'),
(1449, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 28, 'OT', 'Иаков жил в земле Египетской семнадцать лет; и было дней Иакова, лет жизни его, сто сорок семь лет.'),
(1450, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 29, 'OT', 'Приблизились дни Израиля к смерти, и он позвал своего сына Иосифа и сказал ему: если я нашёл благодать в твоих очах, положи, пожалуйста, твою руку под моё бедро, и сделай со мной милость и истину: не хорони меня, пожалуйста, в Египте.'),
(1451, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 30, 'OT', 'И лягу я с отцами моими, и вынесешь меня из Египта, и похоронишь меня в погребении их. И сказал он: я сделаю по слову твоему.'),
(1452, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 47, 31, 'OT', 'И сказал он: поклянись мне. И поклялся ему. И поклонился Израиль на главу постели.'),
(1453, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 1, 'OT', 'И было после этих слов, и сказали Иосифу: вот, отец твой болен. И взял он с собой двух сыновей своих, Манассию и Ефрема.'),
(1454, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 2, 'OT', 'И сказали Иакову: вот, сын твой Иосиф идёт к тебе. И укрепился Израиль, и сел на постель.'),
(1455, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 3, 'OT', 'Иаков сказал Иосифу: Бог Вседержитель явился мне в Лузе, в земле Ханаан, и благословил меня.'),
(1456, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 4, 'OT', 'Он сказал мне: вот, Я делаю тебя плодовитым и размножу тебя, и сделаю тебя собранием народов, и дам эту землю семени твоему после тебя во владение вечное.'),
(1457, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 5, 'OT', 'И ныне два сына твои, родившиеся тебе в земле Египетской, до прихода моего к тебе в Египет, — мои они; Ефрем и Манассия, как Рувим и Симеон, будут моими.'),
(1458, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 6, 'OT', 'И твоё потомство, которое ты родил после них, будет твоим; под именем братьев их они будут называться в наследии их.'),
(1459, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 7, 'OT', 'И я, когда я шёл из Паддана, умерла у меня Рахиль на земле Ханаанской, на пути, когда ещё было малое расстояние земли, чтобы идти в Ефрафу, и я похоронил её там на пути к Ефрафе, то есть Вифлеему.'),
(1460, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 8, 'OT', 'Увидел Израиль сыновей Иосифа и сказал: кто эти?'),
(1461, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 9, 'OT', 'И сказал Иосиф отцу своему: это сыновья мои, которых дал мне Бог здесь; и сказал: приведи их ко мне, и я благословлю их.'),
(1462, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 10, 'OT', 'Очи Израиля отяжелели от старости, не мог он видеть; и он подвёл их к себе, и поцеловал их, и обнял их.'),
(1463, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 11, 'OT', 'Сказал Израиль Иосифу: видеть лицо твоё я не надеялся, и вот Бог показал мне также и семя твоё.'),
(1464, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 12, 'OT', 'И вывел Иосиф их от колен своих, и поклонился лицом своим до земли.'),
(1465, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 13, 'OT', 'И взял Иосиф обоих их: Ефрема в правую руку свою, с левой стороны Израиля, а Манассию в левую руку свою, с правой стороны Израиля, и подвёл к нему.'),
(1466, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 14, 'OT', 'Израиль простёр свою правую руку и возложил её на главу Ефрема, хотя тот был младшим, а левую сторону — на главу Манассии; он переложил свои руки, ибо Манассия был первенцем.'),
(1467, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 15, 'OT', 'И благословил Иосифа и сказал: Бог, пред лицом которого ходили отцы мои Авраам и Исаак, Бог, пасущий меня с самого начала моей жизни до сего дня,'),
(1468, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 16, 'OT', 'Ангел, избавляющий меня от всякого зла, да благословит отроков, и да будет называться в них имя моё и имя отцов моих Авраама и Исаака, и да размножатся они во множество среди земли.'),
(1469, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 17, 'OT', 'И увидел Иосиф, что отец его положил правую руку свою на главу Ефрема, и было это неприятно в очах его; и поддержал он руку отца своего, чтобы снять её с главы Ефрема на главу Манассии.'),
(1470, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 18, 'OT', 'И сказал Иосиф отцу своему: не так, отец мой, ибо это первенец; положи правую руку твою на главу его.'),
(1471, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 19, 'OT', 'Отказался отец его и сказал: знаю, сын мой, знаю; и он будет народом, и он будет велик; но младший брат его будет больше его, и семя его будет множеством народов.'),
(1472, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 20, 'OT', 'И благословил их в тот день, говоря: тобою будет благословлять Израиль, говоря: да сделает тебя Бог, как Ефрема и как Манассию; и поставил Ефрема пред лицом Манассии.'),
(1473, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 21, 'OT', 'И сказал Израиль Иосифу: вот, я умираю, и будет Бог с вами, и возвратит вас в землю отцов ваших.'),
(1474, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 48, 22, 'OT', 'И я даю тебе одну долю сверх братьев твоих, которую я взял из руки Аморрея мечом моим и луком моим.'),
(1475, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 1, 'OT', 'И призвал Иаков сыновей своих и сказал: соберитесь, и я возвещу вам, что будет с вами в конце дней.'),
(1476, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 2, 'OT', 'Соберитесь и слушайте, сыны Иакова, и слушайте Израиля, отца вашего.'),
(1477, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 3, 'OT', 'Рувим, первенец мой, ты — сила моя и начаток силы моей, превосходство возвышения и превосходство сильного.'),
(1478, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 4, 'OT', 'Непостоянство, как вода, — не превзойдёшь, ибо взошёл ты на ложе отца твоего; тогда осквернил ты ложе моё, взойдя.'),
(1479, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 5, 'OT', 'Симеон и Левий — братья, орудия насилия — их жилища.'),
(1480, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 6, 'OT', 'В собрание их да не войдёт душа моя, в собрание их да не приобщится слава моя, ибо во гневе своём они убили человека и по своей воле подрезали жилы вола.'),
(1481, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 7, 'OT', 'Проклят гнев их, ибо жесток, и ярость их, ибо сурова; разделю их в Иакове и рассею их в Израиле.'),
(1482, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 8, 'OT', 'Иуда, тебя восхвалят братья твои, рука твоя на шее врагов твоих, поклонятся тебе сыны отца твоего.'),
(1483, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 9, 'OT', 'Щенок льва Иуда, от добычи, сын мой, ты поднялся; он прилёг, возлёг, как лев, и как львица — кто поднимет его?'),
(1484, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 10, 'OT', 'Не отойдёт жезл от Иуды, и законодатель из-под ног его, доколе не придёт Силом, и ему — послушание народов.'),
(1485, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 11, 'OT', 'Привязывает к виноградной лозе молодого осла своего, и к отборной лозе — сына ослицы своей; моет в вине одежду свою и в крови винограда одеяние своё.'),
(1486, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 12, 'OT', 'Темны очи от вина, и белы зубы от молока.'),
(1487, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 13, 'OT', 'Завулон при береге морей будет обитать, и он при береге кораблей, и предел его — до Сидона.'),
(1488, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 14, 'OT', 'Иссахар — осёл костистый, лежащий между загонами.'),
(1489, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 15, 'OT', 'И увидел он, что покой хорош, и землю, что она приятна, и склонил плечо своё, чтобы нести, и стал он для подати работающим.'),
(1490, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 16, 'OT', 'Дан будет судить народ свой, как одно из колен Израиля.'),
(1491, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 17, 'OT', 'Дан будет змеем на пути, ехидной на дороге, жалящей пяту коня, так что всадник его упадёт на заднюю сторону.'),
(1492, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 18, 'OT', 'На спасение Твоё я уповал, Господь.'),
(1493, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 19, 'OT', 'Гад — отряд будет теснить его, но он будет теснить по пятам.'),
(1494, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 20, 'OT', 'От Асира — тучный хлеб его, и он даст лакомства царя.'),
(1495, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 21, 'OT', 'Неффалим — лань отпущенная, дающая слова красоты.'),
(1496, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 22, 'OT', 'Сын плодоносный Иосиф, сын плодоносный над источником, дочери (ветви) шагают по стене.'),
(1497, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 23, 'OT', 'Огорчили его и враждовали, и ненавидели его стрелки из лука.'),
(1498, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 24, 'OT', 'И остался твёрдым лук его, и напряглись мышцы рук его, от рук Мощного Иакова, оттуда Пастырь, камень Израиля.'),
(1499, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 25, 'OT', 'От Бога отца твоего, и Он поможет тебе, и от Вседержителя, и Он благословит тебя благословениями неба свыше, благословениями бездны, лежащей внизу, благословениями сосцов и утробы.'),
(1500, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 26, 'OT', 'Благословения отца твоего превзошли благословения родителей моих до предела холмов вечности; да будут они на главе Иосифа и на темени назорея среди братьев его.'),
(1501, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 27, 'OT', 'Вениамин — волк хищный; утром будет есть добычу, и вечером разделит добычу.'),
(1502, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 28, 'OT', 'Всё это колена Израиля, двенадцать; и вот что сказал им отец их, и благословил их, каждого человека по его благословению благословил их.'),
(1503, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 29, 'OT', 'И заповедал им и сказал им: я приобщаюсь к народу моему; похороните меня с отцами моими в пещере, которая на поле Ефрона Хеттеянина.'),
(1504, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 30, 'OT', 'в пещере, которая на поле Махпелы, которое напротив Мамаре, в земле Ханаанской, которое купил Авраам поле у Ефрона Хеттеянина во владение для гроба.'),
(1505, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 31, 'OT', 'Там похоронили Авраама и Сарру, жену его; там похоронили Исаака и Ревекку, жену его; и там я похоронил Лию.'),
(1506, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 32, 'OT', 'Скот поля и пещера, которая в нём, от сынов Хета.'),
(1507, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 49, 33, 'OT', 'И закончил Иаков завещать сыновьям своим, и собрал ноги свои на постель, и испустил дух, и приложился к предкам своим.'),
(1508, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 1, 'OT', 'И пал Иосиф на лицо отца своего, и плакал над ним, и целовал его.'),
(1509, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 2, 'OT', 'Иосиф повелел рабам своим, врачам, бальзамировать отца его; и врачи бальзамировали Израиля.'),
(1510, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 3, 'OT', 'И наполнились ему сорок дней, ибо так наполняются дни бальзамирования, и оплакивали его Египтяне семьдесят дней.'),
(1511, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 4, 'OT', 'И прошли дни плача его, и сказал Иосиф дому фараона, говоря: если я нашёл благодать в очах ваших, скажите, пожалуйста, в уши фараона, говоря:'),
(1512, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 5, 'OT', 'Отец мой заклял меня, сказав: вот, я умираю; в гробе моём, который я выкопал себе в земле Ханаанской, там похорони меня; и теперь позволь мне подняться и похоронить отца моего, и я возвращусь.'),
(1513, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 6, 'OT', 'И сказал фараон: пойди и похорони отца твоего, как он заклинал тебя.'),
(1514, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 7, 'OT', 'И поднялся Иосиф похоронить отца своего, и поднялись с ним все рабы фараона, старейшины дома его, и все старейшины земли Египетской.'),
(1515, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 8, 'OT', 'И весь дом Иосифа, и братья его, и дом отца его; только детей своих, и овец своих, и крупный рогатый скот свой оставили они в земле Гошен.'),
(1516, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 9, 'OT', 'И поднялся с ним также колесница и всадники, и был стан весьма тяжёлый.'),
(1517, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 10, 'OT', 'И пришли они до гумна Атада, которое за Иорданом, и плакали там плачем великим и очень тяжёлым, и совершил он по отцу своему плач семь дней.'),
(1518, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 11, 'OT', 'И увидел житель земли Хананеянин плач на гумне терна, и сказали: великий плач это для Египтян; потому и названо имя его Авел-Мицраим, что по ту сторону Иордана.'),
(1519, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 12, 'OT', 'И сделали сыновья его ему так, как он заповедал им.'),
(1520, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 13, 'OT', 'И подняли его сыновья его в землю Ханаанскую, и погребли его в пещере поля Махпелы, которую Авраам купил, поле, во владение для гроба, у Ефрона Хеттеянина, пред лицом Мамаре.'),
(1521, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 14, 'OT', 'И возвратился Иосиф в Египет, он и братья его, и все восходившие с ним хоронить отца его, после того как он похоронил отца своего.'),
(1522, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 15, 'OT', 'Братья Иосифа увидели, что умер их отец, и сказали: «Вдруг Иосиф возненавидит нас и непременно возвратит нам всё то зло, которое мы сделали ему».'),
(1523, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 16, 'OT', 'И приказали они Иосифу, говоря: отец твой повелел перед лицом смерти своей, говоря:'),
(1524, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 17, 'OT', 'Так скажите Иосифу: прости же преступление братьев твоих и грех их, ибо зло они сделали тебе; и теперь прости преступление рабов Бога отца твоего. И заплакал Иосиф, когда они говорили к нему.'),
(1525, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 18, 'OT', 'И пошли также братья его, и пали пред лицом его, и сказали: вот мы тебе в рабы.'),
(1526, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 19, 'OT', 'И сказал им Иосиф: не бойтесь, ибо разве я вместо Бога?'),
(1527, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 20, 'OT', 'Вы замышляли против меня зло; Бог замыслил его во благо, чтобы сделать, как в этот день, сохранить жизнь многочисленному народу.'),
(1528, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 21, 'OT', 'И теперь не бойтесь: я буду содержать вас и детей ваших. И утешил их, и говорил к сердцу их.'),
(1529, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 22, 'OT', 'Иосиф жил в Египте, он и дом отца его; и жил Иосиф сто десять лет.'),
(1530, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 23, 'OT', 'Иосиф увидел у Ефрема сыновей третьего поколения; также сыновья Махыра, сына Манассии, родились на коленях Иосифа.'),
(1531, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 24, 'OT', 'И сказал Иосиф братьям своим: я умираю, но Бог непременно посетит вас и выведет вас из этой земли в землю, которую Он клялся Аврааму, Исааку и Иакову.'),
(1532, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 25, 'OT', 'И заклял Иосиф сынов Израиля, говоря: Бог непременно посетит вас, и вы вынесете кости мои отсюда.'),
(1533, 1, 'GOI_Ru', 'GOI_Ru', 'ru', 'GEN', 50, 26, 'OT', 'И умер Иосиф, сын ста десяти лет, и набальзамировали его, и положили его в ковчег в Египте.'),
(1534, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 1, 'OT', 'И вот имена сынов Израиля, пришедших в Египет, с Иаковом, каждый человек с домом своим, пришли.'),
(1535, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 2, 'OT', 'Рувим, Симеон, Левий и Иуда.'),
(1536, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 3, 'OT', 'Иссахар, Завулон и Вениамин.'),
(1537, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 4, 'OT', 'Дан и Неффалим, Гад и Асир.'),
(1538, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 5, 'OT', 'И было всех душ, вышедших из бедра Иакова, семьдесят душ, а Иосиф был в Египте.'),
(1539, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 6, 'OT', 'И умер Иосиф, и все братья его, и весь род тот.'),
(1540, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 7, 'OT', 'Сыны Израилевы расплодились и размножились, и возросли, и усилились чрезвычайно, и наполнилась ими земля.'),
(1541, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 8, 'OT', 'И восстал новый царь над Египтом, который не знал Иосифа.'),
(1542, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 9, 'OT', 'И сказал он народу своему: вот, народ сынов Израиля многочислен и сильнее нас.'),
(1543, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 10, 'OT', 'Давайте поступим с ним мудро, чтобы он не умножился, и когда случится война, он не присоединился бы также к нашим врагам, и не воевал против нас, и не поднялся из земли.'),
(1544, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 11, 'OT', 'И поставили над ними начальников податей, чтобы изнурять их их бременами; и он построил города для кладовых фараону: Пифом и Раамсес.'),
(1545, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 12, 'OT', 'И как они угнетали его, так он умножался и так распространялся; и они содрогались от лица сынов Израиля.'),
(1546, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 13, 'OT', 'Египтяне принуждали сынов Израиля к жестокой работе.'),
(1547, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 14, 'OT', 'И сделали жизнь их горькою тяжкою работою: глиною и кирпичами, и всякою работою в поле, — всею работою их, которую они совершали у них с жестокостью.'),
(1548, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 15, 'OT', 'Царь Египта сказал еврейским повивальным бабкам, из которых одной имя Шифра, а имя второй Пуа.'),
(1549, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 16, 'OT', 'Когда вы будете принимать у евреек, и увидите на колесе: если это сын, то умертвите его, а если это дочь, то пусть живёт.'),
(1550, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 17, 'OT', 'Повивальные бабки убоялись Бога и не сделали так, как говорил им царь Египта, и оставили детей в живых.'),
(1551, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 18, 'OT', 'Царь Египта призвал повивальных бабок и сказал им: почему вы сделали это слово и оставили детей в живых?'),
(1552, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 19, 'OT', 'И сказали повивальные бабки фараону: потому что не как жены египтянки евреянки, ибо они живы, прежде чем придёт к ним повивальная бабка, они рожают.'),
(1553, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 20, 'OT', 'И Бог делал добро повивальным бабкам, и народ умножался и весьма усиливался.'),
(1554, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 21, 'OT', 'И было: так как повивальные бабки боялись Бога, то Он устроил им дома.'),
(1555, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 1, 22, 'OT', 'И повелел фараон всему народу своему, говоря: всякого сына, рождающегося, бросайте в реку, а всякую дочь оставляйте в живых.'),
(1556, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 1, 'OT', 'Пошёл человек из дома Левия и взял дочь Левия.'),
(1557, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 2, 'OT', 'Жена зачала и родила сына, и, увидев, что он хорош, скрывала его три месяца.'),
(1558, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 3, 'OT', 'И не могла она более скрывать его, и взяла для него ковчег из тростника, и обмазала его смолою и смолою, и положила в нем дитя, и поставила в тростнике на берегу реки.'),
(1559, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 4, 'OT', 'И сестра его встала вдали, чтобы узнать, что будет с ним.'),
(1560, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 5, 'OT', 'Дочь фараона сошла омыться к реке, и девицы её ходили по берегу реки; и увидела она ковчег среди тростника, и послала служанку свою, и взяла его.'),
(1561, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 6, 'OT', 'Она открыла и увидела его, это дитя, и вот, отрок плачет; и сжалилась над ним, и сказала: это одно из детей Евреев.'),
(1562, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 7, 'OT', 'И сказала сестра его дочери фараона: пойти ли мне и позвать к тебе жену кормилицу из Евреек, чтобы она вскормила тебе дитя?'),
(1563, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 8, 'OT', 'И сказала ей дочь фараона: пойди. И пошла дева, и позвала мать дитяти.'),
(1564, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 9, 'OT', 'Дочь фараона сказала ей: возьми это дитя и вскорми его мне, и я дам тебе плату твою; и взяла жена дитя и вскормила его.'),
(1565, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 10, 'OT', 'И выросло дитя, и привела его к дочери фараона, и стал он ей сыном, и нарекла имя ему Моисей, и сказала: потому что из воды я вынула его.'),
(1566, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 11, 'OT', 'И было в те дни, когда вырос Моисей, и вышел он к братьям своим, и увидел бремена их; и увидел он человека Египтянина, бьющего человека Еврея из братьев его.'),
(1567, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 12, 'OT', 'И он обернулся туда и сюда, и увидел, что нет человека, и убил Египтянина, и скрыл его в песке.'),
(1568, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 13, 'OT', 'И вышел он на следующий день, и вот два человека, Евреи, ссорятся; и сказал он виновному: зачем ты бьёшь ближнего твоего?'),
(1569, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 14, 'OT', 'И сказал он: кто поставил тебя человеком князем и судьёю над нами? Не думаешь ли ты убить меня, как убил Египтянина? И убоялся Моисей и сказал: верно, стало известно это слово.'),
(1570, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 15, 'OT', 'Услышал фараон это слово и искал убить Моисея; но Моисей убежал от лица фараона и поселился в земле Мадианской, и сел у колодезя.'),
(1571, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 16, 'OT', 'А у священника Мадианского было семь дочерей; они пришли, и черпали, и наполнили жёлоба, чтобы напоить овец отца своего.'),
(1572, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 17, 'OT', 'И пришли пастухи и отогнали их, и встал Моисей и спас их, и напоил овец их.'),
(1573, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 18, 'OT', 'И пришли они к Рагуилу, отцу своему, и он сказал: почему вы так скоро пришли сегодня?'),
(1574, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 19, 'OT', 'Человек Египтянин избавил нас из руки пастухов, и также начерпал нам воды и напоил овец.'),
(1575, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 20, 'OT', 'И сказал он дочерям своим: где он? Зачем вы оставили этого человека? Позовите его, и пусть он ест хлеб.'),
(1576, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 21, 'OT', 'И согласился Моисей жить у человека, и он дал Сепфору, дочь свою, Моисею.'),
(1577, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 22, 'OT', 'Она родила сына, и он назвал его имя Герсом, потому что сказал: пришельцем я был в чужой земле.'),
(1578, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 23, 'OT', 'И было в те многие дни, и умер царь Египта, и стонали сыны Израиля от работы, и возопили, и поднялся вопль их к Богу от работы.'),
(1579, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 24, 'OT', 'И услышал Бог стенание их, и вспомнил Бог завет Свой с Авраамом, Исааком и Иаковом.'),
(1580, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 2, 25, 'OT', 'И увидел Бог сынов Израиля, и узнал Бог.'),
(1581, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 1, 'OT', 'Моисей пас овец у Иофора, своего тестя, священника Мадианского, и повёл овец за пустыню, и пришёл к горе Божьей, к Хориву.'),
(1582, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 2, 'OT', 'И явился ему ангел Господень в пламени огня из середины тернового куста; и увидел он, что терновый куст горит огнём, но терновый куст не сгорал.'),
(1583, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 3, 'OT', 'И сказал Моисей: пойду я и посмотрю на это великое видение, почему не сгорает терновый куст.'),
(1584, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 4, 'OT', 'Господь увидел, что он подошёл посмотреть, и воззвал к нему Бог из середины тернового куста, и сказал: Моисей, Моисей! И он сказал: вот я.'),
(1585, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 5, 'OT', 'И сказал: не приближайся сюда; сними обувь твою с ног твоих, ибо место, на котором ты стоишь, есть земля святая.'),
(1586, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 6, 'OT', 'И сказал: Я Бог отца твоего, Бог Авраама, Бог Исаака и Бог Иакова. И скрыл Моисей лицо своё, потому что боялся смотреть на Бога.'),
(1587, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 7, 'OT', 'И сказал Господь: Я увидел бедствие народа Моего, который в Египте, и услышал вопль их от лица притеснителей их, ибо Я знаю боль их.'),
(1588, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 8, 'OT', 'И сошёл Я избавить его от руки Египтян и вывести его из земли той в землю хорошую и обширную, в землю, текущую молоком и мёдом, в место Хананеянина и Хеттеянина, и Аморрея, и Ферезея, и Евея, и Иевусея.'),
(1589, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 9, 'OT', 'И вот, вопль сынов Израиля дошёл до Меня, и Я также увидел притеснение, которым Египтяне притесняют их.'),
(1590, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 10, 'OT', 'Итак, иди, и Я пошлю тебя к фараону, и выведи народ Мой, сынов Израиля, из Египта.'),
(1591, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 11, 'OT', 'И сказал Моисей Богу: кто я, чтобы идти к фараону, и чтобы вывести сынов Израиля из Египта?'),
(1592, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 12, 'OT', 'И сказал: Я буду с тобою, и вот тебе знамение, что Я послал тебя: когда ты выведешь народ из Египта, вы будете служить Богу на этой горе.'),
(1593, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 13, 'OT', 'И сказал Моисей Богу: вот, я приду к сынам Израиля и скажу им: Бог отцов ваших послал меня к вам; а они скажут мне: какое имя Его? — что мне сказать им?'),
(1594, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 14, 'OT', 'И сказал Бог Моисею: Я есмь Тот, Кто есмь. И сказал: так скажи сынам Израиля: «Я есмь» послал меня к вам.'),
(1595, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 15, 'OT', 'И сказал ещё Бог Моисею: так скажи сынам Израиля: Господь, Бог отцов ваших, Бог Авраама, Бог Исаака и Бог Иакова, послал меня к вам; это имя Моё на вечность, и это память Моя в род и род.'),
(1596, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 16, 'OT', 'Пойди и собери старейшин Израиля, и скажи им: Господь, Бог отцов ваших, явился мне, Бог Авраама, Исаака и Иакова, говоря: Я непременно посетил вас и то, что сделано с вами в Египте.'),
(1597, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 17, 'OT', 'И сказал Я: выведу вас из бедствия Египта в землю Хананеянина, и Хеттеянина, и Аморрея, и Ферезея, и Евея, и Иевусея, в землю, текущую молоком и мёдом.'),
(1598, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 18, 'OT', 'И послушают они голоса твоего, и пойдёшь ты и старейшины Израиля к царю Египта, и скажете ему: Господь, Бог Евреев, явился нам; и теперь пойдём мы путём трёх дней в пустыню, и принесём жертву Господу, Богу нашему.'),
(1599, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 19, 'OT', 'И я знаю, что не даст вам царь Египта идти, и не рукою крепкою.'),
(1600, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 20, 'OT', 'И простру руку Мою и поражу Египтян всеми чудесами Моими, которые совершу в среде его; и после того он отпустит вас.'),
(1601, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 21, 'OT', 'И дам Я благодать народу этому в очах Египтян, и будет, когда пойдёте, не пойдёте с пустыми руками.'),
(1602, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 3, 22, 'OT', 'Жена попросит у соседки своей и у живущей в доме её сосудов серебряных и сосудов золотых, и одежд, и вы возложите их на сыновей ваших и на дочерей ваших, и оберёте Египтян.'),
(1603, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 1, 'OT', 'И ответил Моисей и сказал: а вот они не поверят мне и не послушают голоса моего, ибо скажут: не явился тебе Господь.'),
(1604, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 2, 'OT', 'И сказал ему Господь: что это в руке твоей? И сказал он: жезл.'),
(1605, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 3, 'OT', 'И сказал он: брось его на землю. И он бросил его на землю, и он стал змеем; и побежал Моисей от лица его.'),
(1606, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 4, 'OT', 'И сказал Господь Моисею: простри руку твою и возьми его за хвост. И простер он руку свою, и схватил его, и стал он жезлом в ладони его.'),
(1607, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 5, 'OT', 'Чтобы они поверили, что явился тебе Господь, Бог отцов их, Бог Авраама, Бог Исаака и Бог Иакова.'),
(1608, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 6, 'OT', 'И сказал Господь ему: ещё вложи руку твою в недро твоё; и вложил руку свою в недро своё, и вынул её, и вот рука его прокажённая, как снег.'),
(1609, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 7, 'OT', 'И сказал: возврати руку твою в недро твоё. И возвратил руку свою в недро своё, и вынул её из недра своего, и вот, она стала как плоть его.'),
(1610, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 8, 'OT', 'И будет, если не поверят тебе и не послушают голоса первого знамения, то поверят голосу последнего знамения.'),
(1611, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 9, 'OT', 'И будет, если они не поверят и этим двум знамениям и не послушают голоса твоего, то возьми воды из реки и вылей на сушу; и вода, которую ты возьмёшь из реки, станет кровью на суше.'),
(1612, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 10, 'OT', 'И сказал Моисей Господу: о, Господь! Я не человек слов, ни со вчерашнего дня, ни с третьего дня, ни с того времени, как Ты говорил к рабу Твоему; ибо я тяжел устами и тяжел языком.'),
(1613, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 11, 'OT', 'И сказал Господь ему: кто дал уста человеку, или кто делает немым, или глухим, или зрячим, или слепым? Не Я ли, Господь?'),
(1614, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 12, 'OT', 'Итак, иди, и Я буду с устами твоими и научу тебя, что говорить.'),
(1615, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 13, 'OT', 'Господь, пошли же через кого-то, кого Ты пошлёшь.'),
(1616, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 14, 'OT', 'И разгневался Господь на Моисея и сказал: разве не Аарон, брат твой, левит? Я знаю, что он будет говорить; и вот, он выходит навстречу тебе, и, увидев тебя, возрадуется в сердце своём.'),
(1617, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 15, 'OT', 'И говори ему, и вложи слова в уста его; и Я буду с устами твоими и с устами его, и научу вас тому, что вам делать.'),
(1618, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 16, 'OT', 'И он будет говорить за тебя к народу; и будет он тебе устами, а ты будешь ему Богом.'),
(1619, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 17, 'OT', 'И возьми этот жезл в руку твою, которым будешь совершать знамения.'),
(1620, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 18, 'OT', 'Пошёл Моисей и возвратился к Иеферу, своему тестю, и сказал ему: «Пойду я и возвращусь к братьям моим, которые в Египте, и посмотрю, живы ли они ещё». И сказал Иофор Моисею: «Иди с миром».'),
(1621, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 19, 'OT', 'Господь сказал Моисею в Мадиане: иди, возвратись в Египет, ибо умерли все люди, искавшие жизни твоей.'),
(1622, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 20, 'OT', 'Взял Моисей жену свою и сыновей своих, и посадил их на осла, и возвратился в землю Египетскую; и взял Моисей жезл Божий в руку свою.'),
(1623, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 21, 'OT', 'И сказал Господь Моисею: когда пойдёшь возвращаться в Египет, смотри, все чудеса, которые Я вложил в руку твою, соверши их пред лицом фараона; а Я ожесточу сердце его, и не отпустит он народ.'),
(1624, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 22, 'OT', 'И скажи фараону: так говорит Господь: сын Мой, первенец Мой — Израиль.'),
(1625, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 23, 'OT', 'И сказал я тебе: отпусти сына моего, и он послужит мне; но ты отказался отпустить его; вот, я убиваю сына твоего, первенца твоего.'),
(1626, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 24, 'OT', 'И было в пути, в гостинице, и встретил его Господь, и искал умертвить его.'),
(1627, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 25, 'OT', 'Взяла Сепфора кремень, отсекла крайнюю плоть сына своего, и коснулась ног его, и сказала: ибо ты жених крови мне.'),
(1628, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 26, 'OT', 'И отпустил Он его; тогда она сказала: жених крови — из-за обрезания.'),
(1629, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 27, 'OT', 'И сказал Господь Аарону: иди навстречу Моисею в пустыню. И пошёл он, и встретил его на горе Божьей, и поцеловал его.'),
(1630, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 28, 'OT', 'Моисей пересказал Аарону все слова Господа, которые Он послал его сказать, и все знамения, которые Он повелел ему совершить.'),
(1631, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 29, 'OT', 'Пошли Моисей и Аарон, и собрали всех старейшин сынов Израиля.'),
(1632, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 30, 'OT', 'И говорил Аарон все слова, которые сказал Господь Моисею, и совершил знамения пред очами народа.'),
(1633, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 4, 31, 'OT', 'И поверил народ, и услышали, что Господь посетил сынов Израиля и что Он увидел бедствие их, и преклонились они, и поклонились.'),
(1634, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 1, 'OT', 'И после того пришли Моисей и Аарон и сказали фараону: так говорит Господь, Бог Израиля: отпусти народ Мой, и пусть они совершат праздник Мне в пустыне.'),
(1635, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 2, 'OT', 'Фараон сказал: кто Господь, чтобы я послушался голоса Его и отпустил Израиль? Я не знаю Господа, и Израиль не отпущу.'),
(1636, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 3, 'OT', 'И сказали они: Бог Евреев призван на нас; пойдём же путём трёх дней в пустыню и принесём жертву Господу, Богу нашему, чтобы не поразил Он нас мором или мечом.'),
(1637, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 4, 'OT', 'И сказал им царь Египта: зачем вы, Моисей и Аарон, отвлекаете народ от дел его? Идите на свои бремена.'),
(1638, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 5, 'OT', 'И сказал фараон: вот, многочислен теперь народ земли, и вы отстраняете их от их бремени.'),
(1639, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 6, 'OT', 'И повелел фараон в тот день надзирателям над народом и его надсмотрщикам, говоря:'),
(1640, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 7, 'OT', 'Не давайте более соломы народу для делания кирпичей, как вчера и третьего дня; пусть они сами идут и собирают себе солому.'),
(1641, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 8, 'OT', 'И меру кирпичей, которую они делали вчера и третьего дня, возложите на них; не убавляйте от неё, ибо они праздны; потому они и вопиют, говоря: пойдём, принесём жертву Богу нашему.'),
(1642, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 9, 'OT', 'Пусть отяготится работа на тех людях, и пусть они занимаются ею, и пусть не обращают внимания на слова лжи.'),
(1643, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 10, 'OT', 'Вышли надзиратели народа и его надсмотрщики и сказали народу так: так говорит фараон: я не даю вам соломы.'),
(1644, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 11, 'OT', 'Идите, возьмите себе солому, где найдёте, ибо не убавлено от работы вашей ни слова.'),
(1645, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 12, 'OT', 'И рассеялся народ по всей земле Египетской, чтобы собирать солому для соломы.'),
(1646, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 13, 'OT', 'И надзиратели торопили, говоря: завершайте ваши дела, слово дня в день его, как было при наличии соломы.'),
(1647, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 14, 'OT', 'И были избиты надзиратели из сынов Израиля, которых поставили над ними приставники фараона, говоря: почему вы не выполнили норму вашу о кирпичах, как вчера, так и сегодня?'),
(1648, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 15, 'OT', 'Пришли надзиратели из сынов Израиля и воззвали к фараону, говоря: зачем ты делаешь так рабам твоим?'),
(1649, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 16, 'OT', 'Солома не даётся рабам твоим, и кирпичи нам говорят: делайте; и вот рабы твои побиты, и грех народа твоего.'),
(1650, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 17, 'OT', 'Он сказал: вы ленивы, ленивы, потому и говорите: пойдём, принесём жертву Господу.'),
(1651, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 18, 'OT', 'Итак, идите, работайте, и солома не будет дана вам, но меру кирпичей вы должны давать.'),
(1652, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 19, 'OT', 'И увидели надзиратели сынов Израилевых себя в беде, говоря: не убавляйте от кирпичей ваших слова дня в день его.'),
(1653, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 20, 'OT', 'И встретили они Моисея и Аарона, стоящих перед ними, когда они вышли от фараона.'),
(1654, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 21, 'OT', 'И сказали они им: да увидит Господь на вас и рассудит, что вы сделали отвратительным запах наш в очах фараона и в очах рабов его, чтобы дать меч в руку их, чтобы убить нас.'),
(1655, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 22, 'OT', 'И возвратился Моисей к Господу и сказал: Господь, зачем Ты сделал зло этому народу, зачем Ты послал меня?'),
(1656, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 5, 23, 'OT', 'И с того времени, как я пришёл к фараону говорить именем Твоим, он сделал зло народу этому, и Ты не избавил народа Твоего.'),
(1657, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 1, 'OT', 'И сказал Господь Моисею: теперь увидишь, что Я сделаю фараону; ибо рукою крепкою он отпустит их, и рукою крепкою изгонит их из земли своей.'),
(1658, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 2, 'OT', 'И говорил Бог к Моисею, и сказал ему: Я Господь.'),
(1659, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 3, 'OT', 'Являлся Я Аврааму, Исааку и Иакову как Бог Вседержитель, а с именем Моим Господь не был Я познан ими.'),
(1660, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 4, 'OT', 'И также Я поставил завет Мой с ними, чтобы дать им землю Ханаан, землю странствия их, в которой они странствовали.'),
(1661, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 5, 'OT', 'И также Я услышал стенание сынов Израиля, которых Египет порабощает, и вспомнил завет Мой.'),
(1662, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 6, 'OT', 'Поэтому скажи сынам Израиля: Я — Господь, и выведу вас из-под бремени Египта, и избавлю вас от работ их, и спасу вас мышцей простёртой и судами великими.'),
(1663, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 7, 'OT', 'И возьму вас Себе в народ, и буду вам Богом, и узнаете, что Я Господь, Бог ваш, выводящий вас из-под бремени Египта.'),
(1664, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 8, 'OT', 'И приведу вас в землю, о которой Я поднял руку Мою, чтобы дать её Аврааму, Исааку и Иакову, и дам её вам в наследие: Я Господь.'),
(1665, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 9, 'OT', 'И говорил Моисей так сынам Израиля, но они не слушали Моисея из-за скорби духа и из-за тяжкой работы.'),
(1666, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 10, 'OT', 'И сказал Господь к Моисею, говоря:'),
(1667, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 11, 'OT', 'Пойди, скажи фараону, царю Египта, чтобы он отпустил сынов Израиля из земли своей.'),
(1668, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 12, 'OT', 'И сказал Моисей пред лицом Господа, говоря: вот, сыны Израиля не послушали меня, и как послушает меня фараон? А я с необрезанными устами.'),
(1669, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 13, 'OT', 'И говорил Господь к Моисею и к Аарону, и повелел им к сынам Израиля и к фараону, царю Египетскому, чтобы вывести сынов Израиля из земли Египетской.'),
(1670, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 14, 'OT', 'Вот главы дома отцов их: сыны Рувима, первенца Израиля: Енох и Фаллу, Хецрон и Кармий; вот семейства Рувима.'),
(1671, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 15, 'OT', 'Сыновья Симеона: Емуил, и Иамин, и Охад, и Иахин, и Цохар, и Саул, сын Хананеянин; это семейства Симеона.'),
(1672, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 16, 'OT', 'И вот имена сынов Левия по родословиям их: Герсон, Кааф и Мерари; а лет жизни Левия было сто тридцать семь лет.'),
(1673, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 17, 'OT', 'Сыновья Герсона: Ливни и Симей, по их семействам.'),
(1674, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 18, 'OT', 'Сыновья Каафа: Амрам, Ицгар, Хеврон и Озиил; и лет жизни Каафа было сто тридцать три года.'),
(1675, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 19, 'OT', 'Сыновья Мерари: Махли и Муший; это семейства Левия по их родословиям.'),
(1676, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 20, 'OT', 'Амрам взял Иохаведу, тётку свою, себе в жёны, и она родила ему Аарона и Моисея; а лет жизни Амрама было сто тридцать семь лет.'),
(1677, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 21, 'OT', 'Сыновья Ицгара: Корей, Нефег и Зихрий.'),
(1678, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 22, 'OT', 'Сыновья Озиила: Мисаил, Елицафан и Сифри.'),
(1679, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 23, 'OT', 'Аарон взял Елисавету, дочь Аминадава, сестру Наассона, себе в жены, и она родила ему Надава и Авиуда, Елеазара и Ифамара.'),
(1680, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 24, 'OT', 'Сыновья Корея: Ассир, Елкана и Авиасаф; это семейства Кореянина.'),
(1681, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 25, 'OT', 'Елеазар, сын Аарона, взял себе из дочерей Путиила себе в жену, и она родила ему Финхеса; это главы отцов левитов по их семействам.'),
(1682, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 26, 'OT', 'Это Аарон и Моисей, которым Господь сказал: выведите сынов Израиля из земли Египетской по войскам их.'),
(1683, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 27, 'OT', 'Они говорили с фараоном, царём Египта, чтобы вывести сынов Израиля из Египта; это Моисей и Аарон.'),
(1684, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 28, 'OT', 'И было в день, когда говорил Господь к Моисею в земле Египетской.'),
(1685, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 29, 'OT', 'И говорил Господь к Моисею, говоря: Я Господь; скажи фараону, царю Египта, всё, что Я говорю тебе.'),
(1686, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 6, 30, 'OT', 'И сказал Моисей пред лицом Господа: вот, я с необрезанными устами, и как же послушает меня фараон?'),
(1687, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 1, 'OT', 'Господь сказал Моисею: вот, Я поставил тебя Богом для фараона, и Аарон, брат твой, будет твоим пророком.'),
(1688, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 2, 'OT', 'Ты говори всё, что Я повелю тебе, и Аарон, брат твой, будет говорить фараону, и он отпустит сынов Израиля из земли своей.'),
(1689, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 3, 'OT', 'А Я ожесточу сердце фараона, и умножу знамения Мои и чудеса Мои в земле Египетской.'),
(1690, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 4, 'OT', 'И не послушает вас фараон, и Я возложу руку Мою на Египет, и выведу войска Мои, народ Мой, сынов Израилевых, из земли Египетской судами великими.'),
(1691, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 5, 'OT', 'И узнают египтяне, что Я — Господь, когда простру руку Мою на Египет, и выведу сынов Израиля из среды их.'),
(1692, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 6, 'OT', 'Моисей и Аарон сделали так, как повелел им Господь; так они и сделали.'),
(1693, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 7, 'OT', 'Моисей был сыном восьмидесяти лет, и Аарон — сыном восьмидесяти трёх лет, когда они говорили с фараоном.'),
(1694, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 8, 'OT', 'И сказал Господь Моисею и Аарону, говоря:'),
(1695, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 9, 'OT', 'Когда фараон скажет вам: «Сделайте себе чудо», — то скажи Аарону: «Возьми твой жезл и брось его перед лицом фараона, и он станет драконом».'),
(1696, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 10, 'OT', 'И пришёл Моисей и Аарон к фараону, и сделали так, как повелел Господь: и бросил Аарон свой жезл перед лицом фараона и перед лицом рабов его, и стал он драконом.'),
(1697, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 11, 'OT', 'И призвал также фараон мудрецов и чародеев, и сделали также они, чародеи Египта, своими чарами так.'),
(1698, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 12, 'OT', 'И бросил каждый человек свой жезл, и они стали драконами, и жезл Аарона поглотил их жезлы.'),
(1699, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 13, 'OT', 'Сердце фараона ожесточилось, и он не послушал их, как и говорил Господь.'),
(1700, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 14, 'OT', 'Господь сказал Моисею: сердце фараона ожесточилось, он не хочет отпустить народ.'),
(1701, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 15, 'OT', 'Иди к фараону утром; вот, он выходит к воде, и стань перед ним на берегу реки, и жезл, который превратился в змея, возьми в руку твою.'),
(1702, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 16, 'OT', 'И скажи ему: Господь, Бог Евреев, послал меня к тебе сказать: отпусти народ Мой, и пусть они служат Мне в пустыне; но вот, ты не послушал до сих пор.'),
(1703, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 17, 'OT', 'Так говорит Господь: из этого ты узнаешь, что Я — Господь: вот, Я ударю жезлом, который в руке Моей, по воде, которая в реке, и она превратится в кровь.'),
(1704, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 18, 'OT', 'И рыба, которая в реке, умрёт, и река воссмердит, и египтяне устанут пить воду из реки.'),
(1705, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 19, 'OT', 'И сказал Господь Моисею: скажи Аарону: возьми жезл твой и простри руку твою на воды Египта, на реки их, на каналы их и на болота их, и на всё собрание вод их, и будут кровью; и будет кровь по всей земле Египетской, и в дереве, и в камне.'),
(1706, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 20, 'OT', 'И сделали так Моисей и Аарон, как повелел Господь: и поднял он жезл, и ударил по воде, которая в реке, пред очами фараона и пред очами рабов его, и обратилась вся вода, которая в реке, в кровь.'),
(1707, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 21, 'OT', 'И рыба, которая в реке, умерла, и река воссмердела, и не могли Египтяне пить воды из реки; и была кровь по всей земле Египетской.'),
(1708, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 22, 'OT', 'И сделали так чародеи Египта тайно, и ожесточилось сердце фараона, и не послушал он их, как говорил Господь.'),
(1709, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 23, 'OT', 'И обернулся фараон, и пошёл в дом свой, и не приложил сердца своего и к этому.'),
(1710, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 24, 'OT', 'И копали все Египтяне вокруг реки воды для питья, потому что не могли пить из вод реки.'),
(1711, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 7, 25, 'OT', 'И исполнилось семь дней после того, как Господь поразил реку.'),
(1712, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 1, 'OT', 'И сказал Господь Моисею: пойди к фараону и скажи ему: так говорит Господь: отпусти народ Мой, и пусть они служат Мне.'),
(1713, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 2, 'OT', 'Если же ты отказываешься отпустить, вот, Я поражаю всю границу твою лягушками.'),
(1714, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 3, 'OT', 'И воскишит река лягушками, и они выйдут и войдут в дом твой, и во внутреннюю комнату ложа твоего, и на постель твою, и в дом рабов твоих, и в народ твой, и в печи твои, и в квашни твои.'),
(1715, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 4, 'OT', 'И на тебя, и на народ твой, и на всех рабов твоих взойдут лягушки.'),
(1716, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 5, 'OT', 'И сказал Господь Моисею: скажи Аарону: простри руку твою с жезлом твоим на реки, на каналы и на болота, и выведи лягушек на землю Египетскую.'),
(1717, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 6, 'OT', 'Простер Аарон руку свою на воды Египта, и вышла лягушка, и покрыла землю Египетскую.'),
(1718, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 7, 'OT', 'И сделали так же чародеи тайнами своими, и вывели лягушек на землю Египетскую.'),
(1719, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 8, 'OT', 'И призвал фараон Моисея и Аарона и сказал: помолитесь Господу, и пусть удалит лягушек от меня и от народа моего, и я отпущу народ, и они принесут жертву Господу.'),
(1720, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 9, 'OT', 'И сказал Моисей фараону: назначь мне, когда мне помолиться о тебе, и о рабах твоих, и о народе твоём, чтобы истребить лягушек от тебя и от домов твоих; только в реке они останутся.'),
(1721, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 10, 'OT', 'И сказал он: завтра. И сказал: по слову твоему, чтобы ты знал, что нет подобного Господу, Богу нашему.'),
(1722, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 11, 'OT', 'И отойдут лягушки от тебя и от домов твоих, и от рабов твоих, и от народа твоего; только в реке они останутся.'),
(1723, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 12, 'OT', 'И вышел Моисей и Аарон от фараона, и воззвал Моисей к Господу о слове лягушек, которых Он навёл на фараона.'),
(1724, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 13, 'OT', 'И сделал Господь по слову Моисея, и умерли лягушки из домов, из дворов и из полей.'),
(1725, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 14, 'OT', 'И собрали их в кучи, кучи, и воссмердела земля.'),
(1726, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 15, 'OT', 'Фараон увидел, что настала передышка, и отягчил сердце своё, и не послушал их, как говорил Господь.'),
(1727, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 16, 'OT', 'И сказал Господь Моисею: скажи Аарону: простри жезл твой и ударь по праху земли, и будет он вошью во всей земле Египетской.'),
(1728, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 17, 'OT', 'И сделали они так: и простёр Аарон руку свою с жезлом своим, и ударил в прах земли, и стала вошь на человеке и на скоте; весь прах земли стал вшами во всей земле Египетской.'),
(1729, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 18, 'OT', 'И сделали так чародеи тайно, чтобы вывести вшей, и не смогли; и были вши на человеке и на скоте.'),
(1730, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 19, 'OT', 'И сказали чародеи фараону: это перст Божий. Но ожесточилось сердце фараона, и он не послушал их, как говорил Господь.'),
(1731, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 20, 'OT', 'И сказал Господь Моисею: встань рано утром и стань пред лицом фараона; вот, он выходит к воде, и скажи ему: так говорит Господь: отпусти народ Мой, и пусть они служат Мне.'),
(1732, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 21, 'OT', 'Если же ты не отпустишь народ Мой, то вот, Я пошлю на тебя, и на рабов твоих, и на народ твой, и на дома твои песьих мух, и наполнятся дома Египтян песьими мухами, и также земля, на которой они.'),
(1733, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 22, 'OT', 'И отделю Я в тот день землю Гошен, на которой стоит народ Мой, чтобы не было там песьих мух, дабы ты знал, что Я — Господь посреди земли.'),
(1734, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 23, 'OT', 'И положу искупление между народом Моим и народом твоим; завтра будет это знамение.'),
(1735, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 24, 'OT', 'И сделал Господь так, и налетели тяжёлые песьи мухи на дом фараона и на дом рабов его, и по всей земле Египетской земля была испорчена от лица песьих мух.'),
(1736, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 25, 'OT', 'И призвал фараон Моисея и Аарона, и сказал: пойдите, принесите жертву Богу вашему в земле.'),
(1737, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 26, 'OT', 'И сказал Моисей: не годится так делать, ибо мерзость для Египтян мы принесём в жертву Господу, Богу нашему; если мы принесём в жертву мерзость для Египтян перед их очами, не побьют ли они нас камнями?'),
(1738, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 27, 'OT', 'Путём трёх дней пойдём в пустыне, и принесём жертву Господу, Богу нашему, как Он скажет нам.'),
(1739, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 28, 'OT', 'И сказал фараон: я отпущу вас, и принесёте жертву Господу, Богу вашему, в пустыне; только не удаляйтесь далеко, идя; помолитесь обо мне.'),
(1740, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 29, 'OT', 'И сказал Моисей: вот, я выхожу от тебя и помолюсь Господу, и удалятся песьи мухи от фараона, от рабов его и от народа его завтра; только пусть фараон не продолжает обманывать, не отпуская народ принести жертву Господу.'),
(1741, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 30, 'OT', 'И вышел Моисей от фараона и помолился Господу.'),
(1742, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 31, 'OT', 'И сделал Господь по слову Моисея, и удалил песьих мух от фараона, от рабов его и от народа его; не осталось ни одной.'),
(1743, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 8, 32, 'OT', 'И ожесточил фараон сердце своё и в этот раз, и не отпустил народ.'),
(1744, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 1, 'OT', 'И сказал Господь Моисею: пойди к фараону и скажи ему: так говорит Господь, Бог Евреев: отпусти народ Мой, и пусть они служат Мне.'),
(1745, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 2, 'OT', 'Если же ты отказываешься отпустить и продолжаешь удерживать их,'),
(1746, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 3, 'OT', 'Вот рука Господа будет на скоте твоём, который в поле, на конях, на ослах, на верблюдах, на крупном рогатом скоте и на овцах: мор весьма тяжёлый.'),
(1747, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 4, 'OT', 'И отличит Господь между скотом Израиля и между скотом Египта, и не умрёт из всего, что у сынов Израиля, ни одно слово.'),
(1748, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 5, 'OT', 'И установил Господь срок, сказав: завтра совершит Господь слово это на земле.'),
(1749, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 6, 'OT', 'Господь сделал это слово на следующий день, и весь скот Египтян умер, а из скота сынов Израиля не умерло ни одного.'),
(1750, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 7, 'OT', 'И послал фараон, и вот, не умерло из скота Израиля ни одно; и отяжелело сердце фараона, и не отпустил он народ.'),
(1751, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 8, 'OT', 'И сказал Господь Моисею и Аарону: возьмите себе полные горсти пепла из печи, и пусть бросит его Моисей к небу на глазах у фараона.'),
(1752, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 9, 'OT', 'И будет это пылью по всей земле Египетской, и будет на человеке и на скоте нарывом, воспаляющим нарывами, по всей земле Египетской.'),
(1753, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 10, 'OT', 'И взяли они пепел из печи, и стали пред лицом фараона, и бросил его Моисей к небу, и сделался нарыв, нарывы, расцветающий на человеке и на скоте.'),
(1754, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 11, 'OT', 'И не могли чародеи стоять пред лицом Моисея из-за нарыва, ибо был нарыв на чародеях и на всех египтянах.'),
(1755, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 12, 'OT', 'И ожесточил Господь сердце фараона, и не послушал он их, как говорил Господь Моисею.'),
(1756, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 13, 'OT', 'И сказал Господь Моисею: встань рано утром и стань пред лицом фараона, и скажи ему: так говорит Господь, Бог Евреев: отпусти народ Мой, и пусть они служат Мне.'),
(1757, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 14, 'OT', 'Ибо в этот раз Я пошлю все язвы Мои на сердце твоё, и на рабов твоих, и на народ твой, ради того, чтобы ты знал, что нет подобного Мне во всей земле.'),
(1758, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 15, 'OT', 'Ибо теперь Я простёр руку Мою и поразил бы тебя и народ твой мором, и ты был бы истреблён с земли.'),
(1759, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 16, 'OT', 'Но ради этого Я поставил тебя, чтобы показать тебе Мою силу, и чтобы возвестить Моё имя по всей земле.'),
(1760, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 17, 'OT', 'Ты всё ещё превозносишься над народом Моим, не желая отпустить их.'),
(1761, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 18, 'OT', 'Вот, Я пролью в это же время завтра град весьма тяжкий, какого не было в Египте от дня основания его и доныне.'),
(1762, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 19, 'OT', 'Итак, пошли, собери скот твой и всё, что у тебя в поле; всякий человек и скот, которые найдутся в поле и не будут собраны в дом, — сойдёт на них град, и они умрут.'),
(1763, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 20, 'OT', 'Боящийся слова Господня из рабов фараона укрыл своих рабов и свой скот в дома.'),
(1764, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 21, 'OT', 'А тот, кто не обратил сердца своего к слову Господа, оставил рабов своих и скот свой в поле.'),
(1765, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 22, 'OT', 'И сказал Господь Моисею: простри руку твою к небу, и будет град по всей земле Египетской, на человека и на скот, и на всякую траву полевую в земле Египетской.'),
(1766, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 23, 'OT', 'И простёр Моисей жезл свой к небу, и Господь дал раскаты грома и град, и пошёл огонь по земле, и пролил Господь град на землю Египетскую.'),
(1767, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 24, 'OT', 'Был град, и огонь, пылающий среди града, весьма тяжёлый, какого не было во всей земле Египта с тех пор, как она стала народом.'),
(1768, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 25, 'OT', 'И поразил град всю землю Египетскую: всё, что было в поле, от человека до скота, и всю траву полевую побил град, и все деревья полевые сломил.'),
(1769, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 26, 'OT', 'Только в земле Гошен, где были сыны Израиля, не было града.'),
(1770, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 27, 'OT', 'И послал фараон, и призвал Моисея и Аарона, и сказал им: согрешил я на этот раз; Господь праведен, а я и народ мой виновны.'),
(1771, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 28, 'OT', 'Умолите Господа, и довольно уже раскатов грома Божьих и града; и я отпущу вас, и не будете более оставаться.'),
(1772, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 29, 'OT', 'И сказал ему Моисей: когда я выйду из города, я простру ладони мои к Господу; раскаты грома прекратятся, и града не будет более, чтобы ты знал, что Господу принадлежит земля.'),
(1773, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 30, 'OT', 'А ты и рабы твои, я знаю, что ещё не убоитесь лица Господа Бога.'),
(1774, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 31, 'OT', 'Лён и ячмень были побиты, потому что ячмень был в колосе, а лён в стебле.'),
(1775, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 32, 'OT', 'Пшеница же и полба не были побиты, ибо они были поздние.'),
(1776, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 33, 'OT', 'И вышел Моисей от фараона из города, и простёр ладони свои к Господу, и прекратились раскаты грома, и град, и дождь не излился на землю.'),
(1777, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 34, 'OT', 'Фараон увидел, что дождь, и град, и раскаты грома прекратились, и продолжал грешить, и отягчил сердце своё он и рабы его.'),
(1778, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 9, 35, 'OT', 'И ожесточилось сердце фараона, и он не отпустил сынов Израиля, как говорил Господь через Моисея.'),
(1779, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 1, 'OT', 'И сказал Господь Моисею: войди к фараону, ибо Я отягчил сердце его и сердце рабов его, чтобы совершить Мои знамения эти среди него.'),
(1780, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 2, 'OT', 'И чтобы ты рассказывал в уши сына твоего и сына сына твоего о том, что Я сделал в Египте, и о знамениях Моих, которые Я совершил среди них, и чтобы вы знали, что Я — Господь.'),
(1781, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 3, 'OT', 'И пришёл Моисей и Аарон к фараону и сказали ему: так говорит Господь, Бог Евреев: доколе ты отказываешься смириться пред лицом Моим? Отпусти народ Мой, и пусть они служат Мне.'),
(1782, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 4, 'OT', 'Если же ты отказываешься отпустить народ Мой, то вот, Я наведу завтра саранчу на границы твои.'),
(1783, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 5, 'OT', 'И покроет поверхность земли, и не сможет видеть земли, и съест остаток уцелевшего, оставшийся у вас от града, и съест всё дерево, растущее у вас из поля.'),
(1784, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 6, 'OT', 'И наполнят дома твои и дома всех рабов твоих, и дома всех Египтян, чего не видели отцы твои и отцы отцов твоих со дня, как они на земле, до сего дня; и он повернулся и вышел от фараона.'),
(1785, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 7, 'OT', 'И сказали рабы фараона ему: доколе это будет для нас западнёй? Отпусти этих людей, и пусть они служат Господу, Богу своему; неужели ты ещё не знаешь, что погиб Египет?'),
(1786, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 8, 'OT', 'И возвращены были Моисей и Аарон к фараону, и сказал он им: идите, служите Господу, Богу вашему; кто и кто идущие?'),
(1787, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 9, 'OT', 'И сказал Моисей: с отроками нашими и со старцами нашими пойдём, с сынами нашими и с дочерями нашими, с овцами нашими и с крупным рогатым скотом нашим пойдём, ибо праздник Господа у нас.'),
(1788, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 10, 'OT', 'И сказал им: да будет так, Господь с вами, когда я отпущу вас и детей ваших; смотрите, зло пред лицом вашим.'),
(1789, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 11, 'OT', 'Не так; идите, мужи, и служите Господу, ибо этого вы ищете. И выгнали их от лица фараона.'),
(1790, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 12, 'OT', 'И сказал Господь Моисею: простри руку твою на землю Египетскую, и пусть поднимется саранча на землю Египетскую и съест всю траву земли, всё, что оставил град.'),
(1791, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 13, 'OT', 'Простёр Моисей жезл свой на землю Египетскую, и Господь навёл ветер восточный на землю весь тот день и всю ночь; настало утро, и ветер восточный понёс саранчу.'),
(1792, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 14, 'OT', 'И поднялась саранча на всю землю Египетскую, и опустилась во всех границах Египта, весьма тяжкая; перед лицом её не было такой саранчи, как она, и после неё не будет такой.'),
(1793, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 15, 'OT', 'И покрыл он поверхность всей земли, и потемнела земля, и съел он всю траву земли и весь плод дерева, который оставил град, и не осталось никакой зелени на дереве и на траве поля во всей земле Египта.'),
(1794, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 16, 'OT', 'Поспешил фараон призвать Моисея и Аарона и сказал: согрешил я пред Господом, Богом вашим, и пред вами.'),
(1795, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 17, 'OT', 'И ныне прости грех мой ещё только на этот раз, и помолитесь Господу Богу вашему, чтобы Он отвёл от меня лишь эту смерть.'),
(1796, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 18, 'OT', 'И вышел он от фараона и помолился Господу.'),
(1797, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 19, 'OT', 'Господь обратил ветер западного моря в очень сильный ветер, и он понёс саранчу, и бросил её в тростниковое море; не осталось ни одной саранчи во всей границе Египта.'),
(1798, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 20, 'OT', 'И укрепил Господь сердце фараона, и не отпустил он сынов Израиля.'),
(1799, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 21, 'OT', 'И сказал Господь Моисею: простри руку твою к небу, и будет тьма на земле Египетской, и осязаема будет тьма.'),
(1800, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 22, 'OT', 'И простёр Моисей руку свою к небу, и была тьма густая по всей земле Египетской три дня.'),
(1801, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 23, 'OT', 'Не видели люди брата своего, и не вставали люди с места своего три дня; а у всех сынов Израиля был свет в жилищах их.'),
(1802, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 24, 'OT', 'И позвал фараон Моисея и сказал: пойдите, служите Господу; только овцы ваши и крупный рогатый скот ваши пусть останутся; также дети ваши пойдут с вами.'),
(1803, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 25, 'OT', 'И сказал Моисей: также ты дашь в руку нашу жертвы и всесожжения, и мы совершим их для Господа, Бога нашего.'),
(1804, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 26, 'OT', 'И также скот наш пойдёт с нами, не останется ни копыта, ибо из него мы возьмём, чтобы служить Господу, Богу нашему; и мы не знаем, чем будем служить Господу, пока не придём туда.'),
(1805, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 27, 'OT', 'И ожесточил Господь сердце фараона, и не захотел он отпустить их.'),
(1806, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 28, 'OT', 'И сказал ему фараон: уйди от меня; берегись, не добавляй видеть лицо моё, ибо в день, когда увидишь лицо моё, умрёшь.'),
(1807, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 10, 29, 'OT', 'И сказал Моисей: так ты сказал; не буду более видеть лица твоего.'),
(1808, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 1, 'OT', 'И сказал Господь Моисею: ещё одну язву наведу на фараона и на Египет; после того он отпустит вас отсюда; когда же он отпустит, то совсем прогонит вас отсюда.'),
(1809, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 2, 'OT', 'Скажи, пожалуйста, в уши народа, и пусть попросит человек у своего ближнего, и жена у своей ближней, сосуды серебряные и сосуды золотые.'),
(1810, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 3, 'OT', 'И дал Господь благодать народу в очах Египтян; также и человек Моисей был очень велик в земле Египетской, в очах рабов фараона и в очах народа.'),
(1811, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 4, 'OT', 'И сказал Моисей: так говорит Господь: в полночь Я выйду в середину Египта.'),
(1812, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 5, 'OT', 'И умрёт всякий первенец в земле Египетской, от первенца фараона, сидящего на престоле своём, до первенца служанки, которая за жёрновом, и весь первенец скота.'),
(1813, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 6, 'OT', 'И будет великий вопль по всей земле Египетской, какого не бывало и какого больше не будет.'),
(1814, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 7, 'OT', 'А у всех сынов Израиля не пошевелит пёс языком своим ни против человека, ни против скота, чтобы вы знали, что Господь отличает между Египтом и Израилем.'),
(1815, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 8, 'OT', 'И сойдут все рабы твои эти ко мне, и поклонятся мне, говоря: выйди ты и весь народ, который в ногах твоих, и после того я выйду; и вышел он от фараона в ярости гнева.'),
(1816, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 9, 'OT', 'И сказал Господь Моисею: не послушает вас фараон, чтобы умножились чудеса Мои в земле Египетской.'),
(1817, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 11, 10, 'OT', 'Моисей и Аарон сделали все эти чудеса пред лицом фараона, и Господь ожесточил сердце фараона, и он не отпустил сынов Израиля из земли его.'),
(1818, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 1, 'OT', 'И сказал Господь Моисею и Аарону в земле Египетской, говоря:'),
(1819, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 2, 'OT', 'Этот месяц для вас — начало месяцев, первый он для вас среди месяцев года.'),
(1820, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 3, 'OT', 'Скажите всему обществу Израиля, говоря: в десятый день этого месяца пусть возьмут себе каждый человек овцу для дома отцов, овцу для дома.'),
(1821, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 4, 'OT', 'А если будет мал дом для овцы, то пусть возьмёт он и сосед его, ближний к дому его, по числу душ; каждый человек по мере пищи своей исчислите на овцу.'),
(1822, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 5, 'OT', 'Овца без порока, самец, сын года, будет у вас; из ягнят и из коз возьмёте.'),
(1823, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 6, 'OT', 'И будет он у вас на сохранение до четырнадцатого дня этого месяца, и заколет его всё собрание общества Израиля между вечерами.'),
(1824, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 7, 'OT', 'И возьмут из крови и помажут на обоих косяках и на перекладине дверей в домах, где будут есть его.'),
(1825, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 8, 'OT', 'И съедят плоть в эту ночь, жареное на огне, и опресноки с горечью съедят её.'),
(1826, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 9, 'OT', 'Не ешьте от него сырого и варёного в воде, но только жареное на огне: глава его с голенями его и с внутренностью его.'),
(1827, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 10, 'OT', 'И не оставляйте от него до утра, а оставшееся от него до утра сожгите на огне.'),
(1828, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 11, 'OT', 'И так ешьте его: чресла ваши препоясаны, обувь ваша на ногах ваших, и жезл ваш в руке вашей; и ешьте его с поспешностью: это Пасха Господня.'),
(1829, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 12, 'OT', 'И пройду Я по земле Египетской в эту ночь, и поражу всякого первенца в земле Египетской, от человека до скота, и над всеми богами Египта совершу суды: Я Господь.'),
(1830, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 13, 'OT', 'И будет кровь у вас знамением на домах, где вы находитесь; и увижу кровь, и пройду мимо вас, и не будет у вас язвы разрушительной, когда поражу землю Египетскую.'),
(1831, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 14, 'OT', 'И будет этот день для вас памятью, и будете праздновать его как праздник Господу; для родов ваших — устав вечности: празднуйте его.'),
(1832, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 15, 'OT', 'Семь дней ешьте опресноки; но в первый день уберите закваску из домов ваших, ибо всякий, кто ест квасное, — истребится та душа из Израиля, от первого дня до седьмого дня.'),
(1833, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 16, 'OT', 'И в первый день — священное собрание, и в седьмой день — священное собрание будет у вас; никакая работа не должна делаться в них, только то, что съедается всякою душою, — оно одно может делаться у вас только оно.'),
(1834, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 17, 'OT', 'Соблюдайте опресноки, ибо в этот самый день Я вывел ваши войска из земли Египетской; и соблюдайте этот день в роды ваши как устав вечности.'),
(1835, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 18, 'OT', 'В первый месяц, в четырнадцатый день месяца, вечером ешьте опресноки до двадцать первого дня месяца, вечером.'),
(1836, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 19, 'OT', 'Семь дней закваска не найдётся в домах ваших, ибо всякий, кто ест квасное, — истребится та душа из общества Израиля, у пришельца и у туземца земли.'),
(1837, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 20, 'OT', 'Всё квасное не ешьте; во всех жилищах ваших ешьте опресноки.'),
(1838, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 21, 'OT', 'И созвал Моисей всех старейшин Израиля и сказал им: выберите и возьмите себе овец по семействам вашим, и заколите Пасху.'),
(1839, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 22, 'OT', 'Возьмите связку иссопа, обмакните её в кровь, которая в чаше, и коснитесь перекладины и обоих косяков кровью, которая в чаше; а вы не выходите, каждый человек, из двери своего дома до утра.'),
(1840, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 23, 'OT', 'И пройдёт Господь, чтобы поразить Египет, и увидит кровь на перекладине и на обоих косяках, и пройдёт Господь мимо двери, и не даст губителю войти в дома ваши, чтобы поразить.'),
(1841, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 24, 'OT', 'И соблюдайте это слово как устав для себя и для сыновей твоих на вечность.'),
(1842, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 25, 'OT', 'И будет, когда вы войдёте в землю, которую Господь даст вам, как Он сказал, и будете соблюдать это служение.'),
(1843, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 26, 'OT', 'И будет, когда скажут вам сыновья ваши: что это за служение у вас?'),
(1844, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 27, 'OT', 'И скажете: это жертва Пасхи Господу, который прошёл мимо домов сынов Израиля в Египте, когда поражал Египет, а дома наши спас; и преклонился народ, и поклонился.'),
(1845, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 28, 'OT', 'И пошли и сделали сыны Израиля; как повелел Господь Моисею и Аарону, так и сделали.'),
(1846, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 29, 'OT', 'И было в половине ночи, и Господь поразил всех первенцев в земле Египетской, от первенца фараона, сидящего на престоле своём, до первенца пленника, который в доме темницы, и всех первенцев скота.'),
(1847, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 30, 'OT', 'Встал фараон ночью, он и все рабы его, и весь Египет; и был великий вопль в Египте, ибо не было дома, где не было бы мёртвого.'),
(1848, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 31, 'OT', 'И призвал он Моисея и Аарона ночью и сказал: встаньте, выйдите из среды народа моего, и вы, и сыны Израиля, и пойдите, служите Господу, как вы говорили.'),
(1849, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 32, 'OT', 'Также овец ваших, также крупный рогатый скот ваш возьмите, как вы говорили, и идите, и благословите также меня.'),
(1850, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 33, 'OT', 'Египтяне настояли на народе, чтобы поскорее выслать их из земли, ибо говорили: все мы умираем.'),
(1851, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 34, 'OT', 'И народ понёс тесто своё, прежде чем оно вскисло; квашни их были завязаны в одеждах их на плечах их.'),
(1852, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 35, 'OT', 'И сыны Израиля сделали по слову Моисея, и попросили у Египта сосуды серебряные и сосуды золотые, и одежды.'),
(1853, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 36, 'OT', 'Господь дал расположение народу в очах Египта, и они дали взаймы им; и они обобрали Египет.'),
(1854, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 37, 'OT', 'Сыны Израиля отправились из Раамсеса в Сокхоф, около шестисот тысяч пеших мужчин, кроме детей.'),
(1855, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 38, 'OT', 'И также смешанное множество многое вышло с ними, и овцы, и крупный рогатый скот, скот весьма тяжёлый.'),
(1856, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 39, 'OT', 'И испекли они тесто, которое вынесли из Египта, лепёшки опресночные, ибо оно не вскисло, потому что они были изгнаны из Египта и не могли медлить, и даже продовольствия не приготовили себе.'),
(1857, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 40, 'OT', 'Пребывание сынов Израиля, которые жили в Египте, — тридцать лет и четыреста лет.'),
(1858, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 41, 'OT', 'И было по прошествии четырёхсот тридцати лет, в тот самый день, вышли все войска Господни из земли Египетской.'),
(1859, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 42, 'OT', 'Ночь бдения это у Господа, чтобы вывести их из земли Египетской; эта ночь — бдение у Господа для всех сынов Израиля в роды их.'),
(1860, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 43, 'OT', 'Господь сказал Моисею и Аарону: вот устав Пасхи: всякий сын чужой не будет есть её.'),
(1861, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 44, 'OT', 'И всякий раб человека, купленный за серебро, — и обрежешь его, тогда он будет есть от него.'),
(1862, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 45, 'OT', 'Пришелец и наёмник не будет есть его.'),
(1863, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 46, 'OT', 'В одном доме должно быть съедено; не выноси из дома плоти на улицу, и кости не ломайте в нём.'),
(1864, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 47, 'OT', 'Всё общество Израиля совершит его.'),
(1865, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 48, 'OT', 'И если поселится у тебя пришелец и совершит Пасху Господу, то пусть будет обрезан у него всякий мужчина, и тогда он может приступить к совершению её; и будет он как туземец земли, а всякий необрезанный не будет есть её.'),
(1866, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 49, 'OT', 'Закон один да будет и для туземца, и для пришельца, живущего среди вас.'),
(1867, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 50, 'OT', 'И сделали все сыны Израиля, как повелел Господь Моисею и Аарону, так и сделали.'),
(1868, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 12, 51, 'OT', 'И было в самый тот день: вывел Господь сынов Израиля из земли Египетской по войскам их.'),
(1869, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(1870, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 2, 'OT', 'Посвяти Мне всё первородное, первенца всякой матки у сынов Израиля, у человека и у скота: Моё оно.'),
(1871, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 3, 'OT', 'И сказал Моисей народу: помни этот день, в который вы вышли из Египта, из дома рабов, ибо крепостью руки Господь вывел вас отсюда; и не должно есть квасное.'),
(1872, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 4, 'OT', 'Сегодня вы выходите в месяце колосьев.'),
(1873, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 5, 'OT', 'И будет, когда введёт тебя Господь в землю Хананеянина, и Хеттеянина, и Аморрея, и Евеев, и Иевусеев, которую Он клялся отцам твоим дать тебе, землю, текущую молоком и мёдом, то соверши это служение в этом месяце.'),
(1874, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 6, 'OT', 'Семь дней ешь опресноки, и в седьмой день — праздник Господу.'),
(1875, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 7, 'OT', 'Опресноки ешь семь дней; и не должно быть видно у тебя квасного, и не должно быть видно у тебя закваски во всех границах твоих.'),
(1876, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 8, 'OT', 'И объяви сыну твоему в тот день, говоря: ради этого сделал Господь для меня, когда я выходил из Египта.'),
(1877, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 9, 'OT', 'И будет это тебе знамением на руке твоей и памятью между очами твоими, дабы закон Господа был в устах твоих, ибо рукою крепкою вывел тебя Господь из Египта.'),
(1878, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 10, 'OT', 'И соблюдай этот устав в назначенное для него время, изо дня в день.'),
(1879, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 11, 'OT', 'И будет, когда введет тебя Господь в землю Хананеянина, как Он клялся тебе и отцам твоим, и даст ее тебе,'),
(1880, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 12, 'OT', 'И посвяти всё, что разверзает матку, Господу; и всё первородное из приплода скота, какое будет у тебя, мужского пола — Господу.'),
(1881, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 13, 'OT', 'И всякого первенца осла выкупи овцою, а если не выкупишь, то сломай ему шею; и всякого первенца человека из сынов твоих выкупи.'),
(1882, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 14, 'OT', 'И будет, когда спросит тебя сын твой завтра, говоря: что это? — и скажешь ему: крепостью руки вывел нас Господь из Египта, из дома рабов.'),
(1883, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 15, 'OT', 'И было: когда фараон упорствовал отпустить нас, Господь убил всех первенцев в земле Египетской, от первенца человека до первенца скота; поэтому я приношу в жертву Господу всё, что разверзает матку, мужского пола, а всех первенцев моих сыновей выкупаю.'),
(1884, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 16, 'OT', 'И будет это знамением на руке твоей и повязкою между очами твоими, ибо крепостью руки вывел нас Господь из Египта.'),
(1885, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 17, 'OT', 'И было, когда отпустил фараон народ, не повёл их Бог путём земли Филистимлян, потому что он близок; ибо сказал Бог: как бы не раскаялся народ, увидев войну, и не возвратился в Египет.'),
(1886, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 18, 'OT', 'И повёл Бог народ путём пустыни к Красному морю, и в строю вышли сыны Израиля из земли Египетской.'),
(1887, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 19, 'OT', 'Взял Моисей кости Иосифа с собою, ибо клятвою заклял сынов Израиля, говоря: непременно посетит вас Бог, и вынесете кости мои отсюда с собою.'),
(1888, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 20, 'OT', 'И двинулись из Сокхофа и расположились станом в Ефаме, на краю пустыни.'),
(1889, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 21, 'OT', 'Господь шёл перед ними днём в столбе облака, чтобы вести их по пути, а ночью в столбе огня, чтобы светить им, чтобы идти им днём и ночью.'),
(1890, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 13, 22, 'OT', 'Не отходил столб облачный днём, и столб огненный ночью, от лица народа.'),
(1891, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(1892, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 2, 'OT', 'Скажи сынам Израиля, и пусть они возвратятся и станут станом перед лицом Пи-Гахирофа, между Магдолом и морем, перед лицом Веельзефона; напротив него станьте станом у моря.'),
(1893, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 3, 'OT', 'И сказал фараон о сынах Израиля: они в замешательстве в земле, заперла их пустыня.'),
(1894, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 4, 'OT', 'И Я ожесточу сердце фараона, и он погонится за ними, и прославлюсь в фараоне и во всём войске его, и узнают Египтяне, что Я — Господь. И сделали так.'),
(1895, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 5, 'OT', 'И было возвещено царю Египта, что народ бежал, и обратилось сердце фараона и рабов его против народа, и сказали они: что это мы сделали, что отпустили Израиля от служения нашего.'),
(1896, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 6, 'OT', 'Он запряг свою колесницу и взял с собой свой народ.'),
(1897, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 7, 'OT', 'И взял шестьсот отборных колесниц и все колесницы Египта, и военачальников над всеми ними.'),
(1898, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 8, 'OT', 'И укрепил Господь сердце фараона, царя Египетского, и он погнался за сынами Израиля; а сыны Израиля выходили с рукою поднятою.'),
(1899, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 9, 'OT', 'И погнались Египтяне за ними, и настигли их, стоящих станом у моря, все кони, колесницы фараона, и всадники его, и войско его, у Пи-Гахирофа, пред лицом Веельзефона.'),
(1900, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 10, 'OT', 'И приблизился фараон, и подняли сыны Израиля очи свои, и вот, Египтяне движутся за ними, и устрашились весьма, и возопили сыны Израиля к Господу.'),
(1901, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 11, 'OT', 'И сказали они Моисею: разве нет гробов в Египте, что ты взял нас умереть в пустыне? Что это ты сделал нам, выведя нас из Египта?'),
(1902, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 12, 'OT', 'Разве не это самое слово мы говорили тебе в Египте, говоря: оставь нас, и будем служить Египтянам? Ибо лучше нам служить Египтянам, чем умереть в пустыне.'),
(1903, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 13, 'OT', 'И сказал Моисей народу: не бойтесь, стойте и смотрите на спасение Господа, которое Он совершит для вас в этот день; ибо тех Египтян, которых вы видите сегодня, не увидите более вовек, до вечности.'),
(1904, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 14, 'OT', 'Господь будет сражаться за вас, а вы будете молчать.'),
(1905, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 15, 'OT', 'И сказал Господь Моисею: что ты вопиёшь ко Мне? Скажи сынам Израиля, и пусть они двинутся в путь.'),
(1906, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 16, 'OT', 'Подними жезл твой и простри руку твою на море, и рассеки его, и войдут сыны Израиля в середину моря по суше.'),
(1907, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 17, 'OT', 'А я, вот, укрепляю сердце Египтян, и они пойдут вслед за ними; и прославлюсь в фараоне и во всём войске его, в колесницах его и во всадниках его.'),
(1908, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 18, 'OT', 'И узнают Египтяне, что Я — Господь, когда Я прославлюсь на фараоне, на колеснице его и на всадниках его.'),
(1909, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 19, 'OT', 'И двинулся ангел Божий, шедший перед станом Израиля, и пошёл позади них; и двинулся столб облака от лица их, и стал позади них.'),
(1910, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 20, 'OT', 'И вошёл он между станом Египта и между станом Израиля, и был облако и тьма, и осветил ночь, и не приблизился один к другому всю ночь.'),
(1911, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 21, 'OT', 'И простёр Моисей руку свою на море, и Господь погнал море сильным восточным ветром всю ночь, и сделал море сушей, и расступились воды.'),
(1912, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 22, 'OT', 'И пошли сыны Израиля посреди моря по суше, и воды были им стеною с правой руки их и с левой стороны их.'),
(1913, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 23, 'OT', 'И погнались Египтяне и вошли за ними, всё кони фараона, колесницы его и всадники его, в середину моря.'),
(1914, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 24, 'OT', 'И было в утреннюю стражу, и воззрел Господь на стан Египтян из столба огня и облака, и привёл в смятение стан Египтян.'),
(1915, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 25, 'OT', 'И снял колесо с колесниц его, и вёл их с тяжестью; и сказал Египет: побегу от лица Израиля, ибо Господь сражается за них против Египта.'),
(1916, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 26, 'OT', 'И сказал Господь Моисею: простри руку твою на море, и возвратятся воды на Египет, на колесницы его и на всадников его.'),
(1917, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 27, 'OT', 'Моисей простер руку свою на море, и море возвратилось к силе своей к наступлению утра, и Египтяне бежали навстречу ему; и Господь встряхнул Египет в середине моря.'),
(1918, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 28, 'OT', 'И возвратились воды и покрыли колесницы и всадников всего войска фараона, которые шли за ними в море; не осталось из них ни одного.'),
(1919, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 29, 'OT', 'Сыны Израиля шли по суше среди моря, и воды были для них стеной по правую руку их и по левую сторону их.'),
(1920, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 30, 'OT', 'И спас Господь в тот день Израиля от руки Египта, и увидел Израиль Египтян мёртвыми на берегу моря.'),
(1921, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 14, 31, 'OT', 'И увидел Израиль руку великую, которую совершил Господь над Египтом, и убоялся народ Господа, и поверили в Господа и в Моисея, раба Его.'),
(1922, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 1, 'OT', 'Тогда воспел Моисей и сыны Израиля эту песнь Господу, и сказали они так: воспою Господу, ибо Он высоко превознёсся, коня и всадника его вверг в море.'),
(1923, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 2, 'OT', 'Сила моя и песнь — Господь, и Он стал мне спасением; Он — Бог мой, и я прославлю Его, Бог отца моего, и я вознесу Его.'),
(1924, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 3, 'OT', 'Господь — человек войны; Господь — имя Его.'),
(1925, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 4, 'OT', 'Колесницы фараона и войско его вверг Он в море, и избранные военачальники его потонули в Красном море.'),
(1926, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 5, 'OT', 'Бездны покрыли их; они опустились в глубины, как камень.'),
(1927, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 6, 'OT', 'Десница Твоя, Господь, славна силою; десница Твоя, Господь, сокрушает врага.'),
(1928, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 7, 'OT', 'И в великом множестве гордости Твоей Ты сокрушаешь восстающих против Тебя; посылаешь ярость Твою, она пожирает их, как солому.'),
(1929, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 8, 'OT', 'И ветром гнева Твоего собрались воды, стали как груда потоки; замерзли бездны в сердце моря.'),
(1930, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 9, 'OT', 'Сказал враг: погонюсь, настигну, разделю добычу; насытится желание моё, обнажу меч мой, истребит их рука моя.'),
(1931, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 10, 'OT', 'Ты дунул ветром Твоим — покрыло их море; они потонули, как свинец, в водах могучих.'),
(1932, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 11, 'OT', 'Кто подобен Тебе среди богов, Господь? Кто подобен Тебе, величествен в святыне, страшен в хвалах, творящий чудо?'),
(1933, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 12, 'OT', 'Ты простёр правую руку Твою — поглотила их земля.'),
(1934, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 13, 'OT', 'Ты вёл милостью Твоею народ, который Ты искупил; Ты сопровождал силою Твоею к жилищу святыни Твоей.'),
(1935, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 14, 'OT', 'Услышали народы — затрепещут; боль объяла жителей Филистии.'),
(1936, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 15, 'OT', 'Тогда устрашились вожди Идумеи, вожди Моава объяла дрожь, растаяли все жители Ханаана.'),
(1937, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 16, 'OT', 'Да падёт на них ужас и страх, от величия мышцы Твоей они онемеют, как камень, доколе не пройдёт народ Твой, Господь, доколе не пройдёт народ, который Ты приобрёл.'),
(1938, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 17, 'OT', 'Ты введёшь их и насадишь их на горе наследия Твоего, основание для пребывания Твоего Ты сотворил, Господь; святилище, Господь, утвердили руки Твои.'),
(1939, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 18, 'OT', 'Господь будет царствовать в вечность и вечность.'),
(1940, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 19, 'OT', 'Ибо конь фараона с колесницей его и всадниками его вошёл в море, и Господь возвратил на них воды моря, а сыны Израиля прошли по суше среди моря.'),
(1941, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 20, 'OT', 'Взяла Мариам пророчица, сестра Аарона, тимпан в руку свою, и вышли все жены за нею с тимпанами и с плясками.'),
(1942, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 21, 'OT', 'И отвечала им Мариам: пойте Господу, ибо высоко поднялся Он; коня и всадника его ввергнул в море.'),
(1943, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 22, 'OT', 'Моисей повёл Израиль от Красного моря, и вышли они в пустыню Сур, и шли три дня по пустыне, и не нашли воды.'),
(1944, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 23, 'OT', 'И пришли в Мару, и не могли пить воды из Мары, потому что она была горька; поэтому нарекли ей имя Мара.'),
(1945, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 24, 'OT', 'И роптал народ на Моисея, говоря: что нам пить?'),
(1946, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 25, 'OT', 'И воззвал он к Господу, и указал ему Господь дерево, и бросил он его в воду, и сделались воды сладкими; там Он дал ему закон и суд, и там испытал его.'),
(1947, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 26, 'OT', 'И сказал: если будешь слушать голос Господа, Бога твоего, и делать правое в очах Его, и внимать заповедям Его, и соблюдать все уставы Его, то никакой болезни, которую Я наложил на Египет, не наложу на тебя, ибо Я — Господь, целитель твой.'),
(1948, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 15, 27, 'OT', 'И пришли в Елим, и там было двенадцать источников воды и семьдесят пальм, и расположились станом там у воды.'),
(1949, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 1, 'OT', 'И двинулись из Елима, и пришло всё общество сынов Израиля в пустыню Син, которая между Елимом и Синаем, в пятнадцатый день второго месяца по выходе их из земли Египетской.'),
(1950, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 2, 'OT', 'И роптало всё общество сынов Израиля на Моисея и на Аарона в пустыне.'),
(1951, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 3, 'OT', 'И сказали им сыны Израиля: о, если бы мы умерли от руки Господа в земле Египетской, когда сидели мы у котла с плотью, когда ели мы хлеб досыта! Ибо вы вывели нас в эту пустыню, чтобы уморить голодом всё это собрание.'),
(1952, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 4, 'OT', 'И сказал Господь Моисею: вот, Я одождю вам хлеб с неба, и выйдет народ и будет собирать слово день за днём, чтобы испытать его, пойдёт ли он по закону Моему или нет.'),
(1953, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 5, 'OT', 'И будет в шестой день, и приготовят то, что принесут, и будет вдвое больше того, что собирают день за днём.'),
(1954, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 6, 'OT', 'И сказал Моисей и Аарон всему собранию сынов Израиля: вечером узнаете, что Господь вывел вас из земли Египетской.'),
(1955, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 7, 'OT', 'И утром вы увидите славу Господа, ибо Он услышал ваш ропот на Господа; а мы что такое, что вы ропщете на нас?'),
(1956, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 8, 'OT', 'И сказал Моисей: когда даёт Господь вам вечером плоть для еды и хлеб утром для насыщения, — ибо слышит Господь ропот ваш, которым вы ропщете на Него, — а мы что? Не на нас ропот ваш, но на Господа.'),
(1957, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 9, 'OT', 'И сказал Моисей Аарону: скажи всему обществу сынов Израиля: предстаньте пред лицом Господа, ибо Он услышал ропот ваш.'),
(1958, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 10, 'OT', 'И было, когда говорил Аарон ко всему обществу сынов Израиля, они обратились к пустыне, и вот, слава Господа явилась в облаке.'),
(1959, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 11, 'OT', 'И сказал Господь Моисею, говоря:'),
(1960, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 12, 'OT', 'Я услышал ропот сынов Израиля; скажи им: между вечерами будете есть плоть, и утром насытитесь хлебом, и узнаете, что Я — Господь, Бог ваш.'),
(1961, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 13, 'OT', 'И был вечер, и поднялся перепел, и покрыл стан; а утром была совокупление росы вокруг стана.'),
(1962, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 14, 'OT', 'И поднялось совокупление росы, и вот, по поверхности пустыни — тонкое, обнажённое, тонкое, как иней, на земле.'),
(1963, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 15, 'OT', 'И увидели сыны Израиля и сказали друг другу: «Что это?» — ибо не знали, что это. И сказал им Моисей: «Это хлеб, который дал вам Господь в пищу».'),
(1964, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 16, 'OT', 'Вот слово, которое повелел Господь: собирайте из него каждый человек по мере пищи своей, омер на голову, по числу душ ваших, каждый человек для тех, кто в шатре его, берите.'),
(1965, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 17, 'OT', 'И сделали так сыны Израиля, и собрали много и мало.'),
(1966, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 18, 'OT', 'И отмеривали омером, и у кого было много, не имел лишнего, и у кого было мало, не имел недостатка; каждый человек по мере еды своей, по пище своей, собирали.'),
(1967, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 19, 'OT', 'И сказал Моисей им: человек пусть не оставляет от него до утра.'),
(1968, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 20, 'OT', 'И не послушали они Моисея, и оставили некоторые люди от него до утра, и завелись черви, и воссмердело, и разгневался на них Моисей.'),
(1969, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 21, 'OT', 'И собирали его каждое утро, каждый человек по мере своей пищи; и когда солнце нагревало, оно таяло.'),
(1970, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 22, 'OT', 'И было в шестой день, собрали они хлеба, двойную (вторую) долю, по два омера на одного; и пришли все князья общества, и возвестили Моисею.'),
(1971, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 23, 'OT', 'И сказал им: это то, что говорил Господь: покой, суббота святыня Господу завтра; что печь — пеките, и что варить — варите, а всё остальное отложите себе на хранение до утра.'),
(1972, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 24, 'OT', 'И они оставили его до утра, как повелел Моисей, и оно не воссмердело, и червя не было в нём.'),
(1973, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 25, 'OT', 'Моисей сказал: ешьте его сегодня, ибо сегодня суббота для Господа; сегодня вы не найдёте его в поле.'),
(1974, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 26, 'OT', 'Шесть дней собирайте его, а в день седьмой — суббота, не будет его в нём.'),
(1975, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 27, 'OT', 'И было в седьмой день, вышли из народа собирать, и не нашли.'),
(1976, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 28, 'OT', 'И сказал Господь Моисею: доколе вы будете отказываться соблюдать заповеди Мои и законы Мои?'),
(1977, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 29, 'OT', 'Смотрите, Господь дал вам субботу, поэтому Он даёт вам в шестой день хлеб на два дня; сидите каждый человек на своём месте, пусть не выходит человек из своего места в седьмой день.'),
(1978, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 30, 'OT', 'И отдыхал народ в день седьмой.'),
(1979, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 31, 'OT', 'И нарек дом Израилев имя ему манна; и она была как семя кориандра, белая, и вкус её как лепёшка с мёдом.'),
(1980, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 32, 'OT', 'И сказал Моисей: вот слово, которое заповедал Господь: полный омер от него для хранения на роды ваши, чтобы видели хлеб, которым Я кормил вас в пустыне, когда выводил вас из земли Египетской.'),
(1981, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 33, 'OT', 'И сказал Моисей Аарону: возьми один сосуд и положи туда полный омер манны, и поставь его пред лицом Господа на хранение на роды ваши.'),
(1982, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 34, 'OT', 'Как повелел Господь Моисею, и положил его Аарон пред лицом свидетельства на хранение.'),
(1983, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 35, 'OT', 'Сыны Израиля ели манну сорок лет, пока не пришли в землю обитаемую; манну ели, пока не пришли к краю земли Ханаанской.'),
(1984, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 16, 36, 'OT', 'Омер же — десятая часть ефы.'),
(1985, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 1, 'OT', 'И отправилось всё общество сынов Израиля из пустыни Син в свои путешествия по повелению Господа, и расположились станом в Рефидиме, и не было воды для питья народу.'),
(1986, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 2, 'OT', 'Народ препирался с Моисеем, и говорили: дай нам воды, и будем пить. И сказал им Моисей: что вы препираетесь со мною? что вы искушаете Господа?'),
(1987, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 3, 'OT', 'И жаждал там народ воды, и роптал народ на Моисея, и говорил: зачем ты вывел нас из Египта, чтобы уморить жаждой меня и сыновей моих и скот мой?'),
(1988, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 4, 'OT', 'И воззвал Моисей к Господу, говоря: что мне делать с народом этим? Ещё немного, и они побьют меня камнями.'),
(1989, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 5, 'OT', 'И сказал Господь Моисею: пройди перед лицом народа и возьми с собой из старейшин Израиля, и жезл твой, которым ты ударил по реке, возьми в руку твою и иди.'),
(1990, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 6, 'OT', 'Вот Я стою пред лицом твоим там на скале в Хориве, и ты ударишь в скалу, и выйдут из неё воды, и будет пить народ; и сделал так Моисей пред очами старейшин Израиля.'),
(1991, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 7, 'OT', 'И назвал он имя месту тому Масса и Мерива, из-за тяжбы сынов Израиля и из-за того, что они искушали Господа, говоря: есть ли Господь среди нас или нет?'),
(1992, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 8, 'OT', 'И пришёл Амалик и воевал с Израилем в Рефидиме.'),
(1993, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 9, 'OT', 'И сказал Моисей Иисусу: выбери нам людей и выйди, сражайся с Амаликом; завтра я стану на главе холма, и жезл Бога в руке моей.'),
(1994, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 10, 'OT', 'Иисус сделал, как сказал ему Моисей, чтобы сражаться с Амаликом; и Моисей, Аарон и Хур взошли на главу холма.'),
(1995, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 11, 'OT', 'И было: когда Моисей поднимал руку свою, одолевал Израиль; а когда опускал руку свою, одолевал Амалик.'),
(1996, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 12, 'OT', 'И руки Моисея отяжелели, и взяли камень и положили под него, и он сел на него; а Аарон и Хур поддерживали его руки, один с одной стороны, и один с другой; и были руки его устойчивы до захода солнца.'),
(1997, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 13, 'OT', 'Иисус поразил Амалика и народ его лезвием меча.'),
(1998, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 14, 'OT', 'И сказал Господь Моисею: напиши это для памяти в книгу и вложи в уши Иисусу, что Я совершенно изглажу память Амалика из-под неба.'),
(1999, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 15, 'OT', 'И построил Моисей жертвенник, и назвал имя его: Господь знамя моё.'),
(2000, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 17, 16, 'OT', 'И сказал: так как рука на престоле Господа, то война у Господа с Амаликом из рода в род.'),
(2001, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 1, 'OT', 'И услышал Иофор, священник Мадиана, тесть Моисея, всё, что сделал Бог для Моисея и для Израиля, народа Его, что вывел Господь Израиля из Египта.'),
(2002, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 2, 'OT', 'Иофор, тесть Моисея, взял Сепфору, жену Моисея, после даров её.'),
(2003, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 3, 'OT', 'и двух сыновей её, которых имя одного Герсом, потому что он сказал: пришельцем был я в земле чужой.'),
(2004, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 4, 'OT', 'А имя другого — Елиезер, потому что Бог отца моего был мне в помощь и избавил меня от меча фараона.'),
(2005, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 5, 'OT', 'И пришёл Иофор, тесть Моисея, с сыновьями его и женой его к Моисею, в пустыню, где он стоял станом у горы Божьей.'),
(2006, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 6, 'OT', 'И сказал он Моисею: я, Иофор, тесть твой, пришёл к тебе, и жена твоя, и два сына её с нею.'),
(2007, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 7, 'OT', 'И вышел Моисей навстречу тестю своему, и поклонился, и поцеловал его, и спросили они друг друга, человек у ближнего своего, о здоровье, и вошли в шатёр.'),
(2008, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 8, 'OT', 'И рассказал Моисей тестю своему всё, что сделал Господь фараону и Египту ради Израиля, и всю тяготу, которая постигла их на пути, и избавил их Господь.'),
(2009, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 9, 'OT', 'Иофор возрадовался о всём добре, которое Господь сделал Израилю, и что Он избавил его из руки Египта.'),
(2010, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 10, 'OT', 'И сказал Иофор: благословен Господь, Который избавил вас из руки Египта и из руки фараона, Который избавил народ из-под руки Египта.'),
(2011, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 11, 'OT', 'Теперь я узнал, что Господь больше всех богов, ибо в том самом слове, которым они превозносились над ними.'),
(2012, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 12, 'OT', 'И взял Иофор, тесть Моисея, всесожжение и жертвы Богу; и пришёл Аарон и все старейшины Израиля есть хлеб с тестем Моисея пред лицом Бога.'),
(2013, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 13, 'OT', 'И было на следующий день: сел Моисей судить народ, и стоял народ перед Моисеем с утра до вечера.'),
(2014, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 14, 'OT', 'И увидел тесть Моисея всё, что он делает для народа, и сказал: что это за слово, которое ты делаешь для народа? Почему ты сидишь отдельно, а весь народ стоит пред тобою с утра до вечера?'),
(2015, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 15, 'OT', 'И сказал Моисей тестю своему: потому что приходит ко мне народ вопрошать Бога.'),
(2016, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 16, 'OT', 'Когда будет у них какое-либо слово, оно приходит ко мне, и я сужу между человеком и его ближним, и объявляю уставы Бога и законы Его.'),
(2017, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 17, 'OT', 'И сказал тесть Моисея ему: не хорошо то слово, которое ты делаешь.'),
(2018, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 18, 'OT', 'Изнеможешь и ты, и народ этот, который с тобою, ибо тяжело для тебя это слово, не можешь делать его один.'),
(2019, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 19, 'OT', 'Теперь послушай моего голоса: я дам тебе совет, и да будет Бог с тобою. Будь ты для народа пред Богом, и приноси ты слова к Богу.'),
(2020, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 20, 'OT', 'И предостереги их об уставах и о законе, и укажи им путь, по которому им идти, и дело, которое им делать.'),
(2021, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 21, 'OT', 'И ты усмотри из всего народа людей способных, боящихся Бога, людей истины, ненавидящих корысть, и поставь над ними князей тысяч, князей сотен, князей пятидесяти и князей десятков.'),
(2022, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 22, 'OT', 'И пусть они судят народ во всякое время; и будет, что всякое великое слово приносить будут к тебе, а всякое малое слово судить будут сами; и облегчат тебя, и понесут с тобою.'),
(2023, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 23, 'OT', 'Если это слово ты сделаешь, и Бог повелит тебе, то ты сможешь устоять, и также весь этот народ придёт на место своё в мире.'),
(2024, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 24, 'OT', 'Моисей послушал голоса своего тестя и сделал всё, что тот сказал.'),
(2025, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 25, 'OT', 'Моисей выбрал способных людей из всего Израиля и поставил их главами над народом: начальниками тысяч, начальниками сотен, начальниками пятидесяти и начальниками десятков.'),
(2026, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 26, 'OT', 'И судили они народ во всякое время; трудное слово приносили к Моисею, а всякое малое слово судили сами.'),
(2027, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 18, 27, 'OT', 'Моисей отпустил своего тестя, и тот пошёл в свою землю.'),
(2028, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 1, 'OT', 'В третий месяц по выходе сынов Израиля из земли Египетской, в этот самый день пришли они в пустыню Синай.'),
(2029, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 2, 'OT', 'И двинулись из Рефидима, и пришли в пустыню Синай, и расположились станом в пустыне; и расположился там Израиль станом напротив горы.'),
(2030, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 3, 'OT', 'И поднялся Моисей к Богу, и воззвал к нему Господь с горы, говоря: так скажи дому Иакова и возвести сынам Израиля.'),
(2031, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 4, 'OT', 'Вы сами видели, что Я сделал Египту, и как Я носил вас на крыльях орлов, и привёл вас к Себе.'),
(2032, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 5, 'OT', 'И ныне, если вы будете слушать голос Мой и соблюдать завет Мой, то будете Моим сокровищем из всех народов, ибо Моя вся земля.'),
(2033, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 6, 'OT', 'И вы будете у Меня царством священников и народом святым; вот слова, которые ты скажешь сынам Израиля.'),
(2034, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 7, 'OT', 'И пришёл Моисей, и созвал старейшин народа, и положил перед лицом их все эти слова, которые заповедал ему Господь.'),
(2035, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 8, 'OT', 'И ответил весь народ вместе, и сказали: всё, что сказал Господь, сделаем. И передал Моисей слова народа Господу.'),
(2036, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 9, 'OT', 'И сказал Господь к Моисею: вот, Я приду к тебе в облаке облачном, ради того чтобы народ слышал, когда Я буду говорить с тобою, и также в тебя будут верить вечно. И пересказал Моисей слова народа к Господу.'),
(2037, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 10, 'OT', 'И сказал Господь Моисею: пойди к народу и освяти их сегодня и завтра, и пусть выстирают свою одежду.'),
(2038, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 11, 'OT', 'И будут готовы к третьему дню, ибо в третий день сойдёт Господь пред очами всего народа на гору Синай.'),
(2039, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 12, 'OT', 'И огради народ вокруг, сказав: берегитесь восходить на гору и прикасаться к краю её; всякий, кто прикоснётся к горе, смертью умрёт.'),
(2040, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 13, 'OT', 'Не коснётся его рука, ибо камнями будет побит или стрелой застрелен; будь то скот или человек, не останется в живых; когда протянется юбилей, они взойдут на гору.'),
(2041, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 14, 'OT', 'И сошёл Моисей с горы к народу, и освятил народ, и они выстирали свои одежды.'),
(2042, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 15, 'OT', 'И сказал он народу: будьте готовы к трём дням; не прикасайтесь к жене.'),
(2043, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 16, 'OT', 'И было на третий день при наступлении утра, и были раскаты грома и молнии, и облако тяжёлое на горе, и голос трубы очень сильный, и затрепетал весь народ, который в стане.'),
(2044, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 17, 'OT', 'Моисей вывел народ навстречу Богу из стана, и они стали в нижней части горы.'),
(2045, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 18, 'OT', 'Гора Синай вся дымилась, потому что Господь сошёл на неё в огне; и поднялся дым её, как дым из печи, и вся гора сильно дрожала.'),
(2046, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 19, 'OT', 'И был голос трубы, усиливающийся весьма; Моисей говорил, и Бог отвечал ему голосом.'),
(2047, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 20, 'OT', 'И сошёл Господь на гору Синай, на главу горы, и призвал Господь Моисея на главу горы, и взошёл Моисей.'),
(2048, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 21, 'OT', 'И сказал Господь Моисею: сойди, предостереги народ, чтобы они не прорвались к Господу, чтобы увидеть, и не пало бы с Него множество.'),
(2049, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 22, 'OT', 'И также священники, приближающиеся к Господу, должны освятиться, чтобы Господь не поразил их.'),
(2050, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 23, 'OT', 'Моисей сказал Господу: не сможет народ взойти на гору Синай, ибо Ты предупредил нас, сказав: огради гору и освяти её.'),
(2051, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 24, 'OT', 'И сказал ему Господь: пойди, сойди, и взойди ты, и Аарон с тобою; а священники и народ пусть не порываются взойти к Господу, чтобы Он не поразил их.'),
(2052, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 19, 25, 'OT', 'И сошёл Моисей к народу и сказал им.'),
(2053, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 1, 'OT', 'И сказал Бог все эти слова, говоря:'),
(2054, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 2, 'OT', 'Я — Господь, Бог твой, Который вывел тебя из земли Египетской, из дома рабов.'),
(2055, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 3, 'OT', 'Да не будет у тебя других богов пред лицом Моим.'),
(2056, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 4, 'OT', 'Не делай себе идола и всякого образа того, что на небе вверху, и того, что на земле внизу, и того, что в воде под землёю.'),
(2057, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 5, 'OT', 'Не поклоняйся им и не служи им, ибо Я — Господь, Бог твой, Бог ревнитель, наказывающий беззаконие отцов на сыновьях, на третьем поколении и на четвёртом, у ненавидящих Меня.'),
(2058, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 6, 'OT', 'и творящий милость до тысячи родов любящим Меня и соблюдающим заповеди Мои'),
(2059, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 7, 'OT', 'Не произноси имени Господа, Бога твоего, напрасно, ибо не оставит Господь без наказания того, кто произносит имя Его напрасно.'),
(2060, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 8, 'OT', 'Помни день субботы, чтобы святить его.'),
(2061, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 9, 'OT', 'Шесть дней работай и делай всю работу твою.'),
(2062, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 10, 'OT', 'А день седьмой — суббота Господу, Богу твоему: не делай никакой работы, ни ты, ни сын твой, ни дочь твоя, ни раб твой, ни служанка твоя, ни скот твой, ни пришелец твой, который в воротах твоих.'),
(2063, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 11, 'OT', 'Ибо в шесть дней создал Господь небо и землю, море и всё, что в них, и почил в день седьмой; посему благословил Господь день субботний и освятил его.'),
(2064, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 12, 'OT', 'Почитай отца твоего и мать твою, чтобы продлились дни твои на земле, которую Господь, Бог твой, даёт тебе.'),
(2065, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 13, 'OT', 'Не убивай.'),
(2066, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 14, 'OT', 'Не прелюбодействуй.'),
(2067, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 15, 'OT', 'Не кради.'),
(2068, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 16, 'OT', 'Не произноси на ближнего твоего свидетельства ложного.'),
(2069, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 17, 'OT', 'Не желай дома ближнего твоего; не желай жены ближнего твоего, ни раба его, ни служанки его, ни вола его, ни осла его, ни всего, что у ближнего твоего.'),
(2070, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 18, 'OT', 'И весь народ видел раскаты грома и факелы, и звук трубы, и гору дымящуюся; и увидел народ, и затрепетал, и стал вдали.'),
(2071, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 19, 'OT', 'И сказали Моисею: говори ты с нами, и мы будем слушать; и пусть не говорит с нами Бог, чтобы нам не умереть.'),
(2072, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 20, 'OT', 'Моисей сказал народу: не бойтесь, ибо для того, чтобы испытать вас, пришёл Бог, и чтобы страх Его был на лицах ваших, дабы вы не грешили.'),
(2073, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 21, 'OT', 'Народ стоял вдали, а Моисей приблизился ко тьме, где был Бог.'),
(2074, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 22, 'OT', 'Господь сказал Моисею: так скажи сынам Израиля: вы видели, что с неба Я говорил с вами.'),
(2075, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 23, 'OT', 'Не делайте предо Мною богов из серебра и богов из золота, не делайте их себе.'),
(2076, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 24, 'OT', 'Жертвенник из земли сделай Мне, и приноси на нём всесожжения твои и мирные жертвы твои, овец твоих и крупный рогатый скот твой; на всяком месте, где Я напомню имя Моё, приду к тебе и благословлю тебя.'),
(2077, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 25, 'OT', 'Если же сделаешь Мне жертвенник из камней, не строй их из тёсаного камня, ибо ты поднял на него меч твой и осквернил его.'),
(2078, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 20, 26, 'OT', 'И не восходи по ступеням к жертвеннику Моему, чтобы не открылась нагота твоя на нём.'),
(2079, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 1, 'OT', 'И вот суды, которые ты положишь перед лицом их.'),
(2080, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 2, 'OT', 'Если купишь раба-Еврея, шесть лет он будет работать, а в седьмой выйдет на свободу даром.'),
(2081, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 3, 'OT', 'Если он пришёл один, то один и выйдет; если же он был господином жены, то выйдет с ним и его жена.'),
(2082, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 4, 'OT', 'Если господин его даст ему жену, и она родит ему сыновей или дочерей, то жена и дети её будут принадлежать господину его, а он выйдет один, в одиночку.'),
(2083, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 5, 'OT', 'Если же раб скажет: я люблю моего господина, мою жену и моих сыновей, не выйду на свободу,'),
(2084, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 6, 'OT', 'И приведёт его господин его к судьям, и приведёт его к двери или к косяку, и проколет господин его ухо его шилом, и будет он рабом его на вечность.'),
(2085, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 7, 'OT', 'И если человек продаст дочь свою в служанки, то она не выйдет, как выходят рабы.'),
(2086, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 8, 'OT', 'Если она не угодна в глазах господина своего, который не обручил её, то пусть он позволит выкупить её; народу чужому не властен он продать её, изменив ей.'),
(2087, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 9, 'OT', 'Если же он предназначит её своему сыну, то по обычаю дочерей поступит с ней.'),
(2088, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 10, 'OT', 'Если другую возьмёт себе, то пищу её, покрывало её и супружескую обязанность её не умалит.'),
(2089, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 11, 'OT', 'А если этих трёх он не сделает для неё, то она выйдет даром, без денег.'),
(2090, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 12, 'OT', 'Кто ударит человека, и тот умрёт, да будет предан смерти.'),
(2091, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 13, 'OT', 'А если кто не подстерегал, и Бог предал в руки его, то Я назначу тебе место, куда он убежит.'),
(2092, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 14, 'OT', 'Если же человек умышленно восстанет на ближнего своего, чтобы убить его хитростью, то от жертвенника Моего возьми его на смерть.'),
(2093, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 15, 'OT', 'Кто ударит отца своего или мать свою, тот должен быть предан смерти.'),
(2094, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 16, 'OT', 'И кто украдёт человека и продаст его, и найдётся он в руке его, тот должен быть предан смерти.'),
(2095, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 17, 'OT', 'И проклинающий отца своего и мать свою смертью да умрёт.'),
(2096, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 18, 'OT', 'И если поссорятся люди, и ударит человек ближнего своего камнем или кулаком, и тот не умрёт, но сляжет на ложе,'),
(2097, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 19, 'OT', 'Если он встанет и будет ходить по улице на своём посохе, то ударивший будет свободен; только за покой его он заплатит и за лечение его обеспечит.'),
(2098, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 20, 'OT', 'Если же человек ударит раба своего или служанку свою жезлом, и тот умрёт под рукою его, то он должен быть непременно отомщён.'),
(2099, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 21, 'OT', 'Но если он проживёт день или два дня, то не будет наказан, потому что это его деньги.'),
(2100, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 22, 'OT', 'И если будут драться люди, и ударят беременную жену, и выйдут её дети, но не будет беды, то будет оштрафован, как наложит на него господин жены, и заплатит через судей.'),
(2101, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 23, 'OT', 'А если будет беда, то отдай душу за душу.'),
(2102, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 24, 'OT', 'Око за око, зуб за зуб, рука за руку, нога за ногу.'),
(2103, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 25, 'OT', 'ожог за ожог, рана за рану, ушиб за ушиб.'),
(2104, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 26, 'OT', 'И если ударит человек око раба своего или око служанки своей и повредит его, то пусть отпустит его на свободу за око его.'),
(2105, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 27, 'OT', 'А если зуб раба его или зуб служанки его выбьет, то на свободу отпустит его за зуб его.'),
(2106, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 28, 'OT', 'Если вол забодает человека или жену, и они умрут, то вол будет побит камнями, и плоть его не будет съедена, а господин вола будет чист.'),
(2107, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 29, 'OT', 'Если же вол бодлив был и вчера и третьего дня, и господин его был предупреждён, но не стерёг его, и он убил человека или жену, то вол будет побит камнями, и господин его также будет предан смерти.'),
(2108, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 30, 'OT', 'Если будет наложен на него выкуп, то он даст выкуп за свою душу, согласно всему, что будет наложено на него.'),
(2109, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 31, 'OT', 'Если же он боднёт сына или боднёт дочь, то по этому правилу должно поступить с ним.'),
(2110, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 32, 'OT', 'Если вол забодает раба или служанку, то серебро в тридцать сиклей даст господину его, а вол будет побит камнями.'),
(2111, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 33, 'OT', 'Если откроет человек колодезь, или если выкопает человек колодезь и не покроет его, и упадёт туда вол или осёл,'),
(2112, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 34, 'OT', 'Господин колодезя заплатит деньги и возвратит его господину его, а мёртвое будет его.'),
(2113, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 35, 'OT', 'Если ударит вол человека вола ближнего его, и тот умрёт, то продадут вола живого и разделят его деньги, и также мёртвого разделят.'),
(2114, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 21, 36, 'OT', 'Если же было известно, что вол бодлив был и прежде, и господин его не стерёг его, то он должен заплатить вола за вола, а мёртвый останется ему.'),
(2115, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 1, 'OT', 'Если украдет человек вола или овцу и заколет его или продаст, пять голов крупного рогатого скота заплатит за вола и четыре овцы за овцу.'),
(2116, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 2, 'OT', 'Если в подкопе будет найден вор, и он будет поражён и умрёт, то нет ему крови.'),
(2117, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 3, 'OT', 'Если взошло солнце над ним, то кровь за него; он должен полностью возместить; если же у него нет, то он будет продан за свою кражу.'),
(2118, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 4, 'OT', 'Если найдена будет в руке его кража, от вола до осла, до овцы, живых, — вдвое заплатит.'),
(2119, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 5, 'OT', 'Если человек потравит поле или виноградник, пустив свой скот, и скот вытравит чужое поле, то он должен возместить лучшим из своего поля и лучшим из своего виноградника.'),
(2120, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 6, 'OT', 'Если выйдет огонь и охватит тёрн, и будет съеден скирд, или колосья, или поле, то заплативший должен заплатить тот, кто зажёг пожар.'),
(2121, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 7, 'OT', 'Если даст человек ближнему своему деньги или сосуды для хранения, и украдено будет из дома того человека, то если найдётся вор, пусть заплатит вдвое.'),
(2122, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 8, 'OT', 'Если не найдётся вор, то пусть господин дома предстанет пред судьями, не простёр ли он руки своей на работу ближнего своего.'),
(2123, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 9, 'OT', 'По всякому слову о преступлении, о воле, об осле, об овце, об одежде, о всякой пропаже, о которой скажут: «это оно», — до судей придёт слово обоих; кого судьи признают виновным, тот заплатит вдвойне ближнему своему.'),
(2124, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 10, 'OT', 'Если человек даст ближнему своему осла, или вола, или овцу, или всякий скот на хранение, и он умрёт, или будет повреждён, или будет уведён, и никто не видел,'),
(2125, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 11, 'OT', 'Клятва Господня будет между ними обоими, что он не простёр руки своей на работу ближнего своего; и возьмёт господин его, и не заплатит.'),
(2126, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 12, 'OT', 'А если будет украдено у него, он заплатит его господину.'),
(2127, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 13, 'OT', 'Если будет растерзан, пусть приведёт свидетеля; за растерзанное не заплатит.'),
(2128, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 14, 'OT', 'Если человек возьмёт взаймы у ближнего своего, и оно сломается или умрёт, а господина его не будет с ним, то он должен заплатить.'),
(2129, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 15, 'OT', 'Если господин его с ним, не заплатит; если он наёмник, то пришёл за плату свою.'),
(2130, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 16, 'OT', 'Если человек обольстит деву, которая не обручена, и ляжет с ней, то пусть он даст выкуп за неё и возьмёт её себе в жёны.'),
(2131, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 17, 'OT', 'Если отец откажется отдать её ему, то пусть он отвесит деньги по вену дев.'),
(2132, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 18, 'OT', 'Ворожею не оставляй в живых.'),
(2133, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 19, 'OT', 'Всё, кто ляжет со скотом, смертью да будет предан.'),
(2134, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 20, 'OT', 'Приносящий жертву богам будет истреблён, кроме одного Господа только.'),
(2135, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 21, 'OT', 'Пришельца не притесняй и не угнетай его, ибо пришельцами вы были в земле Египетской.'),
(2136, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 22, 'OT', 'Всякую вдову и сироту не притесняйте.'),
(2137, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 23, 'OT', 'Если ты будешь притеснять его, то, когда он воззовёт ко Мне, Я непременно услышу вопль его.'),
(2138, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 24, 'OT', 'И воспылает гнев Мой, и убью вас мечом, и будут жёны ваши вдовами, и сыновья ваши сиротами.'),
(2139, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 25, 'OT', 'Если деньги дашь взаймы народу Моему, бедному при тебе, не будь для него притеснителем; не налагай на него лихвы.'),
(2140, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 26, 'OT', 'Если возьмёшь в залог одежду ближнего твоего, до захода солнца возврати её ему.'),
(2141, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 27, 'OT', 'Ибо это покрывало его, единственное, это одежда его для кожи его; в чём ему лежать? И будет, когда он воззовёт ко Мне, Я услышу, ибо Я милостив.'),
(2142, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 28, 'OT', 'Бога не злословь, и князя в народе твоём не проклинай.'),
(2143, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 29, 'OT', 'Урожай твой и напиток твой не задерживай; первенца сынов твоих отдавай Мне.'),
(2144, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 30, 'OT', 'Так поступай с волом твоим и с овцами твоими: семь дней пусть будет он с матерью своею, в день восьмой отдай его Мне.'),
(2145, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 22, 31, 'OT', 'И будете у Меня людьми святыни, и плоть, растерзанную в поле, не ешьте, псу бросайте её.'),
(2146, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 1, 'OT', 'Не принимай слуха ложного; не давай руки твоей с нечестивым, чтобы быть свидетелем насилия.'),
(2147, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 2, 'OT', 'Не следуй за большинством на зло, и не отвечай в тяжбе, уклоняясь за большинством, чтобы исказить правосудие.'),
(2148, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 3, 'OT', 'И бедного не возвышай в тяжбе его.'),
(2149, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 4, 'OT', 'Если встретишь вола врага твоего или осла его заблудившегося, возврати его ему.'),
(2150, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 5, 'OT', 'Если увидишь осла врага твоего лежащим под бременем его, и не захочешь помочь ему, то непременно помоги ему вместе с ним.'),
(2151, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 6, 'OT', 'Не отклоняй суда бедного твоего в тяжбе его.'),
(2152, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 7, 'OT', 'Удаляйся от слова лжи, и невинного и праведного не убивай, ибо Я не оправдаю нечестивого.'),
(2153, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 8, 'OT', 'И не бери взятки, ибо взятка ослепляет зрячих и извращает слова праведных.'),
(2154, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 9, 'OT', 'Пришельца не притесняй, и вы знаете душу пришельца, потому что пришельцами вы были в земле Египетской.'),
(2155, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 10, 'OT', 'И шесть лет засевай землю твою и собирай урожай её.'),
(2156, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 11, 'OT', 'А в седьмой год оставь её и покинь её, и пусть едят бедные из народа твоего, а остаток их пусть едят дикие звери поля; так поступай с виноградником твоим и с маслиной твоей.'),
(2157, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 12, 'OT', 'Шесть дней делай дела твои, а в седьмой день покойся, чтобы отдохнул вол твой и осёл твой, и чтобы вздохнул сын служанки твоей и пришелец.'),
(2158, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 13, 'OT', 'И во всём, что Я сказал вам, соблюдайте; и имени богов других не упоминайте, да не услышится оно на устах твоих.'),
(2159, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 14, 'OT', 'Три раза в год празднуй Мне праздник.'),
(2160, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 15, 'OT', 'Соблюдай праздник опресноков: семь дней ешь опресноки, как Я повелел тебе, в назначенное время месяца колосьев, ибо в нём ты вышел из Египта; и не являйся пред лицо Моё с пустыми руками.'),
(2161, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 16, 'OT', 'И праздник жатвы первых плодов дел твоих, которые ты сеешь в поле, и праздник собрания в исходе года, когда соберёшь дела твои с поля.'),
(2162, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 17, 'OT', 'Три раза в год явится весь мужской пол твой пред лицо Господа, Господа.'),
(2163, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 18, 'OT', 'Не приноси крови жертвы Моей на квасном, и тук праздника Моего не должен оставаться до утра.'),
(2164, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 19, 'OT', 'Начало первых плодов земли твоей приноси в дом Господа, Бога твоего; не вари козлёнка в молоке матери его.'),
(2165, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 20, 'OT', 'Вот, Я посылаю ангела пред лицом твоим, чтобы хранить тебя на пути и привести тебя к месту, которое Я приготовил.'),
(2166, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 21, 'OT', 'Берегись его и слушай голоса его; не упорствуй против него, ибо он не простит преступлений ваших, ибо имя моё в нём.'),
(2167, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 22, 'OT', 'Если ты будешь слушать голос его и делать всё, что Я скажу, то Я буду врагом врагам твоим и противником противникам твоим.'),
(2168, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 23, 'OT', 'Когда пойдёт ангел Мой пред лицом твоим и приведёт тебя к Аморрею, и Хеттеянину, и Ферезеям, и Хананеянину, Евеям и Иевусеям, и истреблю их.'),
(2169, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 24, 'OT', 'Не поклоняйся их богам, и не служи им, и не делай по их делам; ибо разрушь их и сокруши их столбы.'),
(2170, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 25, 'OT', 'И будете служить Господу, Богу вашему, и Он благословит хлеб твой и воду твою, и удалю болезнь из среды твоей.'),
(2171, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 26, 'OT', 'Не будет ни выкидывающей, ни бесплодной в земле твоей; число дней твоих Я исполню.'),
(2172, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 27, 'OT', 'Пошлю ужас Мой пред лицом твоим, и приведу в смятение весь народ, к которому ты придёшь, и обращу всех врагов твоих к тебе шеей.'),
(2173, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 28, 'OT', 'И пошлю Я ос перед тобою, и прогонит она Евеев, Хананеянина и Хеттеянина от лица твоего.'),
(2174, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 29, 'OT', 'Не прогоню их от лица твоего в один год, чтобы земля не стала запустением и не умножились против тебя звери полевые.'),
(2175, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 30, 'OT', 'Немного, немного прогоню его от лица твоего, доколе ты не размножишься и не наследуешь землю.'),
(2176, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 31, 'OT', 'И установлю границу твою от моря Красного до моря Филистимлян, и от пустыни до реки; ибо отдам в руки ваши жителей земли, и изгоню их от лица твоего.'),
(2177, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 32, 'OT', 'Не заключай с ними и с их богами завета.'),
(2178, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 23, 33, 'OT', 'Они не должны жить в земле твоей, чтобы они не ввели тебя в грех против Меня; ибо если ты будешь служить их Богу, это будет для тебя западнёй.'),
(2179, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 1, 'OT', 'И сказал Моисею: взойди к Господу ты и Аарон, Надав и Авиуд, и семьдесят из старейшин Израиля, и поклонитесь издали.'),
(2180, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 2, 'OT', 'И приблизится Моисей отдельно к Господу, а они не приблизятся, и народ не взойдёт с ним.'),
(2181, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 3, 'OT', 'И пришёл Моисей и пересказал народу все слова Господа и все законы; и ответил весь народ одним голосом, и сказали: все слова, которые говорил Господь, сделаем.'),
(2182, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 4, 'OT', 'Моисей записал все слова Господа, и встал рано утром, и построил жертвенник под горою, и двенадцать столбов для двенадцати колен Израиля.'),
(2183, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 5, 'OT', 'И послал он отроков из сынов Израиля, и они принесли всесожжения, и закололи жертвы мирные Господу, тельцов.'),
(2184, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 6, 'OT', 'Моисей взял половину крови и положил в чаши, а половину крови выплеснул на жертвенник.'),
(2185, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 7, 'OT', 'И взял книгу завета и прочитал вслух в уши народа, и сказали они: всё, что говорил Господь, сделаем и послушаем.'),
(2186, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 8, 'OT', 'И взял Моисей кровь и окропил народ, и сказал: вот кровь завета, который заключил Господь с вами о всех словах сих.'),
(2187, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 9, 'OT', 'Взошёл Моисей и Аарон, Надав и Авиуд, и семьдесят из старейшин Израиля.'),
(2188, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 10, 'OT', 'И увидели они Бога Израилева, и под ногами Его — как бы вид из мостовой сапфира и как бы сама кость неба по чистоте.'),
(2189, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 11, 'OT', 'И к вельможам сынов Израиля не простёр Он руки своей; и они видели Бога, и ели, и пили.'),
(2190, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 12, 'OT', 'И сказал Господь Моисею: взойди ко Мне на гору и будь там; и дам тебе доски каменные, и закон, и заповедь, которые Я написал, чтобы наставлять их.'),
(2191, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 13, 'OT', 'Встал Моисей и Иисус, слуга его, и взошёл Моисей на гору Божью.'),
(2192, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 14, 'OT', 'И к старейшинам сказал: оставайтесь здесь для нас, пока мы не вернёмся к вам; и вот, Аарон и Хур с вами; кто имеет дело, пусть идёт к ним.'),
(2193, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 15, 'OT', 'И взошёл Моисей на гору, и покрыло облако гору.'),
(2194, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 16, 'OT', 'И обитала слава Господня на горе Синай, и покрывало её облако шесть дней; и воззвал Он к Моисею в седьмой день из среды облака.'),
(2195, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 17, 'OT', 'И вид славы Господней был как огонь поядающий на главе горы пред очами сынов Израиля.'),
(2196, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 24, 18, 'OT', 'И вошёл Моисей в середину облака и поднялся на гору; и был Моисей на горе сорок дней и сорок ночей.'),
(2197, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 1, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2198, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 2, 'OT', 'Скажи сынам Израиля, и пусть возьмут Мне приношение; от всякого человека, которого сердце побудит, возьмите приношение Моё.'),
(2199, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 3, 'OT', 'И вот приношение, которое вы возьмёте от них: золото, и серебро, и медь.'),
(2200, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 4, 'OT', 'голубой, и багряница, и червлёный багрянец, и виссон, и козы'),
(2201, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 5, 'OT', 'кожа баранья красная и кожа тахаша, и дерево ситтим'),
(2202, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 6, 'OT', 'елей для светила, благовония для елея помазания и для фимиама ароматов.'),
(2203, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 7, 'OT', 'камни оникса и камни посвящения для ефода и для наперсника'),
(2204, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 8, 'OT', 'И сделают они Мне святилище, и буду обитать в середине их.'),
(2205, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 9, 'OT', 'Согласно всему, что Я показываю тебе, образец скинии и образец всех сосудов её, так и сделайте.'),
(2206, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 10, 'OT', 'И сделают ковчег из дерева ситтим: два локтя с половиной длина его, и локоть с половиной ширина его, и локоть с половиной рост его.'),
(2207, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 11, 'OT', 'И покроешь его чистым золотом, изнутри и снаружи покроешь его, и сделаешь на нём венец из золота вокруг.'),
(2208, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 12, 'OT', 'И вылей для него четыре перстня из золота, и прикрепи их к четырём его ножкам, и два перстня на одну его сторону, и два перстня на другую его сторону.'),
(2209, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 13, 'OT', 'Сделай шесты из дерева ситтим и покрой их золотом.'),
(2210, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 14, 'OT', 'И вложи шесты в перстни на сторонах ковчега, чтобы носить ковчег ими.'),
(2211, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 15, 'OT', 'В перстнях ковчега будут шесты, не будут отходить от него.'),
(2212, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 16, 'OT', 'И положи в ковчег свидетельство, которое Я дам тебе.'),
(2213, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 17, 'OT', 'Сделай крышку из чистого золота: два локтя с половиной длина её, и локоть с половиной ширина её.'),
(2214, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 18, 'OT', 'Сделай двух херувимов из золота, чеканной работой сделай их, из двух краёв крышки.'),
(2215, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 19, 'OT', 'Сделай одного херувима с одного края и одного херувима с другого края; из крышки сделайте херувимов на обоих её краях.'),
(2216, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 20, 'OT', 'И будут херувимы распростирать крылья вверх, покрывая своими крыльями над крышкой, и лица их будут обращены друг к другу; к крышке будут лица херувимов.'),
(2217, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 21, 'OT', 'И положи крышку на ковчег сверху, а в ковчег положи свидетельство, которое Я дам тебе.'),
(2218, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 22, 'OT', 'И буду являться тебе там и говорить с тобою над крышкою, из-за двух херувимов, которые над ковчегом свидетельства, всё, что Я повелю тебе для сынов Израиля.'),
(2219, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 23, 'OT', 'Сделай стол из дерева ситтим: два локтя длина его, и локоть ширина его, и локоть с половиною рост его.'),
(2220, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 24, 'OT', 'И покроешь его чистым золотом, и сделаешь ему венец из золота вокруг.'),
(2221, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 25, 'OT', 'И сделай к нему обод в пядь вокруг, и сделай венец из золота для обода его вокруг.'),
(2222, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 26, 'OT', 'И сделай для него четыре кольца из золота, и прикрепи кольца к четырём краям, которые у четырёх ног его.'),
(2223, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 27, 'OT', 'Против ограды будут перстни, для домов, для шестов, чтобы нести стол.'),
(2224, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 28, 'OT', 'И сделай шесты из дерева ситтим, и покрой их золотом, и носи ими стол.'),
(2225, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 29, 'OT', 'Сделай блюда его, и ложки его, и чаши его, и чаши его, которыми возливают; из чистого золота сделай их.'),
(2226, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 30, 'OT', 'И положи на стол хлебы предложения предо Мною постоянно.'),
(2227, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 31, 'OT', 'Сделай светильник из чистого золота; чеканной работой должен быть сделан светильник; основание его и стержень его, чаши его, набалдашники его и цветы его из него должны быть.'),
(2228, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 32, 'OT', 'И шесть стеблей выходят из сторон её: три стебля светильника из стороны одной, и три стебля светильника из стороны второй.'),
(2229, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 33, 'OT', 'Три чаши наподобие миндального цвета на одном стебле, набалдашник и цветок, и три чаши наподобие миндального цвета на другом стебле, набалдашник и цветок; так для шести стеблей, выходящих из светильника.'),
(2230, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 34, 'OT', 'А на светильнике четыре чаши, миндалевидные, с набалдашниками их и цветками их.'),
(2231, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 35, 'OT', 'И набалдашник под двумя стержнями из неё, и набалдашник под двумя стержнями из неё, и набалдашник под двумя стержнями из неё, для шести стержней, выходящих из светильника.'),
(2232, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 36, 'OT', 'Набалдашники их и стержни их из неё будут; всё это — чеканная работа одна, из золота чистого.'),
(2233, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 37, 'OT', 'И сделаешь светильники её семь, и зажжёшь светильники её, и будет светить напротив неё.'),
(2234, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 38, 'OT', 'И щипцы её и кадильницы её — из золота чистого.'),
(2235, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 39, 'OT', 'Из таланта чистого золота сделает её, все эти сосуды.'),
(2236, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 25, 40, 'OT', 'Смотри и сделай по образцу их, который ты видел на горе.'),
(2237, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 1, 'OT', 'И сделай скинию из десяти завес из кручёного виссона, и из голубой, и из багряницы, и из червлёного червя, с херувимами, делом искусного ткача сделай их.'),
(2238, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 2, 'OT', 'Длина завесы одной — двадцать восемь локтей, и ширина — четыре локтя, завеса одна; мера одна для всех завес.'),
(2239, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 3, 'OT', 'Пять завес будут соединены одна с другой, жена к сестре своей; и пять завес соединены одна с другой, жена к сестре своей.'),
(2240, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 4, 'OT', 'И сделай петли из голубой [шерсти] на краю одной завесы, с края, в связи, и так же сделай на краю крайней завесы во второй связи.'),
(2241, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 5, 'OT', 'Пятьдесят петель сделай на одной завесе, и пятьдесят петель сделай на краю завесы, которая во второй связи; петли будут соответствовать одна другой, жена к сестре своей.'),
(2242, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 6, 'OT', 'Сделай пятьдесят крючков из золота и соедини завесы одну с другой, жену к сестре её, крючками, и будет скиния одна.'),
(2243, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 7, 'OT', 'И сделай завесы из козьей шерсти для шатра поверх скинии; одиннадцать завес сделай их.'),
(2244, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 8, 'OT', 'Длина завесы одной — тридцать локтей, и ширина — четыре локтя, завеса одна; мера одна для одиннадцати завес.'),
(2245, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 9, 'OT', 'И соединишь пять завес отдельно, и шесть завес отдельно, и сложишь шестую завесу против лица шатра.'),
(2246, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 10, 'OT', 'Сделай пятьдесят петель на краю завесы, крайней в связи, и пятьдесят петель на краю завесы, второй в связи.'),
(2247, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 11, 'OT', 'И сделай пятьдесят крючков из меди, и введи крючки в петли, и соедини шатёр, и будет он одним.'),
(2248, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 12, 'OT', 'Остаток излишка в завесах шатра — половина излишней завесы пусть свисает на задней стороне скинии.'),
(2249, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 13, 'OT', 'И локоть с одной стороны, и локоть с другой стороны, в избытке по длине завес шатра, будет свисать на стороны скинии с одной и с другой стороны, чтобы покрывать её.'),
(2250, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 14, 'OT', 'И сделай покрывало для шатра из кожи овнов, окрашенной в красный цвет, и покрывало из кожи тахаша сверху.'),
(2251, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 15, 'OT', 'И сделай доски для скинии из дерева ситтим, стоящие.'),
(2252, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 16, 'OT', 'Десять локтей длина доски, и локоть с половиною локтя ширина доски одной.'),
(2253, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 17, 'OT', 'Два шипа у одной доски, соединённые, жена к сестре своей; так сделай для всех досок скинии.'),
(2254, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 18, 'OT', 'И сделай доски для скинии: двадцать досок для края южного, к югу.'),
(2255, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 19, 'OT', 'И сорок подножий из серебра сделай под двадцать досок: два подножия под одну доску для двух шипов её, и два подножия под другую доску для двух шипов её.'),
(2256, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 20, 'OT', 'И для стороны скинии со второй стороны, к краю севера, двадцать досок.'),
(2257, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 21, 'OT', 'и сорок подножий их из серебра: два подножия под одну доску, и два подножия под другую доску.'),
(2258, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 22, 'OT', 'А для окраин скинии к западу сделай шесть досок.'),
(2259, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 23, 'OT', 'И две доски сделай для углов скинии в задней части.'),
(2260, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 24, 'OT', 'И будут они близнецами снизу, и вместе будут цельными на главе его, к перстню одному; так будет для обоих, для двух углов они будут.'),
(2261, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 25, 'OT', 'И будет восемь досок, и подножия их из серебра: шестнадцать подножий, два подножия под одну доску и два подножия под другую доску.'),
(2262, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 26, 'OT', 'И сделай засовы из дерева ситтим: пять для досок одной стороны скинии.'),
(2263, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 27, 'OT', 'И пять засовов для досок боковой стороны скинии второй, и пять засовов для досок боковой стороны скинии к окраинам к западу.'),
(2264, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 28, 'OT', 'И средний засов будет проходить посреди досок, протягиваясь от края до края.'),
(2265, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 29, 'OT', 'Доски обложи золотом, и перстни их сделай из золота, дома для засовов, и засовы обложи золотом.'),
(2266, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 30, 'OT', 'И поставь скинию по образцу её, как ты видел на горе.'),
(2267, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 31, 'OT', 'Сделай завесу из голубой, багряницы, червлёного багрянца и кручёного виссона; делом искусным пусть сделают её с херувимами.'),
(2268, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 32, 'OT', 'И повесишь её на четыре столба из ситтима, обложенных золотом, с крюками из золота, на четырёх подножиях из серебра.'),
(2269, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 33, 'OT', 'И повесишь завесу под крючками, и внесёшь туда, внутрь дома за завесу, ковчег свидетельства; и будет отделять вам завеса между святынею и святынею святынь.'),
(2270, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 34, 'OT', 'И положи крышку на ковчег свидетельства во Святая Святых.'),
(2271, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 35, 'OT', 'Поставь стол снаружи завесы, а светильник напротив стола, на сторону скинии к югу; стол же поставь на сторону к северу.'),
(2272, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 36, 'OT', 'И сделай завесу для двери шатра из голубой, и багряницы, и червца, и червлёного, и кручёного виссона, делом узорчатого ткача.'),
(2273, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 26, 37, 'OT', 'Сделай для завесы пять столбов из ситтима, и покрой их золотом, и крюки их — золотом, и вылей для них пять подножий из меди.'),
(2274, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 1, 'OT', 'Сделай жертвенник из дерева ситтим: пять локтей длина и пять локтей ширина, четырёхугольным будет жертвенник, и три локтя рост его.'),
(2275, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 2, 'OT', 'Сделай рога его на четырёх углах его; из него самого будут рога его, и обложи его медью.'),
(2276, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 3, 'OT', 'Сделай котлы его для золы, и лопаты его, и чаши его, и вилки его, и кадильницы его; для всех сосудов его сделай из меди.'),
(2277, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 4, 'OT', 'Сделай к нему решётку, дело сети из меди, и сделай на сети четыре перстня из меди на четырёх краях её.'),
(2278, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 5, 'OT', 'И положишь её под выступ жертвенника снизу, и будет сеть до половины жертвенника.'),
(2279, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 6, 'OT', 'Сделай шесты для жертвенника, шесты из дерева ситтим, и покрой их медью.'),
(2280, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 7, 'OT', 'И вложены будут шесты его в перстни, и будут шесты на двух сторонах жертвенника, когда поднимают его.'),
(2281, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 8, 'OT', 'Полым из досок сделай его; как показано тебе на горе, так пусть сделают.'),
(2282, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 9, 'OT', 'И сделаешь двор скинии: с южной стороны, к югу, завесы для двора из кручёного виссона, сто локтей длины для одного края.'),
(2283, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 10, 'OT', 'И столбов его двадцать, и подножий их двадцать из меди; крюки столбов и перекладины их из серебра.'),
(2284, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 11, 'OT', 'И так для края северного по длине — завесы в сто длины, и столбы их двадцать, и подножия их двадцать из меди, крюки столбов и связи их из серебра.'),
(2285, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 12, 'OT', 'Ширина двора со стороны моря — завесы в пятьдесят локтей, столбов у них десять и подножий у них десять.'),
(2286, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 13, 'OT', 'Ширина двора к восточной стороне, на восток, пятьдесят локтей.'),
(2287, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 14, 'OT', 'Пятнадцать локтей завес для стороны, столбов их три, и подножий их три.'),
(2288, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 15, 'OT', 'А для второй стороны — пятнадцать завес; столбов их три, и подножий их три.'),
(2289, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 16, 'OT', 'А для ворот двора — завеса в двадцать локтей, из голубой и багряницы, и червца, и червлёного, кручёного льна, дело вышивальщика; столбов их четыре, и подножий их четыре.'),
(2290, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 17, 'OT', 'Все столбы двора кругом обложены серебром, крюки их — серебро, а подножия их — медь.'),
(2291, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 18, 'OT', 'Длина двора — сто локтей, и ширина — пятьдесят на пятьдесят, и рост — пять локтей из кручёного виссона, и подножия их — медь.'),
(2292, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 19, 'OT', 'Для всех сосудов скинии, во всём служении её, и все колья её, и все колья двора — медь.'),
(2293, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 20, 'OT', 'И ты повели сынам Израиля, и пусть возьмут они тебе елей из маслин чистый, выбитый, для светила, чтобы возжигать светильник постоянный.'),
(2294, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 27, 21, 'OT', 'В шатре собрания, вне завесы, которая перед свидетельствами, будет устраивать его Аарон и сыновья его от вечера до утра пред лицом Господа: устав вечный для родов их от сынов Израиля.'),
(2295, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 1, 'OT', 'И ты приблизь к себе Аарона, брата твоего, и сыновей его с ним, из среды сынов Израиля, чтобы он священнодействовал Мне: Аарона, Надава и Авиуда, Елеазара и Ифамара, сыновей Аарона.'),
(2296, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 2, 'OT', 'И сделай одежду святыни для Аарона, брата твоего, для славы и для красоты.'),
(2297, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 3, 'OT', 'И ты скажи всем мудрым сердцем, которых Я исполнил духом мудрости, и пусть они сделают одежды Аарону, чтобы освятить его, чтобы он служил Мне как священник.'),
(2298, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 4, 'OT', 'И вот одежда, которую они сделают: наперсник, и ефод, и верхняя одежда, и хитон с узорами, митра и пояс; и сделают священную одежду для Аарона, брата твоего, и для сыновей его, чтобы служить Мне.'),
(2299, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 5, 'OT', 'И они возьмут золото, и голубой, и багряницу, и червлёный багрянец, и виссон.'),
(2300, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 6, 'OT', 'И сделают ефод из золота, голубой и багряницы, червца и червлёного, и кручёного виссона, делом искусным.'),
(2301, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 7, 'OT', 'Две плеча соединённые будут у него к двум краям его, и соединены будут.'),
(2302, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 8, 'OT', 'Пояс ефода его, который на нём, по делу его из него будет: золото, голубой, и багряница, и червлёного багрянца, и лён кручёный.'),
(2303, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 9, 'OT', 'И возьми два камня оникса и вырежь на них имена сынов Израиля.'),
(2304, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 10, 'OT', 'шесть имён их на одном камне, и имена остальных шести на втором камне, по родословию их.'),
(2305, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 11, 'OT', 'Работой ремесленника по камню, резьбою печати, вырежь на двух камнях имена сынов Израиля; в гнездах золота сделай их.'),
(2306, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 12, 'OT', 'И положишь два камня на плечи ефода, камни памяти для сынов Израиля; и будет носить Аарон имена их пред лицом Господа на двух плечах своих для памяти.'),
(2307, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 13, 'OT', 'И сделай гнезда из золота.'),
(2308, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 14, 'OT', 'И две цепи из чистого золота, сделанные как дело верви, сделай их на концах, и положи цепи верви на гнезда.'),
(2309, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 15, 'OT', 'И сделаешь наперсник для решения делом искусным, как дело ефода, сделаешь его: из золота, голубой, багряницы, червлёного цвета багрянца и кручёного виссона сделаешь его.'),
(2310, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 16, 'OT', 'Четырёхугольным будет он, вдвое сложенным: пядь длина его, и пядь ширина его.'),
(2311, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 17, 'OT', 'И наполнишь его оправой из камня: четыре ряда камней; ряд сардис, топаз и карбункул — ряд первый.'),
(2312, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 18, 'OT', 'второй ряд: изумруд, сапфир и алмаз.'),
(2313, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 19, 'OT', 'И третий ряд: лигур, агат и амистис.'),
(2314, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 20, 'OT', 'Четвёртый ряд — берилл, оникс и яспис; вставленные в золото, они будут в оправах их.'),
(2315, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 21, 'OT', 'И камни будут по именам сынов Израиля: двенадцать по именам их, резьба печати, каждый человек по имени своему, будут они для двенадцати колен.'),
(2316, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 22, 'OT', 'И сделаешь на наперснике цепи витые делом верви из золота чистого.'),
(2317, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 23, 'OT', 'И сделай на наперснике два перстня из золота, и положи два перстня на два края наперсника.'),
(2318, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 24, 'OT', 'И положи две верви из золота на два перстня, на края наперсника.'),
(2319, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 25, 'OT', 'И положи оба края двух вервей на два гнезда, и прикрепи их к плечам ефода, против лица его.'),
(2320, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 26, 'OT', 'И сделай два перстня из золота, и помести их на два края наперсника, на край его, который к стороне ефода, внутрь.'),
(2321, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 27, 'OT', 'И сделай два перстня из золота, и положи их на два плеча ефода снизу, против лица его, против связи его, выше пояса ефода.'),
(2322, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 28, 'OT', 'И прикрепят наперсник перстнями его к перстням ефода шнуром голубым, чтобы он был на поясе ефода, и не соскользнёт наперсник с ефода.'),
(2323, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 29, 'OT', 'И понесёт Аарон имена сынов Израиля на наперснике для решения на сердце своём, когда будет входить во святыню, для памяти пред лицом Господа постоянно.'),
(2324, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 30, 'OT', 'И положишь в наперсник решения урим и туммим, и будут они на сердце Аарона, когда он будет входить пред лицо Господа; и будет носить Аарон решение сынов Израиля на сердце своём пред лицом Господа постоянно.'),
(2325, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 31, 'OT', 'И сделаешь верхнюю одежду ефода всю из голубого.'),
(2326, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 32, 'OT', 'И будет отверстие для главы посреди него; уста вокруг отверстия будут делом ткача, как ворот у кольчуги, будут у него, чтобы не разрывалось.'),
(2327, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 33, 'OT', 'И сделай на краю его гранаты из голубой, багряницы и червлёного по краю его кругом, и колокольчики из золота посреди них кругом.'),
(2328, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 34, 'OT', 'золотой колокольчик и гранат, золотой колокольчик и гранат по краю верхней одежды кругом, вокруг.'),
(2329, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 35, 'OT', 'И будет это на Аароне для служения, и слышен будет голос его при входе его в святыню пред лицом Господа и при выходе его, и не умрёт он.'),
(2330, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 36, 'OT', 'Сделай пластину из чистого золота и вырежи на ней резьбу, как на печати: «Святыня Господня».'),
(2331, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 37, 'OT', 'И прикрепишь его к шнуру голубого цвета, и будет он на митре; к лицу митры он будет.'),
(2332, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 38, 'OT', 'И будет оно на челе Аарона, и понесёт Аарон беззаконие святынь, которые освятят сыны Израиля, во всех дарах святынь их; и будет оно на челе его постоянно, для благоволения им пред лицом Господа.'),
(2333, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 39, 'OT', 'Сделаешь хитон из виссона, и сделаешь митру из виссона, и пояс сделаешь делом узорчатого ткача.'),
(2334, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 40, 'OT', 'И сыновьям Аарона сделай хитоны, и сделай им пояса, и головные повязки сделай им для славы и красоты.'),
(2335, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 41, 'OT', 'Облеки в них Аарона, брата твоего, и сыновей его с ним, и помажь их, и посвяти их, и освяти их, и будут они священниками Мне.'),
(2336, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 42, 'OT', 'Сделай им льняные штаны, чтобы покрывать плоть наготы; от чресл и до бедер пусть будут они.'),
(2337, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 28, 43, 'OT', 'И будут они на Аароне и на сыновьях его, когда входят они в шатёр собрания или приступают к жертвеннику, чтобы служить в святыне, и не понесут беззакония и не умрут. Устав вечный для него и для семени его после него.'),
(2338, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 1, 'OT', 'И вот слово, которое ты сделаешь им, чтобы освятить их для священства Мне: возьми тельца одного, сына крупного рогатого скота, и двух овнов без порока.'),
(2339, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 2, 'OT', 'И хлеб опресноков, и лепёшки опресночные, смешанные с елеем, и лепёшки опресночные, помазанные елеем, из муки пшеничной сделай их.'),
(2340, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 3, 'OT', 'И положи их в одну корзину, и принеси их в корзине, и тельца, и двух овнов.'),
(2341, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 4, 'OT', 'Приведи Аарона и сыновей его ко входу в шатёр собрания, и омой их водою.'),
(2342, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 5, 'OT', 'И возьми одежду, и одень Аарона в хитон, и в верхнюю одежду ефода, и в ефод, и в наперсник, и опояшь его поясом ефода.'),
(2343, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 6, 'OT', 'И возложи митру на главу его, и дай венец святыни на митру.'),
(2344, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 7, 'OT', 'И возьми елей помазания, и возлей на главу его, и помажь его.'),
(2345, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 8, 'OT', 'И приведи сыновей его, и одень их в хитоны.'),
(2346, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 9, 'OT', 'И опояшешь их поясом, Аарона и сынов его, и возложишь на них повязки, и будет им священство по уставу вечному, и наполнишь руку Аарона и руку сынов его.'),
(2347, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 10, 'OT', 'И приведи тельца пред лицо шатра собрания, и возложат Аарон и сыны его руки свои на главу тельца.'),
(2348, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 11, 'OT', 'И заколешь тельца пред лицом Господа, у двери шатра собрания.'),
(2349, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 12, 'OT', 'И возьмёшь из крови тельца и дашь на рога жертвенника перстом твоим, а всю кровь выльешь к основанию жертвенника.'),
(2350, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 13, 'OT', 'И возьми весь тук, покрывающий внутренность, и перепонку на печени, и обе почки, и тук, который на них, и сожги на жертвеннике.'),
(2351, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 14, 'OT', 'А плоть тельца и кожу его и навоз его сожги на огне вне стана; это жертва за грех.'),
(2352, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 15, 'OT', 'И возьми одного овна, и пусть Аарон и сыны его возложат руки свои на главу овна.'),
(2353, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 16, 'OT', 'И заколешь овна, и возьмёшь кровь его, и покропишь на жертвенник кругом.'),
(2354, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 17, 'OT', 'Рассеки овна на куски его, и омой внутренность его и голени его, и положи на куски его и на главу его.'),
(2355, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 18, 'OT', 'И сожги всего овна на жертвеннике; это всесожжение Господу, запах приятного благоухания, жертва Господу.'),
(2356, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 19, 'OT', 'И возьми второго овна, и пусть Аарон и сыны его возложат руки свои на главу овна.'),
(2357, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 20, 'OT', 'И заколешь овна, и возьмёшь из крови его, и дашь на мочку правого уха Аарона и на мочку правого уха сыновей его, и на большой палец правой руки их, и на большой палец правой ноги их, и покропишь кровью на жертвенник со всех сторон в окрестность.'),
(2358, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 21, 'OT', 'И возьмёшь из крови, которая на жертвеннике, и из елея помазания, и покропишь на Аарона и на одежды его, и на сынов его, и на одежды сынов его с ним; и будет свят он и одежды его, и сыны его, и одежды сынов его с ним.'),
(2359, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 22, 'OT', 'И возьми от овна тук и курдюк, и тук, покрывающий внутренность, и перепонку печени, и обе почки, и тук, который на них, и бедро правой руки, ибо это овен посвящения.'),
(2360, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 23, 'OT', 'И один каравай хлеба, и одну лепёшку хлеба с елеем, и одну лепёшку из корзины опресноков, которая пред лицом Господа.'),
(2361, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 24, 'OT', 'И положи всё на ладони Аарона и на ладони сыновей его, и потряси это потрясанием пред лицом Господа.'),
(2362, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 25, 'OT', 'И возьмёшь их из руки их, и сожжёшь на жертвеннике поверх всесожжения, в запах приятного благоухания пред лицом Господа: жертва это Господу.'),
(2363, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 26, 'OT', 'И возьми грудь от овна посвящения, который для Аарона, и соверши потрясание ею пред лицом Господа; и будет она тебе частью.'),
(2364, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 27, 'OT', 'И освяти грудь потрясания и бедро приношения, которые были потрясены и вознесены от овна посвящения, которое для Аарона и которое для сыновей его.'),
(2365, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 28, 'OT', 'И будет это Аарону и сынам его уставом вечным от сынов Израиля, ибо это приношение; и приношение будет от сынов Израиля из жертв мирных их, приношение их Господу.'),
(2366, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 29, 'OT', 'Священные одежды святыни Аарона будут принадлежать его сыновьям после него, для помазания в них и для посвящения их.'),
(2367, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 30, 'OT', 'Семь дней будет облачаться в них священник из сыновей его, который входит в шатёр собрания для служения во святыне.'),
(2368, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 31, 'OT', 'Возьми овна посвящения и свари плоть его на святом месте.'),
(2369, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 32, 'OT', 'И будет есть Аарон и сыновья его плоть овна и хлеб, который в корзине, у двери шатра собрания.'),
(2370, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 33, 'OT', 'И пусть едят их те, кому совершено очищение, чтобы посвятить их для освящения их; а посторонний не будет есть, ибо они святыня.'),
(2371, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 34, 'OT', 'Если же останется от плоти посвящения и от хлеба до утра, то сожги остаток на огне; не должно есть его, ибо это святыня.'),
(2372, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 35, 'OT', 'Сделай Аарону и сыновьям его так, как всё, что Я повелел тебе; семь дней посвящай их.'),
(2373, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 36, 'OT', 'И принесёшь тельца в жертву за грех на день очищения, и очистишь жертвенник, совершая над ним очищение, и помажешь его, чтобы освятить его.'),
(2374, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 37, 'OT', 'Семь дней очищай жертвенник, и освяти его, и будет жертвенник святыней великой; всё, что прикасается к жертвеннику, освятится.'),
(2375, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 38, 'OT', 'И вот что ты будешь приносить на жертвеннике: двух ягнят, сыновей года, каждый день постоянно.'),
(2376, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 39, 'OT', 'одного ягнёнка приноси утром, а другого ягнёнка приноси между вечерами.'),
(2377, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 40, 'OT', 'И десятая часть муки, смешанной с елеем, четверть гина, и возлияние, четверть гина вина, для одного ягнёнка.'),
(2378, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 41, 'OT', 'А второго ягнёнка соверши между вечерами, как утреннее приношение и как возлияние его, соверши для него, в приятное благоухание, жертва Господу.'),
(2379, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 42, 'OT', 'Всесожжение постоянное в роды ваши, у двери шатра собрания пред лицом Господа, где Я буду встречаться с вами, чтобы говорить там с тобою.'),
(2380, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 43, 'OT', 'И встречусь там с сынами Израиля, и освятится оно славою Моею.'),
(2381, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 44, 'OT', 'И освящу шатёр собрания и жертвенник, и Аарона и сыновей его освящу, чтобы они священнодействовали Мне.'),
(2382, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 45, 'OT', 'И поселюсь в середине сынов Израиля и буду им Богом.'),
(2383, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 29, 46, 'OT', 'И узнают, что Я Господь, Бог их, Который вывел их из земли Египетской, чтобы обитать среди них; Я Господь, Бог их.'),
(2384, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 1, 'OT', 'Сделай жертвенник для курения фимиама из дерева ситтим сделай его.'),
(2385, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 2, 'OT', 'Локоть длина его, и локоть ширина его, четырёхугольным будет он, и два локтя рост его; из него рога его.'),
(2386, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 3, 'OT', 'И покроешь его чистым золотом: кровлю его и стены его вокруг, и рога его; и сделаешь ему венец золотой вокруг.'),
(2387, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 4, 'OT', 'И две перстня из золота сделай для него под венцом его, на двух боках его сделай, на двух сторонах его; и будут они домами для шестов, чтобы носить его ими.'),
(2388, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 5, 'OT', 'И сделай шесты из дерева ситтим, и покрой их золотом.'),
(2389, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 6, 'OT', 'И поставь его пред лицом завесы, которая пред ковчегом свидетельства, пред лицом крышки, которая над свидетельством, где Я буду открываться тебе.'),
(2390, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 7, 'OT', 'И воскурит над ним Аарон фимиам из ароматов; каждое утро, утром, когда он поправляет светильники, воскурит его.'),
(2391, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 8, 'OT', 'И когда будет зажигать Аарон светильники между вечерами, он будет воскурять его: фимиам постоянный пред лицом Господа в роды ваши.'),
(2392, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 9, 'OT', 'Не возносите на нём фимиама чуждого, ни всесожжения, ни дара, и возлияния не возливайте на нём.'),
(2393, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 10, 'OT', 'И совершит Аарон очищение над рогами его однажды в год, кровью жертвы за грех очищения однажды в год совершит он очищение над ним для родов ваших; святыня святынь это для Господа.'),
(2394, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 11, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2395, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 12, 'OT', 'Когда будешь исчислять число сынов Израиля по переписи их, пусть дадут каждый человек выкуп за душу свою Господу при исчислении их, и не будет среди них язвы при исчислении их.'),
(2396, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 13, 'OT', 'Всё, проходящее через перепись, даст половину сикля по сиклю святыни: двадцать гер в сикле, половина сикля — приношение Господу.'),
(2397, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 14, 'OT', 'Всё, проходящее через перепись, от сына двадцати лет и выше, даст приношение Господу.'),
(2398, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 15, 'OT', 'Богатый не должен давать больше, и бедный не должен давать меньше половины сикля, чтобы принести приношение Господу для искупления душ ваших.'),
(2399, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 16, 'OT', 'И возьми деньги умилостивления от сынов Израиля и отдай их на служение шатра собрания; и будет это сынам Израиля в память пред лицом Господа, для умилостивления за души ваши.'),
(2400, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 17, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2401, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 18, 'OT', 'Сделай умывальник из меди и основание его из меди, для омовения, и поставь его между шатром собрания и жертвенником, и налей туда воды.'),
(2402, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 19, 'OT', 'И будут омывать Аарон и сыновья его из него руки свои и ноги свои.'),
(2403, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 20, 'OT', 'Когда они входят в шатёр собрания, пусть омываются водою, и не умрут; или когда приступают к жертвеннику для служения, чтобы воскурять жертву Господу.'),
(2404, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 21, 'OT', 'И омоют руки свои и ноги свои, и не умрут; и будет это для них уставом вечным — ему и семени его в роды их.'),
(2405, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 22, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2406, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 23, 'OT', 'И ты возьми себе благовоний лучших: мирры свободной пятьсот, и корицы благовонной половину её — двести пятьдесят, и тростника благовонного двести пятьдесят.'),
(2407, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 24, 'OT', 'кассия пятьсот сиклей святыни, и елей маслины гин'),
(2408, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 25, 'OT', 'И сделаешь из него елей помазания святыни, мазь, составленную по искусству мази, дело мастера; елей помазания святыни будет он.'),
(2409, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 26, 'OT', 'И помажешь им шатёр собрания и ковчег свидетельства.'),
(2410, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 27, 'OT', 'и стол и все сосуды его, и светильник и сосуды его, и жертвенник фимиама'),
(2411, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 28, 'OT', 'и жертвенник всесожжения, и все сосуды его, и умывальник, и основание его'),
(2412, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 29, 'OT', 'И освяти их, и будут они святыней великой; всё, что прикоснётся к ним, освятится.'),
(2413, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 30, 'OT', 'И Аарона и сыновей его помажь, и освяти их, чтобы они были священниками Мне.'),
(2414, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 31, 'OT', 'И скажи сынам Израиля так: елей помазания святыни будет это у Меня для родов ваших.'),
(2415, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 32, 'OT', 'На плоть человека не возливай его, и по составу его не делайте подобного ему; святыня он, святынею будет для вас.'),
(2416, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 33, 'OT', 'Человек, который приготовит подобное ему и который даст от него на постороннего, — и будет истреблён из народа своего.'),
(2417, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 34, 'OT', 'И сказал Господь Моисею: возьми себе ароматы: стакти, оника и гальбан, ароматы и ладан чистый, порциями будет.'),
(2418, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 35, 'OT', 'И сделаешь из этого фимиам, состав, дело мастера, смешанную, чистую, святыню.'),
(2419, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 36, 'OT', 'Истолки её в мелкий порошок, и положи от неё пред лицом свидетельства в шатре собрания, где Я буду открываться тебе; святыня святынь будет она для вас.'),
(2420, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 37, 'OT', 'И фимиам, который ты сделаешь, по составу его не делайте себе; святынею будет он у тебя для Господа.'),
(2421, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 30, 38, 'OT', 'Человек, который сделает подобное ей, чтобы нюхать её, будет истреблён из своего народа.'),
(2422, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(2423, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 2, 'OT', 'Вот, Я призвал по имени Веселеила, сына Урия, сына Хура, из колена Иуды.'),
(2424, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 3, 'OT', 'И наполнил Я его духом Божьим, мудростью и разумением, и знанием, и всякой работой.'),
(2425, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 4, 'OT', 'чтобы делать искусные работы, делать из золота и из серебра и из меди'),
(2426, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 5, 'OT', 'и в резьбе камня для вставки, и в резьбе дерева, чтобы делать всякую работу.'),
(2427, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 6, 'OT', 'И вот, Я дал с ним Аголиава, сына Ахисамаха, из колена Данова, и в сердце каждого мудрого сердцем Я дал мудрость, и сделают они всё, что Я повелел тебе.'),
(2428, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 7, 'OT', 'шатёр собрания, и ковчег свидетельства, и крышку, которая на нём, и все сосуды шатра'),
(2429, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 8, 'OT', 'и стол и сосуды его, и светильник чистый и все сосуды его, и жертвенник фимиама'),
(2430, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 9, 'OT', 'и жертвенник всесожжения и все сосуды его, и умывальник и основание его'),
(2431, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 10, 'OT', 'и одежды служения, и одежды святыни для Аарона, священника, и одежды сыновей его для священнодействия.'),
(2432, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 11, 'OT', 'И елей помазания, и фимиам из ароматов для святыни: всё, что Я повелел тебе, пусть сделают.'),
(2433, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 12, 'OT', 'И сказал Господь Моисею, говоря:'),
(2434, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 13, 'OT', 'А ты говори сынам Израиля, говоря: только субботы Мои соблюдайте, ибо это знамение между Мною и вами для родов ваших, чтобы знать, что Я — Господь, освящающий вас.'),
(2435, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 14, 'OT', 'Соблюдайте субботу, ибо она святыня для вас; оскверняющий её будет предан смерти, ибо всякий, кто делает в ней работу, — та душа будет истреблена из среды народа своего.'),
(2436, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 15, 'OT', 'Шесть дней делается работа, а в седьмой день — суббота покоя, свята для Господа; всякий, кто делает работу в день субботы, будет предан смерти.'),
(2437, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 16, 'OT', 'И будут хранить сыны Израиля субботу, совершая субботу в роды их, завет вечный.'),
(2438, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 17, 'OT', 'Это знамение между Мною и сынами Израиля навеки, ибо в шесть дней Господь сотворил небо и землю, а в день седьмой почил и отдохнул.'),
(2439, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 31, 18, 'OT', 'И дал он Моисею, когда окончил говорить с ним на горе Синай, две доски свидетельства, доски каменные, написанные перстом Божиим.'),
(2440, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 1, 'OT', 'И увидел народ, что Моисей медлит сойти с горы, и собрался народ к Аарону, и сказали ему: встань, сделай нам Бога, который пойдёт перед лицом нашим, ибо этот Моисей, человек, который вывел нас из земли Египетской, — не знаем, что с ним стало.'),
(2441, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 2, 'OT', 'И сказал им Аарон: снимите золотые кольца, которые в ушах жён ваших, сыновей ваших и дочерей ваших, и принесите ко мне.'),
(2442, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 3, 'OT', 'И снял весь народ золотые кольца, которые были в ушах их, и принесли их к Аарону.'),
(2443, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 4, 'OT', 'Он взял их из рук их, и обделал его резцом, и сделал из него литого телёнка, и сказали они: вот боги твои, Израиль, которые вывели тебя из земли Египетской.'),
(2444, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 5, 'OT', 'Увидел Аарон, и построил жертвенник перед лицом его, и воззвал Аарон, и сказал: праздник Господу завтра.'),
(2445, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 6, 'OT', 'И встали они на следующий день, и вознесли всесожжения, и принесли мирные жертвы; и сел народ есть и пить, и встали играть.'),
(2446, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 7, 'OT', 'И сказал Господь Моисею: иди, сойди, ибо развратился народ твой, который ты вывел из земли Египетской.'),
(2447, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 8, 'OT', 'Они скоро уклонились с пути, который Я заповедал им; сделали себе телёнка литого, и поклонились ему, и принесли ему жертвы, и сказали: вот боги твои, Израиль, которые вывели тебя из земли Египетской.'),
(2448, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 9, 'OT', 'И сказал Господь Моисею: Я видел этот народ, и вот, он народ с жестокой шеей.'),
(2449, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 10, 'OT', 'И теперь оставь Меня, и воспламенится гнев Мой на них, и истреблю их, и сделаю тебя народом великим.'),
(2450, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 11, 'OT', 'И умолял Моисей лицо Господа, Бога своего, и сказал: зачем, Господь, воспылает гнев Твой на народ Твой, который Ты вывел из земли Египетской силою великою и рукою крепкою?'),
(2451, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 12, 'OT', 'Зачем Египтяне будут говорить: «Со злом Он вывел их, чтобы убить их в горах и истребить их с лица земли»? Отврати ярость гнева Твоего и пожалей о зле народу Твоему.'),
(2452, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 13, 'OT', 'Вспомни Авраама, Исаака и Израиля, рабов Твоих, которым Ты клялся Собою и говорил им: умножу семя ваше, как звёзды небесные, и всю эту землю, о которой Я сказал, дам семени вашему, и будут владеть ею вечно.'),
(2453, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 14, 'OT', 'И пожалел Господь о зле, которое сказал сделать народу Своему.'),
(2454, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 15, 'OT', 'И повернулся и сошёл Моисей с горы, и две доски свидетельства в руке его; доски, написанные с обоих сторон их, с этой и с той стороны они были написаны.'),
(2455, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 16, 'OT', 'Доски были делом Божьим, и писание было писанием Божьим, вырезанным на досках.'),
(2456, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 17, 'OT', 'И услышал Иисус голос народа в крике его, и сказал Моисею: голос войны в стане.'),
(2457, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 18, 'OT', 'И сказал он: не голос силы, и не голос изнеможения, голос пения я слышу.'),
(2458, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 19, 'OT', 'И было, когда он приблизился к стану, и увидел телёнка и пляску, то воспылал гнев Моисея, и он бросил из рук своих доски, и разбил их под горою.'),
(2459, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 20, 'OT', 'Он взял телёнка, которого они сделали, и сжёг его в огне, и стёр его в порошок, и рассыпал по лицу воды, и напоил сынов Израиля.'),
(2460, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 21, 'OT', 'И сказал Моисей Аарону: что сделал тебе народ этот, что ты навёл на него великий грех?'),
(2461, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 22, 'OT', 'И сказал Аарон: да не воспламенится гнев господина моего; ты знаешь народ, что он во зле.'),
(2462, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 23, 'OT', 'И сказали мне: сделай нам Бога, который пойдёт пред лицом нашим; ибо этот Моисей, человек, который вывел нас из земли Египетской, — не знаем, что с ним стало.'),
(2463, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 24, 'OT', 'И я сказал им: у кого золото, снимите с себя, и они дали мне; и я бросил его в огонь, и вышел этот телёнок.'),
(2464, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 25, 'OT', 'Моисей увидел, что народ был распущен, ибо Аарон распустил его на позор среди врагов их.'),
(2465, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 26, 'OT', 'И стал Моисей в воротах стана и сказал: кто за Господа, ко мне! И собрались к нему все сыны Левия.'),
(2466, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 27, 'OT', 'И сказал им: так говорит Господь, Бог Израиля: возложите каждый человек свой меч на бедро своё, пройдите и возвратитесь от ворот до ворот по стану, и убейте каждый человек брата своего, и каждый человек ближнего своего, и каждый человек родственника своего.'),
(2467, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 28, 'OT', 'Сыновья Левия сделали по слову Моисея, и пало из народа в тот день около трёх тысяч человек.'),
(2468, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 29, 'OT', 'Моисей сказал: посвятите себя сегодня Господу, ибо каждый человек против сына своего и против брата своего, и чтобы дать вам сегодня благословение.'),
(2469, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 30, 'OT', 'На следующий день Моисей сказал народу: вы совершили великий грех; и теперь я взойду к Господу, может быть, я искуплю грех ваш.'),
(2470, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 31, 'OT', 'И возвратился Моисей к Господу и сказал: о, согрешил народ этот грехом великим, и сделали себе богов из золота.'),
(2471, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 32, 'OT', 'И ныне, если простишь грех их, то прости; а если нет, то изгладь меня из книги Твоей, которую Ты написал.'),
(2472, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 33, 'OT', 'И сказал Господь Моисею: кто согрешил предо Мною, того изглажу из книги Моей.'),
(2473, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 34, 'OT', 'Итак, иди, веди народ туда, куда Я сказал тебе; вот, ангел Мой пойдёт пред лицом твоим, а в день посещения Моего Я накажу их за грех их.'),
(2474, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 32, 35, 'OT', 'И поразил Господь народ за то, что они сделали телёнка, которого сделал Аарон.'),
(2475, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 1, 'OT', 'И сказал Господь Моисею: пойди, поднимись отсюда, ты и народ, который ты вывел из земли Египетской, в землю, о которой Я клялся Аврааму, Исааку и Иакову, говоря: семени твоему дам её.'),
(2476, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 2, 'OT', 'И пошлю пред лицом твоим ангела, и прогоню Хананеянина, Аморрея, и Хеттеянина, и Ферезеев, Евеев и Иевусеев.'),
(2477, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 3, 'OT', 'в землю, текущую молоком и мёдом; ибо не взойду среди тебя, потому что ты народ жестоковыйный, чтобы не истребить тебя на пути.'),
(2478, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 4, 'OT', 'И услышал народ это злое слово, и опечалились, и не возложил никто из людей украшения своего на себя.'),
(2479, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 5, 'OT', 'И сказал Господь Моисею: скажи сынам Израиля: вы народ с жестокой шеей; если Я взойду среди тебя на одно мгновение, то истреблю тебя; итак сними с себя украшение твоё, и Я узнаю, что Мне сделать с тобою.'),
(2480, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 6, 'OT', 'И сняли с себя сыны Израиля украшения свои с горы Хорив.'),
(2481, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 7, 'OT', 'И взял Моисей шатёр и раскинул его вне стана, далеко от стана, и назвал его шатром собрания; и было: всякий, ищущий Господа, выходил к шатру собрания, который вне стана.'),
(2482, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 8, 'OT', 'И было: когда выходил Моисей к шатру, весь народ вставал, и каждый человек стоял у двери своего шатра, и смотрели вслед Моисею, пока он не входил в шатёр.'),
(2483, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 9, 'OT', 'И было, когда входил Моисей в шатёр, сходил столб облака и становился у двери шатра, и говорил с Моисеем.'),
(2484, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 10, 'OT', 'И видел весь народ столб облака, стоящий у двери шатра, и вставал весь народ, и поклонялся каждый человек у двери шатра своего.'),
(2485, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 11, 'OT', 'И говорил Господь с Моисеем лицом к лицу, как говорит человек с ближним своим; и возвращался он в стан, а служитель его Иисус, сын Нуна, отрок, не отходил из середины шатра.'),
(2486, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 12, 'OT', 'И сказал Моисей Господу: вот, Ты говоришь мне: веди народ этот, но Ты не открыл мне, кого пошлёшь со мною; а Ты сказал: Я знаю тебя по имени, и ты обрёл благодать в очах Моих.'),
(2487, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 13, 'OT', 'И ныне, если я обрёл благодать в очах Твоих, открой мне путь Твой, чтобы я познал Тебя, дабы обрести благодать в очах Твоих; и посмотри, что народ Твой — этот народ.'),
(2488, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 14, 'OT', 'Лицо Моё пойдёт, и Я дам тебе покой.'),
(2489, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 15, 'OT', 'И сказал ему: если лицо Твоё не идёт с нами, не выводи нас отсюда.'),
(2490, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 16, 'OT', 'И чем будет известно, что я обрёл благодать в очах Твоих, я и народ Твой, — не тем ли, что Ты пойдёшь с нами, и мы будем отделены, я и народ Твой, от всякого народа, который на лице земли?'),
(2491, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 17, 'OT', 'И сказал Господь Моисею: и это слово, которое ты сказал, Я сделаю, ибо ты обрёл благодать в очах Моих, и Я знаю тебя по имени.'),
(2492, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 18, 'OT', 'Покажи мне, пожалуйста, славу Твою.'),
(2493, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 19, 'OT', 'И сказал Он: Я проведу всё благо Моё пред лицом твоим, и воззову именем Господа пред тобою, и помилую, кого помилую, и сжалюсь, над кем сжалюсь.'),
(2494, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 20, 'OT', 'И сказал: не можешь ты увидеть лицо Моё, ибо не увидит Меня человек и останется живым.'),
(2495, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 21, 'OT', 'И сказал Господь: вот место у Меня, и ты станешь на скале.'),
(2496, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 22, 'OT', 'И будет, когда пройдёт слава Моя, Я поставлю тебя в расселине скалы, и покрою ладонью Моей тебя, доколе не пройду.'),
(2497, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 33, 23, 'OT', 'И сниму ладонь Мою, и увидишь заднюю сторону Мою, а лицо Моё не будет видно.'),
(2498, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 1, 'OT', 'И сказал Господь Моисею: вытеши себе две доски из камня, как прежние, и Я напишу на досках слова, которые были на прежних досках, которые ты разбил.'),
(2499, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 2, 'OT', 'Будь готов к утру, и взойди утром на гору Синай, и стань предо Мною там на главе горы.'),
(2500, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 3, 'OT', 'И человек не взойдёт с тобою, и также человек не будет виден на всей горе; даже овцы и крупный рогатый скот не будут пастись напротив той горы.'),
(2501, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 4, 'OT', 'И вытесал две каменные доски, как прежние, и встал Моисей рано утром, и поднялся на гору Синай, как повелел ему Господь, и взял в руку свою две каменные доски.'),
(2502, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 5, 'OT', 'И сошёл Господь в облаке, и стал там с ним, и провозгласил имя Господа.'),
(2503, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 6, 'OT', 'И прошёл Господь пред лицом его, и воззвал: Господь, Господь, Бог милосердный и милостивый, долготерпеливый, и великий в милости и истине.'),
(2504, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 7, 'OT', 'хранящий милость до тысячи поколений, прощающий беззаконие и преступление и грех, но не оставляющий без наказания, наказывающий беззаконие отцов на сыновьях и на сыновьях сыновей, до третьего и четвёртого поколения.'),
(2505, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 8, 'OT', 'И поспешил Моисей, и преклонился до земли, и поклонился.'),
(2506, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 9, 'OT', 'И сказал он: если я обрёл благодать в очах Твоих, Господь, пусть пойдёт Господь среди нас, ибо это народ с жестокой шеей, и прости беззаконие наше и грех наш, и сделай нас наследием Твоим.'),
(2507, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 10, 'OT', 'И сказал Он: вот, Я заключаю завет пред всем народом твоим; совершу чудеса, каких не было во всей земле и у всех народов; и увидит весь народ, среди которого ты находишься, дело Господа, ибо страшно то, что Я делаю с тобою.'),
(2508, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 11, 'OT', 'Соблюдай себе то, что Я заповедую тебе сегодня: вот, Я прогоняю от лица твоего Аморрея, и Хананеянина, и Хеттеянина, и Ферезеев, и Евеев, и Иевусеев.'),
(2509, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 12, 'OT', 'Берегись, чтобы не заключить завет с жителем той земли, на которую ты идёшь, чтобы он не стал западнёй среди тебя.'),
(2510, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 13, 'OT', 'Ибо жертвенники их вы разрушите, и столбы их сокрушите, и Ашеры их срубите.'),
(2511, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 14, 'OT', 'Ибо не поклоняйся богу иному, ибо Господь — имя Его ревнитель; Бог ревнитель Он.'),
(2512, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 15, 'OT', 'чтобы ты не заключил завет с жителем земли, и они не стали блудить вслед за своими богами, и не приносили жертв своим богам, и не позвали тебя, и ты не ел бы от жертвы его.'),
(2513, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 16, 'OT', 'и возьмёшь из дочерей его для сыновей твоих, и будут блудить дочери его вслед за богами своими, и вовлекут в блуд сыновей твоих вслед за богами своими.'),
(2514, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 17, 'OT', 'Не делай себе литых богов.'),
(2515, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 18, 'OT', 'Соблюдай праздник опресноков: семь дней ешь опресноки, как Я повелел тебе, в назначенное время месяца колосьев, ибо в месяце колосьев ты вышел из Египта.'),
(2516, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 19, 'OT', 'Всё, разверзающее матку, — Мне; и весь скот твой, первенец вола и овцы.'),
(2517, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 20, 'OT', 'Первенца осла выкупи овцою, а если не выкупишь, то сломай ему шею; всякого первенца из сыновей твоих выкупай, и не являйся пред лицо Моё с пустыми руками.'),
(2518, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 21, 'OT', 'Шесть дней работай, а в седьмой день покойся; в пахоту и в жатву покойся.'),
(2519, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 22, 'OT', 'И праздник седмиц совершай себе, первый плод жатвы пшеницы, и праздник собрания при кругообороте года.'),
(2520, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 23, 'OT', 'Три раза в год всякий мужской пол у тебя должен явиться пред лицо Господа, Бога Израиля.'),
(2521, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 24, 'OT', 'Ибо Я изгоню народы от лица твоего и расширю границы твои, и никто не пожелает земли твоей, когда ты будешь восходить, чтобы явиться пред лицо Господа, Бога твоего, три раза в год.'),
(2522, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 25, 'OT', 'Не закалывай на квасном крови жертвы Моей, и не оставайся до утра жертва праздника Пасхи.'),
(2523, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 26, 'OT', 'Лучшее из первых плодов земли твоей приноси в дом Господа, Бога твоего; не вари козлёнка в молоке матери его.'),
(2524, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 27, 'OT', 'Господь сказал Моисею: напиши себе эти слова, ибо по этим словам Я заключил с тобой завет и с Израилем.'),
(2525, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 28, 'OT', 'И был он там с Господом сорок дней и сорок ночей, хлеба не ел и воды не пил; и написал на досках слова завета, десять слов.'),
(2526, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 29, 'OT', 'И было, когда сходил Моисей с горы Синай, и две доски свидетельства были в руке Моисея, при сошествии его с горы, и Моисей не знал, что стала сиять кожа лица его, когда Он говорил с ним.'),
(2527, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 30, 'OT', 'И увидел Аарон и все сыны Израиля Моисея, и вот, сияла кожа лица его, и они боялись приблизиться к нему.'),
(2528, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 31, 'OT', 'Моисей позвал их, и возвратились к нему Аарон и все князья в обществе, и говорил Моисей с ними.'),
(2529, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 32, 'OT', 'И после того приблизились все сыны Израиля, и он заповедал им всё, что говорил Господь с ним на горе Синай.'),
(2530, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 33, 'OT', 'И когда Моисей закончил говорить с ними, он положил на лицо своё покрывало.'),
(2531, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 34, 'OT', 'И когда входил Моисей пред лицо Господа, чтобы говорить с Ним, он снимал покрывало, доколе не выходил; и выходил и говорил сынам Израиля то, что было заповедано.'),
(2532, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 34, 35, 'OT', 'И видели сыны Израиля лицо Моисея, что сияла кожа лица Моисея; и возвращал Моисей покрывало на лицо своё, доколе не входил говорить с Ним.'),
(2533, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 1, 'OT', 'Моисей собрал всё общество сынов Израиля и сказал им: вот слова, которые Господь заповедал исполнить.'),
(2534, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 2, 'OT', 'Шесть дней делай работу, а в седьмой день будет у вас свято, суббота покоя Господу: всякий, кто делает в него работу, будет предан смерти.'),
(2535, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 3, 'OT', 'Не разжигайте огня во всех жилищах ваших в день субботы.'),
(2536, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 4, 'OT', 'И сказал Моисей всему обществу сынов Израиля, говоря: вот слово, которое заповедал Господь, говоря.'),
(2537, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 5, 'OT', 'Возьмите из среды вашей приношение Господу: всякий, кто по сердцу своему щедр, пусть принесёт приношение Господу: золото, и серебро, и медь.'),
(2538, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 6, 'OT', 'голубой, и багряница, и червлёного багрянца, и виссон, и козы'),
(2539, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 7, 'OT', 'и кожи бараньи красные, и кожи тахаша, и дерева ситтим'),
(2540, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 8, 'OT', 'И елей для светила, и благовония для елея помазания, и для фимиама из ароматов.'),
(2541, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 9, 'OT', 'И камни оникса, и камни для посвящения — для ефода и для наперсника.'),
(2542, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 10, 'OT', 'И всё мудрое сердцем из вас пусть придут и сделают всё, что повелел Господь.'),
(2543, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 11, 'OT', 'скинию, шатёр её и покрывало её, крючки её и доски её, засовы её, столбы её и подножия её'),
(2544, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 12, 'OT', 'ковчег и шесты его, крышку и завесу завесы'),
(2545, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 13, 'OT', 'стол и его шесты, и все сосуды его, и хлебы предложения'),
(2546, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 14, 'OT', 'И светильник светила, и сосуды его, и светильники его, и елей светила.'),
(2547, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 15, 'OT', 'И жертвенник фимиама, и шесты его, и елей помазания, и фимиам ароматов, и завесу двери для двери скинии.'),
(2548, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 16, 'OT', 'жертвенник всесожжения и медную решётку его, и шесты его, и все сосуды его, умывальник и основание его'),
(2549, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 17, 'OT', 'завесы двора, столбы его и подножия его, и завесу ворот двора'),
(2550, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 18, 'OT', 'колья скинии и колья двора, и верви их'),
(2551, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 19, 'OT', 'Одежды служения для служения в святыне, одежды святыни для Аарона, священника, и одежды сыновей его для священнодействия.'),
(2552, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 20, 'OT', 'И вышло всё общество сынов Израиля от лица Моисея.'),
(2553, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 21, 'OT', 'И пришли все, кого влекло сердце, и все, кого побуждал дух, принесли приношение Господу для работы шатра собрания и для всего служения его, и для священных одежд.'),
(2554, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 22, 'OT', 'И пришли люди с жёнами, все, чьё сердце было щедрым, принесли крючки, и кольца, и перстни, и нагрудные украшения, всякие золотые украшения, и каждый человек, который совершал потрясание золота Господу.'),
(2555, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 23, 'OT', 'И всякий человек, у которого нашлись голубая, и багряница, и червлёного багрянца, и лён, и козы, и кожи овнов, окрашенные в красное, и кожи тахаша, принесли.'),
(2556, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 24, 'OT', 'Все, кто возвышал приношение серебра и меди, принесли приношение Господу; и все, у кого нашлось дерево ситтим для всякой работы служения, принесли.'),
(2557, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 25, 'OT', 'И все жены с мудрым сердцем пряли своими руками и приносили пряжу: голубую, и багряницу, и червленую, и виссон.'),
(2558, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 26, 'OT', 'И все жены, которых сердце побудило к мудрости, пряли козью шерсть.'),
(2559, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 27, 'OT', 'И князья принесли камни оникса и камни для посвящения, для ефода и для наперсника.'),
(2560, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 28, 'OT', 'И благовоние, и елей для светила, и елей для помазания, и фимиам из ароматов.'),
(2561, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 29, 'OT', 'Всякий человек и жена, которых сердце побудило принести для всякой работы, которую Господь повелел сделать через Моисея, — принесли сыны Израиля приношение Господу.'),
(2562, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 30, 'OT', 'И сказал Моисей сынам Израиля: вот, призвал Господь по имени Веселеила, сына Урия, сына Хура, из колена Иуды.'),
(2563, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 31, 'OT', 'И наполнил его духом Бога, мудростью, разумением и знанием, и всякой работой.'),
(2564, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 32, 'OT', 'И искусно работать по золоту, и по серебру, и по меди.'),
(2565, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 33, 'OT', 'и в резьбе по камню для заполнения, и в резьбе по дереву, чтобы делать всякую работу искусной работы.'),
(2566, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 34, 'OT', 'И способность учить вложил в сердце его, он и Аголиав, сын Ахисамаха, из колена Данова.'),
(2567, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 35, 35, 'OT', 'Он наполнил их мудростью сердца, чтобы делать всякую работу ремесленника и замышляющего, и вышивающего по голубой и по багрянице, по червлёного багрянца и по виссону, и ткущего, делающих всякую работу и замышляющих замыслы.'),
(2568, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 1, 'OT', 'И сделал Веселеил и Аголиав и всякий человек мудрый сердцем, которым дал Господь мудрость и разумение, чтобы уметь делать всякую работу служения святыни, всё, что повелел Господь.'),
(2569, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 2, 'OT', 'И созвал Моисей Веселеила и Аголиава, и всякого человека мудрого сердцем, которому Господь дал мудрость в сердце его, всех, кого влекло сердце его приступить к работе, чтобы делать её.'),
(2570, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 3, 'OT', 'Они взяли от лица Моисея всё приношение, которое сыны Израиля принесли для работы служения святыни, чтобы сделать её; и они ещё приносили ему добровольное приношение утром, утром.'),
(2571, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 4, 'OT', 'И пришли все мудрецы, делавшие всю работу святыни, каждый человек от своей работы, которую они делали.'),
(2572, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 5, 'OT', 'И сказали они Моисею, говоря: народ приносит больше, чем достаточно для служения, для работы, которую Господь повелел сделать.'),
(2573, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 6, 'OT', 'И повелел Моисей, и провозгласили объявление по стану, говоря: пусть человек и жена не делают больше работы для приношения святыни. И удержан был народ от приношения.'),
(2574, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 7, 'OT', 'И работы было достаточно для всей работы, чтобы сделать её, и оставалось излишек.'),
(2575, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 8, 'OT', 'И сделали все мудрые сердцем, делающие работу, скинию из десяти завес: из кручёного льна, и голубой, и багряницы, и червлёного багрянца, херувимов, делом искусным сделали их.'),
(2576, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 9, 'OT', 'Длина одной завесы — двадцать восемь локтей, и ширина четыре локтя — завеса одна; мера одна для всех завес.'),
(2577, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 10, 'OT', 'И соединил пять завес одну к другой, и пять завес соединил одну к другой.'),
(2578, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 11, 'OT', 'И сделал петли из голубой ткани на краю одной завесы, с края, в связи; так же сделал на краю крайней завесы во второй связи.'),
(2579, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 12, 'OT', 'Пятьдесят петель сделал он на одной завесе, и пятьдесят петель сделал он на краю завесы, которая во второй связи; петли были расположены одна против другой.'),
(2580, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 13, 'OT', 'И сделал пятьдесят крючков из золота, и соединил завесы одну с другою крючками, и стала скиния единою.'),
(2581, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 14, 'OT', 'Сделал завесы из козьей шерсти для шатра поверх скинии; одиннадцать завес сделал он.'),
(2582, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 15, 'OT', 'Длина одной завесы — тридцать локтей, и четыре локтя ширина одной завесы; мера одна для одиннадцати завес.'),
(2583, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 16, 'OT', 'И соединил пять завес отдельно, и шесть завес отдельно.'),
(2584, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 17, 'OT', 'И сделал пятьдесят петель на краю завесы крайней в связи, и пятьдесят петель сделал на краю завесы второй, соединяющей.'),
(2585, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 18, 'OT', 'И сделал пятьдесят крючков из меди, чтобы соединить шатёр, чтобы он был одним.'),
(2586, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 19, 'OT', 'И сделал покрывало для шатра из кожи овнов, окрашенной в красный цвет, и покрывало из кожи тахаша поверх него.'),
(2587, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 20, 'OT', 'И сделал доски для скинии из дерева ситтим, стоящие.'),
(2588, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 21, 'OT', 'Десять локтей длина доски, и локоть с половиною локтя ширина доски одной.'),
(2589, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 22, 'OT', 'Два шипа у одной доски, соединённые один с другим; так он сделал для всех досок скинии.'),
(2590, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 23, 'OT', 'И сделал доски для скинии: двадцать досок для края юга, к югу.'),
(2591, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 24, 'OT', 'И сорок подножий серебряных сделал под двадцать досок: два подножия под одну доску для двух шипов её, и два подножия под другую доску для двух шипов её.'),
(2592, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 25, 'OT', 'И для стороны скинии, второй, к краю севера, он сделал двадцать досок.'),
(2593, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 26, 'OT', 'и сорок подножий их из серебра: два подножия под одну доску, и два подножия под другую доску.'),
(2594, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 27, 'OT', 'И для окраин скинии к западу сделал шесть досок.'),
(2595, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 28, 'OT', 'И две доски сделал он для углов скинии, в задней части её.'),
(2596, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 29, 'OT', 'И были они близнецами снизу, и вместе будут цельными до главы его, до перстня одного; так сделал он для обоих их, для двух углов.'),
(2597, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 30, 'OT', 'И было восемь досок, и подножий их из серебра шестнадцать подножий: два подножия, два подножия под каждую доску одну.'),
(2598, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 31, 'OT', 'И сделал засовы из дерева ситтим, пять для досок одной стороны скинии.'),
(2599, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 32, 'OT', 'и пять засовов для досок боковой стороны скинии второго, и пять засовов для досок скинии к окраинам к западу.'),
(2600, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 33, 'OT', 'И сделал он средний засов, чтобы проходить посреди досок, от края до края.'),
(2601, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 34, 'OT', 'Доски же он обложил золотом, и кольца их сделал золотыми, домами для засовов, и засовы обложил золотом.'),
(2602, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 35, 'OT', 'И сделал завесу из голубой, и багряницы, и червлёного багрянца, и кручёного виссона; делом искусным сделал её с херувимами.'),
(2603, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 36, 'OT', 'И сделал для неё четыре столба из ситтима, и покрыл их золотом, и крюки их — золото, и вылил для них четыре подножия из серебра.'),
(2604, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 37, 'OT', 'И сделал завесу для двери шатра из голубой, и багряницы, и червца, и червлёного, и кручёного виссона, делом узорчатой работы.'),
(2605, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 36, 38, 'OT', 'И столбы его пять, и крюки их, и покрытие глав их и связи (перекладины) их — золото, а подножия их пять — медь.'),
(2606, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 1, 'OT', 'Сделал Веселеил ковчег из дерева ситтим: два локтя с половиной долгота его, и локоть с половиной ширина его, и локоть с половиной рост его.'),
(2607, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 2, 'OT', 'И покрыл его чистым золотом изнутри и снаружи, и сделал ему венец из золота вокруг.'),
(2608, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 3, 'OT', 'И вылил для него четыре перстня из золота на четыре ножки его, и два перстня на один бок его, и два перстня на второй бок его.'),
(2609, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 4, 'OT', 'И сделал шесты из дерева ситтим, и покрыл их золотом.'),
(2610, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 5, 'OT', 'И вложил шесты в перстни на боках ковчега, чтобы носить ковчег.'),
(2611, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 6, 'OT', 'Сделал крышку из чистого золота: в два локтя с половиной долгота её, и в локоть с половиной ширина её.'),
(2612, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 7, 'OT', 'И сделал двух херувимов из золота; чеканной работой сделал их из двух краёв крышки.'),
(2613, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 8, 'OT', 'Одного херувима с одного края, и одного херувима с другого края; из крышки сделал он херувимов из двух частей её, с краёв её.'),
(2614, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 9, 'OT', 'И были херувимы, распростёршие крылья вверх, покрывающие своими крыльями над крышкой (очистилищем), и лица их — человек к брату своему; к крышке (очистилищу) были лица херувимов.'),
(2615, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 10, 'OT', 'И сделал стол из дерева ситтим: два локтя долгота его, и локоть ширина его, и локоть с половиною рост его.'),
(2616, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 11, 'OT', 'И покрыл его чистым золотом и сделал вокруг него венец из золота вокруг.'),
(2617, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 12, 'OT', 'И сделал он для него обод в пядь вокруг, и сделал венец из золота для обода его вокруг.'),
(2618, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 13, 'OT', 'И вылил для него четыре кольца из золота, и положил кольца на четыре края, которые у четырёх ног его.'),
(2619, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 14, 'OT', 'Против ограды были перстни, домами для шестов, чтобы носить стол.'),
(2620, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 15, 'OT', 'И сделал он шесты из дерева ситтим и покрыл их золотом, чтобы носить стол.'),
(2621, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 16, 'OT', 'И сделал сосуды, которые на столе: блюда его, и ложки его, и чаши его, и чаши для возлияния, которыми возливают; из чистого золота.'),
(2622, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 17, 'OT', 'И сделал он светильник из чистого золота; чеканной работой сделал светильник, основание его и стебель его, чаши его, набалдашники его и цветы его из него были.'),
(2623, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 18, 'OT', 'И шесть стержней выходили из сторон её: три стержня светильника из стороны одной, и три стержня светильника из стороны второй.'),
(2624, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 19, 'OT', 'Три чашечки, подобные миндалю, на одном стебле, набалдашник и цветок, и три чашечки, подобные миндалю, на другом стебле, набалдашник и цветок; так для шести стеблей, выходящих из светильника.'),
(2625, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 20, 'OT', 'И на светильнике четыре чаши, сделанные наподобие миндального цвета, с набалдашниками их и цветками их.'),
(2626, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 21, 'OT', 'И набалдашник под двумя стержнями из неё, и набалдашник под двумя стержнями из неё, и набалдашник под двумя стержнями из неё, для шести стержней, выходящих из неё.'),
(2627, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 22, 'OT', 'Набалдашники их и стержни их были из него; всё это — чеканная работа из чистого золота.'),
(2628, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 23, 'OT', 'И сделал светильники её, семь, и щипцы её, и кадильницы её из чистого золота.'),
(2629, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 24, 'OT', 'Талант чистого золота сделал её и все сосуды её.'),
(2630, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 25, 'OT', 'И сделал жертвенник для фимиама из дерева ситтим: локоть долгота его, и локоть ширина его, четырёхугольный, и два локтя рост его; из него были рога его.'),
(2631, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 26, 'OT', 'И покрыл его чистым золотом — кровлю его и стены его кругом, и роги его; и сделал ему венец золотой вокруг.'),
(2632, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 27, 'OT', 'И сделал он для него два перстня из золота, под венцом его, на двух боковых сторонах его, на двух сторонах его, как дома для шестов, чтобы носить его ими.'),
(2633, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 28, 'OT', 'И сделал он шесты из дерева ситтим и покрыл их золотом.'),
(2634, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 37, 29, 'OT', 'И сделал он елей помазания, святыню, и фимиам из ароматов, чистый, дело благовонного состава.'),
(2635, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 1, 'OT', 'И сделал жертвенник всесожжения из дерева ситтим: пять локтей долгота его, и пять локтей ширина его, четырёхугольный, и три локтя рост его.'),
(2636, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 2, 'OT', 'И сделал рога его на четырёх углах его; из него самого были рога его, и обложил его медью.'),
(2637, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 3, 'OT', 'И сделал все сосуды жертвенника: котлы и лопаты, и чаши, и вилки, и кадильницы; все сосуды его сделал из меди.'),
(2638, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 4, 'OT', 'И сделал для жертвенника решётку, дело сети из меди, под выступом его снизу до половины его.'),
(2639, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 5, 'OT', 'И отлил четыре перстня на четырёх частях медной решётки, как дома для шестов.'),
(2640, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 6, 'OT', 'И сделал он шесты из дерева ситтим, и обложил их медью.'),
(2641, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 7, 'OT', 'И вложил шесты в кольца на боковых сторонах жертвенника, чтобы носить его на них; полым из досок сделал его.'),
(2642, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 8, 'OT', 'И сделал умывальник из меди и основание его из меди, из видений воинов, которые стояли у двери шатра собрания.'),
(2643, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 9, 'OT', 'И сделал он двор: на стороне юга, к югу, завесы двора из кручёного виссона, в сто локтей.'),
(2644, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 10, 'OT', 'Столбов их двадцать, и подножий их двадцать из меди, крюки столбов и перекладины их из серебра.'),
(2645, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 11, 'OT', 'И к краю севера — сто локтей; столбы их двадцать, и подножия их двадцать из меди; крюки столбов и перекладины их из серебра.'),
(2646, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 12, 'OT', 'И к краю западной стороны — завесы в пятьдесят локтей, столбы их — десять, и подножия их — десять; крюки столбов и связи их — серебро.'),
(2647, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 13, 'OT', 'А к краю востока, к востоку, пятьдесят локтей.'),
(2648, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 14, 'OT', 'Завесы в пятнадцать локтей к стороне, столбов их три, и подножий их три.'),
(2649, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 15, 'OT', 'А для второй стороны, с той и с другой стороны ворот двора, завесы в пятнадцать локтей, столбов у них три, и подножий у них три.'),
(2650, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 16, 'OT', 'Все завесы двора кругом — из кручёного льна.'),
(2651, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 17, 'OT', 'Подножия для столбов — из меди, крюки столбов и обручи их — из серебра, и покрытие глав их — из серебра, и они были связаны серебром, все столбы двора.'),
(2652, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 18, 'OT', 'И завеса ворот двора — дело узорчатой работы, из голубой и багряницы, и червца, и червлёного, и кручёного виссона; двадцать локтей долгота, и рост в ширину пять локтей, против завес двора.'),
(2653, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 19, 'OT', 'И столбов их четыре, и подножий их четыре из меди, крюки их из серебра, и покрытие глав их и перекладины их из серебра.'),
(2654, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 20, 'OT', 'И все колья для скинии и для двора вокруг — медь.'),
(2655, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 21, 'OT', 'Вот исчисление скинии, скинии свидетельства, которое было исчислено по повелению Моисея, служение левитов, рукою Ифамара, сына Аарона, священника.'),
(2656, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 22, 'OT', 'Веселеил, сын Урия, сына Хура, из колена Иуды, сделал всё, что повелел Господь Моисею.'),
(2657, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 23, 'OT', 'И с ним Аголиав, сын Ахисамаха, из колена Дана, ремесленник и искусный мастер, и вышивальщик по голубой, и по багрянице, и по червлёному (багряному) цвету, и по виссону.'),
(2658, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 24, 'OT', 'Всё золото, употреблённое на работу, во всякой работе святыни, и было золото потрясания двадцать девять талантов и семьсот тридцать сиклей, сиклями святыни.'),
(2659, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 25, 'OT', 'Серебро исчисленных из общества — сто талантов и тысяча семьсот семьдесят пять сиклей, сиклями святыни.'),
(2660, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 26, 'OT', 'Полсикля с головы, половина сикля по сиклю святыни, за всех проходящих по переписи, от сына двадцати лет и выше, за шестьсот три тысячи пятьсот пятьдесят.'),
(2661, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 27, 'OT', 'И было сто талантов серебра на отливку подножий святыни и подножий завесы: сто подножий из ста талантов, по таланту на подножие.'),
(2662, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 28, 'OT', 'И из тысячи семисот семидесяти пяти сделал крюки для столбов, и покрыл главы их, и связал их.'),
(2663, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 29, 'OT', 'И медь потрясания — семьдесят талантов и две тысячи четыреста сиклей.'),
(2664, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 30, 'OT', 'И сделал из неё подножия для двери шатра собрания, и медный жертвенник, и медную решётку, которая у него, и все сосуды жертвенника.'),
(2665, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 38, 31, 'OT', 'и подножия двора кругом, и подножия ворот двора, и все колья скинии, и все колья двора кругом.'),
(2666, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 1, 'OT', 'Из голубой и багряницы и червлёного багрянца сделали одежды служения для служения в святыне, и сделали одежды святыни, которые для Аарона, как повелел Господь Моисею.'),
(2667, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 2, 'OT', 'Он сделал ефод из золота, голубой и багряницы, и червлёного, и кручёного виссона.'),
(2668, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 3, 'OT', 'И раскатали западни золота и нарезали шнуры, чтобы вделать в середину голубого, и в середину багряницы, и в середину червлёного, и в середину виссона, делом искусным.'),
(2669, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 4, 'OT', 'Сделали у него плечи соединённые; на двух частях его он был соединён по краям.'),
(2670, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 5, 'OT', 'Пояс ефода его, который на нём, из него самого, по работе его: золото, голубой, багряница и червлёного цвета багрянец, и кручёный виссон, как повелел Господь Моисею.'),
(2671, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 6, 'OT', 'И сделали камни оникса, вставленные в гнёзда из золота, с резьбою, как на печати, по именам сынов Израилевых.'),
(2672, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 7, 'OT', 'И положил их на плечи ефода, камни памяти для сынов Израиля, как повелел Господь Моисею.'),
(2673, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 8, 'OT', 'И сделал наперсник делом искусным, как дело ефода: из золота, голубой, и багряницы, и червца, и багрянца, и кручёного виссона.'),
(2674, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 9, 'OT', 'Был он четвероугольный; двойным сделали наперсник: пядь долгота его, и пядь ширина его, двойной.'),
(2675, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 10, 'OT', 'И наполнили его четырьмя рядами камней: ряд сардис, топаз и карбункул — ряд первый.'),
(2676, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 11, 'OT', 'И второй ряд: изумруд, сапфир и алмаз.'),
(2677, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 12, 'OT', 'И третий ряд: лигур, агат и амистис.'),
(2678, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 13, 'OT', 'Четвёртый ряд — берилл, оникс и яспис, вставленные в гнёзда из золота в их оправах.'),
(2679, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 14, 'OT', 'И камни эти — по именам сынов Израилевых, их двенадцать, по именам их; резьба печати, каждый по своему имени, для двенадцати колен.'),
(2680, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 15, 'OT', 'И сделали на наперснике цепи витые, работа из верви, из золота чистого, витые.'),
(2681, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 16, 'OT', 'Сделали два гнезда из золота и два перстня из золота, и прикрепили два перстня к двум краям наперсника.'),
(2682, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 17, 'OT', 'И вложили две верви золота в два перстня на краях наперсника.'),
(2683, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 18, 'OT', 'И два края двух вервей они положили на два гнезда и прикрепили их на плечи ефода, к лицу его.'),
(2684, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 19, 'OT', 'Сделали два перстня из золота и положили их на два края наперсника, на край его, который к стороне ефода, внутрь.'),
(2685, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 20, 'OT', 'И сделали два перстня из золота и положили их на два плеча ефода, снизу, против лица его, против связи его, выше пояса ефода.'),
(2686, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 21, 'OT', 'И скрепили наперсник с его перстней к перстням ефода шнуром из голубого, чтобы он был на поясе ефода, и не отходил наперсник от ефода, как повелел Господь Моисею.'),
(2687, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 22, 'OT', 'И сделал верхнюю одежду для ефода, работу ткача, всю из голубого.'),
(2688, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 23, 'OT', 'И уста верхней одежды в середине её, как ворот у кольчуги; край к устам её вокруг, чтобы не разрывалась.'),
(2689, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 24, 'OT', 'И сделали на краю верхней одежды гранаты из голубого, и багряницы, и червца багряного, кручёного.'),
(2690, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 25, 'OT', 'И сделали колокольчики из чистого золота, и поместили колокольчики в середине гранатов по краю верхней одежды кругом, в середине гранатов.'),
(2691, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 26, 'OT', 'колокольчик и гранат, колокольчик и гранат по краю верхней одежды кругом, для служения, как повелел Господь Моисею.'),
(2692, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 27, 'OT', 'И сделали хитоны из виссона, работа ткача, для Аарона и для сыновей его.'),
(2693, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 28, 'OT', 'И митру из виссона, и украшения повязок из виссона, и льняные штаны из кручёного виссона.'),
(2694, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 29, 'OT', 'И пояс из кручёного виссона, и голубой, и багряница, и червлёного цвета багрянец, работа узорчатой работы, как повелел Господь Моисею.'),
(2695, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 30, 'OT', 'И сделали пластину венца святыни из чистого золота, и написали на нём писание резьбы печати: святыня Господу.'),
(2696, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 31, 'OT', 'И возложили на него шнур голубой, чтобы возложить на митру сверху, как повелел Господь Моисею.'),
(2697, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 32, 'OT', 'И завершилось всё служение скинии шатра собрания, и сделали сыны Израиля всё, что повелел Господь Моисею, так и сделали.'),
(2698, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 33, 'OT', 'И принесли скинию к Моисею: шатёр и все сосуды его, крючки его, доски его, засовы его, столбы его и подножия его.'),
(2699, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 34, 'OT', 'и покрывало из кож овнов красных, и покрывало из кож тахаша, и завесу завесы.'),
(2700, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 35, 'OT', 'ковчег свидетельства и шесты его отдельно, и крышку'),
(2701, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 36, 'OT', 'стол, все сосуды его, и хлебы предложения'),
(2702, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 37, 'OT', 'светильник чистый, светильники его, светильники ряда, и все сосуды его, и елей светила'),
(2703, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 38, 'OT', 'И жертвенник золотой, и елей помазания, и фимиам ароматов, и завесу двери шатра.'),
(2704, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 39, 'OT', 'жертвенник из меди и решётку из меди, которая у него, шесты его и все его сосуды, умывальник и основание его'),
(2705, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 40, 'OT', 'завесы двора, столбы её и подножия её, и завесу для ворот двора, верви её и колья её, и все сосуды служения скинии для шатра собрания'),
(2706, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 41, 'OT', 'Одежды служения для служения в святыне, одежды святыни для Аарона священника, и одежды сыновей его для священнодействия.'),
(2707, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 42, 'OT', 'Как всё, что Господь заповедал Моисею, так и сделали сыны Израиля всё служение.'),
(2708, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 39, 43, 'OT', 'И увидел Моисей всю работу, и вот, они сделали её так, как повелел Господь, — так они сделали; и благословил их Моисей.'),
(2709, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 1, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2710, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 2, 'OT', 'В день первого месяца, в первый день месяца, поставь скинию шатра собрания.'),
(2711, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 3, 'OT', 'И поставь там ковчег свидетельства, и покрой ковчег завесою.'),
(2712, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 4, 'OT', 'И принеси стол, и устрой его в порядке его, и принеси светильник, и зажги светильники его.'),
(2713, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 5, 'OT', 'И поставь жертвенник золотой для фимиама перед лицом ковчега свидетельства, и повесь завесу двери у скинии.'),
(2714, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 6, 'OT', 'И поставь жертвенник всесожжения перед лицом двери скинии шатра собрания.'),
(2715, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 7, 'OT', 'И поставь умывальник между шатром собрания и жертвенником, и налей туда воды.'),
(2716, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 8, 'OT', 'И поставь двор кругом, и повесь завесу у ворот двора.'),
(2717, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 9, 'OT', 'И возьми елей помазания, и помажь скинию и всё, что в ней, и освяти её и все сосуды её, и будет она святынею.'),
(2718, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 10, 'OT', 'И помажешь жертвенник всесожжения и все сосуды его, и освятишь жертвенник, и будет жертвенник святынею святынь.'),
(2719, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 11, 'OT', 'И помажешь умывальник и основание его, и освятишь его.'),
(2720, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 12, 'OT', 'И приведи Аарона и сыновей его ко входу в шатёр собрания, и омой их водою.'),
(2721, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 13, 'OT', 'И облачишь Аарона в одежды святыни, и помажешь его, и освятишь его, и будет он священнодействовать Мне.'),
(2722, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 14, 'OT', 'И сыновей его приведи, и одень их в хитоны.'),
(2723, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 15, 'OT', 'И помажь их, как помазал отца их, и будут они священниками Мне; и будет это им помазанием в священство вечное в роды их.'),
(2724, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 16, 'OT', 'И сделал Моисей всё, как повелел ему Господь, так и сделал.'),
(2725, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 17, 'OT', 'И было в первом месяце второго года, в первый день месяца, поставлена скиния.'),
(2726, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 18, 'OT', 'Моисей поставил скинию, и положил её подножия, и поставил её доски, и вложил её засовы, и поставил её столбы.'),
(2727, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 19, 'OT', 'И распростёр шатёр над скинией, и положил покрывало шатра на него сверху, как повелел Господь Моисею.'),
(2728, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 20, 'OT', 'И взял он и положил свидетельство в ковчег, и поставил шесты на ковчег, и положил крышку на ковчег сверху.'),
(2729, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 21, 'OT', 'И принёс ковчег в скинию, и повесил завесу, и закрыл ею ковчег свидетельства, как повелел Господь Моисею.'),
(2730, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 22, 'OT', 'И поставил стол в шатре собрания, на сторону скинии к северу, вне завесы.'),
(2731, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 23, 'OT', 'И разложил на нём ряд хлеба пред лицом Господа, как повелел Господь Моисею.'),
(2732, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 24, 'OT', 'И поставил светильник в шатре собрания, напротив стола, на стороне скинии к югу.'),
(2733, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 25, 'OT', 'И зажёг светильники пред лицом Господа, как повелел Господь Моисею.'),
(2734, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 26, 'OT', 'И поставил жертвенник золотой в шатре собрания, пред лицом завесы.'),
(2735, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 27, 'OT', 'И воскурил на нем фимиам из ароматов, как повелел Господь Моисею.'),
(2736, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 28, 'OT', 'И поставил завесу двери для скинии.'),
(2737, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 29, 'OT', 'И жертвенник всесожжения поставил у двери скинии шатра собрания, и вознёс на нём всесожжение и хлебное приношение, как повелел Господь Моисею.'),
(2738, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 30, 'OT', 'И поставил умывальник между шатром собрания и жертвенником, и налил туда воды для омовения.'),
(2739, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 31, 'OT', 'И омывали из него Моисей и Аарон и сыновья его руки свои и ноги свои.'),
(2740, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 32, 'OT', 'Когда они входили в шатёр собрания и приближались к жертвеннику, они омывались, как повелел Господь Моисею.'),
(2741, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 33, 'OT', 'И поставил двор вокруг скинии и жертвенника, и дал завесу ворот двора, и окончил Моисей работу.'),
(2742, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 34, 'OT', 'И покрыло облако шатёр собрания, и слава Господа наполнила скинию.'),
(2743, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 35, 'OT', 'И не мог Моисей войти в шатёр собрания, потому что облако осенило его, и слава Господа наполнила скинию.'),
(2744, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 36, 'OT', 'И когда поднималось облако над скинией, отправлялись сыны Израиля во все путешествия свои.'),
(2745, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 37, 'OT', 'А если не поднималось облако, то не отправлялись в путь до дня, когда оно поднималось.'),
(2746, 2, 'GOI_Ru', 'GOI_Ru', 'ru', 'EXO', 40, 38, 'OT', 'Облако Господне было над скинией днём, и огонь был ночью в ней, пред очами всего дома Израилева во всех путешествиях их.'),
(2747, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 1, 'OT', 'И воззвал Он к Моисею, и говорил Господь к нему из шатра собрания, говоря:'),
(2748, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 2, 'OT', 'Скажи сынам Израиля и скажи им: человек, если принесёт из вас приношение Господу, из скота, из крупного рогатого скота и из овец, приносите ваше приношение.'),
(2749, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 3, 'OT', 'Если всесожжение — приношение его из крупного рогатого скота, пусть принесёт его самца без порока; к двери шатра собрания принесёт его, чтобы он был принят пред лицом Господа.'),
(2750, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 4, 'OT', 'И возложит руку свою на главу всесожжения, и будет принято ему для очищения его.'),
(2751, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 5, 'OT', 'И заколет сына крупного рогатого скота пред лицом Господа, и принесут сыны Аарона, священники, кровь, и покропят кровью на жертвенник со всех сторон, который у двери шатра собрания.'),
(2752, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 6, 'OT', 'И снимет кожу с всесожжения, и рассечёт его на куски его.'),
(2753, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 7, 'OT', 'Сыновья Аарона, священника, положат огонь на жертвенник и разложат дерево на огне.'),
(2754, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 8, 'OT', 'И разложат сыны Аарона, священники, куски, главу и тук на дровах, которые на огне, который на жертвеннике.'),
(2755, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 9, 'OT', 'И внутренность его и голени его он омоет в воде, и священник сожжёт всё на жертвеннике: всесожжение, жертва, запах приятного благоухания Господу.'),
(2756, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 10, 'OT', 'А если из овец приношение его, из ягнят или из коз, во всесожжение, самца без порока принесёт его.'),
(2757, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 11, 'OT', 'И заколет его на боку жертвенника, к северу, пред лицом Господа, и покропят сыны Аарона, священники, кровью его на жертвенник со всех сторон.'),
(2758, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 12, 'OT', 'И разрежет его на куски его, и голову его, и тук его; и разложит священник их на дровах, которые на огне, который на жертвеннике.'),
(2759, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 13, 'OT', 'Внутренность и голени он омоет водою, и принесёт священник всё и сожжёт на жертвеннике: это всесожжение, жертва, запах приятного благоухания Господу.'),
(2760, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 14, 'OT', 'Если же из птиц всесожжение — приношение его Господу, то пусть принесёт он из горлиц или из сынов голубя приношение своё.'),
(2761, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 15, 'OT', 'И принесёт его священник к жертвеннику, и отсечёт голову его, и воскурит на жертвеннике, и выцедит кровь его на стену жертвенника.'),
(2762, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 16, 'OT', 'И удалит зоб её с пером её, и бросит его у жертвенника к востоку, на место пепла.'),
(2763, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 1, 17, 'OT', 'И разорвёт её за крылья, не отделяя, и сожжёт её священник на жертвеннике, на дровах, которые на огне; это всесожжение, жертва, запах приятного благоухания Господу.'),
(2764, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 1, 'OT', 'И если душа приносит приношение хлебное Господу, то приношение его будет мука, и он возольёт на неё елей, и положит на неё ладан.'),
(2765, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 2, 'OT', 'И принесёт её к сынам Аарона, священникам, и возьмёт оттуда полную горсть свою из муки её и из елея её, со всем ладаном её, и сожжёт священник памятную часть её на жертвеннике: жертва, запах приятного благоухания Господу.'),
(2766, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 3, 'OT', 'Оставшееся от хлебного приношения — Аарону и сыновьям его: святыня из святынь из жертв Господа.'),
(2767, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 4, 'OT', 'И если приносишь приношение хлебного приношения печёного в печи, то мука, лепёшки опресноки, смешанные с елеем, и лепёшки опресноки, помазанные елеем.'),
(2768, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 5, 'OT', 'Если же приношение твоё — хлебное приношение на сковороде, то да будет это мука, смешанная с елеем, опреснок.'),
(2769, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 6, 'OT', 'Разломи её на куски и возлей на неё елей; это хлебное приношение.'),
(2770, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 7, 'OT', 'Если же хлебное приношение твоё — приношение на сковороде, то из муки на елее пусть будет сделано.'),
(2771, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 8, 'OT', 'И принесёшь хлебное приношение, которое будет сделано из этого, Господу, и представит его священнику, и поднесёт его к жертвеннику.'),
(2772, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 9, 'OT', 'И поднимет священник из хлебного приношения памятную часть его и сожжёт на жертвеннике: жертва, запах приятного благоухания Господу.'),
(2773, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 10, 'OT', 'Оставшееся от приношения — Аарону и сынам его; это святыня из святынь из жертв Господа.'),
(2774, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 11, 'OT', 'Всё приношение, которое вы приносите Господу, не должно быть сделано квасным; ибо всякую закваску и всякий мёд не приносите из него в жертву Господу.'),
(2775, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 12, 'OT', 'Приношение первинок приносите их Господу, а на жертвенник они не должны восходить для запаха приятного благоухания.'),
(2776, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 13, 'OT', 'И всякое приношение хлебного приношения твоего солью соли, и не прекращай соли завета Бога твоего над хлебным приношением твоим; над всяким приношением твоим приноси соль.'),
(2777, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 14, 'OT', 'Если приносишь приношение первых плодов Господу, колосья, высушенные на огне, толчёное зерно из колосьев, приноси приношение первых плодов твоих.'),
(2778, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 15, 'OT', 'И возложишь на неё елей и положишь на неё ладан: это приношение.'),
(2779, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 2, 16, 'OT', 'И воскурит священник памятную часть её из толчёного зерна её и из елея её со всем ладаном её: жертва Господу.'),
(2780, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 1, 'OT', 'И если жертва мирная — приношение его, если из крупного рогатого скота он приносит, то самца или самку, без порока принесёт её пред лицом Господа.'),
(2781, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 2, 'OT', 'И возложит руку свою на главу приношения своего, и заколет его у двери шатра собрания, и окропят сыны Аарона, священники, кровью жертвенник со всех сторон.'),
(2782, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 3, 'OT', 'И принесёт из жертвы мирной жертвы огненную жертву Господу: тук, покрывающий внутренности, и весь тук, который на внутренностях.'),
(2783, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 4, 'OT', 'и обе почки и тук, который на них, который на бёдрах, и перепонку на печени, с почками он снимет.'),
(2784, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 5, 'OT', 'И возложат его сыны Аарона на жертвенник, на всесожжение, которое на дровах, которые на огне; это жертва, запах приятного благоухания Господу.'),
(2785, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 6, 'OT', 'Если же из овец приношение его для жертвы мирной Господу, самец или самка, без порока принесёт его.'),
(2786, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 7, 'OT', 'Если ягнёнок — его приношение, то он принесёт его пред лицо Господа.'),
(2787, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 8, 'OT', 'И возложит руку свою на главу приношения своего, и заколет его пред лицом шатра собрания, и окропят сыны Аарона кровью его на жертвенник вокруг.'),
(2788, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 9, 'OT', 'И принесёт из жертвы мирной жертвы огненную жертву Господу: тук её, курдюк целиком, против хребта снимет его, и тук, покрывающий внутренность, и весь тук, который на внутренности.'),
(2789, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 10, 'OT', 'и обе почки и тук, который на них, который на бёдрах, и перепонку на печени, с почками он снимет.'),
(2790, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 11, 'OT', 'И принесёт его священник на жертвенник, хлеб жертвы Господу.'),
(2791, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 12, 'OT', 'Если же приношение его — коза, то пусть принесёт её пред лицо Господа.'),
(2792, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 13, 'OT', 'И возложит руку свою на главу его, и заколет его пред лицом шатра собрания, и окропят сыны Аарона кровью его жертвенник со всех сторон вокруг.'),
(2793, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 14, 'OT', 'И принесёт из него приношение своё, жертву Господу: тук, покрывающий внутренность, и весь тук, который на внутренности.'),
(2794, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 15, 'OT', 'и обе почки и тук, который на них, который на бёдрах, и перепонку на печени, с почками он снимет.'),
(2795, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 16, 'OT', 'И воскурит их священник на жертвеннике: хлеб жертвы, в запах приятного благоухания, всё тук — Господу.'),
(2796, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 3, 17, 'OT', 'Устав вечный для родов ваших во всех жилищах ваших: весь тук и вся кровь не ешьте.'),
(2797, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(2798, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 2, 'OT', 'Скажи сынам Израиля: если душа согрешит по заблуждению из всех заповедей Господа, которых не должно делать, и сделает одну из них,'),
(2799, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 3, 'OT', 'Если священник помазанник согрешит к вине народа, то пусть принесёт за грех свой, которым согрешил, тельца сына крупного рогатого скота без порока Господу в жертву за грех.'),
(2800, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 4, 'OT', 'И приведёт тельца к двери шатра собрания пред лицо Господа, и возложит руку свою на главу тельца, и заколет тельца пред лицом Господа.'),
(2801, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 5, 'OT', 'И возьмёт священник помазанник из крови тельца и принесёт её к шатру собрания.'),
(2802, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 6, 'OT', 'И окунёт священник перст свой в кровь, и покропит от крови семь раз пред лицом Господа, пред лицом завесы святилища.'),
(2803, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 7, 'OT', 'И возложит священник из крови на роги жертвенника фимиама ароматов пред лицом Господа, который в шатре собрания, и всю кровь тельца выльет к основанию жертвенника всесожжения, который у двери шатра собрания.'),
(2804, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 8, 'OT', 'И весь тук тельца жертвы за грех он снимет с него: тук, покрывающий внутренности, и весь тук, который на внутренностях.'),
(2805, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 9, 'OT', 'И обе почки, и тук, который на них, который на бёдрах, и перепонку на печени, с почками он снимет.'),
(2806, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 10, 'OT', 'как снимается с вола жертвы мирной, и воскурит их священник на жертвеннике всесожжения.'),
(2807, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 11, 'OT', 'И кожу тельца, и всю плоть его с главою его и с голенями его, и внутренность его и навоз его'),
(2808, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 12, 'OT', 'И выведет всего тельца вне стана на чистое место, на излияние пепла, и сожжёт его на дереве в огне; на излиянии пепла он будет сожжён.'),
(2809, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 13, 'OT', 'И если всё общество Израиля согрешит по ошибке, и будет скрыто слово от очей собрания, и сделают они одну из всех заповедей Господа, которые не должны быть делаемы, и будут виновны,'),
(2810, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 14, 'OT', 'И когда станет известен грех, которым они согрешили, пусть собрание принесёт тельца, сына крупного рогатого скота, в жертву за грех, и приведут его пред лицо шатра собрания.'),
(2811, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 15, 'OT', 'И возложат старейшины общества руки свои на главу тельца пред лицом Господа, и заколет тельца пред лицом Господа.'),
(2812, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 16, 'OT', 'И принесёт священник помазанник из крови тельца к шатру собрания.'),
(2813, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 17, 'OT', 'И окунёт священник перст свой в кровь, и покропит семь раз пред лицом Господа пред лицом завесы.'),
(2814, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 18, 'OT', 'и из крови возложит на роги жертвенника, который пред лицом Господа, в шатре собрания, и всю кровь выльет к основанию жертвенника всесожжения, который у двери шатра собрания.'),
(2815, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 19, 'OT', 'И весь тук его отделит от него и сожжёт на жертвеннике.'),
(2816, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 20, 'OT', 'И сделает с тельцом так, как сделал с тельцом жертвы за грех; так сделает с ним, и очистит их священник, и прощено будет им.'),
(2817, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 21, 'OT', 'И выведет тельца за стан, вне стана, и сожжёт его, как сжёг первого тельца; это жертва за грех собрания.'),
(2818, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 22, 'OT', 'Когда князь согрешит и сделает что-то из всех заповедей Господа, Бога своего, чего не должно делать, по заблуждению, и будет виновен,'),
(2819, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 23, 'OT', 'Или если открыт ему грех его, которым он согрешил, то пусть принесёт приношение своё: козла из коз, самца без порока.'),
(2820, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 24, 'OT', 'И возложит руку свою на главу козла, и заколет его на месте, где закалывают всесожжение, пред лицом Господа; это жертва за грех.'),
(2821, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 25, 'OT', 'И возьмёт священник из крови жертвы за грех перстом своим и возложит на рога жертвенника всесожжения, а кровь его выльет к основанию жертвенника всесожжения.'),
(2822, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 26, 'OT', 'И весь тук его он воскурит на жертвеннике, как тук жертвы мирной; и очистит его священник от греха его, и прощено будет ему.'),
(2823, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 27, 'OT', 'И если душа какая согрешит по заблуждению из народа земли, совершив одну из заповедей Господа, которых не должно делать, и будет виновна,'),
(2824, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 28, 'OT', 'Или если станет известен ему грех его, которым он согрешил, то пусть принесёт приношение своё — козлёнка из коз, женщину без порока, за грех его, которым он согрешил.'),
(2825, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 29, 'OT', 'И возложит руку свою на главу жертвы за грех, и заколет жертву за грех на месте всесожжения.'),
(2826, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 30, 'OT', 'И возьмёт священник от крови её перстом своим и возложит на рога жертвенника всесожжения, а всю кровь её выльет к основанию жертвенника.'),
(2827, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 31, 'OT', 'И весь тук её снимет, как снимается тук с мирной жертвы, и сожжёт его священник на жертвеннике в приятное благоухание Господу; и очистит его священник, и прощено будет ему.'),
(2828, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 32, 'OT', 'Если же ягнёнок приносит приношение своё в жертву за грех, женщину непорочную пусть принесёт её.'),
(2829, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 33, 'OT', 'И возложит руку свою на главу жертвы за грех, и заколет её как жертву за грех на месте, где закалывают всесожжение.'),
(2830, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 34, 'OT', 'И возьмёт священник из крови жертвы за грех перстом своим и возложит на рога жертвенника всесожжения, а всю кровь её выльет к основанию жертвенника.'),
(2831, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 4, 35, 'OT', 'И весь тук её снимет, как снимается тук ягнёнка из жертвы мирной, и сожжёт его священник на жертвеннике в жертву Господу; и очистит его священник за грех его, которым он согрешил, и прощено будет ему.'),
(2832, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 1, 'OT', 'Если же душа согрешит, услышав голос проклятия, и он — свидетель, или видел, или знал, если не объявит, то понесёт своё беззаконие.'),
(2833, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 2, 'OT', 'Или душа, которая коснётся всякого слова нечистого, или мертвечины животного нечистого, или мертвечины скота нечистого, или мертвечины гада нечистого, и скрыто будет от него, и он нечист, и виновен.'),
(2834, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 3, 'OT', 'или если коснётся нечистоты человека, какой бы ни была его нечистота, которою он осквернится, и это будет скрыто от него, а он узнает и виновен будет.'),
(2835, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 4, 'OT', 'Или если душа поклянётся, произнеся устами, чтобы сделать зло или добро, — во всём, что человек произнесёт в клятве, — и это будет скрыто от него, а он узнает и окажется виновным в одном из этих [случаев],'),
(2836, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 5, 'OT', 'И будет, когда он провинится в одном из этих, и исповедуется в том, в чём согрешил.'),
(2837, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 6, 'OT', 'И принесёт жертву повинности свою Господу за грех свой, которым согрешил: женщину из овец, овцу или козлёнка из коз, в жертву за грех; и очистит его священник от греха его.'),
(2838, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 7, 'OT', 'Если же рука его не достаточна для овцы, то пусть принесёт жертву повинности свою, в которой он согрешил, двух горлиц или двух сыновей голубя Господу: одного в жертву за грех, а другого во всесожжение.'),
(2839, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 8, 'OT', 'И принесёт их к священнику, и принесёт то, что за грех, первым, и отсечёт голову его от шеи его, и не отделит.'),
(2840, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 9, 'OT', 'И окропит кровью греха на стену жертвенника, а остаток крови выльет к основанию жертвенника; это жертва за грех.'),
(2841, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 10, 'OT', 'И второго сделает всесожжением по предписанию, и очистит его священник от греха его, которым он согрешил, и прощено будет ему.'),
(2842, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 11, 'OT', 'А если средства его не достанут до двух горлиц или до двух сыновей голубя, то пусть принесёт своё приношение, в котором он согрешил, десятую часть ефы муки в жертву за грех; не возложит на неё елея и не положит на неё ладана, ибо это жертва за грех.'),
(2843, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 12, 'OT', 'И принесёт её к священнику, и возьмёт священник из неё полную горсть свою, памятную часть её, и сожжёт на жертвеннике на жертвах Господа; это жертва за грех.'),
(2844, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 13, 'OT', 'И очистит его священник от греха его, который он совершил в одном из этих случаев, и прощено будет ему; и будет оно священнику, как приношение.'),
(2845, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 14, 'OT', 'И говорил Господь к Моисею, говоря:'),
(2846, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 15, 'OT', 'Если душа совершит преступление и согрешит по заблуждению против святынь Господних, то пусть принесёт свою жертву повинности Господу: овна без порока из овец, по твоей оценке серебром в сиклях, по сиклю святыни, в жертву повинности.'),
(2847, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 16, 'OT', 'И то, что он согрешил против святыни, пусть возместит, и пятую часть его прибавит к нему, и отдаст его священнику; и священник совершит искупление за него овном жертвы повинности, и прощено будет ему.'),
(2848, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 17, 'OT', 'Если же душа согрешит и сделает что-то из всех заповедей Господних, чего не должно делать, и не знал, и виновен, то понесёт беззаконие своё.'),
(2849, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 18, 'OT', 'И принесёт овна без порока из овец по оценке твоей в жертву повинности к священнику, и совершит священник очищение за него за заблуждение его, в котором он заблудился, не зная, и прощено будет ему.'),
(2850, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 5, 19, 'OT', 'Это жертва повинности; он виновен пред Господом.'),
(2851, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(2852, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 2, 'OT', 'Если душа согрешит и совершит преступление против Господа, и отопрётся перед ближним своим в поклаже, или во вкладе, отданном на хранение, или в грабеже, или притеснит ближнего своего,'),
(2853, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 3, 'OT', 'или найдёт пропажу и отопрётся в ней, и поклянётся ложно в чём-нибудь из всего того, что человек делает, чтобы согрешить в этом.'),
(2854, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 4, 'OT', 'И будет, если он согрешит и провинится, то возвратит грабёж, который он ограбил, или притеснение, которое он совершил, или поклажу, которая была ему доверена, или пропажу, которую он нашёл.'),
(2855, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 5, 'OT', 'или из всего того, что он поклялся ложно, — и возвратит то сполна, в полной мере, и пятую часть его прибавит к нему; тому, чьё оно, отдаст он в день вины его.'),
(2856, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 6, 'OT', 'И принесёт жертву повинности свою Господу: овна без порока из овец, по оценке твоей, в жертву повинности, к священнику.'),
(2857, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 7, 'OT', 'И очистит его священник пред лицом Господа, и прощено будет ему за всякую вину, которую он совершил.'),
(2858, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 8, 'OT', 'И сказал Господь Моисею, говоря:'),
(2859, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 9, 'OT', 'Повели Аарону и сыновьям его, говоря: вот закон всесожжения: оно — всесожжение на горении на жертвеннике всю ночь до утра, и огонь жертвенника будет гореть на нём.'),
(2860, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 10, 'OT', 'И наденет священник одежду льняную, и льняные штаны наденет на плоть свою, и поднимет пепел, который огонь съел от всесожжения на жертвеннике, и положит его возле жертвенника.'),
(2861, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 11, 'OT', 'И снимет он одежды свои, и наденет другие одежды, и вынесет пепел за пределы стана, вне, на место чистое.'),
(2862, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 12, 'OT', 'И огонь на жертвеннике пусть горит на нём, не погаснет; и пусть зажигает на нём священник дерево каждое утро, каждое утро, и раскладывает на нём всесожжение, и сжигает на нём тук мирных жертв.'),
(2863, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 13, 'OT', 'Огонь постоянный будет гореть на жертвеннике; не погаснет.'),
(2864, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 14, 'OT', 'И вот закон о приношении: пусть сыны Аарона приносят его пред лицом Господа, к лицу жертвенника.'),
(2865, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 15, 'OT', 'И поднимет из него горстью своей из муки хлебного приношения и из елея его, и весь ладан, который на хлебном приношении, и сожжёт на жертвеннике: запах приятного благоухания, памятная часть его — Господу.'),
(2866, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 16, 'OT', 'Оставшееся от неё пусть едят Аарон и сыновья его; опресноки пусть едят на святом месте, во дворе шатра собрания пусть едят её.'),
(2867, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 17, 'OT', 'Не должно быть испечено квасным; часть её Я дал из жертв Моих; это святыня великая, как жертва за грех и как жертва повинности.'),
(2868, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 18, 'OT', 'Всё мужского пола из сыновей Аарона будет есть её; устав вечный для родов ваших из жертв Господа: всё, что прикоснётся к ним, будет свято.'),
(2869, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 19, 'OT', 'И сказал Господь Моисею, говоря:'),
(2870, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 20, 'OT', 'Это приношение Аарона и сыновей его, которое они приносят Господу в день помазания его: десятая часть ефы муки тонкой как приношение постоянное, половина его утром и половина его вечером.'),
(2871, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 21, 'OT', 'На сковороде с елеем пусть она будет сделана; смешанную принеси её; печёное из кусков приношение принеси, запах приятного благоухания Господу.'),
(2872, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 22, 'OT', 'Священник помазанник вместо него из сыновей его совершит её; устав вечный для Господа: целиком сожжена будет.'),
(2873, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 23, 'OT', 'И всякое приношение священника всё будет сожжено, не будет съедено.'),
(2874, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 24, 'OT', 'И сказал Господь Моисею, говоря:'),
(2875, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 25, 'OT', 'Скажи Аарону и сыновьям его: вот закон жертвы за грех: на месте, где закалывается всесожжение, закалывается жертва за грех пред лицом Господа; это святыня святынь.'),
(2876, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 26, 'OT', 'Священник, который приносит её в жертву за грех, съест её; на святом месте она должна быть съедена, во дворе шатра собрания.'),
(2877, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 27, 'OT', 'Всё, что коснётся плоти её, будет свято; и если кровь её попадёт на одежду, то то, на что она попадёт, вымой на святом месте.'),
(2878, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 28, 'OT', 'Сосуд глиняный, в котором она варилась, должен быть разбит; если же она была сварена в сосуде медном, то он должен быть вычищен и промыт водою.'),
(2879, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 29, 'OT', 'Всё мужского пола у священников будет есть её; святыня святынь она.'),
(2880, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 6, 30, 'OT', 'И всякая жертва за грех, чья кровь вносится в шатёр собрания для искупления во святыне, не должна быть съедена; на огне она будет сожжена.'),
(2881, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 1, 'OT', 'И вот закон о жертве повинности: это великая святыня.'),
(2882, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 2, 'OT', 'На месте, где закалывают всесожжение, закалывают жертву повинности, и кровью её кропят на жертвенник со всех сторон вокруг.'),
(2883, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 3, 'OT', 'И весь тук его принесёт из него: курдюк и тук, покрывающий внутренность.'),
(2884, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 4, 'OT', 'и обе почки и тук, который на них, который на бёдрах, и перепонку на печени, с почками он снимет.'),
(2885, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 5, 'OT', 'И воскурит их священник на жертвеннике, жертва Господу; жертва повинности это.'),
(2886, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 6, 'OT', 'Всё мужского пола из священников будет есть его; на святом месте должно есть его: святыня святынь это.'),
(2887, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 7, 'OT', 'Как жертва за грех, так и жертва повинности: один закон для них; священник, который совершает искупление ею, ему она будет.'),
(2888, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 8, 'OT', 'И священник, приносящий всесожжение человека, — кожа всесожжения, которое он принёс, священнику ему будет.'),
(2889, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 9, 'OT', 'И всякое приношение, которое печётся в печи, и всё, что сделано на сковороде, и на сковороде, — священнику, приносящему его, ему будет.'),
(2890, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 10, 'OT', 'И всякое приношение, смешанное с елеем, и сухое, — всё сыновьям Аарона будет, каждому человеку как брату его.'),
(2891, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 11, 'OT', 'И вот закон о жертве мирной, которую приносят Господу.'),
(2892, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 12, 'OT', 'Если он приносит её как благодарственную жертву, то пусть принесёт при жертве благодарности лепёшки пресные, смешанные с елеем, и лепёшки пресные, помазанные елеем, и муку, замешанную, лепёшки, смешанные с елеем.'),
(2893, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 13, 'OT', 'С лепёшками хлеба квасного пусть приносит он приношение своё, вместе с жертвой благодарности мирной жертвы его.'),
(2894, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 14, 'OT', 'И принесёт из него одно из всякого приношения как приношение Господу; священнику, кропящему кровью мирной жертвы, оно будет принадлежать.'),
(2895, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 15, 'OT', 'Плоть жертвы благодарности мирной жертвы его в день приношения его будет съедена; не оставит от неё до утра.'),
(2896, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 16, 'OT', 'Если же это обет или приношение, жертва его приношения, в день принесения его жертвы она будет съедена, а на следующий день оставшееся от неё будет съедено.'),
(2897, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 17, 'OT', 'А оставшееся от плоти жертвы в третий день в огне будет сожжено.'),
(2898, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 18, 'OT', 'Если же будет съедено от плоти жертвы мирной его в третий день, не будет она принята; приносящий её не будет вменено ему, мерзостью будет она, и душа, которая ест от неё, понесёт беззаконие своё.'),
(2899, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 19, 'OT', 'И плоть, которая коснётся чего-либо нечистого, не должна быть съедена; в огне она будет сожжена; а плоть, всякая чистая, может есть плоть.'),
(2900, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 20, 'OT', 'И если какая душа будет есть плоть от мирной жертвы Господней, и на ней будет её нечистота, то истребится та душа из народа своего.'),
(2901, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 21, 'OT', 'И если душа прикоснётся ко всему нечистому, к нечистоте человека, или к скоту нечистому, или ко всякой мерзости нечистой, и поест от плоти жертвы мирной, которая для Господа, то истребится душа та из народа своего.'),
(2902, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 22, 'OT', 'И сказал Господь Моисею, говоря:'),
(2903, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 23, 'OT', 'Скажи сынам Израиля: весь тук вола, ягнёнка и козы не ешьте.'),
(2904, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 24, 'OT', 'Тук мертвечины и тук растерзанного можно употреблять на всякую работу, а есть его не ешьте.'),
(2905, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 25, 'OT', 'Ибо всякий, кто ест тук из скота, который приносит из него жертву Господу, — истребится душа та из народа своего.'),
(2906, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 26, 'OT', 'И всякую кровь не ешьте во всех жилищах ваших, ни от птицы, ни от скота.'),
(2907, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 27, 'OT', 'Всякая душа, которая будет есть всякую кровь, — истребится та душа из народа своего.'),
(2908, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 28, 'OT', 'И сказал Господь Моисею, говоря:'),
(2909, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 29, 'OT', 'Скажи сынам Израиля: приносящий жертву мирную свою Господу пусть принесёт приношение своё Господу из жертвы мирной своей.'),
(2910, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 30, 'OT', 'Руки его должны принести жертву Господу: тук на груди он принесёт, грудь для потрясания пред лицом Господа.'),
(2911, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 31, 'OT', 'И воскурит священник тук на жертвеннике, и будет грудь Аарону и сынам его.'),
(2912, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 32, 'OT', 'И бедро правой руки отдавайте как возношение священнику из жертв мирных ваших.'),
(2913, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 33, 'OT', 'Тот, кто приносит кровь мирной жертвы и тук из сыновей Аарона, — ему будет правое бедро в часть.'),
(2914, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 34, 'OT', 'Ибо грудь потрясания и бедро приношения взял Я от сынов Израиля из жертв мирных их, и дал их Аарону священнику и сынам его уставом вечным от сынов Израиля.'),
(2915, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 35, 'OT', 'Это помазание Аарона и помазание сыновей его из жертв Господа, в день, когда Он привёл их, чтобы священнодействовать Господу.'),
(2916, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 36, 'OT', 'Которую заповедал Господь дать им в день помазания их от сынов Израиля: вечный устав для родов их.'),
(2917, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 37, 'OT', 'Вот закон о всесожжении, о приношении, и о жертве за грех, и о жертве повинности, и о посвящении, и о жертве мирной.'),
(2918, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 7, 38, 'OT', 'Которую заповедал Господь Моисею на горе Синай, в день, когда Он повелел сынам Израиля приносить свои приношения Господу в пустыне Синайской.'),
(2919, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 1, 'OT', 'И сказал Господь к Моисею, говоря:'),
(2920, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 2, 'OT', 'Возьми Аарона и сыновей его с ним, и одежды, и елей помазания, и тельца за грех, и двух овнов, и корзину опресноков.'),
(2921, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 3, 'OT', 'И всё общество собери ко двери шатра собрания.'),
(2922, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 4, 'OT', 'И сделал Моисей, как повелел ему Господь, и собралось общество ко двери шатра собрания.'),
(2923, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 5, 'OT', 'И сказал Моисей обществу: вот слово, которое повелел Господь сделать.'),
(2924, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 6, 'OT', 'И привёл Моисей Аарона и сыновей его, и омыл их водою.'),
(2925, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 7, 'OT', 'И надел на него хитон, и опоясал его поясом, и надел на него верхнюю одежду, и надел на него ефод, и опоясал его поясом ефода, и скрепил им его.'),
(2926, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 8, 'OT', 'И возложил на него наперсник, и вложил в наперсник урим и туммим.'),
(2927, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 9, 'OT', 'И возложил митру на главу его, и возложил на митру, против лица его, пластину из золота, венец святыни, как повелел Господь Моисею.'),
(2928, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 10, 'OT', 'Моисей взял елей помазания и помазал скинию и всё, что в ней, и освятил их.'),
(2929, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 11, 'OT', 'И окропил им жертвенник семь раз, и помазал жертвенник и все сосуды его, и умывальник и основание его, чтобы освятить их.'),
(2930, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 12, 'OT', 'И вылил из елея помазания на главу Аарона, и помазал его, чтобы освятить его.'),
(2931, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 13, 'OT', 'И привёл Моисей сыновей Аарона, и одел их в хитоны, и опоясал их поясами, и повязал им головные повязки, как повелел Господь Моисею.'),
(2932, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 14, 'OT', 'И привёл тельца в жертву за грех, и возложил Аарон и сыновья его руки свои на главу тельца в жертву за грех.'),
(2933, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 15, 'OT', 'И заколол его, и взял Моисей кровь, и возложил на роги жертвенника вокруг перстом своим, и очистил жертвенник, а кровь вылил к основанию жертвенника, и освятил его, чтобы совершить над ним искупление.'),
(2934, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 16, 'OT', 'И взял он весь тук, который на внутренности, и перепонку печени, и обе почки, и тук их, и воскурил Моисей на жертвеннике.'),
(2935, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 17, 'OT', 'И тельца, и кожу его, и плоть его, и навоз его сжёг на огне вне стана, вне стана, как повелел Господь Моисею.'),
(2936, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 18, 'OT', 'И привёл овна всесожжения, и возложили Аарон и сыны его руки свои на главу овна.'),
(2937, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 19, 'OT', 'И заколол, и покропил Моисей кровью на жертвенник со всех сторон вокруг.'),
(2938, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 20, 'OT', 'И расчленил овна на куски его, и воскурил Моисей главу и куски, и тук.'),
(2939, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 21, 'OT', 'И внутренность и голени он омыл водою, и воскурил Моисей всего овна на жертвеннике: это всесожжение, это запах приятного благоухания, жертва Господу, как повелел Господь Моисею.'),
(2940, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 22, 'OT', 'И привёл он овна второго, овна посвящения, и возложили Аарон и сыны его руки свои на главу овна.'),
(2941, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 23, 'OT', 'И заколол, и взял Моисей из крови его, и возложил на мочку правого уха Аарона, и на большой палец правой руки его, и на большой палец правой ноги его.'),
(2942, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 24, 'OT', 'И привёл сыновей Аарона, и дал Моисей из крови на мочку правого уха их, и на большой палец правой руки их, и на большой палец правой ноги их, и окропил Моисей кровью жертвенник со всех сторон вокруг.'),
(2943, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 25, 'OT', 'И взял он тук и курдюк, и весь тук, что на внутренности, и перепонку печени, и обе почки, и тук их, и правое бедро.'),
(2944, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 26, 'OT', 'И из корзины опресноков, которая пред лицом Господа, взял одну лепёшку опресночную и одну лепёшку хлеба с елеем и одну лепёшку, и положил на тук и на бедро правой руки.'),
(2945, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 27, 'OT', 'И положил всё на ладони Аарона и на ладони сыновей его, и потряс это потрясанием пред лицом Господа.'),
(2946, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 28, 'OT', 'Моисей взял их с ладоней их и воскурил на жертвеннике поверх всесожжения; это посвящение в запах приятного благоухания, жертва это Господу.'),
(2947, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 29, 'OT', 'И взял Моисей грудь и потряс её потрясанием пред лицом Господа; из овна посвящения она была частью Моисея, как повелел Господь Моисею.'),
(2948, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 30, 'OT', 'И взял Моисей из елея помазания и из крови, которая на жертвеннике, и покропил на Аарона, на одежды его, и на сынов его, и на одежды сынов его с ним; и освятил Аарона, одежды его, и сынов его, и одежды сынов его с ним.'),
(2949, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 31, 'OT', 'И сказал Моисей Аарону и сынам его: сварите плоть у двери шатра собрания, и там ешьте её и хлеб, который в корзине посвящения, как я повелел, говоря: Аарон и сыны его съедят его.'),
(2950, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 32, 'OT', 'А оставшееся от плоти и от хлеба сожгите в огне.'),
(2951, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 33, 'OT', 'И от двери шатра собрания не выходите семь дней, до дня, когда исполнятся дни вашего посвящения, ибо семь дней будет наполнять Он руки ваши.'),
(2952, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 34, 'OT', 'Как было сделано в этот день, повелел Господь сделать для очищения вас.'),
(2953, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 35, 'OT', 'И у двери шатра собрания сидите днём и ночью семь дней, и соблюдайте стражу Господа, и не умрёте, ибо так мне повелено.'),
(2954, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 8, 36, 'OT', 'И сделал Аарон и сыновья его все слова, которые повелел Господь через Моисея.'),
(2955, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 1, 'OT', 'И было в день восьмой, созвал Моисей Аарона и сыновей его, и старейшин Израиля.'),
(2956, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 2, 'OT', 'И сказал он Аарону: возьми себе телёнка, сына крупного рогатого скота, для жертвы за грех, и овна для всесожжения, без порока, и принеси пред лицо Господа.'),
(2957, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 3, 'OT', 'И к сынам Израиля говори, говоря: возьмите козла из коз для жертвы за грех, и телёнка и ягнёнка, сынов года, непорочных, для всесожжения.'),
(2958, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 4, 'OT', 'И вола и овна в мирную жертву, чтобы принести пред лицом Господа, и приношение, смешанное с елеем, ибо в этот день Господь явится вам.'),
(2959, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 5, 'OT', 'И взяли они то, что повелел Моисей, к лицу шатра собрания, и приблизилось всё общество, и стали пред лицом Господа.'),
(2960, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 6, 'OT', 'И сказал Моисей: вот слово, которое повелел Господь, сделайте; и явится вам слава Господа.'),
(2961, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 7, 'OT', 'И сказал Моисей Аарону: подойди к жертвеннику и соверши жертву за грех твой и всесожжение твоё, и очисти себя и народ, и соверши приношение народа, и очисти их, как повелел Господь.'),
(2962, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 8, 'OT', 'И подошёл Аарон к жертвеннику и заколол телёнка жертвы за грех, который был его.'),
(2963, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 9, 'OT', 'И принесли сыны Аарона кровь к нему, и омочил перст свой в крови, и возложил на рога жертвенника, а кровь вылил к основанию жертвенника.'),
(2964, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 10, 'OT', 'И тук, и почки, и перепонку с печени от жертвы за грех он сжёг на жертвеннике, как повелел Господь Моисею.'),
(2965, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 11, 'OT', 'А плоть и кожу сжёг на огне вне стана.'),
(2966, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 12, 'OT', 'И заколол всесожжение, и подали сыны Аарона ему кровь, и окропил ею жертвенник вокруг.'),
(2967, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 13, 'OT', 'И принесли ему всесожжение по кускам его, и главу, и сжёг на жертвеннике.'),
(2968, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 14, 'OT', 'Он омыл внутренность и голени и воскурил на жертвеннике поверх всесожжения.'),
(2969, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 15, 'OT', 'И принёс приношение народа, и взял козла жертвы за грех, который для народа, и заколол его, и очистил его, как первого.'),
(2970, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 16, 'OT', 'И принёс всесожжение, и совершил его по предписанию.'),
(2971, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 17, 'OT', 'И принёс приношение, и наполнил ладонь свою от него, и воскурил на жертвеннике, кроме утреннего всесожжения.'),
(2972, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 18, 'OT', 'И заколол вола и овна в жертву мирную, которая для народа, и поднесли сыны Аарона кровь к нему, и окропил ею жертвенник со всех сторон вокруг.'),
(2973, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 19, 'OT', 'и тук с вола и с овна, курдюк и покрывало, и почки, и перепонку печени'),
(2974, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 20, 'OT', 'И положили тук на грудь, и сожгли тук на жертвеннике.'),
(2975, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 21, 'OT', 'И грудь и правое бедро Аарон принёс потрясанием пред лицом Господа, как повелел Моисей.'),
(2976, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 22, 'OT', 'И поднял Аарон руку свою к народу и благословил их, и сошёл, совершив жертву за грех, и всесожжение, и мирную жертву.'),
(2977, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 23, 'OT', 'И вошёл Моисей и Аарон в шатёр собрания, и вышли, и благословили народ, и явилась слава Господа всему народу.'),
(2978, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 9, 24, 'OT', 'И вышел огонь от лица Господа и пожрал на жертвеннике всесожжение и тук; и увидел весь народ, и воскликнул, и пал на лицо своё.'),
(2979, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 1, 'OT', 'И взяли сыны Аарона, Надав и Авиуд, каждый свою кадильницу, и положили в них огонь, и возложили на него фимиам, и принесли пред лицо Господа огонь чуждый, которого Он не повелел им.'),
(2980, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 2, 'OT', 'И вышел огонь от лица Господа и пожрал их, и умерли они пред лицом Господа.'),
(2981, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 3, 'OT', 'И сказал Моисей Аарону: это то, что говорил Господь, сказав: в приближающихся ко Мне освящусь, и пред лицом всего народа прославлюсь. И умолк Аарон.'),
(2982, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 4, 'OT', 'И позвал Моисей Мисаила и Елицафана, сыновей Озиила, дяди Аарона, и сказал им: подойдите, вынесите братьев ваших от лица святилища вне стана.'),
(2983, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 5, 'OT', 'И подошли они, и понесли их в хитонах их вне стана, как сказал Моисей.'),
(2984, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 6, 'OT', 'И сказал Моисей Аарону и Елеазару и Ифамару, сыновьям его: голов ваших не обнажайте и одежд ваших не раздирайте, чтобы вам не умереть и чтобы не прогневался он на всё общество; но братья ваши, весь дом Израилев, пусть оплачут сожжение, которое совершил Господь.'),
(2985, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 7, 'OT', 'И из двери шатра собрания не выходите, чтобы не умереть, ибо елей помазания Господня на вас; и сделали по слову Моисея.'),
(2986, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 8, 'OT', 'И сказал Господь Аарону, говоря:'),
(2987, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 9, 'OT', 'Вино и сикер не пей, ты и сыновья твои с тобою, когда входите в шатёр собрания, и не умрёте: устав вечный для родов ваших.'),
(2988, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 10, 'OT', 'И чтобы отличать между святынею и нечистым, и между нечистым и чистым.'),
(2989, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 11, 'OT', 'И учить сынов Израиля всем уставам, которые Господь изрёк им рукою Моисея.'),
(2990, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 12, 'OT', 'И сказал Моисей Аарону и Елеазару и Ифамару, сыновьям его, оставшимся: возьмите приношение, оставшееся от жертв Господа, и ешьте его опресноки у жертвенника, ибо это святыня великая.'),
(2991, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 13, 'OT', 'И ешьте её на святом месте, ибо это устав твой и устав сынов твоих из жертв Господа, ибо так мне повелено.'),
(2992, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 14, 'OT', 'И грудь потрясания и бедро приношения ешьте на месте чистом, ты и сыновья твои и дочери твои с тобою, ибо устав твой и устав сыновей твоих даны из жертв мирных жертв сынов Израиля.'),
(2993, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 15, 'OT', 'Бедро приношения и грудь потрясания вместе с жертвами тука они принесут, чтобы совершить потрясание пред лицом Господа; и будет это тебе и сыновьям твоим с тобою уставом вечным, как повелел Господь.'),
(2994, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 16, 'OT', 'И козла за жертву за грех усердно искал Моисей, и вот, он был сожжён; и разгневался на Елеазара и на Ифамара, сыновей Аарона, оставшихся, говоря:'),
(2995, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 17, 'OT', 'Почему вы не ели жертву за грех на месте святыни? Ибо она — святыня святынь, и Он дал её вам, чтобы нести беззаконие общества, для искупления их пред лицом Господа.'),
(2996, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 18, 'OT', 'Вот, кровь её не внесена в святилище внутрь; ешьте её в святилище, как я повелел.'),
(2997, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 19, 'OT', 'И сказал Аарон Моисею: вот, сегодня принесли они жертву за грех свою и всесожжение своё пред лицом Господа, и постигло меня такое; если бы я ел жертву за грех сегодня, было ли бы это угодно в очах Господа?'),
(2998, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 10, 20, 'OT', 'И услышал Моисей, и было это хорошо в очах его.'),
(2999, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 1, 'OT', 'И сказал Господь Моисею и Аарону, говоря им:'),
(3000, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 2, 'OT', 'Скажите сынам Израиля: вот животное, которое вы можете есть из всего скота, который на земле.'),
(3001, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 3, 'OT', 'Всё, имеющее раздвоенные копыта и расщепление копыт, поднимающее жвачку среди скота, то ешьте.'),
(3002, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 4, 'OT', 'Только этого не ешьте из отрыгивающих жвачку и раздваивающих копыто: верблюда, потому что он отрыгивает жвачку, но копыта не раздваивает, — нечист он для вас.'),
(3003, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 5, 'OT', 'И дамана, потому что он жвачку жуёт, но копыта не раздваивает, — нечист он для вас.'),
(3004, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 6, 'OT', 'И заяц, потому что он жвачку жуёт, но копыто не раздвоил, — нечист он для вас.'),
(3005, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 7, 'OT', 'И свинья, потому что раздваивает копыто, и расщепление копыта у неё есть, но жвачку она не жуёт, — нечиста она для вас.'),
(3006, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 8, 'OT', 'Плоти их не ешьте, и мертвечины их не касайтесь; нечисты они для вас.'),
(3007, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 9, 'OT', 'Это ешьте из всего, что в воде: всё, у чего есть плавники и чешуя, в воде, в морях и в потоках, то ешьте.'),
(3008, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 10, 'OT', 'И всё, у чего нет плавников и чешуи в морях и в потоках, из всего гада водного и из всякого существа живого, которое в воде, — мерзость они для вас.'),
(3009, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 11, 'OT', 'Мерзостью да будут они для вас: плоти их не ешьте, и мертвечину их мерзостью считайте.'),
(3010, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 12, 'OT', 'Всё, что не имеет плавников и чешуи в воде, — мерзость это для вас.'),
(3011, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 13, 'OT', 'И этих из птиц да будете считать мерзостью, не должны они есть: мерзость они — орёл, и скопа, и оспирей.'),
(3012, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 14, 'OT', 'и коршуна, и коршуна по роду её'),
(3013, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 15, 'OT', 'всех воронов по роду их'),
(3014, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 16, 'OT', 'и дочь совы, и ночного ястреба, и кукушку, и ястреба по роду его'),
(3015, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 17, 'OT', 'и чашу, и баклана, и филина'),
(3016, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 18, 'OT', 'и лебедя, и баклана, и стервятника'),
(3017, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 19, 'OT', 'и аиста, цаплю по роду её, и удода, и летучую мышь'),
(3018, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 20, 'OT', 'Всё пресмыкающееся из птиц, ходящее на четырёх, — мерзость оно для вас.'),
(3019, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 21, 'OT', 'Впрочем, вот что вы можете есть из всех гадов птицы, которые ходят на четырёх: у которых есть голени выше ног, чтобы прыгать ими по земле.'),
(3020, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 22, 'OT', 'Из них вы можете есть: саранчу по роду её, и саранчу по роду её, и жука по роду его, и саранчу по роду её.'),
(3021, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 23, 'OT', 'И всякий гад из птиц, у которого четыре ноги, — мерзость он для вас.'),
(3022, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 24, 'OT', 'И от сих вы будете нечисты: всякий, кто прикоснётся к мертвечине их, будет нечист до вечера.'),
(3023, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 25, 'OT', 'И всякий, кто понесёт от их мертвечины, вымоет свою одежду, и будет нечист до вечера.'),
(3024, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 26, 'OT', 'Всё, что из скота имеет раздвоенное копыто, но не расщепляет расщепления, и не поднимает жвачки, — нечисто для вас: всякий, кто прикоснётся к ним, будет нечист.'),
(3025, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 27, 'OT', 'И всё, что ходит на ладонях своих, из всего живого, что ходит на четырёх, — нечисто для вас; всякий, кто прикоснётся к их мертвечине, будет нечист до вечера.'),
(3026, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 28, 'OT', 'И носящий их мертвечину вымоет свою одежду, и будет нечист до вечера; нечисты они для вас.'),
(3027, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 29, 'OT', 'И вот что для вас нечисто из гада, ползающего по земле: ласка, и мышь, и черепаха по роду его.'),
(3028, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 30, 'OT', 'и ящерица, и сила, и ящерица, и улитка, и крот'),
(3029, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 31, 'OT', 'Вот эти нечистые для вас среди всех гадов: всякий, кто прикоснётся к ним после их смерти, будет нечист до вечера.'),
(3030, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 32, 'OT', 'И всё, что упадёт на них из них по смерти их, будет нечисто: из всякого сосуда деревянного, или одежды, или кожи, или вретища, всякий сосуд, который делается для работы, в воду должен быть внесён, и нечист будет до вечера, и станет чист.'),
(3031, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 33, 'OT', 'И всякий глиняный сосуд, в который упадёт что-нибудь из них, всё, что внутри него, станет нечистым, и его разбейте.'),
(3032, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 34, 'OT', 'Вся пища, которую едят, на которую придёт вода, будет нечиста; и всё питьё, которое пьют, во всяком сосуде будет нечисто.'),
(3033, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 35, 'OT', 'И всё, что упадёт на них из мертвечины их, будет нечисто: печь и очаг должны быть разбиты; нечисты они, и нечистыми будут для вас.'),
(3034, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 36, 'OT', 'Только источник и колодезь, собрание воды, будет чист; а прикоснувшийся к мертвечине их осквернится.'),
(3035, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 37, 'OT', 'И если упадёт что-нибудь от мертвечины их на всякое семя посева, которое сеется, — чисто оно.'),
(3036, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 38, 'OT', 'А если будет дана вода на семя, и упадёт на него что-нибудь от мертвечины их, то оно нечисто для вас.'),
(3037, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 39, 'OT', 'И если умрёт из скота, который для вас в пищу, то прикоснувшийся к его мертвечине будет нечист до вечера.'),
(3038, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 40, 'OT', 'И тот, кто ест от мертвечины её, вымоет одежду свою и будет нечист до вечера; и тот, кто несёт мертвечину её, вымоет одежду свою и будет нечист до вечера.'),
(3039, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 41, 'OT', 'И всё, что пресмыкается по земле, — мерзость оно, не должно быть съедено.'),
(3040, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 42, 'OT', 'Всё, что ходит на чреве, и всё, что ходит на четырёх ногах, до всех многих ног, из всех гадов, ползающих по земле, не ешьте их, ибо они мерзость.'),
(3041, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 43, 'OT', 'Не оскверняйте душ ваших всяким гадом, который ползает, и не оскверняйтесь ими, чтобы не стать нечистыми через них.'),
(3042, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 44, 'OT', 'Ибо Я — Господь, Бог ваш: освящайтесь и будьте святы, потому что Я свят, и не оскверняйте душ ваших всем гадом, ползающим по земле.'),
(3043, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 45, 'OT', 'Ибо Я Господь, Который вывел вас из земли Египетской, чтобы быть вам Богом; и будьте святы, ибо свят Я.'),
(3044, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 46, 'OT', 'Это закон о скоте и о птице, и о всяком существе живом, движущемся в воде, и о всяком существе, пресмыкающемся по земле.'),
(3045, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 11, 47, 'OT', 'чтобы отличать нечистое от чистого, и между животным, которое едят, и между животным, которое не едят.'),
(3046, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3047, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 2, 'OT', 'Скажи сынам Израиля: если жена зачнёт и родит мальчика, то она будет нечиста семь дней; как во дни нечистоты её болезни она будет нечиста.'),
(3048, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 3, 'OT', 'И в восьмой день пусть будет обрезана плоть крайней плоти его.'),
(3049, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 4, 'OT', 'И тридцать дней и три дня будет она сидеть в крови очищения; ни к какой святыне не прикоснётся, и в святилище не войдёт, пока не исполнятся дни очищения её.'),
(3050, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 5, 'OT', 'А если женщина родит, то она будет нечиста две седмицы, как во время своей нечистоты, и шестьдесят шесть дней будет сидеть в крови очищения.'),
(3051, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 6, 'OT', 'И когда исполнятся дни очищения её для сына или для дочери, она принесёт ягнёнка в возрасте одного года во всесожжение, и молодого голубя или горлицу в жертву за грех, ко входу шатра собрания, к священнику.'),
(3052, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 7, 'OT', 'И принесёт его пред лицо Господа, и совершит очищение за неё, и она будет чиста от источника крови своей; вот закон родившей — для мужчины или для женщины.'),
(3053, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 12, 8, 'OT', 'А если не найдёт рука её достаточно для овцы, то возьмёт она двух горлиц или двух сыновей голубя: одного во всесожжение и одного в жертву за грех; и очистит её священник, и будет она чиста.'),
(3054, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 1, 'OT', 'И говорил Господь к Моисею и к Аарону, говоря:'),
(3055, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 2, 'OT', 'Если у человека на коже плоти его будет возвышение, или струп, или пятно, и станет на коже плоти его язвой проказы, то он должен быть приведён к Аарону, священнику, или к одному из сыновей его, священников.'),
(3056, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 3, 'OT', 'И увидит священник язву на коже плоти, и если волосы на язве стали белыми, и вид язвы глубже кожи плоти его, то это язва проказы; и осмотрит его священник, и объявит его нечистым.'),
(3057, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 4, 'OT', 'А если пятно белое будет на коже плоти его, и вид его не глубже кожи, и волосы не стали белыми, то священник заключит язву на семь дней.'),
(3058, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 5, 'OT', 'И увидит его священник в седьмой день, и вот, язва осталась в его очах, не распространилась язва по коже, и заключит его священник на семь дней вторично.'),
(3059, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 6, 'OT', 'И увидит его священник в день седьмой во второй раз, и вот, язва потускнела, и не распространилась язва по коже, и объявит его священник чистым: это струп, и пусть он вымоет свои одежды, и будет чист.'),
(3060, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 7, 'OT', 'И если струп распространится по коже после того, как он показался священнику для своего очищения, то он должен показаться вторично священнику.'),
(3061, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 8, 'OT', 'И увидит священник, и вот, распространился струп по коже, и объявит его священник нечистым: это проказа.'),
(3062, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 9, 'OT', 'Если язва проказы будет на человеке, то его приведут к священнику.'),
(3063, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 10, 'OT', 'И увидит священник, и вот опухоль белая на коже, и она обратила волосы в белые, и живая плоть в опухоли.'),
(3064, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 11, 'OT', 'Проказа застарелая на коже плоти его, и объявит его священник нечистым; не заключать его, ибо он нечист.'),
(3065, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 12, 'OT', 'И если расцветёт проказа на коже и покроет проказа всю кожу язвы от главы его и до ног его, по всему виду очей священника,'),
(3066, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 13, 'OT', 'И увидит священник, и вот, проказа покрыла всю плоть его, и объявит он язву чистою: всё обратилось в белое, чист он.'),
(3067, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 14, 'OT', 'И в день, когда явится на нём живая плоть, он будет нечист.'),
(3068, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 15, 'OT', 'И увидит священник живую плоть, и объявит его нечистым; живая плоть — нечиста, это проказа.'),
(3069, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 16, 'OT', 'Или если живая плоть обратится и станет белой, то пусть придёт он к священнику.'),
(3070, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 17, 'OT', 'И увидит его священник, и вот, язва обратилась в белое, и очистит священник язву: чиста она.'),
(3071, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 18, 'OT', 'И если будет на коже плоти его нарыв, и он заживёт'),
(3072, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 19, 'OT', 'И будет на месте нарыва белая опухоль или беловато-красное пятно, и покажется оно священнику.'),
(3073, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 20, 'OT', 'И увидит священник, и вот вид ниже кожи, и волосы её стали белыми, и осквернит его священник: язва проказы это, в нарыве расцвела.'),
(3074, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 21, 'OT', 'И если увидит её священник, и вот нет в ней белых волос, и не ниже она кожи, и она тусклая, то заключит его священник на семь дней.'),
(3075, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 22, 'OT', 'Если же распространится она на коже, то священник объявит его нечистым: это язва.'),
(3076, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 23, 'OT', 'А если пятно останется на своём месте и не распространится, то это воспаление нарыва; и объявит его священник чистым.'),
(3077, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 24, 'OT', 'Или если на коже плоти будет ожог от огня, и живая плоть ожога станет пятном белым с красноватым отливом или белым.'),
(3078, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 25, 'OT', 'И увидит его священник, и вот, волосы превратились в белые в пятне, и вид его глубже кожи: это проказа, расцветшая в ожоге; и объявит его нечистым священник: это язва проказы.'),
(3079, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 26, 'OT', 'И если увидит его священник, и вот нет на пятне белых волос, и не ниже оно кожи, и оно тусклое, то священник заключит его на семь дней.'),
(3080, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 27, 'OT', 'И увидит его священник в седьмой день; если распространится язва на коже, то объявит священник его нечистым: это язва проказы.'),
(3081, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 28, 'OT', 'А если пятно останется на своём месте, не распространилось по коже, и оно побледнело, то это опухоль ожога; и объявит его священник чистым, ибо это воспаление ожога.'),
(3082, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 29, 'OT', 'И если человек или жена будет иметь на нём язву на голове или на бороде'),
(3083, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 30, 'OT', 'И увидит священник язву, и вот, вид её глубже кожи, и в ней волосы желтоватые тонкие, и осквернит его священник: это струп, проказа головы или бороды это.'),
(3084, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 31, 'OT', 'И если увидит священник язву струпа, и вот, вид её не глубже кожи, и волосы чёрные нет на ней, то заключит священник язву струпа на семь дней.'),
(3085, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 32, 'OT', 'И увидит священник язву в седьмой день, и вот, не распространился струп, и нет в нём жёлтых волос, и вид струпа не глубже кожи.'),
(3086, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 33, 'OT', 'И обреется, а струп не обреет, и заключит священник струп на семь дней вторично.'),
(3087, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 34, 'OT', 'И увидит священник струп в седьмой день, и вот, не распространился струп на коже, и вид его не глубже кожи, и очистит его священник, и вымоет одежды свои, и будет чист.'),
(3088, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 35, 'OT', 'Если же струп будет распространяться по коже после его очищения,'),
(3089, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 36, 'OT', 'И увидит его священник, и вот, распространился струп на коже; не будет священник искать волосы желтые, — нечист он.'),
(3090, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 37, 'OT', 'И если в глазах его струп остался на месте, и волосы чёрные выросли на нём, то струп зажил, он чист, и пусть очистит его священник.'),
(3091, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 38, 'OT', 'И если у человека или у жены будет на коже плоти их пятно, пятна белые'),
(3092, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 39, 'OT', 'И увидит священник, и вот на коже плоти их пятна тусклые белые, это лишай, он расцвёл на коже, чист он.'),
(3093, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 40, 'OT', 'Если у человека вылезет голова, он плешив, он чист.'),
(3094, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 41, 'OT', 'Если же с края лица его облысеет голова его, то он лысый, он чист.'),
(3095, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 42, 'OT', 'И если будет на плеши или на плеши язва белая красноватая, это проказа, распускающаяся на плеши его или на плеши его.'),
(3096, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 43, 'OT', 'И увидит его священник, и вот, опухоль язвы беловато-красная на плеши его или на плеши его, как вид проказы кожи плоти.'),
(3097, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 44, 'OT', 'Человек прокажённый он, нечист он; нечистым объявит его священник, на голове его язва его.'),
(3098, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 45, 'OT', 'И прокажённый, у которого язва, — одежда его будет разодрана, и голова его будет не покрыта, и бороду он закроет, и будет взывать: «Нечист, нечист!'),
(3099, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 46, 'OT', 'Все дни, в которые язва на нём, он будет нечист; нечист он, в одиночестве будет сидеть, вне стана его жилище.'),
(3100, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 47, 'OT', 'И если будет на одежде язва проказы, на одежде из шерсти или на одежде из льна,'),
(3101, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 48, 'OT', 'или на основе, или на утке, для льна и для шерсти, или на коже, или на всякой работе из кожи'),
(3102, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 49, 'OT', 'И будет язва зеленоватая или красноватая на одежде, или на коже, или на основе, или на утке, или на всяком сосуде из кожи, — это язва проказы; и покажет её священнику.'),
(3103, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 50, 'OT', 'И увидит священник язву, и заключит язву на семь дней.'),
(3104, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 51, 'OT', 'И осмотрит священник язву в седьмой день; если язва распространилась на одежде, или на основе, или на утке, или на коже, во всём, что делается из кожи для работы, то это проказа злокачественная, язва нечиста она.'),
(3105, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 52, 'OT', 'И сожжёт одежду, или основу, или уток, в шерсти или в льне, или всё изделие из кожи, на котором будет язва, ибо это проказа злокачественная; в огне да будет сожжено.'),
(3106, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 53, 'OT', 'И если увидит священник, и вот не распространилась язва на одежде, или на основе, или на утке, или на всяком изделии из кожи,'),
(3107, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 54, 'OT', 'И прикажет священник, и вымоют то, на чём язва, и заключит его на семь дней вторично.'),
(3108, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 55, 'OT', 'И осмотрит священник язву после того, как она будет вымыта, и вот, если язва не изменила своего вида, и язва не распространилась, то она нечиста; это гниль на огне, она есть плешь на плеши его.'),
(3109, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 56, 'OT', 'И если увидит священник, и вот, язва потускнела после того, как она была вымыта, то пусть вырвет её из одежды, или из кожи, или из основы, или из утка.'),
(3110, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 57, 'OT', 'И если ещё будет видна на одежде, или на основе, или на утке, или на всяком кожаном изделии, расцветающая она, то в огне сожги её, то, на чём язва.'),
(3111, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 58, 'OT', 'И одежда, или основа, или уток, или всякое изделие из кожи, которое будет вымыто, и отойдёт от них язва, то пусть будет вымыто вторично, и будет чисто.'),
(3112, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 13, 59, 'OT', 'Вот закон о язве проказы на одежде из шерсти или льна, на основе или на утке, или на всяком кожаном изделии, чтобы очистить его или осквернить его.'),
(3113, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3114, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 2, 'OT', 'Вот закон о прокажённом в день очищения его: он будет приведён к священнику.'),
(3115, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 3, 'OT', 'И выйдет священник вне стана, и увидит священник, и вот, язва проказы исцелела у прокажённого.'),
(3116, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 4, 'OT', 'И прикажет священник, и возьмёт для очищающегося двух живых чистых птиц, и дерево кедровое, и багряную шерсть, и иссоп.'),
(3117, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 5, 'OT', 'И прикажет священник, и зарежет одну птицу над глиняным сосудом, над живою водою.'),
(3118, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 6, 'OT', 'Живую птицу возьмёт он, и кедровое дерево, и багрянец, и багряную шерсть, и иссоп, и окунёт их и живую птицу в кровь птицы заколотой над живою водою.'),
(3119, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 7, 'OT', 'И окропит на очищаемого от проказы семь раз, и очистит его, и отпустит живую птицу на поверхность поля.'),
(3120, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 8, 'OT', 'И очистит очищаемый одежды свои, и обреет все волосы свои, и омоется в воде, и будет чист; и после войдёт в стан, и будет жить вне шатра своего семь дней.'),
(3121, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 9, 'OT', 'И будет в седьмой день, он обреет все волосы свои: главу свою и бороду свою, и брови очей своих, и все волосы свои обреет; и выстирает одежды свои, и омоет плоть свою в воде, и будет чист.'),
(3122, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 10, 'OT', 'В восьмой день возьмёт он двух ягнят без порока и одну овцу годовалую без порока, и три десятых части муки тонкой, смешанной с елеем, в приношение, и один лог елея.'),
(3123, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 11, 'OT', 'И поставит священник, очищающий, человека очищаемого и их пред лицом Господа, у двери шатра собрания.'),
(3124, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 12, 'OT', 'И возьмёт священник одного ягнёнка и принесёт его в жертву повинности, и лог елея, и потрясёт их потрясанием пред лицом Господа.'),
(3125, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 13, 'OT', 'И заколет ягнёнка на месте, где закалывают жертву за грех и всесожжение, на месте святыни; ибо как жертва за грех, так и жертва повинности принадлежит священнику: это святыня из святынь.'),
(3126, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 14, 'OT', 'И возьмёт священник из крови жертвы повинности, и даст священник на мочку правого уха очищаемого, и на большой палец правой руки его, и на большой палец правой ноги его.'),
(3127, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 15, 'OT', 'И возьмёт священник из лога елея и выльет на ладонь левую священника.'),
(3128, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 16, 'OT', 'И окунёт священник перст свой правый в елей, который на ладони его левой, и покропит из елея перстом своим семь раз пред лицом Господа.'),
(3129, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 17, 'OT', 'И из остатка елея, который на ладони его, даст священник на мочку уха очищаемого правого, и на большой палец руки его правой, и на большой палец ноги его правой, на кровь жертвы повинности.'),
(3130, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 18, 'OT', 'И остаток елея, который на ладони священника, он возложит на голову очищаемого, и очистит его священник пред лицом Господа.'),
(3131, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 19, 'OT', 'И совершит священник жертву за грех, и очистит очищаемого от нечистоты его, и после заколет всесожжение.'),
(3132, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 20, 'OT', 'И вознесёт священник всесожжение и приношение на жертвенник, и совершит священник очищение за него, и будет он чист.'),
(3133, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 21, 'OT', 'Если же он беден и рука его не достигает, то пусть возьмёт одного ягнёнка в жертву повинности для потрясания, чтобы очистить его, и одну десятую часть муки, смешанной с елеем, в приношение, и лог елея.'),
(3134, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 22, 'OT', 'и двух горлиц или двух сыновей голубя, которых достанет рука его; и будет один жертвой за грех, а другой всесожжением.'),
(3135, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 23, 'OT', 'И принесёт их в восьмой день для очищения своего к священнику, ко входу шатра собрания, пред лицо Господа.'),
(3136, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 24, 'OT', 'И возьмёт священник ягнёнка жертвы повинности и лог елея, и совершит священник потрясание ими пред лицом Господа.'),
(3137, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 25, 'OT', 'И заколет ягнёнка жертвы повинности, и возьмёт священник крови жертвы повинности, и возложит на мочку правого уха очищаемого, и на большой палец его правой руки, и на большой палец его правой ноги.'),
(3138, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 26, 'OT', 'И из елея выльет священник на ладонь священника левую.'),
(3139, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 27, 'OT', 'И покропит священник перстом своим правым из елея, который на ладони его левой, семь раз пред лицом Господа.'),
(3140, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 28, 'OT', 'И возложит священник из елея, который на ладони его, на мочку правого уха очищаемого, и на большой палец правой руки его, и на большой палец правой ноги его, на место крови жертвы повинности.'),
(3141, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 29, 'OT', 'Оставшийся елей, который на ладони священника, он даст на голову очищаемого, чтобы очистить его пред лицом Господа.'),
(3142, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 30, 'OT', 'И принесёт он одного из горлиц или из сыновей голубя, что достанет рука его.'),
(3143, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 31, 'OT', 'То, что достанет рука его, одно — в жертву за грех, и одно — во всесожжение, вместе с хлебным приношением; и очистит священник очищаемого пред лицом Господа.'),
(3144, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 32, 'OT', 'Вот закон о том, у кого язва проказы, чья рука не достаёт для очищения его.'),
(3145, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 33, 'OT', 'И сказал Господь к Моисею и к Аарону, говоря:'),
(3146, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 34, 'OT', 'Когда вы придёте в землю Ханаанскую, которую Я даю вам во владение, и Я наведу язву проказы на дом земли владения вашего,'),
(3147, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 35, 'OT', 'И придет тот, чей дом, и объявит священнику, говоря: язва показалась мне в доме.'),
(3148, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 36, 'OT', 'И прикажет священник, и освободят дом прежде, чем войдёт священник осмотреть язву, чтобы не осквернилось всё, что в доме; и после того войдёт священник осмотреть дом.'),
(3149, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 37, 'OT', 'И осмотрит священник язву, и вот, язва на стенах дома — впадины зеленоватые или красноватые, и вид их ниже стены.'),
(3150, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 38, 'OT', 'И выйдет священник из дома к двери дома, и запрет дом на семь дней.'),
(3151, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 39, 'OT', 'И возвратится священник в седьмой день, и увидит, и вот, распространилась язва на стенах дома.'),
(3152, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 40, 'OT', 'И прикажет священник, и вынут камни, на которых язва, и бросят их вне города, на место нечистое.'),
(3153, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 41, 'OT', 'И выскоблит дом изнутри кругом, и высыплют прах, который выскоблили, вне города, на место нечистое.'),
(3154, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 42, 'OT', 'И возьмут другие камни и принесут на место тех камней, и прах другой возьмёт, и обмажет дом.'),
(3155, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 43, 'OT', 'И если возвратится язва и расцветёт в доме после того, как выломаны камни, и после того, как оштукатурен дом, и после того, как обмазан дом,'),
(3156, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 44, 'OT', 'И войдёт священник, и осмотрит, и вот, распространилась язва в доме: проказа злокачественная это в доме, нечист он.'),
(3157, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 45, 'OT', 'И разрушит дом, камни его, и дерево его, и весь прах дома, и вынесет вне города, на место нечистое.'),
(3158, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 46, 'OT', 'И входящий в дом во все дни, когда он заперт, будет нечист до вечера.'),
(3159, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 47, 'OT', 'И спящий в доме вымоет одежду свою, и едящий в доме вымоет одежду свою.'),
(3160, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 48, 'OT', 'И если придёт священник и увидит, и вот не распространилась язва в доме после того, как был оштукатурен дом, то очистит священник дом, ибо исцелела язва.'),
(3161, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 49, 'OT', 'И возьмёт он, чтобы очистить дом, двух птиц, и дерево кедровое, и багряную шерсть, и иссоп.'),
(3162, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 50, 'OT', 'И заколет птицу одну над глиняным сосудом, над живою водою.'),
(3163, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 51, 'OT', 'И возьмёт он дерево кедровое и иссоп, и багряную шерсть, и птицу живую, и окунёт их в кровь птицы заколотой и в воду живую, и покропит на дом семь раз.'),
(3164, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 52, 'OT', 'И очистит дом кровью птицы и живою водою, и живою птицею, и кедровым деревом, и иссопом, и багряною шерстью.'),
(3165, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 53, 'OT', 'И отпустит живую птицу за город, на улицу, в открытое поле, и очистит дом, и будет чист.'),
(3166, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 54, 'OT', 'Это закон для всякой язвы проказы и для струпа.'),
(3167, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 55, 'OT', 'и для проказы на одежде и для дома'),
(3168, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 56, 'OT', 'и для опухоли, и для струпа, и для пятна'),
(3169, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 14, 57, 'OT', 'чтобы учить, в день нечистого и в день чистого; вот закон проказы.'),
(3170, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 1, 'OT', 'И говорил Господь к Моисею и к Аарону, говоря:'),
(3171, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 2, 'OT', 'Скажите сынам Израиля и скажите им: если у человека будет истечение из плоти его, то истечение его нечисто.'),
(3172, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 3, 'OT', 'И вот будет нечистота его в истечении его: если течёт плоть его с истечением его, или задержалась плоть его от истечения его, нечистота его есть.'),
(3173, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 4, 'OT', 'Всё ложе, на котором будет лежать имеющий истечение, будет нечисто; и всё сосуд, на котором он сядет, будет нечист.'),
(3174, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 5, 'OT', 'И человек, который прикоснётся к ложу его, пусть вымоет одежды свои и омоется водою, и будет нечист до вечера.'),
(3175, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 6, 'OT', 'И сидящий на сосуде, на котором сидел имеющий истечение, пусть вымоет одежду свою, и омоется водою, и будет нечист до вечера.'),
(3176, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 7, 'OT', 'И касающийся плоти имеющего истечение пусть вымоет свою одежду и омоется в воде, и будет нечист до вечера.'),
(3177, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 8, 'OT', 'Если же плюнет имеющий истечение на чистого, то пусть выстирает свою одежду и омоется в воде, и будет нечист до вечера.'),
(3178, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 9, 'OT', 'И всякая колесница, на которой поедет имеющий истечение, будет нечиста.'),
(3179, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 10, 'OT', 'И всё, что коснётся всего, что будет под ним, будет нечисто до вечера; и тот, кто понесёт их, вымоет одежды свои и омоется в воде, и будет нечист до вечера.'),
(3180, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 11, 'OT', 'И всякий, кто прикоснётся к нему, у кого течь, а руки свои не омыл водою, пусть выстирает одежды свои и омоется водою, и будет нечист до вечера.'),
(3181, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 12, 'OT', 'И сосуд глиняный, которого коснётся имеющий истечение, будет разбит, а всякий сосуд деревянный будет омыт водою.'),
(3182, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 13, 'OT', 'И когда очистится имеющий истечение от истечения своего, отсчитает себе семь дней для очищения своего, и вымоет одежды свои, и омоет плоть свою в живой воде, и будет чист.'),
(3183, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 14, 'OT', 'А в восьмой день возьмёт он себе двух горлиц или двух сыновей голубя, и придёт пред лицо Господа ко входу шатра собрания, и отдаст их священнику.'),
(3184, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 15, 'OT', 'И сделает их священник: одного в жертву за грех, а другого во всесожжение; и очистит его священник пред лицом Господа от истечения его.'),
(3185, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 16, 'OT', 'И если у человека выйдет из него совокупление семени, то он омоет в воде всё тело своё, и будет нечист до вечера.'),
(3186, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 17, 'OT', 'И всякая одежда, и всякая кожа, на которой будет совокупление семени, должна быть вымыта в воде, и нечиста до вечера.'),
(3187, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 18, 'OT', 'И если жена, с которой ляжет человек совокуплением семени, то пусть омоются водою, и будут нечисты до вечера.'),
(3188, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 19, 'OT', 'И если жена имеет течение, кровь будет течением её в плоти её; семь дней будет она в нечистоте своей, и всякий, кто прикоснётся к ней, будет нечист до вечера.'),
(3189, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 20, 'OT', 'И всё, на чём она будет лежать во время нечистоты своей, будет нечисто; и всё, на чём она будет сидеть, будет нечисто.'),
(3190, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 21, 'OT', 'И всякий, кто прикоснётся к ложу её, пусть вымоет одежды свои и омоется водою, и будет нечист до вечера.'),
(3191, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 22, 'OT', 'И всякий, кто прикоснётся ко всякому сосуду, на котором она сидела, пусть выстирает свою одежду и омоется в воде, и будет нечист до вечера.'),
(3192, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 23, 'OT', 'Если он лежит на ложе или на сосуде, на котором она сидит, при прикосновении к нему он будет нечист до вечера.'),
(3193, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 24, 'OT', 'И если человек ляжет с нею, и будет на нём нечистота её, то он будет нечист семь дней, и всякое ложе, на котором он ляжет, будет нечисто.'),
(3194, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 25, 'OT', 'И если жена имеет истечение крови многие дни не во время нечистоты её, или если истечёт сверх нечистоты её, то во все дни истечения нечистоты её, как во дни нечистоты её, будет она нечиста.'),
(3195, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 26, 'OT', 'Всё ложе, на котором она будет лежать во все дни своего истечения, будет для неё как ложе её нечистоты; и всякий сосуд, на котором она сядет, будет нечист, как нечистота её нечистоты.'),
(3196, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 27, 'OT', 'И всё, кто прикоснётся к ним, будет нечист; и вымоет одежду свою, и омоется в воде, и будет нечист до вечера.'),
(3197, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 28, 'OT', 'И если она очистится от истечения своего, то отсчитает себе семь дней, и после того будет чиста.'),
(3198, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 29, 'OT', 'А в восьмой день пусть возьмёт она двух горлиц или двух сыновей голубя, и принесёт их к священнику, ко входу в шатёр собрания.'),
(3199, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 30, 'OT', 'И совершит священник одного в жертву за грех, а другого во всесожжение, и очистит её священник пред лицом Господа от истечения нечистоты её.'),
(3200, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 31, 'OT', 'И отделите сынов Израиля от нечистоты их, чтобы они не умерли в нечистоте своей, оскверняя скинию Мою, которая среди них.'),
(3201, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 32, 'OT', 'Вот закон об истекающем и о том, у кого выходит совокупление семени для осквернения им.'),
(3202, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 15, 33, 'OT', 'И нечистота её в её нечистоте, и истекающий своим истечением, для мужчины и для женщины, и для человека, который ляжет с нечистой.'),
(3203, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 1, 'OT', 'И говорил Господь к Моисею после смерти двух сыновей Аарона, когда они приблизились пред лицо Господа и умерли.'),
(3204, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 2, 'OT', 'И сказал Господь Моисею: говори Аарону, брату твоему, чтобы он не входил во всякое время во святыню внутрь дома завесы, пред лицо крышки (мерсилища), которая на ковчеге, и не умер, ибо в облаке Я явлюсь над крышкою (мерсилищем).'),
(3205, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 3, 'OT', 'С этим войдёт Аарон в святыню: с тельцом из сынов крупного рогатого скота в жертву за грех и с овном во всесожжение.'),
(3206, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 4, 'OT', 'Хитон из льна, священные, наденет он, и льняные штаны (набедренная повязка) будут на плоти его, и поясом из льна опояшется, и митрой из льна увенчает голову; одежды священные это, и омоет он водою плоть свою, и наденет их.'),
(3207, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 5, 'OT', 'И от общества сынов Израиля возьмёт двух козлов для жертвы за грех и одного овна для всесожжения.'),
(3208, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 6, 'OT', 'И принесёт Аарон тельца за грех, который для него, и совершит искупление за себя и за дом свой.'),
(3209, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 7, 'OT', 'И возьмёт двух козлов, и поставит их пред лицом Господа у двери шатра собрания.'),
(3210, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 8, 'OT', 'И дал Аарон на двух козлов жребии: жребий один Господу, и жребий один козлу отпущения.'),
(3211, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 9, 'OT', 'И принесёт Аарон козла, на которого вышел жребий для Господа, и сделает его жертвой за грех.'),
(3212, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 10, 'OT', 'А козёл, на которого вышел жребий для козла отпущения, будет поставлен живым пред лицом Господа, чтобы совершить над ним искупление, чтобы отпустить его в пустыню как козла отпущения.'),
(3213, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 11, 'OT', 'И принесёт Аарон тельца за грех, который для него, и совершит искупление за себя и за дом свой, и заколет тельца за грех, который для него.'),
(3214, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 12, 'OT', 'И возьмёт полную кадильницу углей огня с жертвенника от лица Господа, и полные горсти свои фимиама ароматов мелкого, и принесёт из дома за завесу.'),
(3215, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 13, 'OT', 'И положит фимиам на огонь пред лицом Господа, и облако фимиама покроет крышку, которая над свидетельством, и не умрёт он.'),
(3216, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 14, 'OT', 'И возьмёт от крови тельца и покропит перстом своим на лицо крышки (мерсилища) к востоку, и пред лицом крышки (мерсилища) покропит семь раз от крови перстом своим.'),
(3217, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 15, 'OT', 'И заколет козла за грех, который для народа, и внесёт кровь его за завесу внутрь дома, и сделает с кровью его, как сделал с кровью тельца, и покропит ею на крышку (очистилище) и перед лицом крышки (очистилища).'),
(3218, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 16, 'OT', 'И очистит святыню от нечистот сынов Израиля и от преступлений их, за все грехи их; и так же поступит с шатром собрания, пребывающим среди них, среди нечистот их.'),
(3219, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 17, 'OT', 'И никакой человек не будет в шатре собрания, когда он входит для искупления в святыню, пока не выйдет; и он искупит за себя и за дом свой, и за всё собрание Израиля.'),
(3220, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 18, 'OT', 'И выйдет к жертвеннику, который пред лицом Господа, и совершит очищение над ним, и возьмёт из крови тельца и из крови козла, и даст на рога жертвенника вокруг.'),
(3221, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 19, 'OT', 'И окропит на него кровью перстом своим семь раз, и очистит его, и освятит его от нечистот сынов Израиля.'),
(3222, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 20, 'OT', 'И когда окончит он очищение святыни, и шатра собрания, и жертвенника, то приведёт козла живого.'),
(3223, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 21, 'OT', 'И возложит Аарон обе руки свои на голову живого козла, и исповедует над ним все беззакония сынов Израиля и все преступления их во всех грехах их, и возложит их на голову козла, и отошлёт рукою человека назначенного в пустыню.'),
(3224, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 22, 'OT', 'И понесёт козёл на себе все беззакония их в землю отрезанную, и отпустит козла в пустыню.'),
(3225, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 23, 'OT', 'И вошёл Аарон в шатёр собрания, и снял льняную одежду, которую надел, входя во святыню, и оставил её там.'),
(3226, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 24, 'OT', 'И омоет плоть свою водою на святом месте, и наденет одежды свои, и выйдет, и совершит всесожжение своё и всесожжение народа, и очистит себя и народ.'),
(3227, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 25, 'OT', 'И тук жертвы за грех он воскурит на жертвеннике.'),
(3228, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 26, 'OT', 'А тот, кто отводит козла к козлу отпущения, пусть вымоет свою одежду и омоет свою плоть в воде, и после того войдёт в стан.'),
(3229, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 27, 'OT', 'И тельца жертвы за грех, и козла жертвы за грех, чья кровь была внесена для искупления в святыню, пусть вынесут за пределы стана, вне стана, и сожгут в огне их кожу, и их плоть, и их навоз.'),
(3230, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 28, 'OT', 'И сжигающий их вымоет свою одежду и омоет свою плоть водою, и после того войдёт в стан.'),
(3231, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 29, 'OT', 'И будет это для вас вечным уставом: в седьмом месяце, в десятый день месяца, смиряйте души ваши, и никакой работы не делайте — ни туземец, ни пришелец, живущий среди вас.'),
(3232, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 30, 'OT', 'Ибо в этот день он очистит вас, чтобы сделать вас чистыми от всех грехов ваших; пред лицом Господа вы будете чисты.'),
(3233, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 31, 'OT', 'Это суббота покоя для вас, и смиряйте души ваши: устав вечный.'),
(3234, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 32, 'OT', 'И очистит священник, который будет помазан и который посвятит себя, чтобы священнодействовать вместо отца своего, и оденется в одежды льняные, одежды святыни.'),
(3235, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 33, 'OT', 'И очистит святилище святыни, и шатёр собрания, и жертвенник очистит, и над священниками, и над всем народом собрания совершит очищение.'),
(3236, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 16, 34, 'OT', 'И будет это для вас уставом вечным, чтобы очищать сынов Израиля от всех грехов их однажды в год; и сделал он так, как повелел Господь Моисею.'),
(3237, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3238, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 2, 'OT', 'Скажи Аарону и сыновьям его, и всем сынам Израиля, и скажи им: вот слово, которое заповедал Господь, говоря:'),
(3239, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 3, 'OT', 'Любой человек из дома Израиля, который заколет вола, или ягнёнка, или козу в стане, или который заколет вне стана,'),
(3240, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 4, 'OT', 'и к двери шатра собрания не принёс его, чтобы принести приношение Господу пред лицом скинии Господа, кровь вменится тому человеку: кровь он пролил, и истребится тот человек из среды народа своего.'),
(3241, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 5, 'OT', 'Чтобы сыны Израиля приносили свои жертвы, которые они закалывают в открытом поле, и приносили их Господу ко входу шатра собрания, к священнику, и закалывали их как мирные жертвы Господу.'),
(3242, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 6, 'OT', 'И окропит священник кровью на жертвенник Господа у двери шатра собрания, и сожжёт тук в приятное благоухание Господу, в запах приятный для Господа.'),
(3243, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 7, 'OT', 'И не будут они больше приносить жертвы свои козлам, за которыми они блудно ходят; уставом вечным будет это для них в роды их.'),
(3244, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 8, 'OT', 'И скажи им: человек из дома Израиля и из пришельца, который живёт среди них, кто вознесёт всесожжение или жертву,'),
(3245, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 9, 'OT', 'и к двери шатра собрания не принесёт его, чтобы совершить его для Господа, — и будет истреблён тот человек из народа своего.'),
(3246, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 10, 'OT', 'И если человек из дома Израиля и из пришельца, живущего среди них, кто будет есть всякую кровь, то Я обращу лицо Моё против души той, которая ест кровь, и истреблю её из среды народа её.'),
(3247, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 11, 'OT', 'Ибо душа плоти — в крови, и Я дал её вам на жертвенник для очищения душ ваших, ибо кровь — душою очищает.'),
(3248, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 12, 'OT', 'Потому Я сказал сынам Израиля: всякая душа из вас не будет есть кровь, и пришелец, живущий среди вас, не будет есть кровь.'),
(3249, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 13, 'OT', 'И человек из сынов Израиля и из пришельца, живущего в середине их, который ловит ловлю животного или птицу, которую едят, и прольёт кровь её, и покроет её прахом.'),
(3250, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 14, 'OT', 'Ибо душа всякой плоти — кровь её, в душе её она; и Я сказал сынам Израиля: кровь всякой плоти не ешьте, ибо душа всякой плоти — кровь её; всякий, кто ест её, будет истреблён.'),
(3251, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 15, 'OT', 'И всякая душа, которая ест мертвечину или растерзанное, из туземца и из пришельца, и вымоет одежды свои, и омоется в воде, и будет нечист до вечера, и будет чист.'),
(3252, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 17, 16, 'OT', 'А если он не вымоет одежды и не омоет плоти своей, то понесёт беззаконие своё.'),
(3253, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3254, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 2, 'OT', 'Скажи сынам Израиля и скажи им: Я Господь, Бог ваш.'),
(3255, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 3, 'OT', 'По делам земли Египетской, в которой вы жили, не делайте, и по делам земли Ханаанской, в которую Я веду вас, не делайте, и по уставам их не ходите.'),
(3256, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 4, 'OT', 'Исполняйте постановления Мои и соблюдайте уставы Мои, чтобы ходить в них; Я — Господь, Бог ваш.'),
(3257, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 5, 'OT', 'Соблюдайте уставы Мои и постановления Мои, которые исполняя, человек будет жив ими: Я Господь.'),
(3258, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 6, 'OT', 'Ни один человек не приближайся к кому-либо из всех близких родственников по плоти своей, чтобы открыть наготу: Я Господь.'),
(3259, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 7, 'OT', 'Наготу отца твоего и наготу матери твоей не открой; она — мать твоя, не открой наготы её.'),
(3260, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 8, 'OT', 'Наготу жены отца твоего не открывай; нагота отца твоего она.'),
(3261, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 9, 'OT', 'Наготу сестры твоей, дочери отца твоего или дочери матери твоей, рождённой в доме или рождённой вне дома, не открывай наготы их.'),
(3262, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 10, 'OT', 'Наготу дочери сына твоего или дочери дочери твоей не открывай, наготу их; ибо нагота твоя они.'),
(3263, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 11, 'OT', 'Нагота дочери жены отца твоего, рождённая отцом твоим, — сестра твоя она; не открывай наготы её.'),
(3264, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 12, 'OT', 'Наготу сестры отца твоего не открывай; близкая родственница отца она.'),
(3265, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 13, 'OT', 'Наготу сестры твоей матери не открывай; ибо она близкая родственница матери твоей.'),
(3266, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 14, 'OT', 'Наготу брата отца твоего не открывай; к жене его не приближайся: тётка твоя она.'),
(3267, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 15, 'OT', 'Наготу невестки твоей не открывай; она жена сына твоего, не открывай наготы её.'),
(3268, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 16, 'OT', 'Наготу жены брата твоего не открывай; нагота брата твоего она.'),
(3269, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 17, 'OT', 'Наготу жены и дочери её не открывай; дочь сына её и дочь дочери её не бери, чтобы открыть наготу её: родственницы они, мерзость это.'),
(3270, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 18, 'OT', 'И жену к сестре её не бери, чтобы открыть наготу её при ней, пока она жива.'),
(3271, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 19, 'OT', 'И к жене в нечистоте её не приближайся, чтобы открыть наготу её.'),
(3272, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 20, 'OT', 'И к жене ближнего твоего не давай ложа твоего для семени, чтобы оскверниться ею.'),
(3273, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 21, 'OT', 'И от семени твоего не давай проводить через огонь для Молоха, и не оскверняй имя Бога твоего: Я Господь.'),
(3274, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 22, 'OT', 'И с мужчиной не ложись на ложе жены: это мерзость.'),
(3275, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 23, 'OT', 'И со всяким скотом не давай ложа твоего для осквернения им, и жена не становись перед лицом скота для совокупления с ним: смешение это.'),
(3276, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 24, 'OT', 'Не оскверняйтесь ничем из всего этого, ибо всем этим осквернились народы, которых Я изгоняю от лица вашего.'),
(3277, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 25, 'OT', 'И осквернилась земля, и Я взыскал беззаконие её на ней, и извергла земля жителей своих.'),
(3278, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 26, 'OT', 'Соблюдайте же вы уставы Мои и постановления Мои, и не делайте ничего из всех этих мерзостей — ни туземец, ни пришелец, живущий среди вас.'),
(3279, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 27, 'OT', 'ибо все эти мерзости делали люди той земли, которая перед вами, и осквернилась земля.'),
(3280, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 28, 'OT', 'И не извергнет вас земля, когда вы оскверните её, как извергла она народ, который был пред лицом вашим.'),
(3281, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 29, 'OT', 'Ибо всякий, кто сделает что-либо из всех этих мерзостей, души делающие будут истреблены из среды народа своего.'),
(3282, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 18, 30, 'OT', 'Соблюдайте заповедь Мою, чтобы не делать обычаев мерзостей, которые делались пред лицом вашим, и не оскверняйтесь ими: Я Господь, Бог ваш.'),
(3283, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3284, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 2, 'OT', 'Скажи всему обществу сынов Израиля и скажи им: святыми будьте, ибо свят Я, Господь, Бог ваш.'),
(3285, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 3, 'OT', 'Каждый человек матери своей и отцу своему бойтесь, и субботы Мои соблюдайте: Я Господь, Бог ваш.'),
(3286, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 4, 'OT', 'Не обращайтесь к идолам, и богов литых не делайте себе; Я — Господь, Бог ваш.'),
(3287, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 5, 'OT', 'И если будете приносить жертву мирную Господу, то по вашему желанию приносите её.'),
(3288, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 6, 'OT', 'В день жертвы вашей пусть будет съедено, и на следующий день; а оставшееся до третьего дня пусть будет сожжено в огне.'),
(3289, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 7, 'OT', 'Если же оно будет съедено в третий день, это мерзость, оно не будет принято.'),
(3290, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 8, 'OT', 'И тот, кто ест её, понесёт своё беззаконие, ибо он осквернил святыню Господню; и будет истреблена та душа из народа своего.'),
(3291, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 9, 'OT', 'И когда будете жать жатву земли вашей, не дожинай края поля твоего, и сбор остатков жатвы твоей не подбирай.'),
(3292, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 10, 'OT', 'И виноградник твой не обирай дочиста, и упавшие ягоды виноградника твоего не подбирай; оставь их бедному и пришельцу. Я — Господь, Бог ваш.'),
(3293, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 11, 'OT', 'Не крадите, и не обманывайте, и не лгите друг другу, человек ближнему своему.'),
(3294, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 12, 'OT', 'Не клянитесь Моим именем во лжи, и не оскверняй имя Бога твоего: Я Господь.'),
(3295, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 13, 'OT', 'Не угнетай ближнего твоего и не грабь; не оставайся у тебя плата наёмника до утра.'),
(3296, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 14, 'OT', 'Не проклинай глухого, и перед лицом слепого не клади преткновения, и бойся Бога твоего: Я Господь.'),
(3297, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 15, 'OT', 'Не делайте беззакония в суде; не будь лицеприятен к лицу бедного и не уважай лица великого; по правде суди ближнего твоего.'),
(3298, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 16, 'OT', 'Не ходи клеветником в народе твоём; не стой против крови ближнего твоего: Я Господь.'),
(3299, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 17, 'OT', 'Не ненавидь брата твоего в сердце твоём; обличай ближнего твоего, и не понеси на нём греха.'),
(3300, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 18, 'OT', 'Не мсти и не храни злобы на сынов народа твоего, но люби ближнего твоего, как самого себя: Я Господь.'),
(3301, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 19, 'OT', 'Соблюдайте уставы Мои: скота твоего не своди с другим скотом для смешения, поля твоего не засевай смешанным семенем, и одежда из смешанной ткани, разношёрстная одежда, не должна надеваться на тебя.'),
(3302, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 20, 'OT', 'И если человек ляжет с женою совокуплением семени, и она будет служанка, обручённая человеку, и не была выкуплена, или свобода не была дана ей, наказание будет ей; не будут преданы смерти, потому что не была освобождена.'),
(3303, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 21, 'OT', 'И принесёт жертву повинности свою Господу ко двери шатра собрания, овна в жертву повинности.'),
(3304, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 22, 'OT', 'И очистит его священник овном жертвы повинности пред лицом Господа за грех его, которым он согрешил, и прощено будет ему за грех его, которым он согрешил.'),
(3305, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 23, 'OT', 'И когда придёте в землю и посадите всякое дерево для пищи, то обрежьте крайнюю плоть его плода; три года будет оно для вас необрезанным, не должно есть его.'),
(3306, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 24, 'OT', 'А в четвёртый год будет весь плод его святынею празднества для Господа.'),
(3307, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 25, 'OT', 'А в пятый год будете есть плод его, чтобы прибавить вам урожай его; Я Господь, Бог ваш.'),
(3308, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 26, 'OT', 'Не ешьте с кровью; не ворожите и не гадайте.'),
(3309, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 27, 'OT', 'Не обстригайте край головы вашей и не порти край бороды твоей.'),
(3310, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 28, 'OT', 'И нарезки ради умершего не делайте на плоти вашей, и начертания начертания не наносите на себя; Я Господь.'),
(3311, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 29, 'OT', 'Не оскверняй дочери твоей, отдавая её на блуд, и не будет блудодействовать земля, и не наполнится земля мерзостью.'),
(3312, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 30, 'OT', 'Соблюдайте субботы Мои и святилище Моё чтите; Я — Господь.'),
(3313, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 31, 'OT', 'Не обращайтесь к волшебникам и к волшебникам, не ищите осквернения через них; Я — Господь, Бог ваш.'),
(3314, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 32, 'OT', 'Перед лицом седины встань и почти лицо старца, и бойся Бога твоего: Я Господь.'),
(3315, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 33, 'OT', 'И если будет жить у тебя пришелец в вашей земле, не притесняйте его.'),
(3316, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 34, 'OT', 'Как туземец из вас будет вам пришелец, живущий с вами, и люби его, как самого себя, ибо пришельцами были вы в земле Египетской: Я Господь, Бог ваш.'),
(3317, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 35, 'OT', 'Не совершайте беззакония в суде, в мере, в весе и в мере.'),
(3318, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 36, 'OT', 'Весы правды, камень правды, ефа правды и гин правды да будут у вас; Я Господь, Бог ваш, Который вывел вас из земли Египетской.'),
(3319, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 19, 37, 'OT', 'Соблюдайте все уставы Мои и все постановления Мои, и исполняйте их: Я Господь.'),
(3320, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3321, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 2, 'OT', 'И скажи сынам Израиля: всякий человек из сынов Израиля и из пришельца, живущего в Израиле, кто даст из семени своего Молоху, да будет предан смерти; народ земли побьёт его камнями.'),
(3322, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 3, 'OT', 'И Я обращу лицо Моё на того человека и истреблю его из среды народа его, потому что он дал из семени своего Молоху, чтобы осквернить святилище Моё и обесчестить имя святыни Моей.'),
(3323, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 4, 'OT', 'И если народ земли закроет глаза свои на того человека, когда он отдаст из семени своего Молоху, чтобы не умертвить его,'),
(3324, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 5, 'OT', 'И обращу Я лицо Моё на того человека и на семейство его, и истреблю его и всех блудящих вслед за ним, чтобы блудить вслед за Молохом, из среды народа их.'),
(3325, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 6, 'OT', 'И душа, которая обратится к волшебникам и к волшебникам, чтобы блудно ходить вслед их, — Я обращу лицо Моё против души той и истреблю её из среды народа её.'),
(3326, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 7, 'OT', 'Освящайте себя и будьте святы, ибо Я — Господь, Бог ваш.'),
(3327, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 8, 'OT', 'Соблюдайте уставы Мои и исполняйте их: Я Господь, освящающий вас.'),
(3328, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 9, 'OT', 'Если человек, который проклянет отца своего и мать свою, смертью да будет умерщвлен; отца своего и мать свою он проклял, кровь его на нем.'),
(3329, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 10, 'OT', 'И человек, который прелюбодействует с женой человека, который прелюбодействует с женой ближнего своего, — смертью да будут преданы смерти прелюбодей и прелюбодейка.'),
(3330, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 11, 'OT', 'Человек, который ляжет с женой отца своего, открыл наготу отца своего; оба они должны быть преданы смерти, кровь их на них.'),
(3331, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 12, 'OT', 'И человек, который ляжет с невесткой своей, — смертью да будут преданы оба; смешение они совершили, кровь их на них.'),
(3332, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 13, 'OT', 'И человек, который ляжет с мужчиной, как с женщиной, — мерзость сделали они оба; смертью да будут преданы смерти, кровь их на них.'),
(3333, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 14, 'OT', 'Человек, который возьмёт жену и её мать, — это мерзость; огнём сожгут его и их, и не будет мерзости среди вас.'),
(3334, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 15, 'OT', 'И если человек ляжет ложе своё со скотом, смертью да будет предан, и скота того убейте.'),
(3335, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 16, 'OT', 'И если жена приблизится к какому-либо скоту, чтобы совокупиться с ним, то убей жену и скот; они должны быть преданы смерти, кровь их на них.'),
(3336, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 17, 'OT', 'И если человек возьмёт сестру свою, дочь отца своего или дочь матери своей, и увидит наготу её, и она увидит наготу его, — это милость; и они будут истреблены пред очами сынов народа своего; наготу сестры своей он открыл, беззаконие своё понесёт.'),
(3337, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 18, 'OT', 'И если человек ляжет с женой во время её месячного очищения и откроет её наготу, обнажив её источник, и она откроет источник своей крови, то оба они будут истреблены из среды своего народа.'),
(3338, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 19, 'OT', 'Наготу сестры твоей матери и сестры отца твоего не открывай; ибо он открыл близкого родственника своего, беззаконие их понесут.'),
(3339, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 20, 'OT', 'И если человек ляжет с тёткой своей, он открыл наготу дяди своего; они понесут грех свой, бездетными умрут.'),
(3340, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 21, 'OT', 'Человек, который возьмёт жену брата своего, — это нечистота; наготу брата своего он открыл, бездетными они будут.'),
(3341, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 22, 'OT', 'Соблюдайте все уставы Мои и все постановления Мои, и исполняйте их, и не извергнет вас земля, в которую Я веду вас, чтобы жить в ней.'),
(3342, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 23, 'OT', 'И не ходите по уставам народа, которого Я изгоняю от лица вашего, ибо они делали всё это, и Я возгнушался ими.'),
(3343, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 24, 'OT', 'И сказал я вам: вы наследуете их землю, и Я дам её вам во владение, землю, текущую молоком и мёдом; Я — Господь, Бог ваш, который отделил вас от народов.'),
(3344, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 25, 'OT', 'И отделяйте скот чистый от нечистого, и птицу нечистую от чистой, и не оскверняйте душ ваших скотом и птицею, и всем, что пресмыкается по земле, которое Я отделил вам как нечистое.'),
(3345, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 26, 'OT', 'И будете у Меня святы, ибо свят Я, Господь, и Я отделил вас от народов, чтобы вы были Моими.'),
(3346, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 20, 27, 'OT', 'И если человек или жена будет в них волшебник или волшебник, то смертью да будут умерщвлены; камнем побьют их, кровь их на них.'),
(3347, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 1, 'OT', 'И сказал Господь Моисею: скажи священникам, сынам Аарона, и объяви им: о мёртвом не должен оскверняться в народе своём.'),
(3348, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 2, 'OT', 'но только для близких родственников своих: для матери своей и для отца своего, и для сына своего, и для дочери своей, и для брата своего.'),
(3349, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 3, 'OT', 'и к сестре своей деве, близкой к нему, которая не была за человеком, — за неё он может оскверниться.'),
(3350, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 4, 'OT', 'Муж не осквернится среди народа своего, чтобы не обесчестить себя.'),
(3351, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 5, 'OT', 'Не должны они делать плешь на голове своей, и край бороды своей не должны сбривать, и на плоти своей не должны делать нарезки.'),
(3352, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 6, 'OT', 'Святыми да будут они для Бога своего, и не будут бесчестить имя Бога своего, ибо жертвы Господа, хлеб Бога своего, они приносят, и будут святыней.'),
(3353, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 7, 'OT', 'Жену блудницу и осквернённую не должны они брать, и жену, отвергнутую своим человеком, не должны они брать, ибо свят он для Бога своего.'),
(3354, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 8, 'OT', 'И освяти его, ибо он приносит хлеб Бога твоего; святым будет он для тебя, ибо свят Я, Господь, освящающий вас.'),
(3355, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 9, 'OT', 'И дочь человека-священника, если она начнёт блудить, она бесчестит своего отца: в огне она будет сожжена.'),
(3356, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 10, 'OT', 'Священник великий из братьев своих, на голову которого возлит елей помазания, и который посвятил себя, чтобы облачаться в одежды, голову свою не должен обнажать и одежды свои не должен раздирать.'),
(3357, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 11, 'OT', 'И ко всякому телу умершего не должен он входить; ради отца своего и ради матери своей не должен он оскверняться.'),
(3358, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 12, 'OT', 'И из святилища не выйдет, и не осквернит святилища Бога своего, ибо посвящение елея помазания Бога его на нём: Я Господь.'),
(3359, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 13, 'OT', 'И он жену в девственности её возьмёт.'),
(3360, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 14, 'OT', 'Вдову и разведённую, и осквернённую блудом, — таких он не должен брать, но только деву из народа своего пусть возьмёт в жёны.'),
(3361, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 15, 'OT', 'и не осквернит семени своего в народе своём, ибо Я Господь, освящающий его.'),
(3362, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 16, 'OT', 'И сказал Господь Моисею, говоря:'),
(3363, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 17, 'OT', 'Скажи Аарону: человек из семени твоего в роды их, у которого будет порок, пусть не приступает, чтобы приносить хлеб Бога своего.'),
(3364, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 18, 'OT', 'Ибо всякий человек, у которого есть порок, не должен приближаться: человек слепой или хромой, или с приплюснутым носом, или с излишним членом.'),
(3365, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 19, 'OT', 'или человек, у которого будет разрушение ноги или разрушение руки.'),
(3366, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 20, 'OT', 'или горбатый, или худой, или пятно в глазу его, или струп, или лишай, или камень на яичках'),
(3367, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 21, 'OT', 'Всякий человек, у которого есть порок, из семени Аарона, священника, не приблизится, чтобы приносить жертвы Господа; порок на нём, к хлебу Бога своего не приблизится, чтобы приносить.'),
(3368, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 22, 'OT', 'Хлеб Бога своего из святынь святых и из святынь он будет есть.'),
(3369, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 23, 'OT', 'Только к завесе не должен он входить, и к жертвеннику не должен приближаться, потому что порок на нём; и не должен он осквернять святилище Моё, ибо Я Господь, освящающий их.'),
(3370, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 21, 24, 'OT', 'И говорил Моисей к Аарону и к сынам его, и ко всем сынам Израиля.'),
(3371, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3372, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 2, 'OT', 'Скажи Аарону и сынам его, чтобы они отделялись от святынь сынов Израиля и не оскверняли святое имя Моё, которое они посвящают Мне; Я — Господь.'),
(3373, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 3, 'OT', 'Скажи им: в роды ваши, всякий человек из всего семени вашего, который приблизится к святыням, которые сыны Израиля посвящают Господу, и нечистота его на нём, — истребится душа та от лица Моего: Я Господь.'),
(3374, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 4, 'OT', 'Человек из семени Аарона, и он прокажённый или имеющий истечение, святынь не будет есть, пока не очистится; и прикасающийся ко всякому нечистому от мёртвого, или человек, из которого выйдет совокупление семени.'),
(3375, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 5, 'OT', 'или человек, который прикоснётся к какому-либо гаду, от которого он осквернится, или к человеку, от которого он осквернится, — ко всей его нечистоте.'),
(3376, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 6, 'OT', 'Человек, который прикоснётся к нему, будет нечист до вечера, и не будет есть от святыни, если только не омоет плоть свою водою.'),
(3377, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 7, 'OT', 'И зайдёт солнце, и он станет чистым, и после того будет есть от святыни, ибо это его хлеб.'),
(3378, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 8, 'OT', 'Мертвечины и растерзанного не должен он есть, чтобы оскверниться ею; Я Господь.'),
(3379, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 9, 'OT', 'И будут соблюдать службу Мою, и не понесут за него греха, и не умрут в нём, если осквернят его; Я Господь, освящающий их.'),
(3380, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 10, 'OT', 'И всякий посторонний не должен есть святыни; пришелец священника и наёмник не должны есть святыни.'),
(3381, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 11, 'OT', 'Священник, если купит душу за серебро, то это будет его имение, и он будет есть от него; и рождённый в доме его, они будут есть от хлеба его.'),
(3382, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 12, 'OT', 'И дочь священника, если она будет за человеком чужим, она от приношения святынь не будет есть.'),
(3383, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 13, 'OT', 'И если дочь священника будет вдовою или разведённою, и семени нет у неё, и возвратится в дом отца своего, как в юности своей, от хлеба отца своего будет есть; а всякий чужой не будет есть от него.'),
(3384, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 14, 'OT', 'И если человек съест святыню по заблуждению, то прибавит пятую часть её к ней и отдаст священнику святыню.'),
(3385, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 15, 'OT', 'И не должны они осквернять святыни сынов Израиля, которые те приносят в дар Господу.'),
(3386, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 16, 'OT', 'И пусть они понесут беззаконие вины, когда будут есть святыни их, ибо Я Господь, освящающий их.'),
(3387, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 17, 'OT', 'И сказал Господь Моисею, говоря:'),
(3388, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 18, 'OT', 'Скажи Аарону и сынам его и всем сынам Израиля, и скажи им: всякий человек из дома Израиля и из пришельцев в Израиле, который приносит своё приношение по всем своим обетам и по всем своим добровольным приношениям, которые они приносят Господу во всесожжение,'),
(3389, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 19, 'OT', 'для благоволения вашего, без порока, самец, из крупного рогатого скота, из ягнят и из коз.'),
(3390, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 20, 'OT', 'Всё, что имеет порок, не приносите, ибо не будет принято вам.'),
(3391, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 21, 'OT', 'И если человек принесёт жертву мирную Господу, чтобы исполнить обет или по приношению, из крупного рогатого скота или из овец, — она должна быть без порока, чтобы быть угодной; всё, что имеет порок, не должно быть в ней.'),
(3392, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 22, 'OT', 'Слепоту или перелом, или раздробление, или бородавку, или струп, или лишай — не приносите этих Господу, и жертвы не давайте из них на жертвенник Господу.'),
(3393, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 23, 'OT', 'Вола и овцу с изъяном и с недостатком в приношение сделаешь, но по обету не будет принято.'),
(3394, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 24, 'OT', 'Раздавленное, и разбитое, и оторванное, и отрезанное не приносите Господу, и в земле вашей не делайте этого.'),
(3395, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 25, 'OT', 'И из руки сына чужого не приносите хлеба Бога вашего из всего этого, ибо порча их в них, порок в них, не будут они угодны для вас.'),
(3396, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 26, 'OT', 'И сказал Господь Моисею, говоря:'),
(3397, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 27, 'OT', 'Вол, или ягнёнок, или коза, когда родится, и будет семь дней под матерью своей, а с восьмого дня и далее будет принят в приношение, жертву Господу.'),
(3398, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 28, 'OT', 'Вола или овцу — его и сына его — не заколайте в один день.'),
(3399, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 29, 'OT', 'И когда будете приносить жертву благодарности Господу, приносите её по вашему благоволению.'),
(3400, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 30, 'OT', 'В тот день это должно быть съедено; не оставляйте от него до утра; Я — Господь.'),
(3401, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 31, 'OT', 'Соблюдайте заповеди Мои и исполняйте их: Я Господь.'),
(3402, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 32, 'OT', 'И не оскверняйте имени святого Моего, и буду освящён среди сынов Израиля; Я Господь, освящающий вас.'),
(3403, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 22, 33, 'OT', 'выводящий вас из земли Египетской, чтобы быть вам Богом, — Я Господь.'),
(3404, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3405, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 2, 'OT', 'Скажи сынам Израиля и скажи им: праздники Господа, которые вы будете называть собраниями святыни, — вот они, праздники Мои.'),
(3406, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 3, 'OT', 'Шесть дней делай работу, а в седьмой день — суббота покоя, собрание святыни; никакой работы не делайте; это суббота Господу во всех жилищах ваших.'),
(3407, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 4, 'OT', 'Вот назначенные времена Господни, священные собрания, которые вы должны созывать в их назначенное время.'),
(3408, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 5, 'OT', 'В первом месяце, в четырнадцатый день месяца, между вечерами — Пасха Господу.'),
(3409, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 6, 'OT', 'И в пятнадцатый день этого месяца — праздник опресноков Господу; семь дней ешьте опресноки.'),
(3410, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 7, 'OT', 'В первый день будет у вас священное собрание; никакой работы служения не делайте.'),
(3411, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 8, 'OT', 'И приносите жертву Господу семь дней; в седьмой день — священное собрание, святыня, никакой работы служения не делайте.'),
(3412, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 9, 'OT', 'И сказал Господь Моисею, говоря:'),
(3413, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 10, 'OT', 'Скажи сынам Израиля и скажи им: когда придёте в землю, которую Я даю вам, и будете жать жатву её, то принесите сноп первинок жатвы вашей к священнику.'),
(3414, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 11, 'OT', 'И поднимет сноп пред лицом Господа, для благоволения вашего; в следующий день после субботы поднимет его священник.'),
(3415, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 12, 'OT', 'И в день возношения вами снопа принесите ягнёнка без порока, сына года своего, во всесожжение Господу.'),
(3416, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 13, 'OT', 'И приношение его — две десятых части муки, смешанной с елеем, жертва Господу, запах приятного благоухания; и возлияние его — вино, четверть гина.'),
(3417, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 14, 'OT', 'И хлеба, и жареного зерна, и свежих колосьев не ешьте до самого этого дня, пока не принесёте приношение Богу вашему; устав вечный для родов ваших во всех жилищах ваших.'),
(3418, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 15, 'OT', 'И отсчитайте себе от следующего дня после субботы, от дня, когда принесёте сноп потрясания, семь полных суббот.'),
(3419, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 16, 'OT', 'до следующего дня после седьмой субботы отсчитайте пятьдесят дней, и принесите хлебное приношение Господу.'),
(3420, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 17, 'OT', 'Из жилищ ваших приносите хлеб потрясания: две десятых части ефы муки пшеничной, квасное пусть будет испечено, первые плоды Господу.'),
(3421, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 18, 'OT', 'И принесите вместе с хлебом семь ягнят без порока, сынов года, и одного тельца из крупного рогатого скота, и двух овнов; они будут всесожжением Господу, и хлебное приношение их, и возлияния их, жертва, запах приятного благоухания Господу.'),
(3422, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 19, 'OT', 'И принесёте одного козла из коз в жертву за грех, и двух ягнят, сынов года, в жертву мирную.'),
(3423, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 20, 'OT', 'И пусть священник потрясёт их вместе с хлебом первого плода как потрясание пред лицом Господа, над двумя ягнятами; святынею будут они для Господа, для священника.'),
(3424, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 21, 'OT', 'И возгласите в самый день сей святое собрание будет вам, всякую работу служения не делайте; устав вечный во всех жилищах ваших для родов ваших.'),
(3425, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 22, 'OT', 'И когда будете жать жатву земли вашей, не дожинай края поля твоего при жатве твоей, и сбор остатков жатвы твоей не подбирай; бедному и пришельцу оставь их. Я Господь, Бог ваш.'),
(3426, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 23, 'OT', 'И сказал Господь Моисею, говоря:'),
(3427, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 24, 'OT', 'Скажи сынам Израиля: в седьмом месяце, в первый день месяца, будет у вас покой, память восклицания, святое собрание.'),
(3428, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 25, 'OT', 'Всякой работы не делайте, и приносите жертву Господу.'),
(3429, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 26, 'OT', 'И сказал Господь Моисею, говоря:'),
(3430, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 27, 'OT', 'Но в десятый день седьмого месяца сего — день очищения он есть, священное собрание святыни будет вам, и смирите души ваши, и принесите жертву Господу.'),
(3431, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 28, 'OT', 'И всякой работы не делайте в самый день этот, ибо день очищения он, чтобы очищать вас пред лицом Господа, Бога вашего.'),
(3432, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 29, 'OT', 'Ибо всякая душа, которая не будет смирять себя в этот самый день, будет истреблена из народа своего.'),
(3433, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 30, 'OT', 'И всякая душа, которая сделает всякую работу в самый этот день, — истреблю Я ту душу из среды народа её.'),
(3434, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 31, 'OT', 'Всякой работы не делайте; устав вечный для родов ваших во всех жилищах ваших.'),
(3435, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 32, 'OT', 'Суббота покоя будет для вас, и смиряйте души ваши; с девятого числа месяца, вечером, от вечера до вечера, празднуйте субботу вашу.'),
(3436, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 33, 'OT', 'И сказал Господь Моисею, говоря:'),
(3437, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 34, 'OT', 'Скажи сынам Израиля: в пятнадцатый день этого седьмого месяца — праздник кущ, семь дней для Господа.'),
(3438, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 35, 'OT', 'В первый день — святое собрание; никакой работы служения не делайте.'),
(3439, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 36, 'OT', 'Семь дней приносите жертву Господу; в восьмой день святое собрание будет у вас, и принесёте жертву Господу: это собрание, — никакой работы не делайте.'),
(3440, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 37, 'OT', 'Вот праздники Господни, которые вы должны созывать как святые собрания, чтобы приносить жертву Господу: всесожжение и хлебное приношение, жертву и возлияния, слово дня в день его.'),
(3441, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 38, 'OT', 'отдельно от суббот Господних, и отдельно от даров ваших, и отдельно от всех обетов ваших, и отдельно от всех приношений ваших, которые вы даёте Господу.'),
(3442, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 39, 'OT', 'Только в пятнадцатый день седьмого месяца, когда вы соберёте урожай земли, празднуйте праздник Господа семь дней; в первый день — покой, и в восьмой день — покой.'),
(3443, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 40, 'OT', 'И возьмите себе в первый день плод дерева великолепия, ветви пальм, и ветвь дерева густого, и ивы потока, и радуйтесь пред лицом Господа, Бога вашего, семь дней.'),
(3444, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 41, 'OT', 'И празднуйте его как праздник Господу семь дней в году; устав вечный для родов ваших: в седьмой месяц празднуйте его.'),
(3445, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 42, 'OT', 'В кущах живите семь дней; всякий туземец в Израиле пусть живёт в кущах.'),
(3446, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 43, 'OT', 'Чтобы знали роды ваши, что в кущах поселил Я сынов Израиля, когда вывел их из земли Египетской: Я Господь, Бог ваш.'),
(3447, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 23, 44, 'OT', 'И объявил Моисей праздники Господни сынам Израилевым.'),
(3448, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3449, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 2, 'OT', 'Вели сынам Израиля, и пусть возьмут они тебе елея маслины чистого, выбитого, для светила, чтобы возжигать светильник постоянный.'),
(3450, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 3, 'OT', 'Вне завесы, перед завесой свидетельства, в шатре собрания, будет расставлять его Аарон от вечера до утра перед лицом Господа постоянно; устав вечный для родов ваших.'),
(3451, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 4, 'OT', 'На чистом светильнике он будет расставлять светильники пред лицом Господа постоянно.'),
(3452, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 5, 'OT', 'И возьми муки, и испеки из неё двенадцать лепёшек; две десятых части эфы да будет на одну лепёшку.'),
(3453, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 6, 'OT', 'И положишь их в два ряда, по шесть хлебов предложения в каждом ряду, на чистый стол пред лицом Господа.'),
(3454, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 7, 'OT', 'И положишь на хлебы предложения чистый ладан, и будет он для хлеба памятной частью, жертвою Господу.'),
(3455, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 8, 'OT', 'В день субботы, в день субботы, он будет раскладывать его пред лицом Господа постоянно, от сынов Израиля — завет вечный.'),
(3456, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 9, 'OT', 'И будет это Аарону и сынам его, и пусть едят его на святом месте, ибо это святыня святынь ему из жертв Господа, устав вечный.'),
(3457, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 10, 'OT', 'И вышел сын жены Израильтянки, и он был сын человека Египтянина, в середине сынов Израиля, и сражались в стане сын Израильтянки и человек Израильтянин.'),
(3458, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 11, 'OT', 'Сын жены-израильтянки произнёс имя и проклял, и привели его к Моисею; а имя его матери — Селомиф, дочь Дибри, из колена Дана.'),
(3459, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 12, 'OT', 'И оставили его под стражей, чтобы объявить им по слову Господа.'),
(3460, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 13, 'OT', 'И сказал Господь Моисею, говоря:'),
(3461, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 14, 'OT', 'Выведи хулителя вне стана, и пусть все слышавшие возложат руки свои на главу его, и пусть всё общество побьёт его камнями.'),
(3462, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 15, 'OT', 'И сынам Израиля скажи: если человек, человек проклянёт Бога своего, то понесёт грех свой.'),
(3463, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 16, 'OT', 'И произносящий имя Господа смертью да будет умерщвлён; камнями побьёт его всё общество: как пришелец, так и туземец, за произнесение имени да будет предан смерти.'),
(3464, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 17, 'OT', 'И человек, если ударит всякую жизнь человека, смертью да будет предан.'),
(3465, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 18, 'OT', 'И ударивший жизнь скота заплатит за неё: жизнь за жизнь.'),
(3466, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 19, 'OT', 'Если человек причинит порок ближнему своему, то, как он сделал, так и ему будет сделано.'),
(3467, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 20, 'OT', 'разрушение за разрушение, око за око, зуб за зуб; как он нанёс порок человеку, так и ему будет нанесено.'),
(3468, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 21, 'OT', 'Кто убьёт скот, тот заплатит за него, а кто убьёт человека, тот будет предан смерти.'),
(3469, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 22, 'OT', 'Один суд будет у вас: как пришелец, так и туземец будет; ибо Я — Господь, Бог ваш.'),
(3470, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 24, 23, 'OT', 'И сказал Моисей сынам Израиля, и вывели проклинавшего за стан, и побили его камнями; и сыны Израиля сделали, как повелел Господь Моисею.'),
(3471, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 1, 'OT', 'И говорил Господь к Моисею на горе Синай, говоря:'),
(3472, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 2, 'OT', 'Скажи сынам Израиля и скажи им: когда придёте в землю, которую Я даю вам, то земля будет покоиться в субботу Господу.'),
(3473, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 3, 'OT', 'Шесть лет засевай поле твоё, и шесть лет обрезай виноградник твой, и собирай урожай его.'),
(3474, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 4, 'OT', 'А в седьмой год будет суббота покоя для земли, суббота Господу: поле твоё не засевай и виноградник твой не обрезай.'),
(3475, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 5, 'OT', 'Самородное растение жатвы твоей не жни, и виноград назорея твоего не собирай; год покоя будет земле.'),
(3476, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 6, 'OT', 'И будет суббота земли вам для пищи: тебе, и рабу твоему, и служанке твоей, и наёмнику твоему, и пришельцу твоему, живущему с тобою.'),
(3477, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 7, 'OT', 'И скоту твоему и животным, которые на земле твоей, будет весь доход её в пищу.'),
(3478, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 8, 'OT', 'И отсчитай себе семь субботних годов, семь лет семь раз; и будут у тебя дни семи субботних годов, сорок девять лет.'),
(3479, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 9, 'OT', 'И проведите трубу трубного звука в седьмом месяце, в десятый день месяца, в день очищения, проведите трубу по всей земле вашей.'),
(3480, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 10, 'OT', 'И освятите пятидесятый год, и провозгласите свободу на земле всем жителям её; юбилеем будет он для вас, и возвратитесь каждый человек во владение своё, и каждый человек в семейство своё возвратитесь.'),
(3481, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 11, 'OT', 'Юбилей он, пятидесятый год будет у вас; не сейте и не жните самородное растение её, и не собирайте назорей её.'),
(3482, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 12, 'OT', 'Ибо это юбилей, святынею будет он для вас; с поля ешьте урожай её.'),
(3483, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 13, 'OT', 'В этот юбилейный год возвращайтесь каждый человек во владение своё.'),
(3484, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 14, 'OT', 'И если будете продавать продажу ближнему своему, или покупать из руки ближнего своего, не обижайте один человека брата своего.'),
(3485, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 15, 'OT', 'По числу лет после юбилея покупай у ближнего твоего; по числу лет урожаев он продаст тебе.'),
(3486, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 16, 'OT', 'По множеству лет увеличивай куплю его, и по малости лет уменьшай куплю его, ибо число доходов он продаёт тебе.'),
(3487, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 17, 'OT', 'И не обижайте человек ближнего своего, и бойся Бога твоего, ибо Я Господь, Бог ваш.'),
(3488, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 18, 'OT', 'Исполняйте уставы Мои и постановления Мои соблюдайте, и исполняйте их, и будете жить на земле безопасно.'),
(3489, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 19, 'OT', 'И даст земля плод свой, и будете есть до насыщения, и будете жить в безопасности на ней.'),
(3490, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 20, 'OT', 'И если вы скажете: что нам есть в седьмой год, ведь мы не сеем и не собираем наш урожай?'),
(3491, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 21, 'OT', 'И повелю благословение Моё вам в шестой год, и оно принесёт урожай на три года.'),
(3492, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 22, 'OT', 'И посеете вы в восьмой год, и будете есть от урожая старое; до девятого года, до прихода урожая его, будете есть старое.'),
(3493, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 23, 'OT', 'И земля не должна продаваться навсегда, ибо Моя земля, и вы пришельцы и поселенцы у Меня.'),
(3494, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 24, 'OT', 'И во всей земле владения вашего дайте искупление земле.'),
(3495, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 25, 'OT', 'Если обеднеет брат твой и продаст из владения своего, то придёт к нему ближайший его родственник и выкупит проданное братом его.'),
(3496, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 26, 'OT', 'А если человек не будет иметь искупителя, но рука его достигнет и найдёт достаточно для его искупления,'),
(3497, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 27, 'OT', 'и исчислит годы продажи, и возвратит излишек тому человеку, которому он продал, и возвратится во владение своё.'),
(3498, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 28, 'OT', 'А если рука его не найдёт достаточно, чтобы возвратить ему, то проданное им останется в руке купившего его до юбилейного года, и в юбилей выйдет оно и возвратится во владение его.'),
(3499, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 29, 'OT', 'Если человек продаст дом жилища в городе, имеющем стену, то искупление его будет до конца года продажи его; дни будет искупление его.'),
(3500, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 30, 'OT', 'А если не будет выкуплен до полного года, то дом, который в городе без стены, останется навсегда у купившего его в роды его; не выйдет он в юбилей.'),
(3501, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 31, 'OT', 'А дома дворов, у которых нет стены вокруг, будут считаться наравне с полем земли; искупление будет ему, и в юбилей он выйдет.'),
(3502, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 32, 'OT', 'Города левитов, дома городов владения их, — вечное искупление будет левитам.'),
(3503, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 33, 'OT', 'И кто выкупит у левитов, то выйдет из продажи дома и города владения его в юбилей, ибо дома городов левитов — это владение их среди сынов Израиля.'),
(3504, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 34, 'OT', 'И поле предместья городов их не должно быть продано, ибо оно — владение вечное для них.'),
(3505, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 35, 'OT', 'И если обеднеет брат твой и ослабеет рука его у тебя, то поддержи его, пришелец и поселенец, и будет жить с тобою.'),
(3506, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 36, 'OT', 'Не бери с него лихвы и прироста, и бойся Бога твоего, и пусть живёт брат твой с тобою.'),
(3507, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 37, 'OT', 'Денег твоих не давай ему в лихву, и в множество не давай пищи твоей.'),
(3508, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 38, 'OT', 'Я Господь, Бог ваш, Который вывел вас из земли Египетской, чтобы дать вам землю Ханаанскую, чтобы быть вам Богом.'),
(3509, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 39, 'OT', 'И если обеднеет брат твой при тебе и продастся тебе, не налагай на него рабской работы раба.'),
(3510, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 40, 'OT', 'Как наёмник, как пришелец, он будет с тобою; до года юбилея он будет работать у тебя.'),
(3511, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 41, 'OT', 'И выйдет он от тебя, он и сыновья его с ним, и возвратится к семейству своему, и к владению отцов своих вернётся.'),
(3512, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 42, 'OT', 'Ибо они — рабы Мои, которых Я вывел из земли Египетской; не должны они быть проданы продажею раба.'),
(3513, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 43, 'OT', 'Не властвуй над ним с жестокостью, и бойся Бога твоего.'),
(3514, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 44, 'OT', 'И раб твой и служанка твоя, которые будут у тебя, — из народов, которые вокруг вас, из них покупайте раба и служанку.'),
(3515, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 45, 'OT', 'И также из сыновей пришельцев, живущих у вас, из них можете покупать, и из семейств их, которые у вас, которые родили в земле вашей; и будут они вам во владение.'),
(3516, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 46, 'OT', 'И передавайте их в наследство сыновьям вашим после вас, чтобы владеть ими как владением навечно; ими будете работать, а над братьями вашими, сынами Израиля, человек над братом своим не должен господствовать с жестокостью.'),
(3517, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 47, 'OT', 'И если достигнет рука пришельца и поселенца у тебя, и обеднеет брат твой при нём, и продастся пришельцу, поселенцу у тебя, или потомству семейства пришельца,'),
(3518, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 48, 'OT', 'После того как он продан, искупление будет ему; один из братьев его выкупит его.'),
(3519, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 49, 'OT', 'Или дядя его, или сын дяди его выкупит его, или кто-нибудь из близких родственников, из плоти его, из семейства его, выкупит его; или если достанет рука его, то он будет выкуплен.'),
(3520, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 50, 'OT', 'И рассчитается с покупателем своим от года продажи его ему до года юбилея; и будет цена продажи его по числу лет, как дни наёмника будет он с ним.'),
(3521, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 51, 'OT', 'Если ещё много лет остаётся, то по числу их он возвратит искупление своё из серебра купли своей.'),
(3522, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 52, 'OT', 'Если же немного останется лет до года юбилея, то пусть рассчитает с ним по числу своих лет; он возвратит своё искупление.'),
(3523, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 53, 'OT', 'Как наёмник, по году за год, он будет у него; не должен он господствовать над ним с жестокостью пред очами твоими.'),
(3524, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 54, 'OT', 'А если не будет выкуплен таким образом, то выйдет в год юбилея, он и сыновья его с ним.'),
(3525, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 25, 55, 'OT', 'Ибо Мне сыны Израиля — рабы; они — рабы Мои, которых Я вывел из земли Египетской. Я — Господь, Бог ваш.'),
(3526, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 1, 'OT', 'Не делайте себе идолов, и идола, и столба не ставьте себе, и камня с изображением не давайте в земле вашей, чтобы поклоняться на нём, ибо Я — Господь, Бог ваш.'),
(3527, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 2, 'OT', 'Субботы Мои соблюдайте и святилище Моё чтите; Я — Господь.'),
(3528, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 3, 'OT', 'Если по уставам Моим будете ходить и заповеди Мои соблюдать и исполнять их,'),
(3529, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 4, 'OT', 'И дам Я дожди ваши во время их, и земля даст плод свой, и дерево полевое даст плод свой.'),
(3530, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 5, 'OT', 'И достигнет у вас молотьба до сбора винограда, и сбор винограда достигнет до посева семени, и будете есть хлеб ваш до насыщения, и будете жить в безопасности на земле вашей.'),
(3531, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 6, 'OT', 'И дам Я мир на земле, и будете лежать, и не будет устрашающего; и удалю Я злого зверя с земли, и меч не пройдёт по земле вашей.'),
(3532, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 7, 'OT', 'И вы будете преследовать врагов ваших, и они падут пред лицом вашим от меча.'),
(3533, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 8, 'OT', 'И будут преследовать из вас пятеро сто, и сто из вас тьму погонят, и падут враги ваши пред лицом вашим от меча.'),
(3534, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 9, 'OT', 'И обращусь Я к вам, и сделаю вас плодовитыми, и размножу вас, и поставлю завет Мой с вами.'),
(3535, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 10, 'OT', 'И будете есть старое, и старое пред лицом нового вынесете.'),
(3536, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 11, 'OT', 'И поставлю скинию Мою среди вас, и не возгнушается душа Моя вами.'),
(3537, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 12, 'OT', 'И буду ходить среди вас, и буду вам Богом, а вы будете Мне народом.'),
(3538, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 13, 'OT', 'Я Господь, Бог ваш, Который вывел вас из земли Египетской, чтобы вы не были им рабами, и сокрушил ярмо вашего ига, и повёл вас с поднятой головой.'),
(3539, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 14, 'OT', 'А если не послушаете Меня и не исполните всех этих заповедей'),
(3540, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 15, 'OT', 'Если же уставы Мои вы презрите, и если постановления Мои возгнушает душа ваша, так что не будете исполнять все заповеди Мои, нарушая завет Мой,'),
(3541, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 16, 'OT', 'И если Я сделаю это вам, то пошлю на вас ужас, чахотку и горячку, которые истребляют глаза и томят душу; и будете сеять семя ваше в тщете, и враги ваши съедят его.'),
(3542, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 17, 'OT', 'И обращу лицо Моё против вас, и будете поражены пред лицом врагов ваших, и будут господствовать над вами ненавидящие вас, и побежите, когда никто не преследует вас.'),
(3543, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 18, 'OT', 'И если вы и после этого не послушаете Меня, то Я прибавлю наказание вам всемеро за грехи ваши.'),
(3544, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 19, 'OT', 'И сокрушу гордость силы вашей, и сделаю небо ваше как железо, и землю вашу как медь.'),
(3545, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 20, 'OT', 'И тщетой истощится сила ваша, и не даст земля ваша плода своего, и дерево земли не даст плода своего.'),
(3546, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 21, 'OT', 'И если пойдете со Мною в противность и не захотите слушать Меня, то прибавлю вам наказание семь раз по грехам вашим.'),
(3547, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 22, 'OT', 'И пошлю на вас зверей полевых, и они лишат вас детей, и истребят скот ваш, и умалят вас, и опустеют пути ваши.'),
(3548, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 23, 'OT', 'И если при этом вы не будете наказаны Мною, и пойдете со Мною в противность'),
(3549, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 24, 'OT', 'И пойду и Я с вами в противность, и поражу вас также Я семь раз за грехи ваши.'),
(3550, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 25, 'OT', 'И наведу на вас меч, мстящий местью завета, и соберётесь вы в города ваши, и пошлю мор в среду вашу, и будете отданы в руку врага.'),
(3551, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 26, 'OT', 'Когда Я сокрушу у вас жезл хлеба, и десять жён испекут ваш хлеб в одной печи, и будут возвращать ваш хлеб по весу, и вы будете есть, но не насытитесь.'),
(3552, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 27, 'OT', 'И если при этом не послушаете Меня и пойдёте со Мною в противность,'),
(3553, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 28, 'OT', 'И пойду с вами в ярости против вас, и накажу вас также Я семикратно за грехи ваши.'),
(3554, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 29, 'OT', 'И будете есть плоть сыновей ваших, и плоть дочерей ваших будете есть.'),
(3555, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 30, 'OT', 'Истреблю высоты ваши, и сокрушу идолов ваших, и положу трупы ваши на трупы идолов ваших, и возгнушается душа Моя вами.'),
(3556, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 31, 'OT', 'И сделаю города ваши развалинами, и опустошу святилища ваши, и не буду обонять запаха приятного благоухания вашего.'),
(3557, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 32, 'OT', 'И Я опустошу землю, и враги ваши, живущие на ней, изумятся над нею.'),
(3558, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 33, 'OT', 'И вас рассею среди народов, и обнажу за вами меч, и будет земля ваша запустением, и города ваши будут развалинами.'),
(3559, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 34, 'OT', 'Тогда земля возместит свои субботы во все дни своего запустения, когда вы будете в земле врагов ваших; тогда земля будет покоиться и возместит свои субботы.'),
(3560, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 35, 'OT', 'все дни запустения она будет покоиться, то, что не покоилось в ваши субботы, когда вы жили на ней'),
(3561, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 36, 'OT', 'И оставшиеся из вас, и Я вложу расслабление в сердце их в землях врагов их, и погонится за ними голос листа, гонимого ветром, и побегут они бегством от меча, и падут, и не будет преследующего.'),
(3562, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 37, 'OT', 'И споткнутся человек о брата своего, как от лица меча, и погони нет, и не будет вам восстания пред лицом врагов ваших.'),
(3563, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 38, 'OT', 'И погибнете вы среди народов, и пожрёт вас земля врагов ваших.'),
(3564, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 39, 'OT', 'И оставшиеся из вас истлеют в беззаконии своём в землях врагов ваших, и также в беззакониях отцов своих с ними истлеют.'),
(3565, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 40, 'OT', 'И исповедуют беззаконие своё и беззаконие отцов своих в преступлении своём, которым они преступили против Меня, и также в том, что они ходили со Мною в противности.'),
(3566, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 41, 'OT', 'И Я пойду с ними в противность и приведу их в землю врагов их; тогда смирится необрезанное сердце их, и тогда они понесут беззаконие своё.'),
(3567, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 42, 'OT', 'И вспомню Я завет Мой с Иаковом, и также завет Мой с Исааком, и также завет Мой с Авраамом вспомню, и землю вспомню.'),
(3568, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 43, 'OT', 'И земля будет оставлена ими и будет наслаждаться своими субботами, будучи опустошена от них, а они будут нести своё беззаконие, за то, что отвергли суды Мои и уставы Мои возгнушалась душа их.'),
(3569, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 44, 'OT', 'И даже и тогда, когда они будут в земле врагов своих, Я не отвергну их и не возгнушаюсь ими, чтобы истребить их, нарушив завет Мой с ними; ибо Я Господь, Бог их.'),
(3570, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 45, 'OT', 'И вспомню Я для них завет прежних, которых Я вывел их из земли Египетской пред очами народов, чтобы быть им Богом: Я Господь.'),
(3571, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 26, 46, 'OT', 'Вот эти уставы и суды и законы, которые дал Господь между Собою и между сынами Израиля на горе Синай через руку Моисея.'),
(3572, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3573, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 2, 'OT', 'Скажи сынам Израиля и скажи им: если человек даст обет по оценке душ Господу,'),
(3574, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 3, 'OT', 'И будет оценка твоя мужчине от сына двадцати лет и до сына шестидесяти лет, и будет оценка твоя пятьдесят сиклей серебра по сиклю святыни.'),
(3575, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 4, 'OT', 'Если же это женщина, то оценка твоя — тридцать сиклей.'),
(3576, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 5, 'OT', 'А если от сына пяти лет и до сына двадцати лет, то оценка твоя для мужчины — двадцать сиклей, а для женщины — десять сиклей.'),
(3577, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 6, 'OT', 'А если от сына месяца и до сына пяти лет, то будет оценка твоя: мужчина — пять сиклей серебра, а женщина — оценка твоя: три сикля серебра.'),
(3578, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 7, 'OT', 'А если от сына шестидесяти лет и выше, если мужчина, то оценка твоя — пятнадцать сиклей, а для женщины — десять сиклей.'),
(3579, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 8, 'OT', 'А если он беден для оценки твоей, то пусть поставят его пред лицо священника, и оценит его священник; по мере того, что достанет рука дающего обет, оценит его священник.'),
(3580, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 9, 'OT', 'Если же это скот, из которого приносят приношение Господу, то всё, что отдаст из него Господу, будет святыней.'),
(3581, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 10, 'OT', 'Не заменит его и не обменяет его, доброе на худое или худое на доброе; а если он обменяет скот на скот, то будет он и возмездие его святынею.'),
(3582, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 11, 'OT', 'И если весь скот нечистый, которого не приносят из него приношение Господу, то он поставит этот скот перед лицом священника.'),
(3583, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 12, 'OT', 'И оценит её священник, между хорошим и худым; по оценке священника так и будет.'),
(3584, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 13, 'OT', 'Если же он выкупит её, то прибавит пятую часть к оценке твоей.'),
(3585, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 14, 'OT', 'И если человек посвятит дом свой как святыню Господу, то пусть оценит его священник, хорош ли он или плох; как оценит его священник, так и будет.'),
(3586, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 15, 'OT', 'Если же освятивший выкупит свой дом, то пусть добавит пятую часть денег к оценке твоей, и будет оно его.'),
(3587, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 16, 'OT', 'И если поле своего владения посвятит человек Господу, то будет оценка твоя по количеству посева его: семя хомер ячменя в пятьдесят сиклей серебра.'),
(3588, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 17, 'OT', 'Если от юбилейного года посвятит он поле своё, по оценке твоей оно утвердится.'),
(3589, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 18, 'OT', 'И если после юбилея он посвятит своё поле, то священник рассчитает ему деньги по числу лет, оставшихся до года юбилея, и будет вычтено из твоей оценки.'),
(3590, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 19, 'OT', 'Если же выкупающий выкупит поле, посвятивший его, то пусть прибавит пятую часть денег к оценке твоей, и оно останется за ним.'),
(3591, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 20, 'OT', 'Если же он не выкупит поле, и если продаст поле другому человеку, то оно уже не будет выкуплено.'),
(3592, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 21, 'OT', 'И будет поле при выходе в юбилей святынею Господу, как поле заклятия; священнику будет владение его.'),
(3593, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 22, 'OT', 'Если же он посвятит Господу купленное им поле, которое не из поля его владения,'),
(3594, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 23, 'OT', 'И исчислит ему священник сумму оценки до года юбилея, и отдаст оценку в тот день, как святыню Господу.'),
(3595, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 24, 'OT', 'В год юбилея поле вернётся к тому, кто купил его у него, к тому, чьё владение — земля.'),
(3596, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 25, 'OT', 'И вся оценка твоя будет по сиклю святыни: двадцать гер будет сикль.'),
(3597, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 26, 'OT', 'Впрочем, первенца из скота, который первенцем принадлежит Господу, не посвятит человек его; если вол или овца, — Господу он.'),
(3598, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 27, 'OT', 'Если же это из скота нечистого, то пусть выкупит его по твоей оценке и прибавит к ней пятую часть; если же не будет выкуплен, то пусть будет продан по твоей оценке.'),
(3599, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 28, 'OT', 'Впрочем, всё заклятие, которое заклятит человек для Господа из всего, что у него, из человека и скота и из поля владения его, не будет продано и не будет выкуплено; всё заклятие — святыня святынь оно для Господа.'),
(3600, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 29, 'OT', 'Всё заклятие, которое будет заклято из человека, не будет выкуплено; смертью будет предан смерти.'),
(3601, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 30, 'OT', 'И вся десятина с земли, из семени земли, из плода дерева, — Господня она; святыня Господня.'),
(3602, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 31, 'OT', 'Если же человек выкупит что-либо из своей десятины, то пусть прибавит к ней пятую часть её.'),
(3603, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 32, 'OT', 'И всякая десятина из крупного рогатого скота и овец, всё, что проходит под жезлом, десятое будет святынею Господу.'),
(3604, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 33, 'OT', 'Не будет он разбирать между хорошим и худым и не заменит его; а если заменит его, то будет он и возмездие его святынею, не будет выкуплено.'),
(3605, 3, 'GOI_Ru', 'GOI_Ru', 'ru', 'LEV', 27, 34, 'OT', 'Вот эти заповеди, которые Господь заповедал Моисею для сынов Израиля на горе Синай.'),
(3606, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 1, 'OT', 'Господь говорил Моисею в пустыне Синайской, в шатре собрания, в первый день второго месяца, во второй год по выходе их из земли Египетской, говоря:'),
(3607, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 2, 'OT', 'Произведите перепись всего общества сынов Израиля по семействам их, по дому отцов их, по числу имён, всех мужчин по головам их.'),
(3608, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 3, 'OT', 'От двадцати лет и выше, все выходящие на военную службу в Израиле, исчислите их по их службам, ты и Аарон.'),
(3609, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 4, 'OT', 'И с вами будут, каждый человек по колену, человек, глава дома отцов своих, он.'),
(3610, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 5, 'OT', 'И вот имена людей, которые будут стоять с вами: для Рувима — Елицур, сын Шедеура.'),
(3611, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 6, 'OT', 'Симеону — Шелумиил, сын Цуришаддая.'),
(3612, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 7, 'OT', 'Иуде — Наассон, сын Аминадава.'),
(3613, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 8, 'OT', 'Иссахару — Нафанаил, сын Цуара.'),
(3614, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 9, 'OT', 'Завулону — Елиав, сын Хелона.'),
(3615, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 10, 'OT', 'Сыновьям Иосифа: для Ефрема — Елишама, сын Аммиуда; для Манассии — Гамалиил, сын Педацура.'),
(3616, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 11, 'OT', 'Вениамину — Авидан, сын Гедеони.'),
(3617, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 12, 'OT', 'Дану — Ахиезер, сын Аммишаддая.'),
(3618, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 13, 'OT', 'Для Асира — Пагиил, сын Окрана.'),
(3619, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 14, 'OT', 'Гаду — Елиасаф, сын Деуила.'),
(3620, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 15, 'OT', 'Неффалиму — Ахира, сын Енана.'),
(3621, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 16, 'OT', 'Это призванные в общество, князья колен отцов их, главы тысяч Израиля, они.'),
(3622, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 17, 'OT', 'Взял Моисей и Аарон этих людей, которые были названы по именам.'),
(3623, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 18, 'OT', 'И собрали всё общество в первый день второго месяца, и записались они по семействам своим, по домам отцов своих, по числу имён, от двадцати лет и выше, по головам их.'),
(3624, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 19, 'OT', 'Как повелел Господь Моисею, и он исчислил их в пустыне Синайской.'),
(3625, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 20, 'OT', 'Сыновья Рувима, первенца Израиля, по их родословиям, по их семействам, по домам их отцов, по числу имён, по головам их, все мужчины от двадцати лет и выше, все выходящие на военную службу.'),
(3626, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 21, 'OT', 'исчисленных их по колену Рувима: сорок шесть тысяч пятьсот'),
(3627, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 22, 'OT', 'Сыновьям Симеона, по родословиям их, по семействам их, по домам отцов их, исчисленные по числу имён, по головам их, все мужчины от двадцати лет и выше, все выходящие на войско.'),
(3628, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 23, 'OT', 'Исчисленных их от колена Симеона: пятьдесят девять тысяч триста.'),
(3629, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 24, 'OT', 'Сыновьям Гада по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие на войско.'),
(3630, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 25, 'OT', 'исчисленных их по колену Гада сорок пять тысяч шестьсот пятьдесят'),
(3631, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 26, 'OT', 'Сыновьям Иуды по родословиям их, по семействам их, по дому отцов их, по числу имён, от двадцати лет и выше, все выходящие в войско.'),
(3632, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 27, 'OT', 'Исчисленных в колене Иуды — семьдесят четыре тысячи шестьсот.'),
(3633, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 28, 'OT', 'Сыновьям Иссахара по родословиям их, по семействам их, по дому отцов их, по числу имён, от двадцати лет и выше, все выходящие в войско.'),
(3634, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 29, 'OT', 'Исчисленных в колене Иссахара — пятьдесят четыре тысячи четыреста.'),
(3635, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 30, 'OT', 'Сыновьям Завулона по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие на войско.'),
(3636, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 31, 'OT', 'исчисленных их в колене Завулона — семь тысяч четыреста пятьдесят'),
(3637, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 32, 'OT', 'Сыновьям Иосифа, сыновьям Ефрема, по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие в войско.'),
(3638, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 33, 'OT', 'исчисленных их по колену Ефрема сорок тысяч пятьсот'),
(3639, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 34, 'OT', 'Сыновьям Манассии по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие в войско.'),
(3640, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 35, 'OT', 'исчисленных их по колену Манассии: тридцать две тысячи двести'),
(3641, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 36, 'OT', 'Сыновьям Вениамина по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие на войско.'),
(3642, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 37, 'OT', 'Исчислено их по колену Вениамина: тридцать пять тысяч четыреста.'),
(3643, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 38, 'OT', 'Сыновьям Дана, по родословиям их, по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие на войну.'),
(3644, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 39, 'OT', 'Исчисленных в колене Дана — шестьдесят две тысячи семьсот.'),
(3645, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 40, 'OT', 'Сынам Асира по родословиям их, по семействам их, по дому отцов их, по числу имён, от двадцати лет и выше, все выходящие на войну.'),
(3646, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 41, 'OT', 'Исчисленных в колене Асира было сорок одна тысяча пятьсот.'),
(3647, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 42, 'OT', 'Сыны Неффалима, родословия их по семействам их, по домам отцов их, по числу имён, от двадцати лет и выше, все выходящие на войну.'),
(3648, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 43, 'OT', 'исчисленных их по колену Неффалима: пятьдесят три тысячи четыреста'),
(3649, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 44, 'OT', 'Вот эти перечисленные, которых перечислили Моисей и Аарон и князья Израиля, двенадцать человек, по одному человеку от дома отцов их, были.'),
(3650, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 45, 'OT', 'И было всех исчисленных из сынов Израиля по домам отцов их, от двадцати лет и выше, всех способных на войну в Израиле'),
(3651, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 46, 'OT', 'И было всех исчисленных шестьсот тысяч и три тысячи пятьсот пятьдесят.'),
(3652, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 47, 'OT', 'Левиты же по колену отцов своих не были перечислены среди них.'),
(3653, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 48, 'OT', 'И сказал Господь Моисею, говоря:'),
(3654, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 49, 'OT', 'Только колено Левия не пересчитывай и перепись их не проводи среди сынов Израиля.'),
(3655, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 50, 'OT', 'И ты поручи левитам над скинией свидетельства, и над всеми её сосудами, и над всем, что у неё; они будут носить скинию и все её сосуды, и они будут служить ей, и вокруг скинии пусть располагаются станом.'),
(3656, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 51, 'OT', 'И когда двинется скиния, снимут её левиты, и когда остановится скиния, поставят её левиты; а посторонний, приближающийся, будет предан смерти.'),
(3657, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 52, 'OT', 'И расположились станом сыны Израиля, каждый человек при стане своём, и каждый человек при знамени своём, по войскам своим.'),
(3658, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 53, 'OT', 'Левиты должны становиться станом вокруг скинии свидетельства, и не будет ярости на общество сынов Израиля; и левиты будут нести стражу скинии свидетельства.'),
(3659, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 1, 54, 'OT', 'Сыны Израиля сделали всё, что Господь заповедал Моисею; так они и сделали.'),
(3660, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 1, 'OT', 'И сказал Господь Моисею и Аарону, говоря:'),
(3661, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 2, 'OT', 'Человек при знамени своём, при знамениях дома отцов своих, пусть становятся станом сыны Израиля; напротив, вокруг шатра собрания пусть становятся станом.'),
(3662, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 3, 'OT', 'И расположившиеся станом к востоку, на восток, — знамя стана Иуды по войскам их; и князь сынов Иуды — Наассон, сын Аминадава.'),
(3663, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 4, 'OT', 'и войско его, и исчисленных в нём: четыре и семьдесят тысяч и шестьсот'),
(3664, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 5, 'OT', 'И стоящие станом при нём — колено Иссахара; и князь у сынов Иссахара — Нафанаил, сын Цуара.'),
(3665, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 6, 'OT', 'и войско его, и исчисленных в нём: пятьдесят четыре тысячи четыреста.'),
(3666, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 7, 'OT', 'Колено Завулона, и князь сынов Завулона — Елиав, сын Хелона.'),
(3667, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 8, 'OT', 'и войско его, и исчисленных в нём: пятьдесят семь тысяч четыреста'),
(3668, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 9, 'OT', 'Всё исчисленное для стана Иуды: сто восемьдесят шесть тысяч четыреста, по войскам их; первыми они отправятся.'),
(3669, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 10, 'OT', 'Знамя стана Рувимова к югу, по войскам их; и князь сынов Рувима — Елицур, сын Шедеура.'),
(3670, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 11, 'OT', 'И войско его, и исчисленных в нём: сорок шесть тысяч пятьсот.'),
(3671, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 12, 'OT', 'И стоящие станом при нём — колено Симеона, и князь сынов Симеона — Шелумиил, сын Цуришаддая.'),
(3672, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 13, 'OT', 'И войско его, и исчисленные в нём: пятьдесят девять тысяч триста.'),
(3673, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 14, 'OT', 'И колено Гада, и князь у сынов Гада — Елиасаф, сын Рагуила.'),
(3674, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 15, 'OT', 'и войско его, и исчисленные в нём: сорок пять тысяч шестьсот пятьдесят.'),
(3675, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 16, 'OT', 'Всё исчисленное для стана Рувима: сто пятьдесят одна тысяча четыреста пятьдесят, по войскам их; и они отправятся вторыми.'),
(3676, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 17, 'OT', 'И двинется шатёр собрания, стан левитов, в середине станов; как они располагаются станом, так и будут двигаться, каждый человек при своём месте, по знамёнам своим.'),
(3677, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 18, 'OT', 'Знамя стана Ефрема по войскам их к морю, и князь сынов Ефрема Елишама, сын Аммиуда.'),
(3678, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 19, 'OT', 'и войско его, и исчисленных в нём: сорок тысяч пятьсот'),
(3679, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 20, 'OT', 'И рядом с ним колено Манассии, и князь у сынов Манассии Гамалиил, сын Педацура.'),
(3680, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 21, 'OT', 'И войско его, и исчисленные в нём: тридцать две тысячи двести.'),
(3681, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 22, 'OT', 'И колено Вениамина, и князь сынов Вениамина — Авидан, сын Гедеони.'),
(3682, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 23, 'OT', 'и войско его, и исчисленных в нём: тридцать пять тысяч четыреста'),
(3683, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 24, 'OT', 'Все исчисленные для стана Ефрема: сто тысяч восемь тысяч и сто, по войскам их; и они отправятся третьими.'),
(3684, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 25, 'OT', 'Знамя стана Данова — к северу, по войскам их; и князь сынов Дана — Ахиезер, сын Аммишаддая.'),
(3685, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 26, 'OT', 'и войско его, и исчисленных в нём: двадцать шесть тысяч семьсот'),
(3686, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 27, 'OT', 'И расположившиеся станом при нём — колено Асира; и князь у сынов Асира — Пагиил, сын Окрана.'),
(3687, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 28, 'OT', 'и войско его, и исчисленных в нём: двадцать одна тысяча пятьсот.'),
(3688, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 29, 'OT', 'И колено Неффалима, и князь сынов Неффалима Ахира, сын Енана.'),
(3689, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 30, 'OT', 'и войско его, и исчисленных в нём: тридцать пять тысяч четыреста.'),
(3690, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 31, 'OT', 'Все исчисленные в стане Дана — сто тысяч пятьдесят семь тысяч шестьсот; последними отправляются по знамёнам своим.'),
(3691, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 32, 'OT', 'Вот перечисленные сыны Израиля по домам отцов их: все исчисленные в станах по войскам их — шестьсот три тысячи пятьсот пятьдесят.'),
(3692, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 33, 'OT', 'Левиты же не были пересчитаны среди сынов Израиля, как повелел Господь Моисею.'),
(3693, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 2, 34, 'OT', 'И сделали сыны Израиля всё, как повелел Господь Моисею: так становились станом по знамёнам своим, и так отправлялись в путь, каждый человек по семействам своим, при доме отцов своих.'),
(3694, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 1, 'OT', 'И вот родословие Аарона и Моисея в день, когда Господь говорил с Моисеем на горе Синай.'),
(3695, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 2, 'OT', 'И вот имена сыновей Аарона: первенец Надав, и Авиуд, Елеазар и Ифамар.'),
(3696, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 3, 'OT', 'Вот имена сыновей Аарона, священников помазанных, которых он посвятил, чтобы священнодействовать.'),
(3697, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 4, 'OT', 'И умерли Надав и Авиуд пред лицом Господа, когда принесли огонь чуждый пред лицо Господа в пустыне Синай, и сыновей не было у них; и священнодействовали Елеазар и Ифамар пред лицом Аарона, отца их.'),
(3698, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 5, 'OT', 'И сказал Господь Моисею, говоря:'),
(3699, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 6, 'OT', 'Подведи колено Левия и поставь его пред лицом Аарона, священника, и пусть они служат ему.'),
(3700, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 7, 'OT', 'И будут они нести служение его и служение всего общества пред лицом шатра собрания, чтобы совершать служение скинии.'),
(3701, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 8, 'OT', 'И будут они хранить все сосуды шатра собрания и служение сынов Израиля, чтобы совершать служение скинии.'),
(3702, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 9, 'OT', 'Отдай левитов Аарону и сыновьям его; отданными, отданными они ему от сыновей Израиля.'),
(3703, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 10, 'OT', 'Поручи Аарону и сыновьям его, и пусть они охраняют священство своё; а посторонний, приближающийся, будет предан смерти.'),
(3704, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 11, 'OT', 'И сказал Господь Моисею, говоря:'),
(3705, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 12, 'OT', 'И вот, Я взял левитов из среды сынов Израиля вместо всех первенцев, открывающих матку, из сынов Израиля, и будут левиты Моими.'),
(3706, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 13, 'OT', 'Ибо Мне принадлежит всякий первенец; в день, когда Я поразил всех первенцев в земле Египетской, Я освятил Себе всех первенцев в Израиле, от человека до скота; Моими они будут: Я Господь.'),
(3707, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 14, 'OT', 'И сказал Господь Моисею в пустыне Синай, говоря:'),
(3708, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 15, 'OT', 'Перечисли сынов Левия по дому отцов их, по семействам их: всех мужского пола от месяца и старше перечисли их.'),
(3709, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 16, 'OT', 'И исчислил их Моисей по слову Господа, как было повелено.'),
(3710, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 17, 'OT', 'И были эти сыны Левия по именам их: Герсон и Кааф и Мерари.'),
(3711, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 18, 'OT', 'И вот имена сыновей Герсона по их семействам: Ливни и Симей.'),
(3712, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 19, 'OT', 'Сыновья Каафа по семействам их: Амрам и Ицгар, Хеврон и Озиил.'),
(3713, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 20, 'OT', 'Сыновья Мерари по семействам их: Махли и Муший; это семейства левитов по дому отцов их.'),
(3714, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 21, 'OT', 'Герсону — семейство Ливнитов и семейство Шимеянина; это семейства Герсонитянина.'),
(3715, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 22, 'OT', 'Исчисленных их, по числу всех мужского пола, от сына месяца и выше, исчисленных их — семь тысяч пятьсот.'),
(3716, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 23, 'OT', 'Семейства Герсонитян позади скинии станут станом, к морю.'),
(3717, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 24, 'OT', 'Князь дома отца Герсонитянина — Елиасаф, сын Лаела.'),
(3718, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 25, 'OT', 'Обязанность сынов Герсона при шатре собрания: скиния и шатёр, покрывало его и завеса двери шатра собрания.'),
(3719, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 26, 'OT', 'и завесы двора, и завесу двери двора, которая вокруг скинии и жертвенника, и верви его для всего служения его.'),
(3720, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 27, 'OT', 'И Каафу — семейство Амрамитян, и семейство Ицгаритов, и семейство Хевронитян, и семейство Оззиелитов; вот они — семейства Каафитян.'),
(3721, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 28, 'OT', 'По числу всех мужского пола, от сына месяца и выше, восемь тысяч шестьсот, стерегущих стражу святыни.'),
(3722, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 29, 'OT', 'Семейства сынов Каафа станут станом на южной стороне скинии, у бока её.'),
(3723, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 30, 'OT', 'Князь дома отца для семейств Каафитян — Елицафан, сын Озиила.'),
(3724, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 31, 'OT', 'И обязанность их — ковчег и стол, и светильник, и жертвенники, и сосуды святыни, которыми служат при них, и завеса, и всё служение его.'),
(3725, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 32, 'OT', 'Князь князей левитов — Елеазар, сын Аарона священника, надзор за стражами обязанности святыни.'),
(3726, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 33, 'OT', 'У Мерари — семейство Махлитов и семейство Мушитов; это семейства Мерари.'),
(3727, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 34, 'OT', 'И перечисленных их по числу всех мужского пола, от месяца и выше, шесть тысяч двести.'),
(3728, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 35, 'OT', 'Князь дома отца для семейств Мерари — Цуриил, сын Авихаила; у бока скинии они будут станом на север.'),
(3729, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 36, 'OT', 'Попечение об обязанности сынов Мерари: доски скинии, и засовы её, и столбы её, и подножия её, и все сосуды её, и всё служение её.'),
(3730, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 37, 'OT', 'И столбы двора вокруг, и подножия их, и колья их, и верви их.'),
(3731, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 38, 'OT', 'И стоящие станом пред лицом скинии к востоку, пред лицом шатра собрания, к востоку, Моисей и Аарон и сыновья его, охраняющие стражу святилища, для стражи сынов Израиля; а посторонний, приближающийся, будет предан смерти.'),
(3732, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 39, 'OT', 'Всё исчисленное из левитов, которых исчислил Моисей и Аарон по повелению Господа, по семействам их, всё мужского пола от сына месяца и выше, двадцать две тысячи.'),
(3733, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 40, 'OT', 'И сказал Господь Моисею: исчисли всех первенцев мужского пола у сынов Израиля, от месяца и выше, и возьми число имён их.'),
(3734, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 41, 'OT', 'И возьми левитов для Меня, Я Господь, вместо всех первенцев у сынов Израиля, и скот левитов вместо всех первенцев в скоте у сынов Израиля.'),
(3735, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 42, 'OT', 'И пересчитал Моисей, как повелел ему Господь, всех первенцев среди сынов Израиля.'),
(3736, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 43, 'OT', 'И было всех первенцев мужского пола по числу имён, от сына одного месяца и выше, по перечислению их: двадцать две тысячи двести семьдесят три.'),
(3737, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 44, 'OT', 'И сказал Господь Моисею, говоря:'),
(3738, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 45, 'OT', 'Возьми левитов вместо всех первенцев среди сынов Израиля, и скот левитов вместо их скота; и будут левиты Моими: Я Господь.'),
(3739, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 46, 'OT', 'И искупленные из двухсот семидесяти трёх, превышающих левитов, из первенцев сынов Израиля'),
(3740, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 47, 'OT', 'возьми пять сиклей на голову, по сиклю святыни возьми, двадцать гер — сикль.'),
(3741, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 48, 'OT', 'Отдай деньги Аарону и сыновьям его, искупленных излишних среди них.'),
(3742, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 49, 'OT', 'И взял Моисей деньги выкупа от тех, которые были сверх числа искупленных левитов.'),
(3743, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 50, 'OT', 'У первенцев сынов Израиля взял он деньги: тысяча триста шестьдесят пять сиклей, по сиклю святыни.'),
(3744, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 3, 51, 'OT', 'И отдал Моисей деньги искупленных Аарону и сыновьям его по повелению Господа, как повелел Господь Моисею.'),
(3745, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 1, 'OT', 'И сказал Господь Моисею и Аарону, говоря:'),
(3746, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 2, 'OT', 'Исчисли перепись сынов Каафа из среды сынов Левия по семействам их, по домам отцов их.'),
(3747, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 3, 'OT', 'От сына тридцати лет и выше и до сына пятидесяти лет, все входящие на службу, чтобы делать работу в шатре собрания.'),
(3748, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 4, 'OT', 'Это служение сынов Каафа в шатре собрания: святыня святынь.'),
(3749, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 5, 'OT', 'И когда двинется стан, придёт Аарон и сыновья его, и снимут завесу, и покроют ею ковчег свидетельства.'),
(3750, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 6, 'OT', 'И положат на него покрывало из кожи тахаша, и расстелют сверху одежду из голубого, и вложат шесты его.'),
(3751, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 7, 'OT', 'И над столом хлебов предложения прострут одежду голубую, и положат на него блюда, и ложки, и чаши, и чаши для возлияния, и хлеб постоянный на нём будет.'),
(3752, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 8, 'OT', 'И разостлали на них одежду из червлёной ткани багрянца, и покрыли её покрывалом из кожи тахаша, и положили её шесты.'),
(3753, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 9, 'OT', 'И возьмут одежду голубую и покроют светильник светила, и светильники его, и щипцы его, и кадильницы его, и все сосуды елея его, которыми служат ему в них.'),
(3754, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 10, 'OT', 'И положат её и все сосуды её на покрывало из кожи тахаша, и положат на шест.'),
(3755, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 11, 'OT', 'И на золотой жертвенник положат одежду голубую и покроют его покрывалом из кожи тахаша, и положат его шесты.'),
(3756, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 12, 'OT', 'И возьмут все сосуды служения, которыми служат во святыне, и положат их на одежду голубую, и покроют их покрывалом из кожи тахаша, и положат на шест.'),
(3757, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 13, 'OT', 'И очистят жертвенник от пепла, и покроют его одеждою из багряницы.'),
(3758, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 14, 'OT', 'И положат на него все сосуды его, которыми служат на нём: кадильницы, вилки, лопаты и чаши, все сосуды жертвенника, и покроют его покрывалом из кожи тахаша, и положат его шесты.'),
(3759, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 15, 'OT', 'И когда окончат Аарон и сыны его покрывать святыню и все сосуды святыни при отправлении стана, тогда после того придут сыны Каафа, чтобы нести; но не прикоснутся они к святыне, иначе умрут. Это бремя сынов Каафа в шатре собрания.'),
(3760, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 16, 'OT', 'Попечение Елеазара, сына Аарона, священника: елей светила, и фимиам ароматов, и хлебное приношение постоянное, и елей помазания, — попечение всей скинии и всего, что в ней, во святыне и в сосудах её.'),
(3761, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 17, 'OT', 'И говорил Господь к Моисею и к Аарону, говоря:'),
(3762, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 18, 'OT', 'Не истребляйте племя семейств Каафитов из среды левитов.'),
(3763, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 19, 'OT', 'И вот что сделайте им, чтобы они жили и не умерли, когда приступят к Святыне святынь: Аарон и сыновья его пусть войдут и поставят каждого человека на его служение и на его бремя.'),
(3764, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 20, 'OT', 'И пусть не приходят смотреть, как поглощается святыня, и не умрут.'),
(3765, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 21, 'OT', 'И сказал Господь Моисею, говоря:'),
(3766, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 22, 'OT', 'Исчисли перепись сынов Герсона также их, по дому отцов их, по семействам их.'),
(3767, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 23, 'OT', 'От сына тридцати лет и выше до сына пятидесяти лет исчисли их, всех входящих в службу для служения служением в шатре собрания.'),
(3768, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 24, 'OT', 'Это служение семейств Герсонитян: для служения и для бремени.'),
(3769, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 25, 'OT', 'И понесут завесы скинии, и шатёр собрания, покрывало его, и покрывало из кожи тахаша, которое на нём сверху, и завесу двери шатра собрания.'),
(3770, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 26, 'OT', 'и завесы двора, и завесу двери ворот двора, которая вокруг скинии и жертвенника, и верви их, и все сосуды служения их, и всё, что делается для них, и они будут служить.'),
(3771, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 27, 'OT', 'По указанию Аарона и сыновей его будет всё служение сынов Герсонитян, для всего бремени их и для всего служения их; и поручите им в надзор всё бремя их.'),
(3772, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 28, 'OT', 'Это служение семейств сынов Герсонитян в шатре собрания, и обязанность их — в руке Ифамара, сына Аарона, священника.'),
(3773, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 29, 'OT', 'Сыновей Мерари по семействам их, по дому отцов их исчисли их.'),
(3774, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 30, 'OT', 'От тридцати лет и выше и до пятидесяти лет, исчисли их, всех входящих на службу, чтобы нести служение при шатре собрания.'),
(3775, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 31, 'OT', 'И вот обязанность бремени их для всего служения их в шатре собрания: доски скинии и засовы её, и столбы её, и подножия её.'),
(3776, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 32, 'OT', 'И столбы двора вокруг, и подножия их, и колья их, и верви их, для всех сосудов их и для всего служения их; и по именам пересчитайте сосуды обязанности бремени их.'),
(3777, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 33, 'OT', 'Это служение семейств сынов Мерари, для всего служения их в шатре собрания, под руководством Ифамара, сына Аарона, священника.'),
(3778, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 34, 'OT', 'Моисей и Аарон и князья общества пересчитали сынов Каафитян по семействам их и по домам отцов их.'),
(3779, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 35, 'OT', 'От сына тридцати лет и выше и до сына пятидесяти лет, всё входящее в службу для служения в шатре собрания.'),
(3780, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 36, 'OT', 'И было исчисленных их по семействам их две тысячи семьсот пятьдесят.'),
(3781, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 37, 'OT', 'Вот эти перечисленные семейства Каафитов, все служащие в шатре собрания, которых перечислили Моисей и Аарон по повелению Господа рукою Моисея.'),
(3782, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 38, 'OT', 'И исчисленные сынов Герсона по семействам их и по домам отцов их'),
(3783, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 39, 'OT', 'От сына тридцати лет и выше и до сына пятидесяти лет, все входящие в службу для служения в шатре собрания.'),
(3784, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 40, 'OT', 'И было их по семействам их, по дому отцов их: две тысячи шестьсот тридцать.'),
(3785, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 41, 'OT', 'Вот эти исчисленные из семейств сынов Герсона, все служащие в шатре собрания, которых исчислили Моисей и Аарон по повелению Господа.'),
(3786, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 42, 'OT', 'И исчисленные из семейств сынов Мерари, по семействам их, по дому отцов их.'),
(3787, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 43, 'OT', 'От сына тридцати лет и выше и до сына пятидесяти лет, все приходящие на службу для служения в шатре собрания.'),
(3788, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 44, 'OT', 'И было перечисленных их по семействам их три тысячи двести.'),
(3789, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 45, 'OT', 'Вот эти перечисленные семейства сыновей Мерари, которых перечислил Моисей и Аарон по повелению Господа рукою Моисея.'),
(3790, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 46, 'OT', 'Всё исчисленное, что исчислили Моисей и Аарон и князья Израиля, левитов по семействам их и по домам отцов их.'),
(3791, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 47, 'OT', 'От тридцати лет и выше до пятидесяти лет, все, кто приходит для служения служением служения и служением бремени в шатре собрания, от сына тридцати лет и выше до сына пятидесяти лет.'),
(3792, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 48, 'OT', 'И было их исчисленных восемь тысяч пятьсот восемьдесят.'),
(3793, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 4, 49, 'OT', 'По повелению Господа были они пересчитаны рукою Моисея, каждый человек по служению своему и по бремени своему, и перечисленные его, которые повелел Господь Моисею.'),
(3794, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3795, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 2, 'OT', 'Повели сынам Израиля, и пусть вышлют из стана всякого прокажённого, и всякого имеющего истечение, и всякого осквернённого мёртвым.'),
(3796, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 3, 'OT', 'От мужчины до женщины вышлите, за пределы стана вышлите их, и пусть не оскверняют стан свой, в котором Я обитаю в середине их.'),
(3797, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 4, 'OT', 'И сделали так сыны Израиля, и выслали их за стан, как говорил Господь Моисею; так сделали сыны Израиля.'),
(3798, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 5, 'OT', 'И сказал Господь Моисею, говоря:'),
(3799, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 6, 'OT', 'Скажи сынам Израиля: если человек или жена сделает какой-либо из всех грехов человеческих, совершив преступление против Господа, и виновна будет та душа,'),
(3800, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 7, 'OT', 'И пусть исповедуют свой грех, который они совершили, и возвратит жертву повинности в полной мере, и пятую часть её прибавит к ней, и отдаст тому, против кого согрешил.'),
(3801, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 8, 'OT', 'Если же нет у человека родственника, которому можно было бы возвратить жертву повинности, то жертва повинности, возвращаемая Господу, принадлежит священнику, отдельно от овна очищения, которым он совершит очищение за него.'),
(3802, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 9, 'OT', 'И всякое приношение из всех святынь сынов Израиля, которые они приносят священнику, ему принадлежит.'),
(3803, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 10, 'OT', 'И человеку священные дары его ему будут; человек, который даст священнику, ему будет.'),
(3804, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 11, 'OT', 'И сказал Господь Моисею, говоря:'),
(3805, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 12, 'OT', 'Говори к сынам Израиля и скажи им: если человек, человек, когда жена его уклонится и совершит против него преступление,'),
(3806, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 13, 'OT', 'И ляжет с ней человек совокуплением семени, и будет скрыто от очей её мужа, и она утаится, и она осквернится, и свидетеля нет на ней, и она не будет схвачена.'),
(3807, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 14, 'OT', 'И если пройдёт по нему дух ревности, и он возревнует жену свою, и она осквернена, или пройдёт по нему дух ревности, и он возревнует жену свою, и она не осквернена,'),
(3808, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 15, 'OT', 'И приведёт человек жену свою к священнику и принесёт приношение её за неё: десятую часть ефы муки ячменной; не возольёт на неё елея и не положит на неё ладана, ибо это приношение ревности, приношение памяти, напоминающее о беззаконии.'),
(3809, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 16, 'OT', 'И приведёт её священник, и поставит её пред лицом Господа.'),
(3810, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 17, 'OT', 'И возьмёт священник святой воды в глиняный сосуд, и из праха, который на дне скинии, возьмёт священник и положит в воду.'),
(3811, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 18, 'OT', 'И поставит священник жену пред лицом Господа, и распустит главу жены, и даст на ладони её приношение памяти, приношение ревности это, а в руке священника будут воды горькие, наводящие проклятие.'),
(3812, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 19, 'OT', 'И заклянет её священник и скажет жене: если не лежал с тобой человек, и если не уклонилась ты в нечистоту под человеком твоим, будь чиста от этих горьких вод, наводящих проклятие.'),
(3813, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 20, 'OT', 'А ты, если уклонилась под своего человека и если осквернилась, и дал человек в тебе своё ложе, кроме твоего человека'),
(3814, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 21, 'OT', 'И пусть священник заставит жену поклясться клятвою проклятия, и скажет священник жене: да сделает Господь тебя проклятием и клятвою среди народа твоего, когда Господь сделает бедро твоё опадающим и чрево твоё вздутым.'),
(3815, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 22, 'OT', 'И войдут воды эти проклинающие в чрево твоё, чтобы распухло чрево и опало бедро; и скажет жена: аминь, аминь.'),
(3816, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 23, 'OT', 'И напишет священник эти проклятия в книге и смоет их в горькую воду.'),
(3817, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 24, 'OT', 'И напоит он жену водою горькою, проклинающею, и войдут в неё воды проклинающие для горечи.'),
(3818, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 25, 'OT', 'И возьмёт священник из руки жены приношение ревности, и вознесёт это приношение пред лицом Господа, и принесёт его к жертвеннику.'),
(3819, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 26, 'OT', 'И возьмёт священник из хлебного приношения памятную часть его и сожжёт на жертвеннике, и после того напоит жену водою.'),
(3820, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 27, 'OT', 'И напоит её водою, и если она осквернилась и совершила преступление против своего человека, то войдут в неё воды проклятия для горечи, и раздуется чрево её, и опадет бедро её, и будет жена проклятием среди народа своего.'),
(3821, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 28, 'OT', 'А если не осквернилась жена и чиста она, то останется невиновной и будет иметь семя.'),
(3822, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 29, 'OT', 'Это закон ревности, когда жена согрешит против человека своего и осквернится.'),
(3823, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 30, 'OT', 'Или человек, когда пройдёт по нему дух ревности, и он возревнует жену свою, и поставит жену пред лицом Господа, и совершит над нею священник всё это закон.'),
(3824, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 5, 31, 'OT', 'И очистится человек от беззакония, а жена та понесёт беззаконие своё.'),
(3825, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 1, 'OT', 'И сказал Господь Моисею, говоря:'),
(3826, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 2, 'OT', 'Скажи сынам Израиля и скажи им: если человек или жена даст обет назорейства, чтобы посвятить себя Господу,'),
(3827, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 3, 'OT', 'От вина и сикера он воздержится, уксуса из вина и уксуса из сикера не будет пить, и всякого рассола из винограда не будет пить, и винограда свежего и сушёного не будет есть.'),
(3828, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 4, 'OT', 'Во все дни назорейства своего, от всего, что делается из виноградной лозы вина, от зерна и до кожуры, не должен он есть.'),
(3829, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 5, 'OT', 'Во все дни обета назорейства своего бритва не пройдёт по главе его; до исполнения дней, которые он посвятит Господу, свят будет он, отращивая волосы головы своей.'),
(3830, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 6, 'OT', 'Во все дни назорейства своего Господу, к телу умершего не придёт он.'),
(3831, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 7, 'OT', 'Отцу своему и матери своей, брату своему и сестре своей не должен он оскверняться при смерти их, ибо посвящение Бога его на главе его.'),
(3832, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 8, 'OT', 'Во все дни посвящения своего он свят для Господа.'),
(3833, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 9, 'OT', 'И если умрёт кто-нибудь внезапно при нём, и осквернит главу назорейства своего, то пусть обреет главу свою в день очищения своего, в седьмой день обреет её.'),
(3834, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 10, 'OT', 'И в восьмой день принесёт он двух горлиц или двух сыновей голубя к священнику, ко входу шатра собрания.'),
(3835, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 11, 'OT', 'И совершит священник одного в жертву за грех и одного во всесожжение, и очистит его от того, чем он согрешил по нечистоте от прикосновения к умершему, и освятит главу его в тот день.'),
(3836, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 12, 'OT', 'И посвятит Господу дни назорейства своего, и принесёт ягнёнка сына года своего в жертву повинности; а прежние дни будут потеряны, ибо осквернено назорейство его.'),
(3837, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 13, 'OT', 'И вот закон о назорее: в день исполнения дней назорейства его, он должен привести его ко входу шатра собрания.'),
(3838, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 14, 'OT', 'И принесёт он приношение своё Господу: одного ягнёнка, сына года своего, непорочного, во всесожжение, и одну овцу годовалую, непорочную, в жертву за грех, и одного овна непорочного в мирную жертву.'),
(3839, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 15, 'OT', 'и корзину опресноков из муки, лепёшки, смешанные с елеем, и лепёшки опресночные, помазанные елеем, и хлебное приношение их, и возлияния их.'),
(3840, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 16, 'OT', 'И принесёт священник пред лицо Господа и совершит жертву за грех его и всесожжение его.'),
(3841, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 17, 'OT', 'И овна принесёт в жертву мирную Господу вместе с корзиной опресноков; и совершит священник хлебное приношение его и возлияние его.'),
(3842, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 18, 'OT', 'И обреет назорей у двери шатра собрания главу посвящения своего, и возьмёт волосы главы посвящения своего, и положит на огонь, который под жертвой мирной.'),
(3843, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 19, 'OT', 'И возьмёт священник мышцу варёную из овна, и одну лепёшку опресночную из корзины, и одну лепёшку опресночную, и положит на ладони назорея, после того как обриет он посвящённые волосы свои.'),
(3844, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 20, 'OT', 'И пусть священник потрясёт их потрясанием пред лицом Господа; это святыня для священника, вместе с грудью потрясания и бедром приношения; и после этого пусть пьёт назорей вино.'),
(3845, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 21, 'OT', 'Вот закон о назорее: приношение его Господу за обет назорейства его — отдельно от того, что достанет рука его; по слову обета его, который он дал, так он должен поступать по закону обета назорейства его.'),
(3846, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 22, 'OT', 'И сказал Господь Моисею, говоря:'),
(3847, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 23, 'OT', 'Скажи Аарону и сыновьям его так: так благословляйте сынов Израиля, говоря им:'),
(3848, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 24, 'OT', 'Да благословит тебя Господь и сохранит тебя.'),
(3849, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 25, 'OT', 'Да воссияет Господь лицом Своим к тебе и помилует тебя.'),
(3850, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 26, 'OT', 'Да поднимет Господь лицо Своё на тебя и даст тебе мир.'),
(3851, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 6, 27, 'OT', 'И возложат имя Моё на сынов Израиля, и Я благословлю их.'),
(3852, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 1, 'OT', 'И было в день, когда Моисей окончил воздвигать скинию, и помазал её, и освятил её, и все сосуды её, и жертвенник, и все сосуды его, и помазал их, и освятил их.'),
(3853, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 2, 'OT', 'И принесли князья Израиля, главы дома отцов их; они — князья колен, они стояли над перечисленными.'),
(3854, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 3, 'OT', 'И принесли они приношение своё пред лицом Господа: шесть повозок, крытых покрывалом, и двенадцать из крупного рогатого скота, повозку на двух князей и вола на одного, и принесли их пред лицом скинии.'),
(3855, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 4, 'OT', 'И сказал Господь Моисею, говоря:'),
(3856, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 5, 'OT', 'Возьми от них, и будут они для служения служению шатра собрания, и отдай их левитам, каждому человеку по мере служения его.'),
(3857, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 6, 'OT', 'И взял Моисей повозки и быков, и отдал их левитам.'),
(3858, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 7, 'OT', 'Две повозки и четырех волов он дал сынам Герсона, по мере служения их.'),
(3859, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 8, 'OT', 'И четыре повозки и восемь волов отдал сынам Мерари, по мере служения их, через Ифамара, сына Аарона, священника.'),
(3860, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 9, 'OT', 'А сыновьям Каафа не дал, потому что служение святыни на них: на плечах они будут носить.'),
(3861, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 10, 'OT', 'И принесли князья освящение жертвенника в день помазания его, и принесли князья приношение своё пред лицом жертвенника.'),
(3862, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 11, 'OT', 'И сказал Господь Моисею: один князь в день, один князь в день пусть приносят своё приношение для освящения жертвенника.'),
(3863, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 12, 'OT', 'И приносящий в первый день приношение своё — Наассон, сын Аминадава, из колена Иуды.'),
(3864, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 13, 'OT', 'И приношение его: одно серебряное блюдо, весом в сто тридцать сиклей, одна серебряная чаша в семьдесят сиклей, по сиклю святыни, оба наполнены мукой, смешанной с елеем, в хлебное приношение.'),
(3865, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 14, 'OT', 'одна ложка, десять золота, наполненная фимиамом'),
(3866, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 15, 'OT', 'Телец один, сын крупного рогатого скота, овен один, ягнёнок один, сын года своего, во всесожжение.'),
(3867, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 16, 'OT', 'один козёл из коз в жертву за грех'),
(3868, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 17, 'OT', 'И для жертвы мирной — крупного рогатого скота два, овнов пять, козлов пять, ягнят однолетних пять; это приношение Наассона, сына Аминадава.'),
(3869, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 18, 'OT', 'Во второй день принёс приношение Нафанаил, сын Цуара, князь Иссахара.'),
(3870, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 19, 'OT', 'Он принёс своё приношение: одно серебряное блюдо, весом в сто тридцать [сиклей], одну серебряную чашу в семьдесят сиклей, по сиклю святыни, оба наполнены мукой, смешанной с елеем, для хлебного приношения.'),
(3871, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 20, 'OT', 'одна ложка, десять золота, наполненная фимиамом'),
(3872, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 21, 'OT', 'Телец один, молодой телец, овен один, ягнёнок один, сын года своего, во всесожжение.'),
(3873, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 22, 'OT', 'один козёл из коз в жертву за грех'),
(3874, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 23, 'OT', 'И для жертвы мирной — крупного рогатого скота два, овнов пять, козлов пять, ягнят однолетних пять; это приношение Нафанаила, сына Цуара.'),
(3875, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 24, 'OT', 'В третий день князь сынов Завулона, Елиав, сын Хелона.'),
(3876, 4, 'GOI_Ru', 'GOI_Ru', 'ru', 'NUM', 7, 25, 'OT', 'Приношение его — одно серебряное блюдо, весом в сто тридцать сиклей, одна серебряная чаша в семьдесят сиклей, по сиклю святыни; оба они наполнены мукой, смешанной с елеем, для хлебного приношения.'),
